// ============================================================================
// CLI argument parsing
// ============================================================================

const { values: args } = parseArgs({
	args: process.argv.slice(2),
	options: {
		repo: { type: "string", default: "jlowin_fastmcp" },
		limit: { type: "string", default: "30" },
		output: {
			type: "string",
			default: "eval/mnemex-search-steps-evaluation/runs/first-run",
		},
		"eval-repos-dir": {
			type: "string",
			default: "/Users/jack/mag/agentbench/data/eval-repos",
		},
		verbose: { type: "boolean", default: false },
	},
});

const repoName = args.repo as string;
const symbolLimit = Number.parseInt(args.limit as string, 10);
const outputDir = args.output as string;
const evalReposDir = args["eval-repos-dir"] as string;
const verbose = Boolean(args.verbose);

const repoPath = `${evalReposDir}/${repoName}`;

// ============================================================================
// Step 1: Load top symbols from the index via FileTracker
// ============================================================================

console.log(`Repo:    ${repoPath}`);
console.log(`Symbols: top ${symbolLimit} by PageRank`);
console.log(`Output:  ${outputDir}`);
console.log();

const indexDbPath = getIndexDbPath(repoPath);
const fileTracker = createFileTracker(indexDbPath, repoPath);

const topSymbols = fileTracker.getTopSymbols(symbolLimit);
fileTracker.close();

if (topSymbols.length === 0) {
	console.error(
		`No symbols found in index at: ${indexDbPath}\n` +
			"Run `mnemex index` on the repo first.",
	);
	process.exit(1);
}

console.log(`Loaded ${topSymbols.length} symbols from index.`);

// ============================================================================
// Step 2: Build HarnessQuery[] from symbols
//
// Query text  = symbol name (e.g. "FastMCP", "create_server", "Client")
// Ground truth = the file path where the symbol lives (file-level matching)
// codeUnitId  = filePath::symbolName (used as fallback if groundTruthFiles missing)
// routerLabel = "symbol_lookup" (we're searching by symbol name)
// ============================================================================

const queries: HarnessQuery[] = topSymbols.map((sym, idx) => {
	const queryId = `sym-${String(idx + 1).padStart(3, "0")}-${sym.name}`;
	return {
		id: queryId,
		// codeUnitId is the fallback ground truth when groundTruthFiles is empty
		codeUnitId: `${sym.filePath}::${sym.name}`,
		type: "doc_api_lookup" as QueryType,
		query: sym.name,
		shouldFind: true,
		routerLabel: "symbol_lookup",
		// File-level ground truth: the result is correct if it mentions sym.filePath
		groundTruthFiles: [sym.filePath],
	};
});

if (verbose) {
	console.log("\nSample queries:");
	for (const q of queries.slice(0, 5)) {
		console.log(`  [${q.id}] "${q.query}"  ->  ${q.groundTruthFiles?.[0]}`);
	}
	console.log();
}

// ============================================================================
// Step 3: Create indexer and wire up the real search function
// ============================================================================

const indexer = createIndexer({ projectPath: repoPath });

// The index stores relative paths in symbols (e.g. "src/fastmcp/server.py") but
// the search API returns absolute paths.  Strip the repo prefix so retrieved
// docIds match the relative paths stored as groundTruthFiles.
const repoPrefixWithSlash = repoPath.endsWith("/") ? repoPath : `${repoPath}/`;

const searchFn: SearchFunction = async (query, opts) => {
	const results = await indexer.search(query, {
		limit: opts.k,
		useCase: "search",
	});
	return results.map((r) => {
		// Normalize to relative path for consistent matching against ground truth
		const filePath = r.chunk.filePath.startsWith(repoPrefixWithSlash)
			? r.chunk.filePath.slice(repoPrefixWithSlash.length)
			: r.chunk.filePath;
		return {
			// File-level docId so it matches groundTruthFiles (relative file path)
			docId: filePath,
			score: r.score,
			snippet: r.chunk.content.slice(0, 200),
		};
	});
};

// ============================================================================
// Step 4: Find Condition A and run it
// ============================================================================

const conditionA = STANDARD_CONDITIONS.find((c) => c.name === "A");
if (!conditionA) {
	console.error(
		"Condition A not found in STANDARD_CONDITIONS — check ablation.ts",
	);
	process.exit(1);
}

await mkdir(outputDir, { recursive: true });

console.log(`Running Condition A: "${conditionA.description}" ...`);
console.log(`  Queries: ${queries.length}`);

const conditionResult = await runCondition(conditionA, {
	conditions: [conditionA],
	querySet: queries,
	outputDir,
	kValues: [1, 5, 10, 100],
	verbose,
	searchFn,
});

// ============================================================================
// Step 5: Generate the markdown report
// ============================================================================

const reportPath = `${outputDir}/report.md`;
await generateReport([conditionResult], reportPath);

// ============================================================================
// Step 6: Print summary and close
// ============================================================================

const m = conditionResult.metrics;
const l = conditionResult.latency;

console.log("\n=== Condition A Results ===");
console.log(`  Queries:    ${conditionResult.nQueries}`);
console.log(`  MRR@10:     ${m.mrrAt10.toFixed(3)}`);
console.log(`  NDCG@10:    ${m.ndcgAt10.toFixed(3)}`);
console.log(`  NDCG@5:     ${m.ndcgAt5.toFixed(3)}`);
console.log(`  Recall@100: ${m.recallAt100.toFixed(3)}`);
console.log(`  P50 lat:    ${Math.round(l.p50)}ms`);
console.log(`  P95 lat:    ${Math.round(l.p95)}ms`);
console.log(`\nReport:  ${reportPath}`);
console.log(`Results: ${outputDir}/condition_A.json`);

await indexer.close();

#!/usr/bin/env bun
/**
 * Run one Claude Code x mnemex-rg eval case and emit JSON.
 *
 * This driver is shared by the promptfoo smoke eval and the HTML report. It
 * launches Claude Code against the pinned rg testdata, injects a temporary
 * logging `rg` shim, routes that shim through the current repo's built
 * `dist/index.js`, and captures enough evidence to score the tool trajectory.
 */

import { spawnSync } from "node:child_process";
import {
	chmodSync,
	copyFileSync,
	existsSync,
	mkdirSync,
	mkdtempSync,
	readFileSync,
	rmSync,
	statSync,
	unlinkSync,
	writeFileSync,
} from "node:fs";
import { homedir, tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

type JsonObject = Record<string, unknown>;
type ToolCall = {
	id?: unknown;
	name?: unknown;
	input?: Record<string, unknown>;
};

const __filename = fileURLToPath(import.meta.url);
const EVAL_ROOT = dirname(__filename);
const REPO_ROOT = resolve(EVAL_ROOT, "../..");
const TESTDATA = join(REPO_ROOT, "tests", "testdata", "rg-corpus");
const DIST_CLI = join(REPO_ROOT, "dist", "index.js");
const VSCODE_RG = join(
	REPO_ROOT,
	"node_modules",
	"@vscode",
	"ripgrep",
	"bin",
	"rg",
);
const RG_SHIM_PATH = join(homedir(), ".local", "bin", "rg");
const LOG_DIR = join(REPO_ROOT, "eval", "rg", "logs");

const STARTUP_RG_RE = /args=(--version|--files\b)/;
const FORBIDDEN_TOOLS = new Set(["Bash"]);

class DriverError extends Error {}

function shellQuote(value: string): string {
	return `'${value.replace(/'/g, `'\\''`)}'`;
}

function commandExists(command: string): boolean {
	const result = spawnSync("sh", ["-lc", `command -v ${shellQuote(command)}`], {
		stdio: "ignore",
	});
	return result.status === 0;
}

function requirePreconditions(buildIndex: boolean): void {
	if (!existsSync(TESTDATA)) {
		throw new DriverError(`testdata missing at ${TESTDATA}`);
	}
	if (!existsSync(DIST_CLI)) {
		throw new DriverError(
			`built CLI missing at ${DIST_CLI}; run \`bun run build\``,
		);
	}
	if (!existsSync(VSCODE_RG)) {
		throw new DriverError(
			`bundled rg missing at ${VSCODE_RG}; run \`bun install\``,
		);
	}
	if (!commandExists("bun")) {
		throw new DriverError("bun not on PATH");
	}
	if (!commandExists("claude")) {
		throw new DriverError("claude CLI not on PATH");
	}

	const indexDb = join(TESTDATA, ".mnemex", "index.db");
	if (!existsSync(indexDb)) {
		if (!buildIndex) {
			throw new DriverError(
				`testdata index missing at ${join(TESTDATA, ".mnemex")}`,
			);
		}
		const result = spawnSync("bun", [DIST_CLI, "index", "--force"], {
			cwd: TESTDATA,
			encoding: "utf8",
		});
		if (result.status !== 0) {
			throw new DriverError(
				`failed to build testdata index: ${result.stderr || result.stdout}`,
			);
		}
	}
}

class TemporaryShims {
	readonly binDir: string;
	private originalRg: Buffer | null = null;
	private originalMode: number | null = null;

	constructor(
		private readonly workDir: string,
		private readonly rgTrace: string,
		private readonly mnemexTrace: string,
	) {
		this.binDir = join(workDir, "bin");
	}

	install(): void {
		mkdirSync(this.binDir, { recursive: true });
		mkdirSync(dirname(RG_SHIM_PATH), { recursive: true });

		if (existsSync(RG_SHIM_PATH)) {
			const currentRg = readFileSync(RG_SHIM_PATH);
			if (
				!currentRg
					.toString("utf8")
					.startsWith("#!/bin/sh\n# MNEMEX_RG_EVAL_RG_SHIM")
			) {
				this.originalRg = currentRg;
				this.originalMode = statSync(RG_SHIM_PATH).mode & 0o777;
			}
		}

		const mnemexWrapper = join(this.binDir, "mnemex");
		writeFileSync(
			mnemexWrapper,
			[
				"#!/bin/sh",
				"# MNEMEX_RG_EVAL_MNEMEX_SHIM",
				'TRACE="${MNEMEX_SHIM_TRACE:-/tmp/mnemex-rg-eval-mnemex.log}"',
				'echo "[$(date +%H:%M:%S)] MNEMEX_HIT pid=$$ ppid=$PPID args=$*" >> "$TRACE"',
				`exec bun ${shellQuote(DIST_CLI)} "$@"`,
				"",
			].join("\n"),
			"utf8",
		);
		chmodSync(mnemexWrapper, 0o755);

		writeFileSync(
			RG_SHIM_PATH,
			[
				"#!/bin/sh",
				"# MNEMEX_RG_EVAL_RG_SHIM",
				'TRACE="${RG_SHIM_TRACE:-/tmp/mnemex-rg-eval-rg.log}"',
				'echo "[$(date +%H:%M:%S)] SHIM_HIT pid=$$ ppid=$PPID args=$*" >> "$TRACE"',
				'exec mnemex rg "$@"',
				"",
			].join("\n"),
			"utf8",
		);
		chmodSync(RG_SHIM_PATH, 0o755);
	}

	restore(): void {
		if (this.originalRg) {
			writeFileSync(RG_SHIM_PATH, this.originalRg);
			if (this.originalMode !== null) {
				chmodSync(RG_SHIM_PATH, this.originalMode);
			}
			return;
		}

		try {
			const content = readFileSync(RG_SHIM_PATH, "utf8");
			if (content.startsWith("#!/bin/sh\n# MNEMEX_RG_EVAL_RG_SHIM")) {
				unlinkSync(RG_SHIM_PATH);
			}
		} catch {
			// Already gone.
		}
	}
}

function readTail(path: string, lines = 20): string {
	try {
		return readFileSync(path, "utf8")
			.split(/\r?\n/)
			.filter(Boolean)
			.slice(-lines)
			.join("\n");
	} catch {
		return "";
	}
}

function parseStreamJson(path: string): JsonObject {
	const grepCalls: JsonObject[] = [];
	const grepToolIds = new Set<string>();
	const allToolCalls: ToolCall[] = [];
	const nonGrepToolCalls: ToolCall[] = [];
	const toolResultPreviews: string[] = [];
	const finalTextParts: string[] = [];
	let toolResultCount = 0;
	let grepToolResultCount = 0;

	let rawLines: string[] = [];
	try {
		rawLines = readFileSync(path, "utf8").split(/\r?\n/).filter(Boolean);
	} catch {
		rawLines = [];
	}

	for (const raw of rawLines) {
		let event: JsonObject;
		try {
			event = JSON.parse(raw) as JsonObject;
		} catch {
			continue;
		}

		const eventType = event.type;
		const message = event.message as JsonObject | undefined;
		const content = Array.isArray(message?.content)
			? message.content
			: undefined;
		if (!content) continue;

		for (const itemValue of content) {
			if (!itemValue || typeof itemValue !== "object") continue;
			const item = itemValue as JsonObject;

			if (eventType === "assistant" && item.type === "tool_use") {
				const toolName = item.name;
				const toolInput =
					item.input && typeof item.input === "object"
						? (item.input as Record<string, unknown>)
						: {};
				const toolCall: ToolCall = {
					id: item.id,
					name: toolName,
					input: toolInput,
				};
				allToolCalls.push(toolCall);

				if (toolName === "Grep") {
					if (item.id) grepToolIds.add(String(item.id));
					grepCalls.push({
						pattern: toolInput.pattern ?? null,
						path: toolInput.path ?? null,
						glob: toolInput.glob ?? null,
						head_limit: toolInput.head_limit ?? null,
						output_mode: toolInput.output_mode ?? null,
					});
				} else {
					nonGrepToolCalls.push(toolCall);
				}
			} else if (eventType === "user" && item.type === "tool_result") {
				toolResultCount += 1;
				if (!grepToolIds.has(String(item.tool_use_id))) continue;
				grepToolResultCount += 1;

				let resultContent = item.content;
				if (Array.isArray(resultContent)) {
					resultContent = resultContent
						.map((part) =>
							part && typeof part === "object"
								? String((part as JsonObject).text ?? "")
								: "",
						)
						.join(" ");
				}
				if (typeof resultContent === "string") {
					toolResultPreviews.push(resultContent.slice(0, 2000));
				}
			} else if (eventType === "assistant" && item.type === "text") {
				finalTextParts.push(String(item.text ?? ""));
			}
		}
	}

	const successfulPreviews = toolResultPreviews.filter(
		(preview) => preview.trim() && !preview.includes("<tool_use_error>"),
	);
	const grepResultPreview =
		successfulPreviews[0] ?? toolResultPreviews[0] ?? "";

	return {
		grep_tool_calls: grepCalls,
		grep_tool_call_count: grepCalls.length,
		all_tool_call_count: allToolCalls.length,
		non_grep_tool_call_count: nonGrepToolCalls.length,
		non_grep_tool_calls: nonGrepToolCalls.slice(0, 5),
		forbidden_tool_call_count: nonGrepToolCalls.filter((call) =>
			FORBIDDEN_TOOLS.has(String(call.name)),
		).length,
		forbidden_tool_calls: nonGrepToolCalls
			.filter((call) => FORBIDDEN_TOOLS.has(String(call.name)))
			.slice(0, 5),
		tool_result_count: toolRe

