	let timeout = 60000;
	let retries = 2;

	for (let i = 0; i < args.length; i++) {
		const arg = args[i];
		switch (arg) {
			case "--model": {
				const name = args[++i];
				const model = findModel(name);
				if (!model) {
					console.error(`Model not found: ${name}`);
					console.error(
						`Available: ${BENCH_MODELS.map((m) => m.name).join(", ")}`,
					);
					process.exit(1);
				}
				models = [model];
				break;
			}
			case "--family": {
				const family = args[++i] as BenchModel["family"];
				const familyModels = getFamily(family);
				if (familyModels.length === 0) {
					console.error(`Unknown family: ${family}. Use qwen3.5 or lfm2`);
					process.exit(1);
				}
				models = familyModels;
				break;
			}
			case "--dry-run":
				dryRun = true;
				break;
			case "--skip-load":
				skipLoad = true;
				break;
			case "--port":
				port = parseInt(args[++i], 10);
				break;
			case "--timeout":
				timeout = parseInt(args[++i], 10);
				break;
			case "--retries":
				retries = parseInt(args[++i], 10);
				break;
			default:
				console.error(`Unknown option: ${arg}`);
				process.exit(1);
		}
	}

	return { models, dryRun, skipLoad, port, timeout, retries };
}

