interface Config {
	seedsPath: string;
	outputPath: string;
	models: ModelConfig[];
	limit: number;
	concurrency: number;
	dryRun: boolean;
	resume: boolean;
}

function parseArgs(): Config {
	const args = process.argv.slice(2);
	const ROOT = join(dirname(new URL(import.meta.url).pathname), "..");
	let seedsPath = join(ROOT, "seeds/code-queries.jsonl");
	let outputPath = join(ROOT, "data/train.jsonl");
	let selectedModels = [...MODELS];
	let limit = Infinity;
	let concurrency = 3;
	let dryRun = false;
	let resume = false;

	for (let i = 0; i < args.length; i++) {
		switch (args[i]) {
			case "--seeds":
				seedsPath = args[++i];
				break;
			case "--output":
				outputPath = args[++i];
				break;
			case "--models": {
				const ids = args[++i].split(",").map((s) => s.trim());
				selectedModels = ids.map((id) => {
					const found = MODELS.find(
						(m) =>
							m.id === id || m.name.toLowerCase().includes(id.toLowerCase()),
					);
					if (!found) {
						console.error(`Unknown model: ${id}`);
						console.error(`Available: ${MODELS.map((m) => m.id).join(", ")}`);
						process.exit(1);
					}
					return found;
				});
				break;
			}
			case "--limit":
				limit = parseInt(args[++i], 10);
				break;
			case "--concurrency":
				concurrency = parseInt(args[++i], 10);
				break;
			case "--dry-run":
				dryRun = true;
				break;
			case "--resume":
				resume = true;
				break;
			default:
				console.error(`Unknown option: ${args[i]}`);
				process.exit(1);
		}
	}

	return {
		seedsPath,
		outputPath,
		models: selectedModels,
		limit,
		concurrency,
		dryRun,
		resume,
	};
}

