function sleep(ms: number, token: vscode.CancellationToken): Promise<boolean> {
	return new Promise((resolve) => {
		const t = setTimeout(() => resolve(true), ms);
		const sub = token.onCancellationRequested(() => {
			clearTimeout(t);
			sub.dispose();
