class JsonlRpcClient implements vscode.Disposable {
	private proc: ChildProcessWithoutNullStreams;
	private rl: readline.Interface;
	private pending = new Map<
		string,
		{ resolve: (v: any) => void; reject: (e: any) => void }
	>();

	constructor(
		args: { binaryPath: string; projectPath: string; env: NodeJS.ProcessEnv },
		private readonly output: vscode.OutputChannel,
	) {
		this.proc = spawn(
			args.binaryPath,
			["--autocomplete-server", "--project", args.projectPath],
			{
				env: args.env,
				stdio: "pipe",
			},
		);

		this.output.appendLine(
			`[spawn] ${args.binaryPath} --autocomplete-server --project ${args.projectPath}`,
		);

		this.proc.on("error", (err) => {
			for (const { reject } of this.pending.values()) reject(err);
			this.pending.clear();
		});

		this.proc.on("exit", (code, signal) => {
			const err = new Error(
				`mnemex autocomplete server exited (${code ?? "null"} / ${signal ?? "null"})`,
			);
			for (const { reject } of this.pending.values()) reject(err);
			this.pending.clear();
		});

		this.proc.stderr.on("data", (chunk) => {
			this.output.appendLine(chunk.toString());
		});

		this.rl = readline.createInterface({
			input: this.proc.stdout,
			crlfDelay: Number.POSITIVE_INFINITY,
		});
		this.rl.on("line", (line) => {
			let msg: RpcResponse;
			try {
				msg = JSON.parse(line) as RpcResponse;
			} catch {
				return;
			}

			const pending = this.pending.get(msg.id);
			if (!pending) return;
			this.pending.delete(msg.id);
			if ("error" in msg) pending.reject(new Error(msg.error.message));
			else pending.resolve(msg.result);
		});
	}

	request<T = any>(
		method: string,
		params: any,
		requestId?: string,
	): Promise<T> {
		const id = requestId || randomUUID();
		const payload = JSON.stringify({ id, method, params });

		return new Promise<T>((resolve, reject) => {
			this.pending.set(id, { resolve, reject });
			this.proc.stdin.write(payload + "\n", (err) => {
				if (err) {
					this.pending.delete(id);
					reject(err);
				}
			});
		});
	}

	cancel(targetId: string): void {
		const id = randomUUID();
		this.proc.stdin.write(
			JSON.stringify({ id, method: "cancel", params: { id: targetId } }) + "\n",
		);
	}

	dispose(): void {
		try {
			this.rl.close();
		} catch {}

		try {
			this.proc.kill();
		} catch {}
	}
}

class ClientManager implements vscode.Disposable {
	private clients = new Map<string, JsonlRpcClient>();

	constructor(
		private readonly context: vscode.ExtensionContext,
		private readonly output: vscode.OutputChannel,
	) {}

	async getClient(folder: vscode.WorkspaceFolder): Promise<JsonlRpcClient> {
		const key = folder.uri.fsPath;
		const existing = this.clients.get(key);
		if (existing) return existing;

		const cfg = getConfig();
		const env: NodeJS.ProcessEnv = { ...process.env };

		if (cfg.llmProvider) env.MNEMEX_LLM_PROVIDER = cfg.llmProvider;
		if (cfg.llmModel) env.MNEMEX_LLM_MODEL = cfg.llmModel;
		if (cfg.llmEndpoint) env.MNEMEX_LLM_ENDPOINT = cfg.llmEndpoint;

		const openRouterKey = await this.context.secrets.get(
			"mnemex.openrouterApiKey",
		);
		if (openRouterKey) env.OPENROUTER_API_KEY = openRouterKey;

		const client = new JsonlRpcClient(
			{
				binaryPath: cfg.binaryPath,
				projectPath: folder.uri.fsPath,
				env,
			},
			this.output,
		);

		this.clients.set(key, client);
		try {
			await client.request("initialize", { projectPath: folder.uri.fsPath });
		} catch (e) {
			client.dispose();
			this.clients.delete(key);
			throw e;
		}

		return client;
	}

	restartAll(): void {
		for (const client of this.clients.values()) client.dispose();
		this.clients.clear();
	}

	dispose(): void {
		this.restartAll();
	}
}

export function activate(context: vscode.ExtensionContext) {
	const output = vscode.window.createOutputChannel("mnemex Autocomplete");
	context.subscriptions.push(output);

	const manager = new ClientManager(context, output);
	context.subscriptions.push(manager);

	context.subscriptions.push(
		vscode.commands.registerCommand(
			"mnemexAutocomplete.restartServer",
			async () => {
				manager.restartAll();
				vscode.window.showInformationMessage(
					"mnemex autocomplete server restarted.",
				);
			},
		),
	);

	context.subscriptions.push(
		vscode.commands.registerCommand(
			"mnemexAutocomplete.setOpenRouterKey",
