				const value = await vscode.window.showInputBox({
					title: "OpenRouter API Key",
					password: true,
					ignoreFocusOut: true,
					placeHolder: "sk-or-v1-…",
				});
				if (!value) return;
				await context.secrets.store("mnemex.openrouterApiKey", value);
				manager.restartAll();
