		const runSequence = () => {
			setActionStep(0);
			let cumDelay = 0;
			timeline.forEach(({ step, delay }) => {
				timeouts.push(setTimeout(() => setActionStep(step), delay));
				cumDelay = Math.max(cumDelay, delay);
			});
			// Reset loop
			timeouts.push(setTimeout(runSequence, cumDelay + 1000));
