import { existsSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

const KNOWN_NODE_LIBS = [
	"react",
	"next",
	"vue",
	"nuxt",
	"svelte",
	"@sveltejs/kit",
	"angular",
	"@angular/core",
	"express",
	"fastify",
	"@nestjs/core",
	"hono",
	"koa",
	"prisma",
	"drizzle-orm",
	"typeorm",
	"zod",
	"vitest",
	"jest",
	"typescript",
];

export interface ProjectFacts {
	text: string;
	sourceMtimeMs?: number;
}

function formatNodeFacts(pkg: {
	name?: string;
	dependencies?: Record<string, string>;
	devDependencies?: Record<string, string>;
}): string {
	const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
	const matches = KNOWN_NODE_LIBS.filter((name) => deps[name]).map(
		(name) => `${name}@${deps[name]}`,
	);

	const lines: string[] = [];
	if (pkg.name) lines.push(`package: ${pkg.name}`);
	if (matches.length > 0) lines.push(`stack: ${matches.join(", ")}`);
	return lines.join("\n");
}

export function loadProjectFacts(projectPath: string): ProjectFacts {
	const packageJsonPath = join(projectPath, "package.json");
	if (!existsSync(packageJsonPath)) {
		return { text: "" };
	}

	try {
		const stat = statSync(packageJsonPath);
		const content = readFileSync(packageJsonPath, "utf-8");
		const parsed = JSON.parse(content) as {
			name?: string;
			dependencies?: Record<string, string>;
			devDependencies?: Record<string, string>;
		};

		return {
			text: formatNodeFacts(parsed),
			sourceMtimeMs: stat.mtimeMs,
		};
	} catch {
		return { text: "" };
	}
}

import type { BaseDocument, EnrichedSearchResult } from "../types.js";

export interface StyleHints {
	indent?: string;
	semicolons?: boolean;
	quotes?: "single" | "double";
}

export function inferStyleHints(text: string): StyleHints {
	const lines = text.split(/\r?\n/).slice(0, 400);

	let tabIndented = 0;
	let twoSpaces = 0;
	let fourSpaces = 0;
	let semicolons = 0;
	let statementLines = 0;
	let singleQuotes = 0;
	let doubleQuotes = 0;

	for (const line of lines) {
		if (line.startsWith("\t")) tabIndented++;
		if (line.startsWith("  ") && !line.startsWith("   ")) twoSpaces++;
		if (line.startsWith("    ") && !line.startsWith("     ")) fourSpaces++;

		const trimmed = line.trim();
		if (!trimmed) continue;

		if (!trimmed.startsWith("//") && !trimmed.startsWith("#")) {
			statementLines++;
			if (trimmed.endsWith(";")) semicolons++;
		}

		singleQuotes += (trimmed.match(/'/g) || []).length;
		doubleQuotes += (trimmed.match(/"/g) || []).length;
	}

	let indent: string | undefined;
	if (tabIndented > twoSpaces && tabIndented > fourSpaces) indent = "\t";
	else if (fourSpaces > twoSpaces) indent = "    ";
	else if (twoSpaces > 0) indent = "  ";

	const quotes: StyleHints["quotes"] =
		singleQuotes > doubleQuotes
			? "single"
			: doubleQuotes > singleQuotes
				? "double"
				: undefined;

	return {
		indent,
		semicolons:
			statementLines > 20 ? semicolons / statementLines > 0.6 : undefined,
		quotes,
	};
}

function clip(text: string, maxChars: number): string {
	if (text.length <= maxChars) return text;
	return `${text.slice(0, maxChars)}\n…[truncated]`;
}

function formatDoc(doc: BaseDocument, maxChars: number): string {
	const header = [
		`type: ${doc.documentType}`,
		doc.filePath ? `file: ${doc.filePath}` : undefined,
		doc.metadata?.startLine ? `line: ${doc.metadata.startLine}` : undefined,
	]
		.filter(Boolean)
		.join("\n");

	switch (doc.documentType) {
		case "code_chunk":
			return `${header}\ncontent:\n${clip(doc.content, maxChars)}`;
		case "file_summary":
		case "symbol_summary":
		case "idiom":
		case "usage_example":
		case "anti_pattern":
		case "project_doc":
			return `${header}\ncontent:\n${clip(doc.content, maxChars)}`;
		default:
			return `${header}\ncontent:\n${clip(doc.content, maxChars)}`;
	}
}

export function buildAutocompletePrompt(args: {
	filePath: string;
	language: string;
	projectFacts?: string;
	styleHints?: StyleHints;
	astContext?: string;
	retrieval?: {
		repoMapContext?: string;
		results: EnrichedSearchResult[];
	};
	prefix: string;
	suffix: string;
}): { systemPrompt: string; userPrompt: string } {
	const systemPrompt = [
		"You are a code autocomplete engine.",
		"Return ONLY the text to insert at the cursor.",
		"Do not wrap in markdown or code fences.",
		"Do not repeat the prefix or the suffix.",
		"Match the project's style and conventions.",
		"If you are not confident, return an empty string.",
	].join("\n");

	const userParts: string[] = [];
	userParts.push(`file: ${args.filePath}`);
	userParts.push(`language: ${args.language}`);

	if (args.projectFacts) {
		userParts.push(`\n[project]\n${args.projectFacts.trim()}`);
	}

	if (args.styleHints && Object.keys(args.styleHints).length > 0) {
		userParts.push(`\n[style_hints]\n${JSON.stringify(args.styleHints)}`);
	}

	if (args.astContext) {
		userParts.push(`\n[ast_context]\n${args.astContext.trim()}`);
	}

	if (args.retrieval?.repoMapContext) {
		userParts.push(`\n[repo_map]\n${args.retrieval.repoMapContext.trim()}`);
	}

	if (args.retrieval?.results?.length) {
		const docs = args.retrieval.results
			.slice(0, 12)
			.map(
				(r, i) =>
					`\n[context_${i + 1}] score=${r.score.toFixed(3)}\n${formatDoc(r.document, 1400)}`,
			)
			.join("\n");
		userParts.push(`\n[retrieved_context]${docs}`);
	}

	userParts.push(
		[
			"\n[fim]",
			"--- prefix ---",
			args.prefix,
			"--- suffix ---",
			args.suffix,
			"--- end ---",
		].join("\n"),
	);

	return {
		systemPrompt,
		userPrompt: userParts.join("\n"),
	};
}

export function stripCodeFences(text: string): string {
	let out = text.trim();
	if (out.startsWith("```")) {
		const firstNewline = out.indexOf("\n");
		if (firstNewline !== -1) out = out.slice(firstNewline + 1);
		if (out.endsWith("```")) out = out.slice(0, -3);
	}
	return out.trim();
}

export function trimPrefixOverlap(
	prefix: string,
	completion: string,
	maxOverlap = 80,
): string {
	const max = Math.min(maxOverlap, prefix.length, completion.length);
	for (let k = max; k > 0; k--) {
		if (prefix.endsWith(completion.slice(0, k))) {
			return completion.slice(k);
		}
	}
	return completion;
}

export function truncateAtSuffixHint(
	suffix: string,
	completion: string,
): string {
	const hint = suffix.trim().slice(0, 40);
	if (!hint) return completion;
	const idx = completion.indexOf(hint);
	if (idx === -1) return completion;
	return completion.slice(0, idx);
}

/**
 * Autocomplete protocol (JSONL-RPC)
 *
 * One JSON object per line over stdin/stdout.
 */

export type AutocompleteMethod =
	| "initialize"
	| "complete"
	| "cancel"
	| "shutdown";

export interface AutocompletePosition {
	/** 0-based line */
	line: number;
	/** 0-based character (UTF-16 code units, VSCode-style) */
	character: number;
}

export interface AutocompleteInitializeParams {
	projectPath: string;
}

export interface AutocompleteCancelParams {
	/** ID of the in-flight request to cancel */
	id: string;
}

export interface AutocompleteCompleteParams {
	projectPath: string;
	filePath: string;
	/** Full document text (optional; expensive to send) */
	text?: string;
	/** Cursor position in the provided `text` */
	position?: AutocompletePosition;
	/** Prefix (text before cursor). If provided, server can avoid needing full `text`. */
	prefix?: string;
	/** Suffix (text after cursor). */
	suffix?: string;
	languageId?: string;
	options?: {
		maxPrefixChars?: number;
		maxSuffixChars?: number;
		maxContextResults?: number;
		repoMapTokens?: number;
		maxTokens?: number;
		temperature?: number;
	};
}

export interface AutocompleteCompleteResult {
	completion: string;
	provider: string;
	model: string;
	latencyMs: number;
	context: {
		retrievedDocuments: number;
		includesRepoMap: boolean;
	};
}

export interface AutocompleteRequest {
	id: string;
	method: AutocompleteMethod;
	params?: unknown;
}

export interface AutocompleteSuccessResponse {
	id: string;
	result: unknown;
}

export interface AutocompleteErrorResponse {
	id: string;
	error: { message: string };
}

export type AutocompleteResponse =
	| AutocompleteSuccessResponse
	| AutocompleteErrorResponse;

import { resolve } from "node:path";
import readline from "node:readline";
import { AutocompleteEngine } from "./engine.js";
import type {
	AutocompleteCompleteParams,
	AutocompleteRequest,
	AutocompleteResponse,
} from "./protocol.js";

function writeResponse(res: AutocompleteResponse): void {
	process.stdout.write(`${JSON.stringify(res)}\n`);
}

function errorResponse(id: string, message: string): AutocompleteResponse {
	return { id, error: { message } };
}

export async function startAutocompleteServer(
	args: { projectPath?: string } = {},
): Promise<void> {
	const projectPath = resolve(args.projectPath || process.cwd());
	const engine = new AutocompleteEngine(projectPath);

	const pending = new Map<string, AbortController>();

	const rl = readline.createInterface({
		input: process.stdin,
		crlfDelay: Number.POSITIVE_INFINITY,
	});

	rl.on("line", async (line) => {
		if (!line.trim()) return;

		let req: AutocompleteRequest;
		try {
			req = JSON.parse(line) as AutocompleteRequest;
		} catch {
			return;
		}

		const id = req.id;
		try {
			switch (req.method) {
				case "initialize": {
					await engine.initialize();
					writeResponse({ id, result: { ok: true, projectPath } });
					break;
				}

				case "complete": {
					const params = req.params as AutocompleteCompleteParams;
					if (!params?.filePath) {
						writeResponse(errorResponse(id, "Invalid complete params"));
						break;
					}

					const hasTextMode = !!params.text && !!params.position;
					const hasFimMode =
						params.prefix !== undefined && params.suffix !== undefined;
					if (!hasTextMode && !hasFimMode) {
						writeResponse(
							errorResponse(
								id,
								"Invalid complete params: provide {text, position} or {prefix, suffix}",
							),
						);
						break;
					}

					if (
						params.projectPath &&
						resolve(params.projectPath) !== projectPath
					) {
						writeResponse(
							errorResponse(id, `Server projectPath mismatch (${projectPath})`),
						);
						break;
					}

					const controller = new AbortController();
					pending.set(id, controller);

					try {
						const result = await engine.complete({
							...params,
							abortSignal: controller.signal,
						});
						writeResponse({ id, result });
					} finally {
						pending.delete(id);
					}
					break;
				}

				case "cancel": {
					const params = (req.params || {}) as { id?: string };
					const targetId = params.id;
					if (!targetId) {
						writeResponse(errorResponse(id, "Invalid cancel params"));
						break;
					}

					const controller = pending.get(targetId);
					if (controller) controller.abort();
					writeResponse({ id, result: { ok: true } });
					break;
				}

				case "shutdown": {
					for (const controller of pending.values()) controller.abort();
					pending.clear();
					await engine.close();
					writeResponse({ id, result: { ok: true } });
					rl.close();
					break;
				}

				default:
					writeResponse(errorResponse(id, `Unknown method: ${req.method}`));
			}
		} catch (error) {
			const msg = error instanceof Error ? error.message : String(error);
			writeResponse(errorResponse(id, msg));
		}
	});

	rl.on("close", async () => {
		for (const controller of pending.values()) controller.abort();
		pending.clear();
		await engine.close();
		process.exit(0);
	});

	process.on("SIGTERM", () => rl.close());
	process.on("SIGINT", () => rl.close());
}

