	);
	console.log(
		`${c.orange}${c.bold}║${c.reset}                         ${c.bold}QUALITY SCORES${c.reset}                                 ${c.orange}${c.bold}║${c.reset}`,
	);
	console.log(
		`${c.orange}${c.bold}╚═══════════════════════════════════════════════════════════════════════════╝${c.reset}`,
	);
