// ============================================================================
// Phase Executor Interface
// ============================================================================

/** Context passed to phase executors */
export interface PhaseContext {
	db: BenchmarkDatabase;
	run: BenchmarkRun;
	config: BenchmarkConfig;
	stateMachine: PipelineStateMachine;
}

/** Result of a phase execution */
export interface PhaseResult {
	success: boolean;
	itemsProcessed: number;
	error?: string;
	/** Detailed failure information for display after phase completes */
	failures?: Array<{ model: string; count: number; error: string }>;
	/** Reason for skipping (when itemsProcessed=0 and success=true) */
	skipReason?: string;
}

/** Phase executor function signature */
export type PhaseExecutor = (context: PhaseContext) => Promise<PhaseResult>;

// ============================================================================
// Orchestrator
// ============================================================================

export interface OrchestratorOptions {
	/** Progress callback for all phases */
	onProgress?: BenchmarkProgressCallback;
	/** Callback when a phase completes (with results including failures) */
	onPhaseComplete?: (phase: BenchmarkPhase, result: PhaseResult) => void;
	/** Whether to run evaluation phases in parallel */
	parallelEvaluation?: boolean;
	/** Abort signal for cancellation */
	abortSignal?: AbortSignal;
}

export class PipelineOrchestrator {
	private db: BenchmarkDatabase;
	private stateMachine: PipelineStateMachine;
	private config: BenchmarkConfig;
	private benchmarkRun: BenchmarkRun;
	private options: OrchestratorOptions;
	private phaseExecutors: Map<BenchmarkPhase, PhaseExecutor>;

	constructor(
		db: BenchmarkDatabase,
		benchmarkRun: BenchmarkRun,
		options: OrchestratorOptions = {},
	) {
		this.db = db;
		this.benchmarkRun = benchmarkRun;
		this.config = benchmarkRun.config;
		this.options = options;

		this.stateMachine = new PipelineStateMachine(
			db,
			benchmarkRun,
			options.onProgress,
		);
		this.phaseExecutors = new Map();
	}

	// ==========================================================================
	// Executor Registration
	// ==========================================================================

	registerExecutor(phase: BenchmarkPhase, executor: PhaseExecutor): void {
		this.phaseExecutors.set(phase, executor);
	}

	registerAllExecutors(executors: Record<BenchmarkPhase, PhaseExecutor>): void {
		for (const [phase, executor] of Object.entries(executors)) {
			this.phaseExecutors.set(phase as BenchmarkPhase, executor);
		}
	}

	// ==========================================================================
	// Execution
	// ==========================================================================

	async run(): Promise<BenchmarkReport> {
		try {
			// Start or resume the benchmark
			if (this.stateMachine.canResume()) {
				this.stateMachine.resume();
			}

			// Execute phases in order
			await this.executePhases();

			// Return final report
			return this.generateReport();
		} catch (error) {
			const wrappedError = wrapError(
				error,
				this.stateMachine.getCurrentPhase(),
			);
			this.stateMachine.fail(wrappedError.message);
			throw wrappedError;
		}
	}

	async runPhase(phase: BenchmarkPhase): Promise<PhaseResult> {
		const executor = this.phaseExecutors.get(phase);
		if (!executor) {
			throw new BenchmarkError(
				`No executor registered for phase: ${phase}`,
				"MISSING_EXECUTOR",
			);
		}

		// Validate we can run this phase
		this.stateMachine.validateTransition(
			this.stateMachine.getCurrentPhase(),
			phase,
		);

		const context: PhaseContext = {
			db: this.db,
			run: this.benchmarkRun,
			config: this.config,
			stateMachine: this.stateMachine,
		};

		try {
			const result = await executor(context);

			// If executor returned early without starting the phase (itemsProcessed=0),
			// trigger a progress notification so CLI can show "skipped"
			if (
				result.itemsProcessed === 0 &&
				!this.stateMachine.getPhaseState(phase)
			) {
				this.stateMachine.startPhase(phase, 0);
			}

			if (result.success) {
				this.stateMachine.completePhase(phase);
			} else {
				// Ensure we fail the phase even if no error message is provided
				this.stateMachine.failPhase(
					phase,
					result.error || "Phase failed without error message",
				);
			}

			// Notify about phase completion (with failures if any)
			this.options.onPhaseComplete?.(phase, result);

			return result;
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			this.stateMachine.failPhase(phase, message);
			throw error;
		}
	}

	private async executePhases(): Promise<void> {
		// Check for abort
		if (this.options.abortSignal?.aborted) {
			throw new BenchmarkError("Benchmark aborted", "ABORTED");
		}

		// Get the next phase to execute
		let nextPhase = this.stateMachine.getNextPhase();

		while (nextPhase) {
			// Check for abort before each phase
			if (this.options.abortSignal?.aborted) {
				this.stateMachine.pause();
				throw new BenchmarkError("Benchmark aborted", "ABORTED");
			}

			// Check if the benchmark has failed (don't continue after failure)
			if (this.stateMachine.getStatus() === "failed") {
				const error = this.stateMachine.getError() || "Benchmark failed";
				throw new BenchmarkError(error, "PHASE_FAILED");
			}

			// Check if we have an executor for this phase
			if (!this.phaseExecutors.has(nextPhase)) {
				// Skip phases without executors (disabled evaluations)
				this.stateMachine.startPhase(nextPhase, 0);
				this.stateMachine.completePhase(nextPhase);
				nextPhase = this.stateMachine.getNextPhase();
				continue;
			}

			// Check if we can run evaluation phases in parallel
			if (
				this.options.parallelEvaluation &&
				nextPhase.startsWith("evaluation:")
			) {
				await this.executeEvaluationPhasesParallel();
			} else {
				await this.runPhase(nextPhase);
			}

			nextPhase = this.stateMachine.getNextPhase();
		}
	}

	private async executeEvaluationPhasesParallel(): Promise<void> {
		const evaluationPhases: BenchmarkPhase[] = [
			"evaluation:judge",
			"evaluation:contrastive",
			"evaluation:retrieval",
			"evaluation:downstream",
		];

		// Filter to only enabled evaluations and those not yet complete
		const phasesToRun = evaluationPhases.filter((phase) => {
			if (this.stateMachine.isPhaseComplete(phase)) return false;

			// Check if evaluation is enabled in config
			switch (phase) {
				case "evaluation:judge":
					return this.config.evaluation.judge.enabled;
				case "evaluation:contrastive":
					return this.config.evaluation.contrastive.enabled;
				case "evaluation:retrieval":
					return this.config.evaluation.retrieval.enabled;
				case "evaluation:downstream":
					return this.config.evaluation.downstream.enabled;
				default:
					return true;
			}
		});

		if (phasesToRun.length === 0) return;

		// Run enabled phases in parallel
		const results = await Promise.allSettled(
			phasesToRun.map((phase) => this.runPhase(phase)),
		);

		// Check for failures
		const failures = results.filter(
			(r): r is PromiseRejectedResult => r.status === "rejected",
		);

		if (failures.length > 0) {
			const errors = failures.map((f) => f.reason?.message || String(f.reason));
			throw new BenchmarkError(
				`Evaluation phases failed: ${errors.join("

/**
 * Pipeline State Machine
 *
 * Manages benchmark execution state with support for:
 * - Phase transitions with validation
 * - Resumability from any phase
 * - Progress tracking
 * - Error recovery
 */

import {
	IncompletePhaseError,
	InvalidPhaseTransitionError,
	StateError,
} from "../errors.js";
import type { BenchmarkDatabase } from "../storage/benchmark-db.js";
import type {
	BenchmarkPhase,
	BenchmarkProgressCallback,
	BenchmarkRun,
	BenchmarkStatus,
} from "../types.js";

// ============================================================================
// Phase Definitions
// ============================================================================

/** Ordered list of all benchmark phases */
export const PHASES: readonly BenchmarkPhase[] = [
	"extraction",
	"generation",
	"evaluation:iterative", // Runs first to refine summaries before other evaluations
	"evaluation:judge",
	"evaluation:contrastive",
	"evaluation:retrieval",
	"evaluation:downstream",
	"evaluation:self",
	"aggregation",
	"reporting",
] as const;

/** Phase dependencies - which phases must complete before a phase can start */
export const PHASE_DEPENDENCIES: Record<BenchmarkPhase, BenchmarkPhase[]> = {
	extraction: [],
	generation: ["extraction"],
	"evaluation:iterative": ["generation"],
	"evaluation:judge": ["evaluation:iterative"], // Uses refined summaries
	"evaluation:contrastive": ["evaluation:iterative"],
	"evaluation:retrieval": ["evaluation:iterative"],
	"evaluation:downstream": ["evaluation:iterative"],
	"evaluation:self": ["evaluation:iterative"],
	aggregation: [
		"evaluation:iterative",
		"evaluation:judge",
		"evaluation:contrastive",
		"evaluation:retrieval",
		"evaluation:downstream",
		"evaluation:self",
	],
	reporting: ["aggregation"],
};

/** Human-readable phase names */
export const PHASE_NAMES: Record<BenchmarkPhase, string> = {
	extraction: "Code Extraction",
	generation: "Summary Generation",
	"evaluation:iterative": "Iterative Refinement",
	"evaluation:judge": "LLM-as-Judge Evaluation",
	"evaluation:contrastive": "Contrastive Matching",
	"evaluation:retrieval": "Retrieval Evaluation",
	"evaluation:downstream": "Downstream Tasks",
	"evaluation:self": "Self-Evaluation",
	aggregation: "Score Aggregation",
	reporting: "Report Generation",
};

// ============================================================================
// State Machine
// ============================================================================

export interface PhaseState {
	phase: BenchmarkPhase;
	total: number;
	completed: number;
	isComplete: boolean;
	error?: string;
}

export interface PipelineState {
	runId: string;
	status: BenchmarkStatus;
	currentPhase?: BenchmarkPhase;
	phases: Map<BenchmarkPhase, PhaseState>;
	startedAt: string;
	pausedAt?: string;
	completedAt?: string;
	error?: string;
}

export class PipelineStateMachine {
	private db: BenchmarkDatabase;
	private runId: string;
	private state: PipelineState;
	private progressCallback?: BenchmarkProgressCallback;

	constructor(
		db: BenchmarkDatabase,
		run: BenchmarkRun,
		progressCallback?: BenchmarkProgressCallback,
	) {
		this.db = db;
		this.runId = run.id;
		this.progressCallback = progressCallback;

		// Initialize state from run
		this.state = {
			runId: run.id,
			status: run.status,
			currentPhase: run.currentPhase,
			phases: new Map(),
			startedAt: run.startedAt,
			pausedAt: run.pausedAt,
			completedAt: run.completedAt,
			error: run.error,
		};

		// Load phase progress from database
		this.loadPhaseProgress();
	}

	private loadPhaseProgress(): void {
		for (const phase of PHASES) {
			const progress = this.db.getPhaseProgress(this.runId, phase);
			if (progress) {
				this.state.phases.set(phase, {
					phase,
					total: progress.total,
					completed: progress.completed,
					isComplete: progress.isComplete,
				});
			}
		}
	}

	// ==========================================================================
	// State Queries
	// ==========================================================================

	getState(): PipelineState {
		return { ...this.state };
	}

	getCurrentPhase(): BenchmarkPhase | undefined {
		return this.state.currentPhase;
	}

	getStatus(): BenchmarkStatus {
		return this.state.status;
	}

	getError(): string | undefined {
		return this.state.error;
	}

	getPhaseState(phase: BenchmarkPhase): PhaseState | undefined {
		return this.state.phases.get(phase);
	}

	isPhaseComplete(phase: BenchmarkPhase): boolean {
		return this.state.phases.get(phase)?.isComplete ?? false;
	}

	areAllDependenciesComplete(phase: BenchmarkPhase): boolean {
		const dependencies = PHASE_DEPENDENCIES[phase];
		return dependencies.every((dep) => this.isPhaseComplete(dep));
	}

	getNextPhase(): BenchmarkPhase | null {
		// Find the first incomplete phase whose dependencies are satisfied
		for (const phase of PHASES) {
			if (
				!this.isPhaseComplete(phase) &&
				this.areAllDependenciesComplete(phase)
			) {
				return phase;
			}
		}
		return null;
	}

	getIncompletePhases(): BenchmarkPhase[] {
		return PHASES.filter((phase) => !this.isPhaseComplete(phase));
	}

	isComplete(): boolean {
		return PHASES.every((phase) => this.isPhaseComplete(phase));
	}

	canResume(): boolean {
		return (
			this.state.status === "paused" ||
			this.state.status === "failed" ||
			this.state.status === "pending"
		);
	}

	// ==========================================================================
	// Phase Transitions
	// ==========================================================================

	startPhase(phase: BenchmarkPhase, totalItems: number): void {
		// Validate transition
		if (!this.areAllDependenciesComplete(phase)) {
			const incomplete = PHASE_DEPENDENCIES[phase].filter(
				(dep) => !this.isPhaseComplete(dep),
			);
			throw new IncompletePhaseError(
				phase,
				`Dependencies not complete: ${incomplete.join(", ")}`,
			);
		}

		// Update state
		this.state.currentPhase = phase;
		this.state.status = "running";
		this.state.phases.set(phase, {
			phase,
			total: totalItems,
			completed: 0,
			isComplete: false,
		});

		// Persist to database
		this.db.updateRunStatus(this.runId, "running", phase);
		this.db.startPhase(this.runId, phase, totalItems);

		// Notify callback
		this.notifyProgress(phase, 0, totalItems);
	}

	updateProgress(
		phase: BenchmarkPhase,
		completed: number,
		lastProcessedId?: string,
		details?: string,
	): void {
		const phaseState = this.state.phases.get(phase);
		if (!phaseState) {
			throw new StateError(`Phase ${phase} has not been started`);
		}

		phaseState.completed = completed;

		// Persist to database
		this.db.updatePhaseProgress(this.runId, phase, completed, lastProcessedId);

		// Notify callback
		this.notifyProgress(phase, completed, phaseState.total, details);
	}

	completePhase(phase: BenchmarkPhase): void {
		const phaseState = this.state.phases.get(phase);
		if (!phaseState) {
			throw new StateError(`Phase ${phase} has not been started`);
		}

		phaseState.isComplete = true;
		phaseState.completed = phaseState.total;

		// Persist to database
		this.db.completePhase(this.runId, phase);

		// Check if all phases complete
		if (this.isComplete()) {
			this.complete();
		}
	}

	failPhase(phase: BenchmarkPhase, error: string): void {
		const phaseState = this.state.phases.get(phase);
		if (phaseState) {
			phaseState.error = error;
		}

		this.state.status = "failed";
		this.state.error = error;

		// Persist to database
		this.db.updateRunStatus(this.runId, "failed", phase, error);
	}

	pause(): void {
		if (this.state.status !== "running") {
			throw new StateError(`Cannot pause: status is ${this.state.status}`);
		}

		this.state.status = "paused";
