/**
 * Markdown Reporter
 *
 * Outputs benchmark results as a Markdown document.
 * Designed for GitHub READMEs and documentation.
 */

import { writeFileSync } from "node:fs";
import { detectSameProviderBias } from "../index.js";
import type { ModelAggregation } from "../scorers/aggregator.js";
import type {
	CorrelationMatrix,
	InterRaterAgreement,
} from "../scorers/statistics.js";
import type {
	AggregatedScore,
	BenchmarkConfig,
	BenchmarkRun,
} from "../types.js";

// ============================================================================
// Markdown Reporter
// ============================================================================

export interface MarkdownReporterOptions {
	includeDetailedMetrics?: boolean;
	includeCorrelationMatrix?: boolean;
	includeCharts?: boolean; // Mermaid diagrams
}

export class MarkdownReporter {
	private options: MarkdownReporterOptions;

	constructor(options: MarkdownReporterOptions = {}) {
		this.options = {
			includeDetailedMetrics: options.includeDetailedMetrics ?? true,
			includeCorrelationMatrix: options.includeCorrelationMatrix ?? true,
			includeCharts: options.includeCharts ?? true,
		};
	}

	/**
	 * Generate Markdown report
	 */
	generate(input: {
		run: BenchmarkRun;
		config: BenchmarkConfig;
		aggregations: Map<string, ModelAggregation>;
		scores: AggregatedScore[];
		correlationMatrix?: CorrelationMatrix;
		interRaterAgreement?: InterRaterAgreement;
	}): string {
		const {
			run,
			config,
			aggregations,
			scores,
			correlationMatrix,
			interRaterAgreement,
		} = input;

		const sections: string[] = [];

		// Header
		sections.push(this.generateHeader(run));

		// Executive Summary
		sections.push(this.generateExecutiveSummary(run, scores, aggregations));

		// Rankings Table
		sections.push(this.generateRankingsTable(scores));

		// Bar Chart (Mermaid)
		if (this.options.includeCharts) {
			sections.push(this.generateBarChart(scores));
		}

		// Detailed Metrics
		if (this.options.includeDetailedMetrics) {
			sections.push(this.generateDetailedMetrics(aggregations, scores));
		}

		// Correlation Matrix
		if (this.options.includeCorrelationMatrix && correlationMatrix) {
			sections.push(this.generateCorrelationMatrix(correlationMatrix));
		}

		// Inter-Rater Agreement
		if (interRaterAgreement) {
			sections.push(this.generateInterRaterAgreement(interRaterAgreement));
		}

		// Methodology
		sections.push(
			this.generateMethodology(
				config,
				scores.map((s) => s.modelId),
			),
		);

		// Footer
		sections.push(this.generateFooter(run));

		return sections.join("\n\n");
	}

	/**
	 * Write report to file
	 */
	writeToFile(report: string, filePath: string): void {
		writeFileSync(filePath, report, "utf-8");
	}

	// ============================================================================
	// Section Generators
	// ============================================================================

	private generateHeader(run: BenchmarkRun): string {
		return `# LLM Summary Benchmark Report

**Run:** ${run.name}
**Date:** ${new Date(run.startedAt).toLocaleDateString()}
**Status:** ${run.status}`;
	}

	private generateExecutiveSummary(
		run: BenchmarkRun,
		scores: AggregatedScore[],
		aggregations: Map<string, ModelAggregation>,
	): string {
		const topModel = scores.length > 0 ? scores[0] : null;

		// Calculate totals
		let totalEvaluations = 0;
		for (const agg of aggregations.values()) {
			totalEvaluations +=
				agg.judge.pointwise.overall.count +
				agg.contrastive.embedding.count +
				agg.contrastive.llm.count;
		}

		return `## Executive Summary

| Metric | Value |
|--------|-------|
| Models Evaluated | ${scores.length} |
| Code Units | ${run.codebaseInfo?.sampledCodeUnits || "N/A"} |
| Total Evaluations | ${totalEvaluations} |
| **Top Model** | **${topModel?.modelId || "N/A"}** |
| Top Score | ${topModel ? `${(topModel.overallScore * 100).toFixed(1)}%` : "N/A"} |`;
	}

	private generateRankingsTable(scores: AggregatedScore[]): string {
		const rows = scores.map((score) => {
			const medal =
				score.rank === 1
					? "🥇"
					: score.rank === 2
						? "🥈"
						: score.rank === 3
							? "🥉"
							: "";
			return `| ${medal} ${score.rank} | ${score.modelId} | ${(score.overallScore * 100).toFixed(1)}% | ${(score.retrievalMRR * 100).toFixed(1)}% | ${(score.contrastiveAccuracy * 100).toFixed(1)}% | ${((score.judgeScore / 5) * 100).toFixed(1)}% |`;
		});

		return `## Quality Rankings

How well summaries serve LLM agents for code understanding.

| Rank | Model | Overall | Retrieval (45%) | Contrastive (30%) | Judge (25%) |
|------|-------|---------|-----------------|-------------------|-------------|
${rows.join("\n")}`;
	}

	private generateBarChart(scores: AggregatedScore[]): string {
		const bars = scores
			.slice(0, 10) // Top 10
			.map(
				(score) =>
					`    "${score.modelId.slice(-20)}" : ${Math.round(score.overallScore * 100)}`,
			);

		return `## Overall Scores

\`\`\`mermaid
xychart-beta
    title "Model Performance Comparison"
    x-axis [${scores
			.slice(0, 10)
			.map((s) => `"${s.modelId.slice(-15)}"`)
			.join(", ")}]
    y-axis "Score (%)" 0 --> 100
    bar [${scores
			.slice(0, 10)
			.map((s) => Math.round(s.overallScore * 100))
			.join(", ")}]
\`\`\``;
	}

	private generateDetailedMetrics(
		aggregations: Map<string, ModelAggregation>,
		scores: AggregatedScore[],
	): string {
		const sections: string[] = ["## Detailed Metrics"];

		// Helper to safely format stats (handles null/undefined/NaN)
		const fmt = (val: number | null | undefined): string => {
			if (val === null || val === undefined || isNaN(val)) return "N/A";
			return val.toFixed(2);
		};

		for (const score of scores.slice(0, 5)) {
			const agg = aggregations.get(score.modelId);
			if (!agg) continue;

			const pw = agg.judge.pointwise;
			sections.push(`### ${score.modelId}

**Judge Scores (1-5 scale):**
| Criterion | Mean | Std Dev | Min | Max |
|-----------|------|---------|-----|-----|
| Accuracy | ${fmt(pw.accuracy.mean)} | ${fmt(pw.accuracy.stdDev)} | ${fmt(pw.accuracy.min)} | ${fmt(pw.accuracy.max)} |
| Completeness | ${fmt(pw.completeness.mean)} | ${fmt(pw.completeness.stdDev)} | ${fmt(pw.completeness.min)} | ${fmt(pw.completeness.max)} |
| Semantic Richness | ${fmt(pw.semanticRichness.mean)} | ${fmt(pw.semanticRichness.stdDev)} | ${fmt(pw.semanticRichness.min)} | ${fmt(pw.semanticRichness.max)} |
| Abstraction | ${fmt(pw.abstraction.mean)} | ${fmt(pw.abstraction.stdDev)} | ${fmt(pw.abstraction.min)} | ${fmt(pw.abstraction.max)} |
| Conciseness | ${fmt(pw.conciseness.mean)} | ${fmt(pw.conciseness.stdDev)} | ${fmt(pw.conciseness.min)} | ${fmt(pw.conciseness.max)} |

**Pairwise Tournament:**
- Wins: ${agg.judge.pairwise.wins}
- Losses: ${agg.judge.pairwise.losses}
- Ties: ${agg.judge.pairwise.ties}
- Win Rate: ${(agg.judge.pairwise.winRate * 100).toFixed(1)}%

**Retrieval Performance:**
${Object.entries(agg.retrieval.precision)
	.map(([k, v]) => `- P@${k}: ${(v * 100).toFixed(1)}%`)
	.join("\n")}
- MRR: ${(agg.retrieval.mrr * 100).toFixed(1)}%${
				agg.iterative
					? `

**Iterative Refinement:**
- Summaries Evaluated: ${agg.iterative.totalEvaluated}
- Success Rate: ${(agg.iterative.successRate * 100).toFixed(1)}%
- Avg Rounds to Success: ${agg.iterative.avgRounds.toFixed(2)}
- Refinement Score: ${(agg.iterative.avgRefinementScore * 100).toFixed(1)}% (Brokk-style: 1/log₂(rounds+2))
- Avg Rank Improvement: ${agg.iterative.avgRankImprovement.toFixed(2)}`
					: ""
			}${
				agg.self
					? `

**Self-Evaluation (Internal Consistency):**
- Self-Retrieval Accuracy: ${(agg.self.retrieval.accuracy * 100).toFixed(1)}% (n=${agg.self.retrieval.count})
- Self-Retrieval Confidence: ${(agg.self.retrieval.avgConfidence * 100).toFixed(1)}%
- Function Selection: ${(agg.self.functionSelection.accuracy * 100).toFixed(1)}% (n=${agg.self.functionSelection.count})
- Overall Self-Use: ${(agg.self.overall * 100).toFixed(1)}%`
					: ""
			}`);
		}

		return sections.join("\n\n");
	}

/**
 * Score Aggregator
 *
 * Aggregates raw evaluation results into model-level scores.
 * Handles weighted combinations, normalization, and statistics.
 */

import {
	aggregateIterativeResults,
	type IterativeMetrics,
} from "../evaluators/iterative/index.js";
import { aggregateTournamentResults } from "../evaluators/judge/pairwise.js";
import type { AggregatedRetrievalMetrics } from "../evaluators/retrieval/index.js";
import { aggregateRetrievalResults } from "../evaluators/retrieval/index.js";
import {
	aggregateSelfEvaluationResults,
	type SelfEvaluationMetrics,
} from "../evaluators/self/index.js";
import type {
	AggregatedScore,
	BenchmarkConfig,
	EvaluationResult,
	GeneratedSummary,
	PairwiseResult,
	ScoringConfig,
} from "../types.js";

// ============================================================================
// Types
// ============================================================================

export interface AggregationInput {
	summaries: GeneratedSummary[];
	evaluationResults: EvaluationResult[];
	pairwiseResults: PairwiseResult[];
	kValues: number[];
}

export interface ModelAggregation {
	modelId: string;
	judge: JudgeAggregation;
	contrastive: ContrastiveAggregation;
	retrieval: AggregatedRetrievalMetrics;
	downstream: DownstreamAggregation;
	iterative?: IterativeMetrics; // Optional: iterative refinement performance
	self?: SelfEvaluationMetrics; // Optional: model's ability to use its own summaries
	overall: OverallScore;
}

export interface JudgeAggregation {
	pointwise: {
		accuracy: CriterionStats;
		completeness: CriterionStats;
		semanticRichness: CriterionStats;
		abstraction: CriterionStats;
		conciseness: CriterionStats;
		overall: CriterionStats;
	};
	pairwise: {
		wins: number;
		losses: number;
		ties: number;
		winRate: number;
		btScore: number;
	};
}

export interface ContrastiveAggregation {
	embedding: {
		accuracy: number;
		count: number;
	};
	llm: {
		accuracy: number;
		count: number;
	};
	combined: number;
}

export interface DownstreamAggregation {
	completion: {
		bleuScore: number;
		exactMatch: number;
		count: number;
	};
	bugLocalization: {
		accuracy: number;
		count: number;
	};
	functionSelection: {
		accuracy: number;
		count: number;
	};
	overall: number;
}

export interface CriterionStats {
	mean: number;
	median: number;
	stdDev: number;
	min: number;
	max: number;
	count: number;
}

export interface OverallScore {
	score: number;
	rank: number;
	confidence: number;
}

// ============================================================================
// Score Aggregator
// ============================================================================

export class ScoreAggregator {
	private scoringConfig: ScoringConfig;

	constructor(config: BenchmarkConfig) {
		this.scoringConfig = config.weights;
	}

	/**
	 * Aggregate all evaluation results into model scores
	 */
	aggregate(input: AggregationInput): Map<string, ModelAggregation> {
		const { summaries, evaluationResults, pairwiseResults, kValues } = input;

		// Group by model
		const modelIds = [...new Set(summaries.map((s) => s.modelId))];
		const resultsByModel = new Map<string, EvaluationResult[]>();
		const summariesByModel = new Map<string, GeneratedSummary[]>();

		for (const modelId of modelIds) {
			const modelSummaryIds = new Set(
				summaries.filter((s) => s.modelId === modelId).map((s) => s.id),
			);

			resultsByModel.set(
				modelId,
				evaluationResults.filter((r) => modelSummaryIds.has(r.summaryId)),
			);

			summariesByModel.set(
				modelId,
				summaries.filter((s) => s.modelId === modelId),
			);
		}

		// Calculate pairwise tournament scores ONCE with ALL models
		// (must be done before per-model aggregation)
		const tournamentScores = aggregateTournamentResults(
			pairwiseResults,
			modelIds,
		);

		// Aggregate each model
		const aggregations = new Map<string, ModelAggregation>();

		for (const modelId of modelIds) {
			const modelResults = resultsByModel.get(modelId) || [];

			// Aggregate self-evaluation (if present)
			const selfMetrics = aggregateSelfEvaluationResults(
				evaluationResults,
				modelId,
			);
			const hasSelfResults =
				selfMetrics.retrieval.count > 0 ||
				selfMetrics.functionSelection.count > 0;

			// Aggregate iterative refinement (if present)
			const iterativeMetrics = aggregateIterativeResults(
				evaluationResults,
				modelId,
			);
			const hasIterativeResults = iterativeMetrics.totalEvaluated > 0;

			aggregations.set(modelId, {
				modelId,
				judge: this.aggregateJudge(modelResults, tournamentScores, modelId),
				contrastive: this.aggregateContrastive(modelResults),
				retrieval: this.aggregateRetrieval(modelResults, kValues),
				downstream: this.aggregateDownstream(modelResults),
				iterative: hasIterativeResults ? iterativeMetrics : undefined,
				self: hasSelfResults ? selfMetrics : undefined,
				overall: { score: 0, rank: 0, confidence: 0 }, // Calculated after all models
			});
		}

		// Calculate overall scores and rankings
		this.calculateOverallScores(aggregations);

		return aggregations;
	}

	/**
	 * Convert aggregations to final scores for storage
	 */
	toAggregatedScores(
		aggregations: Map<string, ModelAggregation>,
	): AggregatedScore[] {
		const scores: AggregatedScore[] = [];

		for (const [modelId, agg] of aggregations) {
			scores.push({
				modelId,
				judgeScore: agg.judge.pointwise.overall.mean,
				contrastiveAccuracy: agg.contrastive.combined,
				retrievalMRR: agg.retrieval.mrr,
				retrievalPrecision: agg.retrieval.precision,
				downstreamScore: agg.downstream.overall,
				overallScore: agg.overall.score,
				rank: agg.overall.rank,
			});
		}

		return scores.sort((a, b) => a.rank - b.rank);
	}

