import type { PhaseContext, PhaseResult } from "../pipeline/orchestrator.js";
import type { NormalizedScores } from "../types.js";
import { createScoreAggregator } from "./aggregator.js";

/**
 * Create the scoring phase executor
 */
export function createScoringPhaseExecutor(): (
	context: PhaseContext,
) => Promise<PhaseResult> {
	return async (context: PhaseContext): Promise<PhaseResult> => {
		const { db, run, config, stateMachine } = context;

		try {
			// Count models for progress tracking
			const summaries = db.getSummaries(run.id);
			const modelIds = new Set(summaries.map((s) => s.modelId));
			const totalSteps = modelIds.size + 1; // +1 for final save

			stateMachine.startPhase("aggregation", totalSteps);
			stateMachine.updateProgress(
				"aggregation",
				0,
				undefined,
				"Loading evaluation results...",
			);

			// Get all data
			const evaluationResults = db.getEvaluationResults(run.id);
			const pairwiseResults = db.getPairwiseResults(run.id);

			stateMachine.updateProgress(
				"aggregation",
				0,
				undefined,
				"Aggregating scores...",
			);

			// Aggregate scores
			const aggregator = createScoreAggregator(config);
			const aggregations = aggregator.aggregate({
				summaries,
				evaluationResults,
				pairwiseResults,
				kValues: config.evaluation.retrieval.kValues,
			});

			// Save normalized scores to database
			let savedCount = 0;
			for (const [modelId, agg] of aggregations) {
				const normalizedScores: NormalizedScores = {
					modelId,
					judge: {
						pointwise: agg.judge.pointwise.overall.mean / 5,
						pairwise: agg.judge.pairwise.btScore,
						combined:
							(agg.judge.pointwise.overall.mean / 5 +
								agg.judge.pairwise.btScore) /
							2,
					},
					contrastive: {
						embedding: agg.contrastive.embedding.accuracy,
						llm: agg.contrastive.llm.accuracy,
						combined: agg.contrastive.combined,
					},
					retrieval: {
						precision1: agg.retrieval.precision[1] || 0,
						precision5: agg.retrieval.precision[5] || 0,
						mrr: agg.retrieval.mrr,
						winRate: agg.retrieval.winRate,
						// Use win rate as primary metric (cross-model competition)
						// Falls back to MRR if win rate not available (single model run)
						combined:
							agg.retrieval.winRate > 0
								? agg.retrieval.winRate
								: agg.retrieval.mrr,
					},
					downstream: {
						completion: agg.downstream.completion.bleuScore,
						bugLocalization: agg.downstream.bugLocalization.accuracy,
						functionSelection: agg.downstream.functionSelection.accuracy,
						combined: agg.downstream.overall,
					},
					overall: agg.overall.score,
					// Operational metrics (don't affect quality ranking)
					iterative: agg.iterative
						? {
								avgRounds: agg.iterative.avgRounds,
								successRate: agg.iterative.successRate,
								avgRefinementScore: agg.iterative.avgRefinementScore,
							}
						: undefined,
					self: agg.self
						? {
								overall: agg.self.overall,
								retrieval: agg.self.retrieval.accuracy,
								functionSelection: agg.self.functionSelection.accuracy,
							}
						: undefined,
				};
				db.saveAggregatedScores(run.id, modelId, normalizedScores);
				savedCount++;
				stateMachine.updateProgress(
					"aggregation",
					savedCount,
					modelId,
					`Saved ${modelId}`,
				);
			}

			stateMachine.updateProgress(
				"aggregation",
				totalSteps,
				"complete",
				"Scoring complete",
			);

			return {
				success: true,
				itemsProcessed: aggregations.size,
			};
		} catch (error) {
			const message = error instanceof Error ? error.message : String(error);
			return {
				success: false,
				itemsProcessed: 0,
				error: message,
			};
		}
	};
}

/**
 * Score Normalizer
 *
 * Normalizes raw scores to comparable scales.
 * Supports min-max normalization, z-score normalization, and percentile ranking.
 */

import type { AggregatedScore } from "../types.js";

// ============================================================================
// Types
// ============================================================================

export type NormalizationMethod = "min-max" | "z-score" | "percentile";

export interface NormalizationOptions {
	method: NormalizationMethod;
	targetMin?: number; // For min-max, default 0
	targetMax?: number; // For min-max, default 1
}

export interface NormalizedScores {
	modelId: string;
	judgeScore: number;
	contrastiveAccuracy: number;
	retrievalMRR: number;
	downstreamScore: number;
	overallScore: number;
	originalRank: number;
	normalizedRank: number;
}

// ============================================================================
// Score Normalizer
// ============================================================================

export class ScoreNormalizer {
	private options: NormalizationOptions;

	constructor(options: Partial<NormalizationOptions> = {}) {
		this.options = {
			method: options.method || "min-max",
			targetMin: options.targetMin ?? 0,
			targetMax: options.targetMax ?? 1,
		};
	}

	/**
	 * Normalize all scores across models
	 */
	normalize(scores: AggregatedScore[]): NormalizedScores[] {
		if (scores.length === 0) return [];

		// Extract score arrays for each metric
		const judgeScores = scores.map((s) => s.judgeScore);
		const contrastiveScores = scores.map((s) => s.contrastiveAccuracy);
		const retrievalScores = scores.map((s) => s.retrievalMRR);
		const downstreamScores = scores.map((s) => s.downstreamScore);
		const overallScores = scores.map((s) => s.overallScore);

		// Normalize each metric
		const normalizedJudge = this.normalizeArray(judgeScores);
		const normalizedContrastive = this.normalizeArray(contrastiveScores);
		const normalizedRetrieval = this.normalizeArray(retrievalScores);
		const normalizedDownstream = this.normalizeArray(downstreamScores);
		const normalizedOverall = this.normalizeArray(overallScores);

		// Build result
		const results: NormalizedScores[] = scores.map((score, i) => ({
			modelId: score.modelId,
			judgeScore: normalizedJudge[i],
			contrastiveAccuracy: normalizedContrastive[i],
			retrievalMRR: normalizedRetrieval[i],
			downstreamScore: normalizedDownstream[i],
			overallScore: normalizedOverall[i],
			originalRank: score.rank,
			normalizedRank: 0, // Calculated below
		}));

		// Calculate normalized rankings
		const sortedByNormalizedScore = [...results].sort(
			(a, b) => b.overallScore - a.overallScore,
		);
		sortedByNormalizedScore.forEach((result, index) => {
			result.normalizedRank = index + 1;
		});

		return results;
	}

	/**
	 * Normalize a single array of values
	 */
	normalizeArray(values: number[]): number[] {
		switch (this.options.method) {
			case "min-max":
				return this.minMaxNormalize(values);
			case "z-score":
				return this.zScoreNormalize(values);
			case "percentile":
				return this.percentileNormalize(values);
			default:
				return this.minMaxNormalize(values);
		}
	}

	/**
	 * Min-max normalization: scale to [targetMin, targetMax]
	 */
	private minMaxNormalize(values: number[]): number[] {
		if (values.length === 0) return [];
		if (values.length === 1) return [this.options.targetMax!];

		const min = Math.min(...values);
		const max = Math.max(...values);
		const range = max - min;

		if (range === 0) {
			// All values are the same
			return values.map(
				() => (this.options.targetMin! + this.options.targetMax!) / 2,
			);
		}

		const targetRange = this.options.targetMax! - this.options.targetMin!;

		return values.map(
			(v) => this.options.targetMin! + ((v - min) / range) * targetRange,
		);
	}

	/**
	 * Z-score normalization: (value - mean) / stdDev
	 */
	private zScoreNormalize(values: number[]): number[] {
		if (values.length === 0) return [];
		if (values.length === 1) return [0];

		const mean = values.reduce((a, b) => a + b, 0) / values.length;
		const squaredDiffs = values.map((v) => (v - mean) ** 2);
		const variance = squaredDiffs.reduce((a, b) => a + b, 0) / values.length;
		const stdDev = Math.sqrt(variance);

		if (stdDev === 0) {
			return values.map(() => 0);
		}

		return values.map((v) => (v - mean) / stdDev);
	}

	/**
	 * Percentile normalization: rank-based percentile
	 */
	private percentileNormalize(values: number[]): number[] {
		if (values.length === 0) return [];
		if (values.length === 1) return [1];

		// Create sorted indices
		const indexed = values.map((v, i) => ({ value: v, index: i }));
		indexed.sort((a, b) => a.value - b.value);

		// Assign percentiles
		const result = new Array(values.length);
		indexed.forEach((item, rank) => {
			result[item.index] = (rank + 1) / values.length;
		});

		return result;
	}
}

