	for (const s of summaries) {
		console.log(`  ${s.modelId}: "${s.summary}"`);
	}
	console.log();

	// Generate a test query
	const query = "function add numbers typescript";
	console.log(`Test query: "${query}"\n`);

	// Embed everything
	console.log("Embedding summaries and query...");
	const [summaryEmbeddings, queryEmbedding] = await Promise.all([
		embeddingsClient.embed(summaries.map((s) => s.summary)),
		embeddingsClient.embedOne(query),
	]);
	console.log("Done.\n");

	// For each summary, calculate its rank against competitors
	for (let i = 0; i < summaries.length; i++) {
		const testSummary = summaries[i];
		const competitors = summaries.filter((_, j) => j !== i);

		console.log(`=== Testing ${testSummary.modelId}'s summary ===`);
		console.log(`Competitors: ${competitors.map((c) => c.modelId).join(", ")}`);

		const totalCandidates = competitors.length + 1;
		console.log(`Total candidates: ${totalCandidates}`);

		// Calculate target rank adjustment
		const configuredTargetRank = 3;
		const effectiveTargetRank = Math.min(
			configuredTargetRank,
			Math.max(1, Math.ceil(totalCandidates * 0.5)),
		);
		console.log(`Configured targetRank: ${configuredTargetRank}`);
		console.log(`Effective targetRank: ${effectiveTargetRank}`);

		// Calculate similarities
		const testSimilarity = cosineSimilarity(
			queryEmbedding,
			summaryEmbeddings.embeddings[i],
		);
		console.log(`Test summary similarity: ${testSimilarity.toFixed(4)}`);

		const allSimilarities: Array<{
			modelId: string;
			similarity: number;
			isTest: boolean;
		}> = [
			{
				modelId: testSummary.modelId,
				similarity: testSimilarity,
				isTest: true,
			},
		];

		for (let j = 0; j < competitors.length; j++) {
			const compIndex = summaries.findIndex(
				(s) => s.modelId === competitors[j].modelId,
			);
			const compSimilarity = cosineSimilarity(
				queryEmbedding,
				summaryEmbeddings.embeddings[compIndex],
			);
			allSimilarities.push({
				modelId: competitors[j].modelId,
				similarity: compSimilarity,
				isTest: false,
			});
			console.log(
				`Competitor ${competitors[j].modelId} similarity: ${compSimilarity.toFixed(4)}`,
			);
		}

		// Sort by similarity (descending)
		allSimilarities.sort((a, b) => b.similarity - a.similarity);
		console.log("\nRanking:");
		allSimilarities.forEach((s, idx) => {
			const marker = s.isTest ? " <-- TEST" : "";
			console.log(
				`  #${idx + 1}: ${s.modelId} (${s.similarity.toFixed(4)})${marker}`,
			);
		});

		// Find rank of test summary
		const rank = allSimilarities.findIndex((s) => s.isTest) + 1;
		const passed = rank <= effectiveTargetRank;

		console.log(`\nResult: Rank ${rank}, Passed: ${passed}`);
		if (!passed) {
			console.log(
				`  → Would trigger refinement (rank ${rank} > target ${effectiveTargetRank})`,
			);
		} else {
			console.log(
				`  → Passes without refinement (rank ${rank} <= target ${effectiveTargetRank})`,
			);
		}
		console.log();
	}

	// Now check if BOTH models could pass simultaneously
	// (This would mean 0 rounds for both, which is what we're seeing)
	console.log("=== ANALYSIS ===");
	console.log(
		"If both models' summaries rank #1 when tested against each other,",
	);
	console.log("then both would pass without refinement → 0.0 rnd for both.");
	console.log("\nThis can happen if:");
	console.log(
		"  1. Embeddings are very similar (both summaries semantically equivalent)",
	);
	console.log(
		"  2. Query favors one model consistently but we test each separately",
	);
	console.log(
		"\nThe fix should work IF rank > effectiveTargetRank for some summaries.",
	);
}

testIterativeLogic().catch(console.error);

/**
 * Benchmark V2 Types
 *
 * Complete type definitions for the LLM code summary evaluation benchmark.
 * Implements the 4-phase evaluation pipeline:
 *   Phase 1: Extraction (code units from codebase)
 *   Phase 2: Generation (summaries from each model)
 *   Phase 3: Evaluation (Judge, Contrastive, Retrieval, Downstream)
 *   Phase 4: Aggregation & Reporting
 */

import type { CodeChunk } from "../types.js";

// ============================================================================
// Code Unit Types (Phase 1: Extraction)
// ============================================================================

/** Types of code units that can be benchmarked */
export type CodeUnitType = "function" | "class" | "method" | "file" | "module";

/** Parameter definition from AST */
export interface Parameter {
	name: string;
	type?: string;
	description?: string;
	optional: boolean;
	defaultValue?: string;
}

/** AST-derived metadata for a code unit */
export interface CodeUnitMetadata {
	startLine: number;
	endLine: number;
	signature?: string;
	parameters?: Parameter[];
	returnType?: string;
	visibility?: "public" | "private" | "protected";
	decorators?: string[];
	dependencies: string[];
	exports?: string[];
	complexity?: number;
	isAsync?: boolean;
}

/** Relationships extracted from AST */
export interface CodeUnitRelationships {
	parentId?: string;
	childIds: string[];
	callsIds: string[];
	calledByIds: string[];
}

/**
 * A code unit represents a single extractable piece of code
 * (function, class, method, or file) that will be summarized.
 *
 * Note: We extend CodeChunk from the main codebase where applicable,
 * but add benchmark-specific fields for full spec compliance.
 */
export interface BenchmarkCodeUnit {
	/** Unique identifier (hash of content + path) */
	id: string;
	/** File path relative to repo root */
	path: string;
	/** Function/class/file name */
	name: string;
	/** Type of code unit */
	type: CodeUnitType;
	/** Programming language */
	language: string;
	/** The actual code content */
	content: string;
	/** AST-derived metadata */
	metadata: CodeUnitMetadata;
	/** Relationships from AST */
	relationships: CodeUnitRelationships;
	/** Original CodeChunk reference (for reusing existing infrastructure) */
	sourceChunk?: CodeChunk;
}

// ============================================================================
// Generated Summary Types (Phase 2: Generation)
// ============================================================================

/** Metadata about how a summary was generated */
export interface GenerationMetadata {
	modelName: string;
	modelVersion: string;
	promptVersion: string;
	temperature: number;
	maxTokens: number;
	generatedAt: string;
	latencyMs: number;
	inputTokens: number;
	outputTokens: number;
	cost?: number;
}

/** A summary generated by an LLM for a code unit */
export interface GeneratedSummary {
	/** Unique identifier */
	id: string;
	/** Reference to the code unit */
	codeUnitId: string;
	/** Which model generated this */
	modelId: string;
	/** The generated summary text */
	summary: string;
	/** Generation metadata */
	generationMetadata: GenerationMetadata;
}

// ============================================================================
// Evaluation Result Types (Phase 3: Evaluation)
// ============================================================================

/** Types of evaluations supported */
export type EvaluationType =
	| "judge"
	| "contrastive"
	| "retrieval"
	| "downstream"
	| "self"
	| "iterative";

/** Scores from judge evaluation (1-5 scale) */
export interface JudgeScores {
	accuracy: number;
	completeness: number;
	semanticRichness: number;
	abstraction: number;
	conciseness: number;
}

/** Results from LLM-as-Judge evaluation */
export interface JudgeResults {
	judgeModelId: string;
	scores: JudgeScores;
	reasoning: string;
	weightedAverage: number;
	pairwiseWins?: number;
	pairwiseLosses?: number;
	pairwiseTies?: number;
	/** Cost of this judge evaluation in USD */
	cost?: number;
}

/** Method used for contrastive matching */
export type ContrastiveMethod = "embedding" | "llm";

/** Results from contrastive matching evaluation */
export interface ContrastiveResults {
	correct: boolean;
	predictedRank: number;
	distractorIds: string[];
	method: ContrastiveMethod;
	confidenceGap?: number;
	embeddingModel?: string;
	llmModel?: string;
}

/** Results from retrieval evaluation */
export interface RetrievalResults {
	queryId: string;
	queryType: string;
	query: string;
	hitAtK: Record<number, boolean>;
	reciprocalRank: number;
	retrievedRank: number | null;
	// Cross-model competition fields (optional for backward compatibility)
	/** Rank among models (1 = this model's summary ranked highest) */
	modelRank?: number;
	/** Total number of models competing */
	totalModels?: number;
	/** Did this model win (rank #1 among models)? */
	isWinner?: boolean;
	/** Total items in the combined index */
	poolSize?: number;
	/** Which embedding model was used for this retrieval (multi-model comparison) */
	embeddingModelId?: string;
}

/** Downstream task types */
export type DownstreamTaskType =
	| "completion"
	| "bug_localization"
	| "function_selection";

/** Results from downstream task evaluation */
export interface DownstreamResults {
	taskType: DownstreamTaskType;
	taskId: string;
	success: boolean;
	partialScore?: number;
	bleuScore?: number;
	details?: Record<string, unknown>;
}

/** Self-evaluation task types */
export type SelfEvalTaskType =
	| "retrieval"
	| "completion"
	| "function_selection";

/** Results from self-evaluation (model uses its own summaries) */
export interface SelfEvaluationResults {
	/** The generating model that was tested */
	generatingModelId: string;
	/** Type of self-evaluation task */
	taskType: SelfEvalTaskType;
	/** For retrieval: did the model find the right code using its own summary? */
	retrievalResults?: {
		queryId: string;
		query: string;
		/** Did the model correctly identify the source code from its summary? */
		correct: boolean;
		/** Confidence score (0-1) from the model */
		confidence: number;
		/** Model's reasoning for its choice */
		reasoning?: string;
	};
	/** For completion: could the model complete code using its own summary? */
	completionResults?: {
		taskId: string;
		/** BLEU score of completion */
		bleuScore: number;
		/** Did it pass tests? */
		passedTests: boolean;
		/** Model's generated completion */
		completion: string;
	};
	/** For function selection: could the model pick the right function using its summary? */
	functionSelectionResults?: {
		taskId: string;
		/** Did it select the correct function? */
		correct: boolean;
		/** Which function was selected */
		selectedFunction: string;
		/** Model's reasoning */
		reasoning?: string;
	};
}

/** Results from iterative refinement evaluation */
export interface IterativeResults {
	/** The model that generated the summary */
	modelId: string;
	/** Code unit this summary is for */
	codeUnitId: string;
	/** Number of refinement rounds executed (0 = initial was good) */
	rounds: number;
	/** Whether target rank was achieved */
	success: boolean;
	/** Initial summary quality rank */
	initialRank: number | null;
	/** Final summary quality rank */
	finalRank: number | null;
	/** Brokk-style score: 1.0 / log2(rounds + 2) */
	refinementScore: number;
	/** History of all refinement attempts */
	history: Array<{
		round: number;
		rank: number | null;
		passed: boolean;
		summary?: string;
	}>;
	/** Strategy used for quality testing */
	strategyName: string;
	/** The final refined summary (if different from original) */
	refinedSummary?: string;
	/** Total time spent on refinement */
	durationMs: number;
}

/** Complete evaluation result for a summary */
export interface EvaluationResult {
	id: string;
	summaryId: string;
	evaluationType: EvaluationType;
	judgeResults?: JudgeResults;
	contrastiveResults?: ContrastiveResults;
	retrievalResults?: RetrievalResults;
	downstreamResults?: Do

