import { FileSummaryExtractor } from "../../core/enrichment/extractors/file-summary.js";
import { SymbolSummaryExtractor } from "../../core/enrichment/extractors/symbol-summary.js";
import type {
	CodeChunk,
	FileSummary,
	ILLMClient,
	SymbolSummary,
} from "../../types.js";
import type {
	GenerationResult,
	GeneratorInfo,
	ISummaryGenerator,
	UsageStats,
} from "../types.js";

// ============================================================================
// Summary Generator Implementation
// ============================================================================

/**
 * Summary generator that wraps existing extractors.
 * Tracks timing and usage for benchmark purposes.
 */
export class SummaryGenerator implements ISummaryGenerator {
	private llmClient: ILLMClient;
	private info: GeneratorInfo;
	private fileSummaryExtractor: FileSummaryExtractor;
	private symbolSummaryExtractor: SymbolSummaryExtractor;
	private accumulatedUsage: UsageStats;

	constructor(llmClient: ILLMClient, info: GeneratorInfo) {
		this.llmClient = llmClient;
		this.info = info;
		this.fileSummaryExtractor = new FileSummaryExtractor();
		this.symbolSummaryExtractor = new SymbolSummaryExtractor();
		this.accumulatedUsage = {
			inputTokens: 0,
			outputTokens: 0,
			cost: 0,
			calls: 0,
		};
	}

	async generateFileSummary(
		filePath: string,
		fileContent: string,
		language: string,
		codeChunks: CodeChunk[],
	): Promise<GenerationResult<FileSummary>> {
		// Reset LLM client usage tracking
		this.llmClient.resetAccumulatedUsage();
		const startTime = Date.now();

		try {
			// Use existing extractor
			const docs = await this.fileSummaryExtractor.extract(
				{
					filePath,
					fileContent,
					language,
					codeChunks,
					projectPath: "",
				},
				this.llmClient,
			);

			const durationMs = Date.now() - startTime;
			const usage = this.llmClient.getAccumulatedUsage();

			// Accumulate stats
			this.accumulateUsage(usage);

			if (docs.length === 0) {
				throw new Error("No file summary generated");
			}

			const result = docs[0] as FileSummary;

			return {
				result,
				durationMs,
				usage: {
					inputTokens: usage.inputTokens,
					outputTokens: usage.outputTokens,
					cost: usage.cost,
				},
			};
		} catch (error) {
			const durationMs = Date.now() - startTime;
			const usage = this.llmClient.getAccumulatedUsage();
			this.accumulateUsage(usage);

			throw new Error(
				`Failed to generate file summary for ${filePath}: ${
					error instanceof Error ? error.message : String(error)
				}`,
			);
		}
	}

	async generateSymbolSummary(
		chunk: CodeChunk,
		fileContent: string,
		language: string,
	): Promise<GenerationResult<SymbolSummary>> {
		// Reset LLM client usage tracking
		this.llmClient.resetAccumulatedUsage();
		const startTime = Date.now();

		try {
			// Use existing extractor with single chunk
			const docs = await this.symbolSummaryExtractor.extract(
				{
					filePath: chunk.filePath,
					fileContent,
					language,
					codeChunks: [chunk],
					projectPath: "",
				},
				this.llmClient,
			);

			const durationMs = Date.now() - startTime;
			const usage = this.llmClient.getAccumulatedUsage();

			// Accumulate stats
			this.accumulateUsage(usage);

			if (docs.length === 0) {
				throw new Error(`No symbol summary generated for ${chunk.name}`);
			}

			const result = docs[0] as SymbolSummary;

			return {
				result,
				durationMs,
				usage: {
					inputTokens: usage.inputTokens,
					outputTokens: usage.outputTokens,
					cost: usage.cost,
				},
			};
		} catch (error) {
			const durationMs = Date.now() - startTime;
			const usage = this.llmClient.getAccumulatedUsage();
			this.accumulateUsage(usage);

			throw new Error(
				`Failed to generate symbol summary for ${chunk.name}: ${
					error instanceof Error ? error.message : String(error)
				}`,
			);
		}
	}

	getInfo(): GeneratorInfo {
		return { ...this.info };
	}

	getUsage(): UsageStats {
		return { ...this.accumulatedUsage };
	}

	resetUsage(): void {
		this.accumulatedUsage = {
			inputTokens: 0,
			outputTokens: 0,
			cost: 0,
			calls: 0,
		};
	}

	private accumulateUsage(usage: {
		inputTokens: number;
		outputTokens: number;
		cost: number;
		calls: number;
	}): void {
		this.accumulatedUsage.inputTokens += usage.inputTokens;
		this.accumulatedUsage.outputTokens += usage.outputTokens;
		this.accumulatedUsage.cost += usage.cost;
		this.accumulatedUsage.calls += usage.calls;
	}
}

/**
 * Batch Summary Generator
 *
 * Special generator for Anthropic Batch API that queues all requests
 * and submits them as a single batch for processing.
 *
 * 50% cheaper than regular API, ideal for benchmarks.
 */

import type { AnthropicBatchLLMClient } from "../../llm/providers/anthropic-batch.js";
import type { CodeChunk, FileSummary, SymbolSummary } from "../../types.js";
import type {
	GenerationResult,
	GeneratorInfo,
	ISummaryGenerator,
	UsageStats,
} from "../types.js";

// ============================================================================
// Types
// ============================================================================

interface QueuedRequest {
	type: "file" | "symbol";
	id: string;
	prompt: string;
	systemPrompt: string;
	startTime: number;
	// For file summaries
	filePath?: string;
	fileContent?: string;
	language?: string;
	codeChunks?: CodeChunk[];
	// For symbol summaries
	chunk?: CodeChunk;
	// Promise resolution
	resolve: (result: GenerationResult<FileSummary | SymbolSummary>) => void;
	reject: (error: Error) => void;
}

// ============================================================================
// Batch Summary Generator
// ============================================================================

export class BatchSummaryGenerator implements ISummaryGenerator {
	private batchClient: AnthropicBatchLLMClient;
	private info: GeneratorInfo;
	private accumulatedUsage: UsageStats;
	private requestQueue: Map<string, QueuedRequest> = new Map();
	private requestCounter = 0;

	/** Flag to identify this as a batch generator */
	readonly isBatch = true;

	constructor(batchClient: AnthropicBatchLLMClient, info: GeneratorInfo) {
		this.batchClient = batchClient;
		this.info = info;
		this.accumulatedUsage = {
			inputTokens: 0,
			outputTokens: 0,
			cost: 0,
			calls: 0,
		};
	}

	/**
	 * Queue a file summary request.
	 * Returns a promise that resolves when flushBatch() completes.
	 */
	async generateFileSummary(
		filePath: string,
		fileContent: string,
		language: string,
		codeChunks: CodeChunk[],
	): Promise<GenerationResult<FileSummary>> {
		return new Promise((resolve, reject) => {
			const id = `file_${this.requestCounter++}`;
			const startTime = Date.now();

			// Build prompt using same format as FileSummaryExtractor
			const { systemPrompt, userPrompt } = this.buildFileSummaryPrompt(
				filePath,
				fileContent,
				language,
				codeChunks,
			);

			this.requestQueue.set(id, {
				type: "file",
				id,
				prompt: userPrompt,
				systemPrompt,
				startTime,
				filePath,
				fileContent,
				language,
				codeChunks,
				resolve: resolve as (
					result: GenerationResult<FileSummary | SymbolSummary>,
				) => void,
				reject,
			});
		});
	}

	/**
	 * Queue a symbol summary request.
	 * Returns a promise that resolves when flushBatch() completes.
	 */
	async generateSymbolSummary(
		chunk: CodeChunk,
		fileContent: string,
		language: string,
	): Promise<GenerationResult<SymbolSummary>> {
		return new Promise((resolve, reject) => {
			const id = `symbol_${this.requestCounter++}`;
			const startTime = Date.now();

			// Build prompt using same format as SymbolSummaryExtractor
			const { systemPrompt, userPrompt } = this.buildSymbolSummaryPrompt(
				chunk,
				fileContent,
				language,
			);

			this.requestQueue.set(id, {
				type: "symbol",
				id,
				prompt: userPrompt,
				systemPrompt,
				startTime,
				chunk,
				resolve: resolve as (
					result: GenerationResult<FileSummary | SymbolSummary>,
				) => void,
				reject,
			});
		});
	}

	/**
	 * Get the number of queued requests.
	 */
	getQueueSize(): number {
		return this.requestQueue.size;
	}

	/**
	 * Submit all queued requests as a batch and wait for results.
	 * This resolves all the promises returned by generateFileSummary/generateSymbolSummary.
	 */
	async flushBatch(): Promise<void> {
		if (this.requestQueue.size === 0) {
			return;
		}

		// Submit all requests to the batch client
		const requestPromises: Array<Promise<void>> = [];
		const requestMap = new Map<string, QueuedRequest>();

		for (const [id, request] of this.requestQueue) {
			requestMap.set(id, request);

			// Queue the request in the batch client
			const clientPromise = this.batchClient
				.complete([{ role: "user", content: request.prompt }], {
					systemPrompt: request.systemPrompt,
					maxTokens: 4096,
				})
				.then((response) => {
					const durationMs = Date.now() - request.startTime;

					try {
						// Parse the JSON response
						let content = response.content.trim();
						if (content.startsWith("```json")) {
							content = content.slice(7);
						} else if (content.startsWith("```")) {
							content = content.slice(3);
						}
						if (content.endsWith("```")) {
							content = content.slice(0, -3);
						}
						content = content.trim();

						const parsed = JSON.parse(content);

						// Build the result
						const result: GenerationResult<FileSummary | SymbolSummary> = {
							result:
								request.type === "file"
									? this.parseFileSummaryResponse(parsed, request)
									: this.parseSymbolSummaryResponse(parsed, request),
							durationMs,
							usage: {
								inputTokens: response.usage?.inputTokens || 0,
								outputTokens: response.usage?.outputTokens || 0,
								cost: response.usage?.cost || 0,
							},
						};

						// Accumulate usage
						this.accumulateUsage(result.usage);

						request.resolve(result);
					} catch (parseError) {
						request.reject(
							new Error(
								`Failed to parse response: ${parseError instanceof Error ? parseError.message : String(parseError)}`,
							),
						);
					}
				})
				.catch((error) => {
					request.reject(
						error instanceof Error ? error : new Error(String(error)),
					);
				});

			requestPromises.push(clientPromise as Promise<void>);
		}

		// Flush the batch client (this submits to API and waits for results)
		await this.batchClient.flushBatch();

		// Wait for all promise handlers to complete
		await Promise.allSettled(requestPromises);

		// Clear the queue
		this.requestQueue.clear();
	}

	getInfo(): GeneratorInfo {
		return { ...this.info };
	}

	getUsage(): UsageStats {
		return { ...this.accumulatedUsage };
	}

	resetUsage(): void {
		this.accumulatedUsage = {
			inputTokens: 0,
			outputTokens: 0,
			cost: 0,
			calls: 0,
		};
		this.requestQueue.clear();
		this.requestCounter = 0;
	}

	private accumulateUsage(usage: {
		inputTokens: number;
		outputTokens: number;
		cost: number;
	}): void {
		this.accumulatedUsage.inputTokens += usage.inputTokens;
		this.accumulatedUsage.outputTokens += usage.outputTokens;
		this.accumulatedUsage.cost += usage.cost;
		this.accumulatedUsage.calls += 1;
	}

	// ============================================================================
	// Prompt Building (matching extractors)
	// ============================================================================

	private buildFileSummaryPrompt(
		filePath: string,
		fileContent: string,
		language: string,
		codeChunks: CodeChunk[],
	): { systemPrompt: string; userPrompt: string } {
		const systemPrompt = `You are a code documentation expert. Analyze the provided source file and generate a comprehensive summary.

