/**
 * Blind Judge
 *
 * Wrapper that ensures the judge cannot see which model generated the summary.
 * This helps prevent bias in evaluation.
 *
 * Note: In practice, the LLM judge doesn't know which model generated the summary
 * anyway (we don't include that in the prompt). This wrapper is primarily useful
 * for batch evaluation where we want to randomize the order of candidates.
 */

import type { FileSummary, SymbolSummary } from "../../types.js";
import type {
	IJudge,
	JudgeContext,
	JudgeInfo,
	JudgmentResult,
} from "../types.js";

// ============================================================================
// Blind Judge Implementation
// ============================================================================

export class BlindJudge implements IJudge {
	private innerJudge: IJudge;

	constructor(innerJudge: IJudge) {
		this.innerJudge = innerJudge;
	}

	async judge(
		generated: FileSummary | SymbolSummary,
		context: JudgeContext,
	): Promise<JudgmentResult> {
		// Create a copy of the summary without any identifying information
		const anonymizedSummary = this.anonymize(generated);

		// Create a copy of the context without any identifying information
		const anonymizedContext: JudgeContext = {
			...context,
			// Remove file path from context to prevent bias based on file name
			filePath: "source_file",
		};

		// Delegate to inner judge
		const result = await this.innerJudge.judge(
			anonymizedSummary,
			anonymizedContext,
		);

		// Mark as blind judgment
		return {
			...result,
			judgedBy: `Blind(${result.judgedBy})`,
		};
	}

	getInfo(): JudgeInfo {
		const innerInfo = this.innerJudge.getInfo();
		return {
			name: `Blind ${innerInfo.name}`,
			model: innerInfo.model,
			type: "blind",
		};
	}

	/**
	 * Remove any identifying information from the summary.
	 */
	private anonymize(
		summary: FileSummary | SymbolSummary,
	): FileSummary | SymbolSummary {
		if ("symbolName" in summary) {
			// SymbolSummary - keep symbol name as it's needed for understanding
			return {
				...summary,
				// Remove enrichedAt timestamp which could identify the model
				enrichedAt: undefined,
				// Remove source IDs
				sourceIds: [],
			};
		} else {
			// FileSummary - anonymize file path
			return {
				...summary,
				filePath: "source_file",
				enrichedAt: undefined,
				sourceIds: [],
			};
		}
	}
}

// ============================================================================
// Batch Blind Evaluation
// ============================================================================

/**
 * Candidate summary for batch evaluation
 */
export interface EvaluationCandidate {
	/** Anonymous identifier (e.g., "A", "B", "C") */
	id: string;
	/** The generated summary */
	summary: FileSummary | SymbolSummary;
	/** Original generator identifier (hidden from judge) */
	generatorId: string;
}

/**
 * Result of batch blind evaluation
 */
export interface BatchBlindResult {
	/** Candidate ID */
	candidateId: string;
	/** Generator ID (revealed after evaluation) */
	generatorId: string;
	/** Judgment result */
	judgment: JudgmentResult;
}

/**
 * Shuffle an array using Fisher-Yates algorithm
 */
function shuffle<T>(array: T[]): T[] {
	const result = [...array];
	for (let i = result.length - 1; i > 0; i--) {
		const j = Math.floor(Math.random() * (i + 1));
		[result[i], result[j]] = [result[j], result[i]];
	}
	return result;
}

/**
 * Evaluate multiple candidates blindly.
 * Shuffles the order and assigns anonymous IDs before evaluation.
 */
export async function evaluateBlindly(
	candidates: Array<{
		summary: FileSummary | SymbolSummary;
		generatorId: string;
	}>,
	context: JudgeContext,
	judge: IJudge,
): Promise<BatchBlindResult[]> {
	// Assign anonymous IDs and shuffle
	const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
	const evaluationCandidates: EvaluationCandidate[] = candidates.map(
		(c, i) => ({
			id: letters[i % letters.length],
			summary: c.summary,
			generatorId: c.generatorId,
		}),
	);

	const shuffled = shuffle(evaluationCandidates);

	// Create blind judge
	const blindJudge = new BlindJudge(judge);

	// Evaluate each candidate
	const results: BatchBlindResult[] = [];
	for (const candidate of shuffled) {
		const judgment = await blindJudge.judge(candidate.summary, context);
		results.push({
			candidateId: candidate.id,
			generatorId: candidate.generatorId,
			judgment,
		});
	}

	return results;
}

/**
 * Consensus Judge
 *
 * Runs multiple judges and aggregates their scores using median or mean.
 * Provides more robust evaluation than a single judge.
 */

import type { FileSummary, SymbolSummary } from "../../types.js";
import type {
	IJudge,
	JudgeContext,
	JudgeInfo,
	JudgmentResult,
} from "../types.js";

// ============================================================================
// Types
// ============================================================================

export type AggregationMethod = "median" | "mean";

// ============================================================================
// Consensus Judge Implementation
// ============================================================================

export class ConsensusJudge implements IJudge {
	private judges: IJudge[];
	private aggregationMethod: AggregationMethod;

	constructor(
		judges: IJudge[],
		aggregationMethod: AggregationMethod = "median",
	) {
		if (judges.length === 0) {
			throw new Error("ConsensusJudge requires at least one judge");
		}
		this.judges = judges;
		this.aggregationMethod = aggregationMethod;
	}

	async judge(
		generated: FileSummary | SymbolSummary,
		context: JudgeContext,
	): Promise<JudgmentResult> {
		const startTime = Date.now();

		// Run all judges in parallel
		const results = await Promise.all(
			this.judges.map((judge) => judge.judge(generated, context)),
		);

		// Filter out failed judgments (those with default scores due to errors)
		const validResults = results.filter(
			(r) => !r.feedback?.startsWith("Judgment failed:"),
		);

		// If all failed, return the first result
		if (validResults.length === 0) {
			return results[0];
		}

		// Aggregate scores
		const usefulness = this.aggregate(validResults.map((r) => r.usefulness));
		const conciseness = this.aggregate(validResults.map((r) => r.conciseness));
		const clarity = this.aggregate(validResults.map((r) => r.clarity));

		// Calculate overall quality score
		const qualityScore = Math.round(
			usefulness * 0.5 + conciseness * 0.25 + clarity * 0.25,
		);

		// Combine feedback from all judges
		const feedbackParts = validResults
			.map((r) => r.feedback)
			.filter((f): f is string => !!f);
		const feedback =
			feedbackParts.length > 0 ? feedbackParts.join(" | ") : undefined;

		const durationMs = Date.now() - startTime;
		const judgeNames = this.judges
			.map((j) => j.getInfo().model || j.getInfo().name)
			.join(", ");

		return {
			usefulness,
			conciseness,
			clarity,
			qualityScore,
			feedback,
			judgedBy: `Consensus (${judgeNames})`,
			durationMs,
		};
	}

	getInfo(): JudgeInfo {
		const judgeModels = this.judges
			.map((j) => j.getInfo().model || j.getInfo().name)
			.join(", ");

		return {
			name: `Consensus Judge (${this.aggregationMethod})`,
			model: judgeModels,
			type: "consensus",
		};
	}

	/**
	 * Aggregate values using the configured method.
	 */
	private aggregate(values: number[]): number {
		if (values.length === 0) return 0;
		if (values.length === 1) return values[0];

		if (this.aggregationMethod === "median") {
			return median(values);
		} else {
			return mean(values);
		}
	}
}

// ============================================================================
// Utility Functions
// ============================================================================

function mean(values: number[]): number {
	if (values.length === 0) return 0;
	const sum = values.reduce((a, b) => a + b, 0);
	return Math.round(sum / values.length);
}

function median(values: number[]): number {
	if (values.length === 0) return 0;
	if (values.length === 1) return values[0];

	const sorted = [...values].sort((a, b) => a - b);
	const mid = Math.floor(sorted.length / 2);

	if (sorted.length % 2 === 0) {
		return Math.round((sorted[mid - 1] + sorted[mid]) / 2);
	} else {
		return sorted[mid];
	}
}

/**
 * Judge Factory
 *
 * Creates judge instances for evaluating summary quality.
 * Uses LLMResolver for consistent model spec parsing.
 */

import { LLMResolver } from "../../llm/resolver.js";
import type { LLMProvider } from "../../types.js";
import type { IJudge } from "../types.js";
import { BlindJudge } from "./blind-judge.js";
import { type AggregationMethod, ConsensusJudge } from "./consensus-judge.js";
import { LLMJudge } from "./llm-judge.js";

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Create an LLM judge for the specified model.
 *
 * @param model - Model identifier (e.g., "claude-sonnet-4", "openai/gpt-4o", "a/opus", "cc/sonnet")
 * @param provider - Optional provider override (auto-detected from model if not specified)
 */
export async function createJudge(
	model: string,
	provider?: LLMProvider,
): Promise<IJudge> {
	// Use LLMResolver for consistent spec parsing
	const client = await LLMResolver.createClient(
		model,
		provider ? { provider } : undefined,
	);
	return new LLMJudge(client);
}

/**
 * Create a consensus judge from multiple models.
 *
 * @param models - Array of model identifiers
 * @param aggregation - Aggregation method (default: "median")
 */
export async function createConsensusJudge(
	models: string[],
	aggregation: AggregationMethod = "median",
): Promise<IJudge> {
	const judges = await Promise.all(models.map((model) => createJudge(model)));

	return new ConsensusJudge(judges, aggregation);
}

/**
 * Create a blind judge wrapper.
 *
 * @param model - Model identifier for the underlying judge
 */
export async function createBlindJudge(model: string): Promise<IJudge> {
	const innerJudge = await createJudge(model);
	return new BlindJudge(innerJudge);
}

/**
 * Parse judge specification and create appropriate judge.
 * Supports formats:
 * - "claude-sonnet-4" -> Single LLM judge
 * - "a/opus" -> Single LLM judge with Anthropic provider
 * - "cc/sonnet" -> Single LLM judge with Claude Code provider
 * - "claude-sonnet-4,gpt-4o" -> Consensus judge
 * - "blind:claude-sonnet-4" -> Blind judge
 * - "consensus:median:claude-sonnet-4,gpt-4o" -> Consensus with method
 */
export async function parseAndCreateJudge(spec: string): Promise<IJudge> {
	// Check for blind prefix
	if (spec.startsWith("blind:")) {
		const model = spec.slice(6);
		return createBlindJudge(model);
	}

	// Check for consensus prefix
	if (spec.startsWith("consensus:")) {
		const rest = spec.slice(10);
		const parts = rest.split(":");

		if (parts.length === 2) {
			// consensus:method:models
			const method = parts[0] as AggregationMethod;
			const models = parts[1].split(",").map((m) => m.trim());
			return createConsensusJudge(models, method);
		} else {
			// consensus:models (default method)
			const models = parts[0].split(",").map((m) => m.trim());
			return createConsensusJudge(models);
		}
	}

	// Check for comma-separated models (implicit consensus)
	if (spec.includes(",")) {
		const models = spec.split(",").map((m) => m.trim());
		return createConsensusJudge(models);
	}

	// Single model
	return createJudge(spec);
}

