/**
 * LLM Judge
 *
 * Uses an LLM to evaluate the quality of generated summaries.
 * Scores: usefulness, conciseness, clarity.
 */

import type { FileSummary, ILLMClient, SymbolSummary } from "../../types.js";
import type {
	IJudge,
	JudgeContext,
	JudgeInfo,
	JudgmentResult,
} from "../types.js";

// ============================================================================
// Constants
// ============================================================================

const JUDGE_SYSTEM_PROMPT = `You are an expert code reviewer evaluating the quality of automatically generated code documentation.

Your task is to score a generated summary on three dimensions (0-100 each):

1. **USEFULNESS** (most important):
   - Does the summary help a developer understand the code?
   - Does it explain the PURPOSE, not just restate the code?
   - Does it cover key parameters, return values, and behavior?
   - HIGH (90-100): Excellent explanation of purpose, covers all key aspects, would help new developers
   - MEDIUM (50-89): Basic purpose explained, covers most aspects
   - LOW (0-49): Vague, obvious, or missing important information

2. **CONCISENESS**:
   - Is the summary information-dense without unnecessary verbosity?
   - Does every sentence add value?
   - HIGH (90-100): Tight, no redundancy, every word matters
   - MEDIUM (50-89): Mostly concise with minor verbosity
   - LOW (0-49): Wordy, repetitive, or states the obvious

3. **CLARITY**:
   - Is the summary well-written and easy to understand?
   - Does it use appropriate technical terminology?
   - HIGH (90-100): Crystal clear, professional quality
   - MEDIUM (50-89): Understandable with minor awkwardness
   - LOW (0-49): Confusing, poorly structured, or unclear

Be strict but fair. Most summaries should score between 50-85.
Perfect scores (95+) should be rare - only for exceptional quality.

IMPORTANT: Respond with ONLY valid JSON. No markdown, no explanation.`;

// ============================================================================
// LLM Judge Implementation
// ============================================================================

interface JudgeResponse {
	usefulness: number;
	conciseness: number;
	clarity: number;
	feedback: string;
}

export class LLMJudge implements IJudge {
	private llmClient: ILLMClient;
	private model: string;

	constructor(llmClient: ILLMClient) {
		this.llmClient = llmClient;
		this.model = llmClient.getModel();
	}

	async judge(
		generated: FileSummary | SymbolSummary,
		context: JudgeContext,
	): Promise<JudgmentResult> {
		const startTime = Date.now();

		try {
			const prompt = this.buildPrompt(generated, context);

			const response = await this.llmClient.completeJSON<JudgeResponse>(
				[{ role: "user", content: prompt }],
				{
					systemPrompt: JUDGE_SYSTEM_PROMPT,
					temperature: 0.1, // Low temperature for consistent scoring
					maxTokens: 500,
				},
			);

			const durationMs = Date.now() - startTime;

			// Clamp scores to 0-100
			const usefulness = clamp(response.usefulness, 0, 100);
			const conciseness = clamp(response.conciseness, 0, 100);
			const clarity = clamp(response.clarity, 0, 100);

			// Calculate overall quality score (weighted average)
			const qualityScore = Math.round(
				usefulness * 0.5 + conciseness * 0.25 + clarity * 0.25,
			);

			return {
				usefulness,
				conciseness,
				clarity,
				qualityScore,
				feedback: response.feedback || undefined,
				judgedBy: this.model,
				durationMs,
			};
		} catch (error) {
			const durationMs = Date.now() - startTime;

			// Return neutral scores on error
			return {
				usefulness: 50,
				conciseness: 50,
				clarity: 50,
				qualityScore: 50,
				feedback: `Judgment failed: ${error instanceof Error ? error.message : String(error)}`,
				judgedBy: this.model,
				durationMs,
			};
		}
	}

	getInfo(): JudgeInfo {
		return {
			name: `LLM Judge (${this.model})`,
			model: this.model,
			type: "llm",
		};
	}

	private buildPrompt(
		generated: FileSummary | SymbolSummary,
		context: JudgeContext,
	): string {
		const summaryType = "symbolName" in generated ? "symbol" : "file";
		const summaryContent = this.formatSummary(generated);
		const codeContent = context.codeChunk?.content || context.fileContent;

		// Truncate code if too long
		const maxCodeLength = 3000;
		const truncatedCode =
			codeContent.length > maxCodeLength
				? `${codeContent.slice(0, maxCodeLength)}\n... (truncated)`
				: codeContent;

		return `Evaluate this ${summaryType} summary.

## SOURCE CODE
\`\`\`${context.language}
${truncatedCode}
\`\`\`

## GENERATED SUMMARY
${summaryContent}

## YOUR TASK
Score the summary on usefulness (0-100), conciseness (0-100), and clarity (0-100).
Also provide brief feedback explaining your scores.

Respond with JSON:
{
  "usefulness": <0-100>,
  "conciseness": <0-100>,
  "clarity": <0-100>,
  "feedback": "<brief explanation>"
}`;
	}

	private formatSummary(summary: FileSummary | SymbolSummary): string {
		if ("symbolName" in summary) {
			// SymbolSummary
			const parts = [
				`**Symbol:** ${summary.symbolName}`,
				`**Type:** ${summary.symbolType}`,
				`**Summary:** ${summary.summary}`,
			];

			if (summary.parameters && summary.parameters.length > 0) {
				parts.push(
					`**Parameters:**\n${summary.parameters
						.map((p) => `  - ${p.name}: ${p.description}`)
						.join("\n")}`,
				);
			}

			if (summary.returnDescription) {
				parts.push(`**Returns:** ${summary.returnDescription}`);
			}

			if (summary.sideEffects && summary.sideEffects.length > 0) {
				parts.push(`**Side Effects:** ${summary.sideEffects.join(", ")}`);
			}

			if (summary.usageContext) {
				parts.push(`**Usage:** ${summary.usageContext}`);
			}

			return parts.join("\n");
		} else {
			// FileSummary
			const parts = [
				`**File:** ${summary.filePath}`,
				`**Summary:** ${summary.summary}`,
			];

			if (summary.responsibilities && summary.responsibilities.length > 0) {
				parts.push(
					`**Responsibilities:**\n${summary.responsibilities
						.map((r) => `  - ${r}`)
						.join("\n")}`,
				);
			}

			if (summary.exports && summary.exports.length > 0) {
				parts.push(`**Exports:** ${summary.exports.join(", ")}`);
			}

			if (summary.dependencies && summary.dependencies.length > 0) {
				parts.push(`**Dependencies:** ${summary.dependencies.join(", ")}`);
			}

			if (summary.patterns && summary.patterns.length > 0) {
				parts.push(`**Patterns:** ${summary.patterns.join(", ")}`);
			}

			return parts.join("\n");
		}
	}
}

// ============================================================================
// Utility Functions
// ============================================================================

function clamp(value: number, min: number, max: number): number {
	return Math.max(min, Math.min(max, value));
}

/**
 * CLI Table Reporter
 *
 * Formats benchmark results as a pretty CLI table.
 * Shows full model names and detailed error information.
 */

import type {
	BenchmarkResults,
	GeneratorResults,
	IReporter,
	ReportFormat,
} from "../types.js";

// ============================================================================
// Colors
// ============================================================================

const c = {
	reset: "\x1b[0m",
	bold: "\x1b[1m",
	dim: "\x1b[2m",
	green: "\x1b[38;5;78m",
	yellow: "\x1b[33m",
	red: "\x1b[31m",
	cyan: "\x1b[36m",
	orange: "\x1b[38;5;209m",
};

// ============================================================================
// CLI Reporter Implementation
// ============================================================================

export class CLIReporter implements IReporter {
	private useColors: boolean;

	constructor(useColors = true) {
		this.useColors = useColors;
	}

	async report(results: BenchmarkResults): Promise<string> {
		const lines: string[] = [];

		// Header
		lines.push("");
		lines.push(
			this.color(`${c.orange}${c.bold}🏁 LLM BENCHMARK RESULTS${c.reset}`),
		);
		lines.push("");

		// Metadata
		lines.push(
			this.color(`${c.dim}Project: ${results.metadata.projectPath}${c.reset}`),
		);
		lines.push(
			this.color(
				`${c.dim}Test cases: ${results.metadata.totalTestCases} (${results.metadata.testCaseTypes.file_summary} files, ${results.metadata.testCaseTypes.symbol_summary} symbols)${c.reset}`,
			),
		);
		lines.push(
			this.color(
				`${c.dim}Judges: ${results.metadata.judges.length > 0 ? results.metadata.judges.join(", ") : "none"}${c.reset}`,
			),
		);
		lines.push("");

		// Results table
		lines.push(this.formatResultsTable(results));

		// Failed models section (detailed errors)
		const failedGenerators = results.generators.filter(
			(g) => g.metrics.failures > 0 || g.scores.overall === 0,
		);
		if (failedGenerators.length > 0) {
			lines.push("");
			lines.push(this.color(`${c.red}${c.bold}⚠ FAILED MODELS${c.reset}`));
			for (const gen of failedGenerators) {
				lines.push(
					this.formatFailedGenerator(gen, results.metadata.totalTestCases),
				);
			}
		}

		// Rankings (only show models that didn't completely fail)
		const successfulModels = results.rankings.byOverallScore.filter((model) => {
			const gen = results.generators.find((g) => g.info.model === model);
			return gen && gen.scores.overall > 0;
		});

		if (successfulModels.length > 0) {
			lines.push("");
			lines.push(this.color(`${c.bold}Rankings:${c.reset}`));
			lines.push(
				this.color(
					`  ${c.cyan}Overall:${c.reset} ${this.formatRanking(successfulModels)}`,
				),
			);
			lines.push(
				this.color(
					`  ${c.cyan}Correctness:${c.reset} ${this.formatRanking(results.rankings.byCorrectness.filter((m) => successfulModels.includes(m)))}`,
				),
			);
			lines.push(
				this.color(
					`  ${c.cyan}Speed:${c.reset} ${this.formatRanking(results.rankings.bySpeed.filter((m) => successfulModels.includes(m)))}`,
				),
			);
			lines.push(
				this.color(
					`  ${c.cyan}Cost:${c.reset} ${this.formatRanking(results.rankings.byCost.filter((m) => successfulModels.includes(m)))}`,
				),
			);
		}

		// Weights legend
		lines.push("");
		lines.push(this.formatWeightsLegend(results.metadata.weights));

		return lines.join("\n");
	}

	getFormat(): ReportFormat {
		return "cli";
	}

	/**
	 * Format the main results table with dynamic column widths.
	 */
	private formatResultsTable(results: BenchmarkResults): string {
		const lines: string[] = [];

		// Calculate dynamic model name width (full names, no truncation)
		const maxModelLen = Math.max(
			5, // minimum "Model" header
			...results.generators.map((g) => g.info.displayName.length),
		);

		// Check if we have per-judge breakdowns (multi-judge mode)
		const hasJudgeBreakdown = results.generators.some(
			(g) => g.scores.judgeBreakdown && g.scores.judgeBreakdown.length > 1,
		);

		// Calculate width for usefulness column based on breakdown
		const usefulWidth = hasJudgeBreakdown
			? this.calculateBreakdownWidth(results, "usefulness")
			: 8;

		// Calculate price column width based on actual costs
		const priceWidth =
			Math.max(
				6,
				...results.generators.map(
					(g) => this.formatPrice(g.metrics.totalCost).length,
				),
			) + 1;

		// Headers and widths
		const headers = [
			"Model",
			"Overall",
			"Correct",
			"Complete",
			"Useful",
			"Speed",
			"Price",
			"Time",
			"Status",
		];
		const widths = [
			maxModelLen + 2,
			8,
			8,
			9,
			usefulWidth,
			6,
			priceWidth,
			8,
			12,
		];

		const headerRow = headers.map((h, i) => h.padEnd(widths[i])).join(" ");
		lines.push(this.color(`  ${c.bold}${headerRow}${c.reset}`));
		lines.push(`  ${"─".repeat(headerRow.length)}`);

		// Find best/worst for highlighting
		const validOverall = results.generators
			.filter((g) => g.scores.overall > 0)
			.map((g) => g.scores.overall);
		const maxOverall = validOverall.length > 0 ? Math.max(...validOverall) : 0;
		const minOverall = validOverall.length > 0 ? Math.min(...validOverall) : 0;

		// Data rows
		for (const gen of results.generators) {
			const row = this.formatGeneratorRow(
				gen,
				widths,
				maxOverall,
				minOverall,
				results.metadata.totalTestCases,
				hasJudgeBreakdown,
			);
			lines.push(`  ${row}`);
		}

		return lines.join("\n");
	}

	/**
	 * Calculate width needed for breakdown column.
	 */
	private calculateBreakdownWidth(
		results: BenchmarkResults,
		_field: "usefulness" | "conciseness",
	): number {
		let maxLen = 8; // minimum width
