/**
 * JSON Reporter
 *
 * Outputs benchmark results as machine-readable JSON.
 * Useful for automation, further analysis, or integrations.
 */

import type { BenchmarkResults, IReporter, ReportFormat } from "../types.js";

// ============================================================================
// JSON Reporter Implementation
// ============================================================================

export class JSONReporter implements IReporter {
	private pretty: boolean;

	constructor(pretty = true) {
		this.pretty = pretty;
	}

	async report(results: BenchmarkResults): Promise<string> {
		// Clean up results for JSON output
		const cleanResults = this.cleanResults(results);

		if (this.pretty) {
			return JSON.stringify(cleanResults, null, 2);
		}
		return JSON.stringify(cleanResults);
	}

	getFormat(): ReportFormat {
		return "json";
	}

	/**
	 * Clean results for JSON serialization.
	 * Removes circular references and simplifies nested structures.
	 */
	private cleanResults(results: BenchmarkResults): object {
		return {
			metadata: results.metadata,
			rankings: results.rankings,
			generators: results.generators.map((gen) => ({
				info: gen.info,
				scores: gen.scores,
				metrics: gen.metrics,
				testCaseCount: gen.testCaseResults.length,
				// Summarize test case results instead of including full content
				testCaseSummary: {
					avgOverallScore: this.avg(
						gen.testCaseResults.map((r) => r.overallScore),
					),
					scoreDistribution: this.scoreDistribution(
						gen.testCaseResults.map((r) => r.overallScore),
					),
					failedCount: gen.metrics.failures,
				},
			})),
			// Include full test case results as separate section
			testCaseDetails: results.generators.map((gen) => ({
				generator: gen.info.model,
				results: gen.testCaseResults.map((tcr) => ({
					testCaseId: tcr.testCase.id,
					type: tcr.testCase.type,
					filePath: tcr.testCase.filePath,
					overallScore: tcr.overallScore,
					scores: tcr.scores.reduce(
						(acc, s) => ({ ...acc, [s.criterion]: s.score }),
						{} as Record<string, number>,
					),
					judgment: tcr.judgment
						? {
								usefulness: tcr.judgment.usefulness,
								conciseness: tcr.judgment.conciseness,
								clarity: tcr.judgment.clarity,
								judgedBy: tcr.judgment.judgedBy,
							}
						: null,
					generation: {
						durationMs: tcr.generation.durationMs,
						cost: tcr.generation.usage.cost,
						tokens:
							tcr.generation.usage.inputTokens +
							tcr.generation.usage.outputTokens,
					},
				})),
			})),
		};
	}

	/**
	 * Calculate average.
	 */
	private avg(values: number[]): number {
		if (values.length === 0) return 0;
		return Math.round(values.reduce((a, b) => a + b, 0) / values.length);
	}

	/**
	 * Calculate score distribution buckets.
	 */
	private scoreDistribution(scores: number[]): Record<string, number> {
		const buckets = {
			"90-100": 0,
			"80-89": 0,
			"70-79": 0,
			"60-69": 0,
			"50-59": 0,
			"0-49": 0,
		};

		for (const score of scores) {
			if (score >= 90) buckets["90-100"]++;
			else if (score >= 80) buckets["80-89"]++;
			else if (score >= 70) buckets["70-79"]++;
			else if (score >= 60) buckets["60-69"]++;
			else if (score >= 50) buckets["50-59"]++;
			else buckets["0-49"]++;
		}

		return buckets;
	}
}

/**
 * Completeness Scorer
 *
 * Validates that summaries cover all important aspects.
 * Measures: Are all expected elements documented?
 *
 * Weight: 20% of total score
 */

import type { FileSummary, SymbolSummary } from "../../types.js";
import type {
	GenerationResult,
	IScorer,
	JudgmentResult,
	ScoreResult,
	ScoringCriterion,
	TestCase,
} from "../types.js";
import { fuzzyMatch } from "./utils.js";

// ============================================================================
// Completeness Scorer Implementation
// ============================================================================

export class CompletenessScorer implements IScorer {
	async score(
		testCase: TestCase,
		generation: GenerationResult<FileSummary | SymbolSummary>,
		_judgment?: JudgmentResult,
	): Promise<ScoreResult> {
		const summary = generation.result;
		const groundTruth = testCase.groundTruth;

		let score: number;
		let details: Record<string, unknown>;

		if (testCase.type === "file_summary") {
			const fileSummary = summary as FileSummary;
			const result = this.scoreFileSummaryCompleteness(
				fileSummary,
				groundTruth,
			);
			score = result.score;
			details = result.details;
		} else {
			const symbolSummary = summary as SymbolSummary;
			const result = this.scoreSymbolSummaryCompleteness(
				symbolSummary,
				groundTruth,
			);
			score = result.score;
			details = result.details;
		}

		const criterion = this.getCriterion();

		return {
			criterion: criterion.name,
			score,
			weight: criterion.weight,
			weightedScore: score * criterion.weight,
			details,
		};
	}

	getCriterion(): ScoringCriterion {
		return {
			name: "completeness",
			weight: 0.2,
			description:
				"Are all important elements (params, exports, side effects) documented?",
		};
	}

	/**
	 * Score file summary completeness.
	 */
	private scoreFileSummaryCompleteness(
		summary: FileSummary,
		groundTruth: TestCase["groundTruth"],
	): { score: number; details: Record<string, unknown> } {
		const actualExports = groundTruth.exports || [];
		const actualDeps = groundTruth.dependencies || [];
		const mentionedExports = summary.exports || [];
		const mentionedDeps = summary.dependencies || [];

		// Calculate export coverage (40% weight)
		// What percentage of actual exports are mentioned?
		let exportCoverage = 100;
		if (actualExports.length > 0) {
			const coveredExports = actualExports.filter((actual) =>
				mentionedExports.some((mentioned) => fuzzyMatch(mentioned, actual)),
			);
			exportCoverage = (coveredExports.length / actualExports.length) * 100;
		}

		// Calculate dependency coverage (30% weight)
		let depCoverage = 100;
		if (actualDeps.length > 0) {
			const coveredDeps = actualDeps.filter((actual) =>
				mentionedDeps.some((mentioned) => fuzzyMatch(mentioned, actual)),
			);
			depCoverage = (coveredDeps.length / actualDeps.length) * 100;
		}

		// Check for essential fields (30% weight)
		let fieldCompleteness = 0;
		if (summary.summary && summary.summary.length > 20) fieldCompleteness += 50;
		if (summary.responsibilities && summary.responsibilities.length > 0)
			fieldCompleteness += 30;
		if (summary.patterns && summary.patterns.length > 0)
			fieldCompleteness += 20;

		const score = Math.round(
			exportCoverage * 0.4 + depCoverage * 0.3 + fieldCompleteness * 0.3,
		);

		return {
			score,
			details: {
				actualExports: actualExports.length,
				coveredExports: Math.round(exportCoverage),
				actualDependencies: actualDeps.length,
				coveredDependencies: Math.round(depCoverage),
				hasSummary: !!summary.summary && summary.summary.length > 20,
				hasResponsibilities: summary.responsibilities?.length > 0,
				hasPatterns: summary.patterns?.length > 0,
				fieldCompleteness,
			},
		};
	}

	/**
	 * Score symbol summary completeness.
	 */
	private scoreSymbolSummaryCompleteness(
		summary: SymbolSummary,
		groundTruth: TestCase["groundTruth"],
	): { score: number; details: Record<string, unknown> } {
		const actualParams = groundTruth.parameters || [];
		const mentionedParams = summary.parameters || [];
		const hasSideEffects =
			groundTruth.sideEffects && groundTruth.sideEffects.length > 0;

		// Calculate parameter coverage (50% weight)
		let paramCoverage = 100;
		if (actualParams.length > 0) {
			const coveredParams = actualParams.filter((actual) =>
				mentionedParams.some((mentioned) => mentioned.name === actual.name),
			);
			paramCoverage = (coveredParams.length / actualParams.length) * 100;
		}

		// Check for essential fields (50% weight)
		let fieldCompleteness = 0;

		// Summary is required (30%)
		if (summary.summary && summary.summary.length > 10) {
			fieldCompleteness += 30;
		}

		// Return description if function has return type (20%)
		if (groundTruth.returnType) {
			if (summary.returnDescription && summary.returnDescription.length > 0) {
				fieldCompleteness += 20;
			}
		} else {
			fieldCompleteness += 20; // No return type = full points for this
		}

		// Side effects documentation if applicable (25%)
		if (hasSideEffects) {
			if (summary.sideEffects && summary.sideEffects.length > 0) {
				fieldCompleteness += 25;
			}
		} else {
			fieldCompleteness += 25; // No side effects = full points
		}

		// Usage context is bonus (25%)
		if (summary.usageContext && summary.usageContext.length > 0) {
			fieldCompleteness += 25;
		}

		const score = Math.round(paramCoverage * 0.5 + fieldCompleteness * 0.5);

		return {
			score,
			details: {
				actualParams: actualParams.length,
				coveredParams: mentionedParams.length,
				paramCoverage: Math.round(paramCoverage),
				hasSummary: !!summary.summary && summary.summary.length > 10,
				hasReturnDescription: !!summary.returnDescription,
				hasSideEffects: (summary.sideEffects?.length ?? 0) > 0,
				hasUsageContext: !!summary.usageContext,
				fieldCompleteness,
			},
		};
	}
}

/**
 * Composite Scorer
 *
 * Combines multiple scorers into a single weighted score.
 * Allows customizing weights for different evaluation priorities.
 */

import type { FileSummary, SymbolSummary } from "../../types.js";
import type {
	GenerationResult,
	IScorer,
	JudgmentResult,
	ScoreResult,
	ScoringCriterion,
	TestCase,
} from "../types.js";

// ============================================================================
// Composite Scorer Implementation
// ============================================================================

export class CompositeScorer implements IScorer {
	private scorers: IScorer[];
	private weights: Record<string, number>;

	/**
	 * Create a composite scorer from multiple scorers.
	 *
	 * @param scorers - Individual scorers to combine
	 * @param weights - Optional weight overrides (keys match criterion names)
	 */
	constructor(scorers: IScorer[], weights?: Record<string, number>) {
		this.scorers = scorers;
		this.weights = weights || this.extractDefaultWeights();
	}

	async score(
		testCase: TestCase,
		generation: GenerationResult<FileSummary | SymbolSummary>,
		judgment?: JudgmentResult,
	): Promise<ScoreResult> {
		// Run all scorers
		const results = await Promise.all(
			this.scorers.map((scorer) =>
				scorer.score(testCase, generation, judgment),
			),
		);

		// Calculate weighted sum
		let totalWeightedScore = 0;
		let totalWeight = 0;

		for (const result of results) {
			const weight = this.weights[result.criterion] ?? result.weight;
			totalWeightedScore += result.score * weight;
			totalWeight += weight;
		}

		// Normalize if weights don't sum to 1
		const score =
			totalWeight > 0 ? Math.round(totalWeightedScore / totalWeight) : 50;

		const criterion = this.getCriterion();

		return {
			criterion: criterion.name,
			score,
			weight: 1.0, // Composite is the final score
			weightedScore: score,
			details: {
				componentScores: results.reduce(
					(acc, r) => {
						acc[r.criterion] = {
							score: r.score,
							weight: this.weights[r.criterion] ?? r.weight,
							weightedScore: r.score * (this.weights[r.criterion] ?? r.weight),
						};
						return acc;
					},
					{} as Record<
						string,
						{ score: number; weight: number; weightedScore: number }
					>,
				),
				totalWeight,
			},
		};
	}

	getCriterion(): ScoringCriterion {
		return {
			name: "overall",
			weight: 1.0,
			description: "Weighted composite of all scoring criteria",
		};
	}

	/**
	 * Score a test case and return all component results.
	 * More detailed than score() for reporting purposes.
	 */
	async scoreDetailed(
		testCase: TestCase,
		generation: GenerationResult<FileSummary | SymbolSummary>,
		judgment?: JudgmentResult,
	): Promise<{
		overall: number;
		components: ScoreResult[];
	}> {
		// Run all scorers
		const components = await Promise.all(
			this.scorers.map((scorer) =>
				scorer.score(testCase, generation, judgment),
			),
		);

		// Calculate weighted sum
		let totalWeightedScore = 0;
		let totalWeight = 0;

		for (const result of components) {
			const weight = this.weights[result.criterion] ?? result.weight;
			totalWeightedScore += result.score * weight;
			totalWeight += weight;
		}

		const overall =
			totalWeight > 0 ? Math.round(totalWeightedScore / totalWeight) : 50;

		return { overall, components };
	}

	/**
	 * Get the scorers in this composite.
	 */
	getScorers(): IScorer[] {
		return [...this.scorers];
	}

	/**
	 * Get the weight for a specific criterion.
	 */
	getWeight(criterion: string): number {
		return this.weights[criterion] ?? 0;
	}

	/**
	 * Get all weights.
	 */
	getWeights(): Record<string, number> {
		return { ...this.weights };
	}

	/**
	 * Extract default weights from scorers.
	 */
	private extractDefaultWeights(): Record<string, number> {
		const weights: Record<string, number> = {};
		for (const scorer of this.scorers) {
			const criterion = scorer.getCriterion();
			weights[criterion.name] = criterion.weight;
		}
		return weights;
	}
}

