		// If no judgment available, return 0 (not fake 50%)
		const hasJudgment =
			judgment !== undefined && judgment.judgedBy !== "no judge";
		const score = hasJudgment ? judgment.conciseness : 0;

		const criterion = this.getCriterion();

		return {
			criterion: criterion.name,
			score,
			weight: criterion.weight,
			weightedScore: score * criterion.weight,
			details: {
				judgedBy: judgment?.judgedBy || "no judge",
				clarity: judgment?.clarity,
				hasValidJudgment: hasJudgment,
			},
		};
	}

	getCriterion(): ScoringCriterion {
		return {
			name: "conciseness",
			weight: 0.1,
			description:
				"Is the summary information-dense without unnecessary verbosity?",
		};
	}
}

// ============================================================================
// Combined Quality Scorer
// ============================================================================

/**
 * Combines usefulness and conciseness into a single quality score.
 * Useful when you want to treat all judge-based scores as one criterion.
 */
export class QualityScorer implements IScorer {
	async score(
		_testCase: TestCase,
		_generation: GenerationResult<FileSummary | SymbolSummary>,
		judgment?: JudgmentResult,
	): Promise<ScoreResult> {
		// If no judgment available, return 0 (not fake 50%)
		const hasJudgment =
			judgment !== undefined && judgment.judgedBy !== "no judge";

		const usefulness = hasJudgment ? judgment.usefulness : 0;
		const conciseness = hasJudgment ? judgment.conciseness : 0;
		const clarity = hasJudgment ? judgment.clarity : 0;

		// Weighted combination: usefulness is most important
		const score = hasJudgment
			? Math.round(usefulness * 0.5 + conciseness * 0.25 + clarity * 0.25)
			: 0;

		const criterion = this.getCriterion();

		return {
			criterion: criterion.name,
			score,
			weight: criterion.weight,
			weightedScore: score * criterion.weight,
			details: {
				usefulness,
				conciseness,
				clarity,
				judgedBy: judgment?.judgedBy || "no judge",
				feedback: judgment?.feedback,
				hasValidJudgment: hasJudgment,
			},
		};
	}

	getCriterion(): ScoringCriterion {
		return {
			name: "quality",
			weight: 0.3, // Combined weight of usefulness (20%) + conciseness (10%)
			description:
				"Overall subjective quality from LLM judge (usefulness, conciseness, clarity)",
		};
	}
}

/**
 * Scorer Utilities
 *
 * Shared utility functions for benchmark scorers.
 */

/**
 * Fuzzy match two strings, considering:
 * - Normalized string comparison (alphanumeric only)
 * - Substring containment
 * - Module path basename matching
 */
export function fuzzyMatch(mentioned: string, actual: string): boolean {
	const normalizedMentioned = mentioned.toLowerCase().replace(/[^a-z0-9]/g, "");
	const normalizedActual = actual.toLowerCase().replace(/[^a-z0-9]/g, "");

	// Exact match
	if (normalizedMentioned === normalizedActual) return true;

	// One contains the other
	if (normalizedMentioned.includes(normalizedActual)) return true;
	if (normalizedActual.includes(normalizedMentioned)) return true;

	// Match module paths (e.g., "./store" matches "store.js")
	const mentionedBase =
		mentioned
			.split("/")
			.pop()
			?.replace(/\.(js|ts|tsx|jsx)$/, "") || mentioned;
	const actualBase =
		actual
			.split("/")
			.pop()
			?.replace(/\.(js|ts|tsx|jsx)$/, "") || actual;
	if (mentionedBase.toLowerCase() === actualBase.toLowerCase()) return true;

	return false;
}

