 * Create a CloudAuthManager using the default credentials path
 * (~/.mnemex/credentials.json).
 */
export function createCloudAuthManager(
	credentialsPath?: string,
): CloudAuthManager {
	return new CloudAuthManager(credentialsPath);
}

