				chunksToUpload = embeddedChunks.chunks;
				embeddingCost = em

/**
 * Generate and persist a stable anonymous machine ID.
 * Stored at ~/.mnemex/machine-id — created on first call, reused thereafter.
 * Used as X-Mnemex-Machine-ID header for server-side device tracking.
 */

import { randomUUID } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const MACHINE_ID_DIR = join(homedir(), ".mnemex");
const MACHINE_ID_FILE = join(MACHINE_ID_DIR, "machine-id");

/** Get the machine ID, creating it if it doesn't exist. Synchronous for simplicity. */
export function getMachineId(): string {
	try {
		if (existsSync(MACHINE_ID_FILE)) {
			const id = readFileSync(MACHINE_ID_FILE, "utf-8").trim();
			if (id.length > 0) return id;
		}

		// Create directory if needed
		mkdirSync(MACHINE_ID_DIR, { recursive: true });

		const id = randomUUID();
		writeFileSync(MACHINE_ID_FILE, id, { encoding: "utf-8", mode: 0o600 });
		return id;
	} catch {
		// If anything fails (permissions, etc.), return a session-scoped ID.
		// This is better than crashing or sending no ID at all.
		return randomUUID();
	}
}

/**
 * OverlayMerger — merges cloud search results with local overlay results
 *
 * The merge strategy:
 *  1. Convert CloudSearchResult → SearchResult (with synthetic CodeChunk)
 *  2. Filter cloud results whose filePath is in dirtyFilePaths (belt-and-suspenders,
 *     since the cloud API should already have suppressed those paths)
 *  3. Normalise cloud scores and overlay scores independently to [0, 1]
 *     using min-max normalisation
 *  4. Tag each result with source: "cloud" | "overlay"
 *  5. Merge, sort by normalised score descending, slice to limit
 */

import type { SearchResult } from "../types.js";
import type { CloudSearchResult } from "./types.js";

// ============================================================================
// Types
// ============================================================================

export interface MergedSearchResult extends SearchResult {
	/** Whether this result came from the cloud index or the local overlay */
	source: "cloud" | "overlay";
}

// ============================================================================
// OverlayMerger
// ============================================================================

export class OverlayMerger {
	/**
	 * Merge cloud and overlay results into a single ranked list.
	 *
	 * @param cloudResults    Results from the cloud API (may already exclude dirty paths)
	 * @param overlayResults  Results from the local overlay index (dirty files only)
	 * @param dirtyFilePaths  Paths of dirty files (for belt-and-suspenders filtering)
	 * @param limit           Maximum number of results to return (default: 10)
	 */
	static merge(
		cloudResults: CloudSearchResult[],
		overlayResults: SearchResult[],
		dirtyFilePaths: string[],
		limit = 10,
	): MergedSearchResult[] {
		const dirtySet = new Set(dirtyFilePaths);

		// ── Step 1: Filter cloud results for dirty files ────────────────────
		const filteredCloud = cloudResults.filter((r) => !dirtySet.has(r.filePath));

		// ── Step 2: Convert cloud results → SearchResult ────────────────────
		const cloudAsSearchResults: Array<{
			result: SearchResult;
			rawScore: number;
		}> = filteredCloud.map((r) => ({
			result: cloudResultToSearchResult(r),
			rawScore: r.score,
		}));

		const overlayAsSearchResults: Array<{
			result: SearchResult;
			rawScore: number;
		}> = overlayResults.map((r) => ({
			result: r,
			rawScore: r.score,
		}));

		// ── Step 3: Handle fully empty case ──────────────────────────────────
		if (
			cloudAsSearchResults.length === 0 &&
			overlayAsSearchResults.length === 0
		) {
			return [];
		}

		// ── Step 4: Normalise scores independently ───────────────────────────
		//
		// Always normalise — even in single-source cases — so that:
		//  - A single result normalises to score 1.0
		//  - Identical scores all normalise to 1.0
		//  - Results are always sorted by normalised score
		const normaliseScores = (
			items: Array<{ result: SearchResult; rawScore: number }>,
		): number[] => {
			if (items.length === 0) return [];
			const scores = items.map((i) => i.rawScore);
			const min = Math.min(...scores);
			const max = Math.max(...scores);
			if (max === min) {
				// All identical (or single item) — normalise to 1.0
				return scores.map(() => 1.0);
			}
			return scores.map((s) => (s - min) / (max - min));
		};

		const cloudNormalised = normaliseScores(cloudAsSearchResults);
		const overlayNormalised = normaliseScores(overlayAsSearchResults);

		// ── Step 5: Tag and combine ──────────────────────────────────────────
		const tagged: MergedSearchResult[] = [];

		for (let i = 0; i < cloudAsSearchResults.length; i++) {
			tagged.push({
				...cloudAsSearchResults[i].result,
				score: cloudNormalised[i],
				source: "cloud",
			});
		}

		for (let i = 0; i < overlayAsSearchResults.length; i++) {
			tagged.push({
				...overlayAsSearchResults[i].result,
				score: overlayNormalised[i],
				source: "overlay",
			});
		}

		// ── Step 6: Sort by normalised score descending and slice ────────────
		tagged.sort((a, b) => b.score - a.score);
		return tagged.slice(0, limit);
	}
}

// ============================================================================
// Helpers
// ============================================================================

/**
 * Convert a CloudSearchResult into a SearchResult, constructing a synthetic
 * CodeChunk from the available metadata.
 *
 * Cloud results do not carry the full source text — the CodeChunk.content
 * is left empty. Callers that need source text should fetch it separately.
 */
function cloudResultToSearchResult(r: CloudSearchResult): SearchResult {
	return {
		chunk: {
			// Use contentHash as a stable ID (no position ambiguity for cloud chunks)
			id: r.contentHash,
			contentHash: r.contentHash,
			content: "", // Source text not available from cloud search response
			filePath: r.filePath,
			startLine: r.startLine,
			endLine: r.endLine,
			language: r.language,
			chunkType: r.chunkType as import("../types.js").ChunkType,
			name: r.name,
			fileHash: "", // Not available from cloud
		},
		score: r.score,
		vectorScore: r.score, // Cloud returns a combined score; use it for both
		keywordScore: 0,
		summary: r.summary,
	};
}

/**
 * OverlayIndex — local LanceDB index for uncommitted (dirty) files
 *
 * Layered on top of the cloud index to provide up-to-date search results
 * for files that have not yet been committed and uploaded. The overlay is
 * stored at `{projectPath}/.mnemex/overlay/` and uses the same
 * VectorStore + chunkFileByPath infrastructure as the main index.
 *
 * Staleness detection uses a SHA-256 fingerprint computed from each dirty
 * file's path and mtime. If the fingerprint changes (files modified, added,
 * or removed) the overlay is rebuilt automatically before search.
 */

import { createHash } from "node:crypto";
import {
	existsSync,
	readFileSync,
	statSync,
	unlinkSync,
	writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { chunkFileByPath } from "../core/chunker.js";
import { VectorStore } from "../core/store.js";
import { getParserManager } from "../parsers/parser-manager.js";
import type { IEmbeddingsClient, SearchResult } from "../types.js";
import type { DirtyFile, IOverlayIndex } from "./types.js";

// ============================================================================
// Options
// ============================================================================

export interface OverlayIndexOptions {
	/** Absolute path to the project root */
	projectPath: string;
	/**
	 * Directory where the overlay LanceDB database is stored.
	 * Typically `{projectPath}/.mnemex/overlay`.
	 */
	overlayDir: string;
	/** Embeddings client used to generate vectors for dirty file chunks */
	embeddingsClient: IEmbeddingsClient;
}

// ============================================================================
// OverlayIndex
// ============================================================================

export class OverlayIndex implements IOverlayIndex {
	private readonly projectPath: string;
	private readonly overlayDir: string;
	private readonly embeddingsClient: IEmbeddingsClient;
	private readonly fingerprintPath: string;
	private vectorStore: VectorStore;
	private initialized = false;

	constructor(options: OverlayIndexOptions) {
		this.projectPath = options.projectPath;
		this.overlayDir = options.overlayDir;
		this.embeddingsClient = options.embeddingsClient;
		this.fingerprintPath = join(options.overlayDir, ".fingerprint");
		this.vectorStore = new VectorStore(
			join(options.overlayDir, "vectors"),
			options.projectPath,
		);
	}

	// --------------------------------------------------------------------------
	// IOverlayIndex
	// --------------------------------------------------------------------------

	/**
	 * Check whether the overlay is stale given the current set of dirty files.
	 *
	 * Returns true if:
	 * - No fingerprint file exists (first use)
	 * - The computed fingerprint differs from the stored fingerprint
	 */
	async isStale(dirtyFiles: DirtyFile[]): Promise<boolean> {
		const current = this.computeFingerprint(dirtyFiles);
		if (!existsSync(this.fingerprintPath)) {
			return true;
		}
		try {
			const stored = readFileSync(this.fingerprintPath, "utf8").trim();
			return stored !== current;
		} catch {
			return true;
		}
	}

	/**
	 * Rebuild the overlay index from the provided dirty files.
	 *
	 * Steps:
	 *  1. Filter out deleted files (status === "deleted")
	 *  2. Read each file from disk, skip on error
	 *  3. Chunk via chunkFileByPath
	 *  4. Embed chunks
	 *  5. Clear existing overlay vectors
	 *  6. Write new chunks to LanceDB
	 *  7. Write new fingerprint file
	 */
	async rebuild(
		dirtyFiles: DirtyFile[],
		onProgress?: (msg: string) => void,
	): Promise<void> {
		const report = onProgress ?? (() => {});

		// Initialize parsers + store
		await this.ensureInitialized();

		const filesToProcess = dirtyFiles.filter((f) => f.status !== "deleted");
		report(
			`Overlay: rebuilding from ${filesToProcess.length} dirty file(s)...`,
		);

		// Collect chunks from all dirty files
		const allChunksWithContent: Array<{
			chunk: import("../types.js").CodeChunk;
			content: string;
		}> = [];

		for (const dirty of filesToProcess) {
			const absolutePath = join(this.projectPath, dirty.filePath);
			let source: string;
			try {
				source = readFileSync(absolutePath, "utf8");
			} catch {
				// File may have been removed between getDirtyFiles and rebuild
				continue;
			}

			const fileHash = createHash("sha256").update(source).digest("hex");
			const chunks = await chunkFileByPath(source, dirty.filePath, fileHash);
			for (const chunk of chunks) {
				allChunksWithContent.push({ chunk, content: chunk.content });
			}
		}

		report(
			`Overlay: collected ${allChunksWithContent.length} chunk(s), embedding...`,
		);

		// Clear existing overlay
		await this.vectorStore.clear();

		if (allChunksWithContent.length === 0) {
			// Nothing to index — write fingerprint and return
			this.writeFingerprint(dirtyFiles);
			report("Overlay: no chunks to index.");
			return;
		}

		// Embed all chunks
		const texts = allChunksWithContent.map((c) => c.content);
		const embedResult = await this.embeddingsClient.embed(texts);
		const vectors = embedResult.embeddings;

		// Build ChunkWithEmbedding objects
		const chunksWithEmbedding = allChunksWithContent.map((c, i) => ({
			...c.chunk,
			vector: vectors[i],
		}));

		// Write to LanceDB
		await this.vectorStore.addChunks(chunksWithEmbedding);

		// Persist fingerprint
		this.writeFingerprint(dirtyFiles);

		report(
			`Overlay: indexed ${chunksWithEmbedding.length} chunk(s) from ${filesToProcess.length} file(s).`,
		);
	}

	/** Search the overlay index */
	async search(
		queryVector: number[],
		queryText: string,
		limit?: number,
	): Promise<SearchResult[]> {
		await this.ensureInitialized();
		return this.vectorStore.search(queryText, queryVector, {
			limit: limit ?? 10,
		});
	}

	/** Return stats about the overlay contents */
	async getStats(): Promise<{ chunkCount: number; fileCount: number }> {
		await this.ensureInitialized();
		const stats = await this.vectorStore.getStats();
		return {
			chunkCount: stats.totalChunks,
			fileCount: stats.uniqueFiles,
		};
	}

	/**
	 * Invalidate the overlay by deleting the fingerprint file.
	 * The next call to isStale() will return true, forcing a rebuild.
	 */
	async invalidate(): Promise<void> {
		if (existsSync(this.fingerprintPath)) {
			try {
				unlinkSync(this.fingerprintPath);
			} catch {
				// Ignore errors (race condition or already deleted)
			}
		}
	}

	/** Release resources held by the overlay */
	async close(): Promise<void> {
		await this.vectorStore.close();
	}

	// --------------------------------------------------------------------------
	// Private helpers
	// --------------------------------------------------------------------------

	/**
	 * Ensure the vector store is initialized and parsers are ready.
	 * Idempotent — subsequent calls are no-ops.
	 */
	private async ensureInitialized(): Promise<void> {
		if (this.initialized) return;
		const parserManager = getParserManager();
		await parserManager.initialize();
		await this.vectorStore.initialize();
		this.initialized = true;
	}

	/**
	 * Compute a fingerprint for the current set of dirty files.
	 *
	 * The fingerprint is SHA-256 of the sorted list of
	 * `{filePath}:{mtimeMs}` pairs, so any file modification, addition,
	 * or removal changes the fingerprint.
	 *
	 * Deleted files (status === "deleted") do not have an mtime on disk;
	 * we include them with mtime "0" so that removing a file is still
	 * detected as a change.
	 */
	private computeFingerprint(dirtyFiles: DirtyFile[]): string {
		const parts = dirtyFiles
			.map((f) => {
				if (f.status === "deleted") {
					return `${f.filePath}:0`;
				}
				const absolutePath = join(this.projectPath, f.filePath);
				try {
					const mtime = statSync(absolutePath).mtimeMs;
					return `${f.filePath}:${mtime}`;
				} catch {
					return `${f.filePath}:0`;
				}
			})
			.sort();

		return createHash("sha256").update(parts.join("\n")).digest("hex");
	}

	/** Write the current fingerprint to disk

/**
 * CloudAwareSearch — orchestrates merged cloud + overlay search
 *
 * 7-step search flow:
 *  1. getDirtyFiles()                     → dirtyFiles
 *  2. overlayIndex.isStale(dirtyFiles)    → rebuild if stale
 *  3. embeddingsClient.embedOne(query)    → queryVector
 *  4a. cloudClient.search(...)            → cloudResults  ─┐ parallel
 *  4b. overlayIndex.search(...)           → overlayResults ─┘
 *  5. OverlayMerger.merge(...)            → merged results
 *  6. Return merged results
 *
 * Cloud errors are handled gracefully — if the cloud search fails the
 * method still returns overlay-only results (best-effort degradation).
 */

import type {
	IEmbeddingsClient,
	SearchOptions,
	SearchResult,
} from "../types.js";
import { type MergedSearchResult, OverlayMerger } from "./merger.js";
import type {
	DirtyFile,
	IChangeDetector,
	ICloudIndexClient,
	IOverlayIndex,
} from "./types.js";

// ============================================================================
// Options
// ============================================================================

export interface CloudSearchOptions {
	/** Absolute path to the project root */
	projectPath: string;
	/** Cloud API client (real or stub) */
	cloudClient: ICloudIndexClient;
	/** Local overlay index for dirty files */
	overlayIndex: IOverlayIndex;
	/** Git change detector */
	changeDetector: IChangeDetector;
	/** Embeddings client used to embed the query */
	embeddingsClient: IEmbeddingsClient;
	/** Repository slug used for cloud API calls */
	repoSlug: string;
	/** Current HEAD commit SHA used for cloud API calls */
	commitSha: string;
}

// ============================================================================
// CloudAwareSearch
// ============================================================================

export class CloudAwareSearch {
	private readonly projectPath: string;
	private readonly cloudClient: ICloudIndexClient;
	private readonly overlayIndex: IOverlayIndex;
	private readonly changeDetector: IChangeDetector;
	private readonly embeddingsClient: IEmbeddingsClient;
	private readonly repoSlug: string;
	private readonly commitSha: string;

	constructor(options: CloudSearchOptions) {
		this.projectPath = options.projectPath;
		this.cloudClient = options.cloudClient;
		this.overlayIndex = options.overlayIndex;
		this.changeDetector = options.changeDetector;
		this.embeddingsClient = options.embeddingsClient;
		this.repoSlug = options.repoSlug;
		this.commitSha = options.commitSha;
	}

	/**
	 * Run a merged cloud + overlay search.
	 *
	 * Never throws — returns best-effort results even when cloud is offline.
	 */
	async search(
		queryText: string,
		options: SearchOptions & { onProgress?: (msg: string) => void } = {},
	): Promise<MergedSearchResult[]> {
		const report = options.onProgress ?? (() => {});
		const limit = options.limit ?? 10;

		// ── Step 1: Get dirty files ──────────────────────────────────────────
		let dirtyFiles: DirtyFile[] = [];
		try {
			dirtyFiles = await this.changeDetector.getDirtyFiles();
		} catch (err) {
			// Non-fatal — treat as no dirty files
			report(`CloudAwareSearch: could not get dirty files: ${String(err)}`);
		}

		const dirtyFilePaths = dirtyFiles.map((f) => f.filePath);

		// ── Step 2: Rebuild overlay if stale ─────────────────────────────────
		try {
			const stale = await this.overlayIndex.isStale(dirtyFiles);
			if (stale) {
				report("CloudAwareSearch: overlay is stale, rebuilding...");
				await this.overlayIndex.rebuild(dirtyFiles, report);
			}
		} catch (err) {
			// Non-fatal — proceed without overlay
			report(`CloudAwareSearch: overlay rebuild failed: ${String(err)}`);
		}

		// ── Step 3: Embed query ───────────────────────────────────────────────
		let queryVector: number[];
		try {
			queryVector = await this.embeddingsClient.embedOne(queryText);
		} catch (err) {
			// Cannot search without a query vector
			report(`CloudAwareSearch: embedding failed: ${String(err)}`);
			return [];
		}

		// ── Step 4: Parallel cloud + overlay search ───────────────────────────
		// We request limit * 2 from each source so the merger has enough
		// candidates to fill the final limit after filtering dirty paths.
		const fetchLimit = limit * 2;

		const [cloudResults, overlayResults] = await Promise.all([
			// Cloud search (with graceful degradation)
			(async () => {
				try {
					return await this.cloudClient.search({
						repoSlug: this.repoSlug,
						commitSha: this.commitSha,
						queryText,
						queryVector,
						limit: fetchLimit,
						language: options.language,
						chunkType: options.chunkType,
					});
				} catch (err) {
					report(
						`CloudAwareSearch: cloud search failed (offline?): ${String(err)}`,
					);
					return [];
				}
			})(),
			// Overlay search (with graceful degradation)
			(async (): Promise<SearchResult[]> => {
				try {
					return await this.overlayIndex.search(
						queryVector,
						queryText,
						fetchLimit,
					);
				} catch (err) {
					report(`CloudAwareSearch: overlay search failed: ${String(err)}`);
					return [];
				}
			})(),
		]);

		// ── Step 5: Merge results ─────────────────────────────────────────────
		return OverlayMerger.merge(
			cloudResults,
			overlayResults,
			dirtyFilePaths,
			limit,
		);
	}
}

// ============================================================================
// Factory
// ============================================================================

/**
 * Create a CloudAwareSearch instance.
 */
export function createCloudAwareSearch(
	options: CloudSearchOptions,
): CloudAwareSearch {
	return new CloudAwareSearch(options);
}

/**
 * Server configuration for the mnemex cloud test server.
 */

export interface ServerConfig {
	/** HTTP port to listen on (default: 4510) */
	port: number;
	/** PostgreSQL connection string */
	databaseUrl: string;
	/** Embedding vector dimension (default: 8 for tests) */
	embeddingDim: number;
	/** Master API key from MASTER_API_KEY env var. undefined = auth disabled. */
	masterApiKey?: string;
}

/**
 * Load server config from environment variables with defaults.
 */
export function loadConfig(): ServerConfig {
	const databaseUrl = process.env.DATABASE_URL;
	if (!databaseUrl) {
		// No hardcoded fallback: a real connection string must never live in
		// source (it would leak the credential to git history and every fork).
		throw new Error(
			"DATABASE_URL is required. Set it in the environment; there is no default.",
		);
	}

	return {
		port: Number.parseInt(process.env.PORT ?? "4510", 10),
		databaseUrl,
		embeddingDim: Number.parseInt(process.env.EMBEDDING_DIM ?? "8", 10),
		masterApiKey: process.env.MASTER_API_KEY || undefined,
	};
}

/**
 * PostgreSQL database connection and helpers for the cloud test server.
 * Uses the `postgres` npm package (porsager/postgres).
 */

import postgres from "postgres";

export type Sql = postgres.Sql;
// TransactionSql is Omit<Sql, ...> but TypeScript drops call signatures from Omit.
// Use postgres.Sql as the transaction type — it's structurally compatible at runtime.
export type TxSql = postgres.Sql;

/**
 * Create a postgres connection pool.
 */
export function createDatabase(connectionString: string): Sql {
	return postgres(connectionString, {
		max: 10,
		idle_timeout: 30,
		connect_timeout: 30,
	});
}

/**
 * Truncate all tables for test isolation.
 */
export async function resetDatabase(sql: Sql): Promise<void> {
	await sql`TRUNCATE TABLE api_key_usage, api_keys, enrichment_docs, commit_files, commits, chunks, repos RESTART IDENTITY CASCADE`;
}

/**
 * POST /v1/chunks/check
 * Check which content hashes are already stored in the cloud.
 */

import type { RequestContext } from "../router.js";
import { json } from "../router.js";

const MAX_HASHES = 2000;

export async function check(ctx: RequestContext): Promise<Response> {
	let body: Record<string, unknown>;
	try {
		body = (await ctx.req.json()) as Record<string, unknown>;
	} catch {
		ctx.metrics.errorCode = "invalid_json";
		return json({ error: "invalid_json" }, 400);
	}

	const { hashes } = body;

	if (!Array.isArray(hashes)) {
		ctx.metrics.errorCode = "invalid_field";
		return json({ error: "invalid_field", field: "hashes" }, 400);
	}

	if (hashes.length > MAX_HASHES) {
		ctx.metrics.errorCode = "too_many_hashes";
		return json({ error: "too_many_hashes", max: MAX_HASHES }, 400);
	}

	// Extract correlation header — optional, missing on older clients.
	// Prefer X-Mnemex-* with legacy X-ClaudeMem-* fallback.
	const commitSha =
		ctx.req.headers.get("X-Mnemex-Commit-SHA") ??
		ctx.req.headers.get("X-ClaudeMem-Commit-SHA");
	if (commitSha) {
		ctx.metrics.commitSha = commitSha;
	}

	ctx.metrics.hashesChecked = hashes.length;

	if (hashes.length === 0) {
		ctx.metrics.hashesExisting = 0;
		ctx.metrics.hashesMissing = 0;
		return json({ existing: [], missing: [] });
	}

	// Query which hashes already exist
	const rows = await ctx.sql<{ content_hash: string }[]>`
		SELECT content_hash
		FROM chunks
		WHERE content_hash = ANY(${hashes}::text[])
	`;

	const existingSet = new Set(rows.map((r) => r.content_hash));
	const existing: string[] = [];
	const missing: string[] = [];

	for (const hash of hashes) {
		if (typeof hash === "string") {
			if (existingSet.has(hash)) {
				existing.push(hash);
			} else {
				missing.push(hash);
			}
		}
	}

	ctx.metrics.hashesExisting = existing.length;
	ctx.metrics.hashesMissing = missing.length;

	return json({ existing, missing });
}

/**
 * POST /v1/index
 * Upload chunk index for a commit. Handles thin mode (with vectors) and
 * smart mode (text only). Inherits unchanged files from parent commits.
 */

import type { UploadChunk, UploadIndexRequest } from "../../types.js";
import type { Sql } from "../db.js";
import type { RequestContext } from "../router.js";
import { json } from "../router.js";

export async function uploadIndex(ctx: RequestContext): Promise<Response> {
	let body: UploadIndexRequest;
	try {
		body = (await ctx.req.json()) as UploadIndexRequest;
	} catch {
		ctx.metrics.errorCode = "invalid_json";
		return json({ error: "invalid_json" }, 400);
	}

	const {
		orgSlug,
		repoSlug,
		commitSha,
		parentShas,
		chunks,
		deletedFiles = [],
		mode,
		enrichmentDocs = [],
	} = body;

	// Validate required fields
	if (!orgSlug || !repoSlug || !commitSha || !mode) {
		ctx.metrics.errorCode = "missing_field";
		return json({ error: "missing_field" }, 400);
	}

	if (!/^[0-9a-f]{40}$/i.test(commitSha)) {
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.errorCode = "invalid_field";
		return json({ error: "invalid_field", field: "commitSha" }, 422);
	}

	if (mode !== "thin" && mode !== "smart") {
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.errorCode = "invalid_field";
		return json({ error: "invalid_field", field: "mode" }, 422);
	}

	// Run everything in a transaction
	let result: {
		commitId: number;
		status: string;
		newChunks: number;
		deduplicatedChunks: number;
	};

	try {
		// TransactionSql from postgres is Omit<Sql, ...> which loses call signatures
		// in TypeScript. Cast to Sql to use tagged template literals.
		result = await ctx.sql.begin(
			async (
				txRaw: unknown,
			): Promise<{
				commitId: number;
				status: string;
				newChunks: number;
				deduplicatedChunks: number;
			}> => {
				const sql = txRaw as Sql;
				return runTransaction(
					sql,
					orgSlug,
					repoSlug,
					commitSha,
					parentShas,
					chunks,
					deletedFiles,
					mode,
					enrichmentDocs,
				);
			},
		);
	} catch (err) {
		const e = err as {
			httpStatus?: number;
			errorCode?: string;
			expected?: number;
			received?: number;
			message?: string;
		};
		if (e.httpStatus) {
			ctx.metrics.orgSlug = orgSlug;
			ctx.metrics.repoSlug = repoSlug;
			ctx.metrics.commitSha = commitSha;
			ctx.metrics.mode = mode;
			ctx.metrics.errorCode = e.errorCode ?? "error";
			return json(
				{
					error: e.errorCode ?? "error",
					expected: e.expected,
					received: e.received,
					message: e.message,
				},
				e.httpStatus,
			);
		}
		console.error("[index-handler] Transaction error:", err);
		const message = err instanceof Error ? err.message : String(err);
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.commitSha = commitSha;
		ctx.metrics.errorCode = "internal_error";
		return json({ error: "internal_error", message }, 500);
	}

	// Count total files after commit for inherited count
	const inheritedResult = await ctx.sql<{ count: string }[]>`
		SELECT COUNT(*) AS count
		FROM commit_files
		WHERE commit_id = ${result.commitId}
	`;
	const totalFiles = Number.parseInt(inheritedResult[0]?.count ?? "0", 10);
	const changedFileCount = new Set(chunks.map((c) => c.filePath)).size;
	const inheritedFiles = Math.max(0, totalFiles - changedFileCount);

	const responseBody: Record<string, unknown> = {
		ok: true,
		commitSha,
		status: result.status,
		chunksAdded: result.newChunks,
		chunksDeduplicated: result.deduplicatedChunks,
		chunksStored: result.newChunks,
		chunksDeduped: result.deduplicatedChunks,
		inheritedFiles,
	};

	if (mode === "smart") {
		const estimatedReadyAt = new Date(
			Date.now() + result.newChunks * 50,
		).toISOString();
		responseBody.pendingChunks = result.newChunks;
		responseBody.estimatedReadyAt = estimatedReadyAt;
	}

	// Telemetry for the index upload
	ctx.metrics.orgSlug = orgSlug;
	ctx.metrics.repoSlug = repoSlug;
	ctx.metrics.commitSha = commitSha;
	ctx.metrics.mode = mode;
	ctx.metrics.chunksTotal = chunks.length;
	ctx.metrics.chunksNew = result.newChunks;
	ctx.metrics.chunksDeduped = result.deduplicatedChunks;
	ctx.metrics.filesChanged = changedFileCount;
	ctx.metrics.filesInherited = inheritedFiles;

	return json(responseBody, 202);
}

// ============================================================================
// Transaction implementation
// ============================================================================

async function runTransaction(
	sql: Sql,
	orgSlug: string,
	repoSlug: string,
	commitSha: string,
	parentShas: string[],
	chunks: UploadChunk[],
	deletedFiles: string[],
	mode: "thin" | "smart",
	enrichmentDocs: import("../../types.js").CloudEnrichmentDoc[],
): Promise<{
	commitId: number;
	status: string;
	newChunks: number;
	deduplicatedChunks: number;
}> {
	// Step 1 — resolve repo
	const repos = await sql<{ repo_id: number; embedding_dim: number }[]>`
		SELECT r.id AS repo_id, r.embedding_dim
		FROM repos r
		JOIN orgs o ON r.org_id = o.id
		WHERE o.slug = ${orgSlug} AND r.slug = ${repoSlug}
		LIMIT 1
	`;

	if (repos.length === 0) {
		throw Object.assign(new Error("repo_not_found"), {
			httpStatus: 404,
			errorCode: "repo_not_found",
		});
	}

	const { repo_id: repoId, embedding_dim: embeddingDim } = repos[0]!;

	// Validate dimensions for thin mode
	if (mode === "thin") {
		for (const chunk of chunks) {
			if (chunk.vector && chunk.vector.length !== embeddingDim) {
				throw Object.assign(
					new Error(
						`Dimension mismatch: expected ${embeddingDim}, got ${chunk.vector.length}`,
					),
					{
						httpStatus: 422,
						errorCode: "dimension_mismatch",
						expected: embeddingDim,
						received: chunk.vector.length,
					},
				);
			}
		}
	}

	// Step 2 — advisory lock (idempotency guard)
	await sql`SELECT pg_advisory_xact_lock(hashtext(${`${String(repoId)}:${commitSha}`}))`;

	// Step 3 — upsert commit record
	const insertedCommits = await sql<{ id: number; status: string }[]>`
		INSERT INTO commits (repo_id, sha, parent_shas, status)
		VALUES (${repoId}, ${commitSha}, ${parentShas}, 'pending')
		ON CONFLICT (repo_id, sha) DO NOTHING
		RETURNING id, status
	`;

	let commitId: number;
	let commitStatus: string;

	if (insertedCommits.length > 0) {
		commitId = insertedCommits[0]?.id;
		commitStatus = insertedCommits[0]?.status;
	} else {
		// Already exists
		const existing = await sql<{ id: number; status: string }[]>`
			SELECT id, status FROM commits
			WHERE repo_id = ${repoId} AND sha = ${commitSha}
			LIMIT 1
		`;
		commitId = existing[0]?.id;
		commitStatus = existing[0]?.status;
	}

	// If already ready, return early (idempotent)
	if (commitStatus === "ready") {
		return {
			commitId,
			status: "ready",
			newChunks: 0,
			deduplicatedChunks: 0,
		};
	}

	// Step 4 — insert chunk metadata (content-addressed)
	let newChunks = 0;
	let deduplicatedChunks = 0;

	if (chunks.length > 0) {
		for (const c of chunks) {
			const insertResult = await sql<{ content_hash: string }[]>`
				INSERT INTO chunks (
					content_hash, file_path, start_line, end_line,
					name, kind, chunk_type, language, text
				)
				VALUES (
					${c.contentHash},
					${c.filePath},
					${c.startLine},
					${c.endLine},
					${c.name ?? null},
					${c.chunkType},
					${c.chunkType},
					${c.language},
					${mode === "smart" ? (c.text ?? null) : null}
				)
				ON CONFLICT (content_hash) DO NOTHING
				RETURNING content_hash
			`;
			if (insertResult.length > 0) {
				newChunks++;
			} else {
				deduplicatedChunks++;
			}
		}

		// Step 5 — store vectors (thin mode)
		if (mode === "thin") {
			for (const chunk of chunks) {
				if (chunk.vector && chunk.vector.length > 0) {
					const vecStr = `[${chunk.vector.join(",")}]`;
					await sql`
						UPDATE chunks
						SET vector = ${vecStr}::vector
						WHERE content_hash = ${chunk.contentHash} AND vector IS NULL
					`;
				}
			}
		}
	}

	// Step 6 — insert com

/**
 * API key management handlers.
 *
 * POST   /v1/keys         — createKey
 * GET    /v1/keys         — listKeys
 * DELETE /v1/keys/:keyId  — deleteKey
 *
 * All endpoints require master key (enforced by authMiddleware before reaching here).
 */

import { createHash, randomBytes } from "node:crypto";
import type { RequestContext } from "../router.js";
import { json } from "../router.js";

// ============================================================================
// Key generation
// ============================================================================

function generateApiKey(): { key: string; hash: string; prefix: string } {
	const raw = randomBytes(16).toString("hex"); // 32 hex chars
	const key = `cmem_${raw}`; // e.g. cmem_a1b2c3d4e5f6...
	const hash = createHash("sha256").update(key).digest("hex");
	const prefix = raw.slice(0, 8); // first 8 hex chars of random part
	return { key, hash, prefix };
}

// ============================================================================
// Handlers
// ============================================================================

/**
 * POST /v1/keys — Create a new API key.
 * Returns the full secret once (not stored in DB after this point).
 */
export async function createKey(ctx: RequestContext): Promise<Response> {
	let body: Record<string, unknown>;
	try {
		body = (await ctx.req.json()) as Record<string, unknown>;
	} catch {
		return json({ error: "invalid_json" }, 400);
	}

	const name = typeof body.name === "string" ? body.name.trim() : "";
	if (!name) {
		return json({ error: "missing_field", field: "name" }, 400);
	}

	const { key, hash, prefix } = generateApiKey();

	const rows = await ctx.sql<{ id: number; created_at: Date }[]>`
		INSERT INTO api_keys (key_hash, key_prefix, name)
		VALUES (${hash}, ${prefix}, ${name})
		RETURNING id, created_at
	`;
	const row = rows[0]!;

	return json(
		{
			ok: true,
			key: {
				id: row.id,
				name,
				prefix,
				createdAt: row.created_at.toISOString(),
				lastUsedAt: null,
				isActive: true,
			},
			secret: key,
		},
		201,
	);
}

/**
 * GET /v1/keys — List all API keys with usage stats.
 */
export async function listKeys(ctx: RequestContext): Promise<Response> {
	const keys = await ctx.sql<
		{
			id: number;
			name: string;
			key_prefix: string;
			created_at: Date;
			last_used_at: Date | null;
			is_active: boolean;
		}[]
	>`
		SELECT id, name, key_prefix, created_at, last_used_at, is_active
		FROM api_keys
		ORDER BY created_at DESC
	`;

	// Aggregate usage per key in one query
	const keyIds = keys.map((k) => k.id);
	const usageRows =
		keyIds.length > 0
			? await ctx.sql<{ key_id: number; endpoint: string; cnt: string }[]>`
			SELECT key_id, endpoint, COUNT(*)::text AS cnt
			FROM api_key_usage
			WHERE key_id = ANY(${keyIds}::int[])
			GROUP BY key_id, endpoint
		`
			: [];

	// Build usage map
	const usageMap = new Map<
		number,
		{ total: number; byEndpoint: Record<string, number> }
	>();
	for (const row of usageRows) {
		const entry = usageMap.get(row.key_id) ?? {
			total: 0,
			byEndpoint: {} as Record<string, number>,
		};
		const cnt = Number.parseInt(row.cnt, 10);
		entry.total += cnt;
		entry.byEndpoint[row.endpoint] = cnt;
		usageMap.set(row.key_id, entry);
	}

	return json({
		keys: keys.map((k) => ({
			id: k.id,
			name: k.name,
			prefix: k.key_prefix,
			createdAt: k.created_at.toISOString(),
			lastUsedAt: k.last_used_at?.toISOString() ?? null,
			isActive: k.is_active,
			usage: usageMap.get(k.id) ?? { total: 0, byEndpoint: {} },
		})),
	});
}

/**
 * DELETE /v1/keys/:keyId — Hard delete an API key.
 * Usage rows cascade via FK ON DELETE CASCADE.
 */
export async function deleteKey(ctx: RequestContext): Promise<Response> {
	const keyId = Number.parseInt(ctx.params.keyId ?? "", 10);
	if (!Number.isFinite(keyId)) {
		return json({ error: "invalid_param" }, 400);
	}

	const result = await ctx.sql<{ id: number }[]>`
		DELETE FROM api_keys WHERE id = ${keyId} RETURNING id
	`;

	if (result.length === 0) {
		return json({ error: "not_found" }, 404);
	}

	return json({ ok: true, deleted: true });
}

/**
 * POST /v1/repos/:orgSlug/:repoSlug/register
 * Register a repository. Idempotent — calling twice with same params succeeds.
 * Returns 409 if called with a different embeddingModel for an existing repo.
 */

import type { RequestContext } from "../router.js";
import { json } from "../router.js";

export async function register(ctx: RequestContext): Promise<Response> {
	const { orgSlug, repoSlug } = ctx.params;

	if (!orgSlug || !repoSlug) {
		ctx.metrics.errorCode = "missing_param";
		return json({ error: "missing_param" }, 400);
	}

	let body: Record<string, unknown>;
	try {
		body = (await ctx.req.json()) as Record<string, unknown>;
	} catch {
		ctx.metrics.errorCode = "invalid_json";
		return json({ error: "invalid_json" }, 400);
	}

	const embeddingModel =
		typeof body.embeddingModel === "string"
			? body.embeddingModel
			: "synthetic-8d";
	const embeddingDim =
		typeof body.embeddingDim === "number" ? body.embeddingDim : 8;

	if (!Number.isInteger(embeddingDim) || embeddingDim <= 0) {
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.errorCode = "invalid_field";
		return json({ error: "invalid_field", field: "embeddingDim" }, 400);
	}

	// Auto-create org if it doesn't exist (no auth = no pre-seeding)
	const orgs = await ctx.sql<{ id: number }[]>`
		INSERT INTO orgs (slug)
		VALUES (${orgSlug})
		ON CONFLICT (slug) DO UPDATE SET slug = EXCLUDED.slug
		RETURNING id
	`;
	const orgId = orgs[0]!.id;

	// Try to insert repo (ON CONFLICT DO NOTHING for idempotency)
	const inserted = await ctx.sql<
		{ id: number; embedding_model: string; embedding_dim: number }[]
	>`
		INSERT INTO repos (org_id, slug, embedding_model, embedding_dim)
		VALUES (${orgId}, ${repoSlug}, ${embeddingModel}, ${embeddingDim})
		ON CONFLICT (org_id, slug) DO NOTHING
		RETURNING id, embedding_model, embedding_dim
	`;

	let repoId: number;
	let existingModel: string;
	let existingDim: number;

	if (inserted.length > 0) {
		repoId = inserted[0]!.id;
		existingModel = inserted[0]!.embedding_model;
		existingDim = inserted[0]!.embedding_dim;
	} else {
		// Already exists — fetch to check for conflicts
		const existing = await ctx.sql<
			{ id: number; embedding_model: string; embedding_dim: number }[]
		>`
			SELECT id, embedding_model, embedding_dim
			FROM repos
			WHERE org_id = ${orgId} AND slug = ${repoSlug}
			LIMIT 1
		`;

		if (existing.length === 0) {
			ctx.metrics.orgSlug = orgSlug;
			ctx.metrics.repoSlug = repoSlug;
			ctx.metrics.errorCode = "internal_error";
			return json({ error: "internal_error" }, 500);
		}

		repoId = existing[0]!.id;
		existingModel = existing[0]!.embedding_model;
		existingDim = existing[0]!.embedding_dim;

		if (existingModel !== embeddingModel) {
			ctx.metrics.orgSlug = orgSlug;
			ctx.metrics.repoSlug = repoSlug;
			ctx.metrics.errorCode = "embedding_model_mismatch";
			return json(
				{
					error: "embedding_model_mismatch",
					existing: existingModel,
					requested: embeddingModel,
				},
				409,
			);
		}
		if (existingDim !== embeddingDim) {
			ctx.metrics.orgSlug = orgSlug;
			ctx.metrics.repoSlug = repoSlug;
			ctx.metrics.errorCode = "embedding_dim_mismatch";
			return json(
				{
					error: "embedding_dim_mismatch",
					existing: existingDim,
					requested: embeddingDim,
				},
				409,
			);
		}
	}

	ctx.metrics.orgSlug = orgSlug;
	ctx.metrics.repoSlug = repoSlug;
	return json({
		ok: true,
		created: inserted.length > 0,
		repoId,
		repoSlug,
		orgSlug,
		embeddingModel: existingModel ?? embeddingModel,
		embeddingDim: existingDim ?? embeddingDim,
	});
}

/**
 * POST /v1/search
 * Semantic vector search against a commit's indexed chunks using pgvector.
 */

import type { CloudSearchRequest, CloudSearchResult } from "../../types.js";
import type { RequestContext } from "../router.js";
import { json } from "../router.js";

export async function search(ctx: RequestContext): Promise<Response> {
	let body: CloudSearchRequest;
	try {
		body = (await ctx.req.json()) as CloudSearchRequest;
	} catch {
		ctx.metrics.errorCode = "invalid_json";
		return json({ error: "invalid_json" }, 400);
	}

	const {
		repoSlug: rawRepoSlug,
		commitSha,
		queryVector,
		queryText = "",
		limit: rawLimit,
		language,
		chunkType,
		suppressPaths = [],
	} = body as CloudSearchRequest & { suppressPaths?: string[] };

	if (!rawRepoSlug || !commitSha) {
		ctx.metrics.errorCode = "missing_field";
		return json({ error: "missing_field" }, 400);
	}

	// queryVector is required for vector search
	if (!queryVector || !Array.isArray(queryVector)) {
		ctx.metrics.errorCode = "missing_field";
		return json({ error: "missing_field", field: "queryVector" }, 400);
	}

	const limit = Math.min(rawLimit ?? 10, 100);

	// repoSlug may be "orgSlug/repoSlug" or just "repoSlug"
	const slashIdx = rawRepoSlug.indexOf("/");
	let orgSlug: string;
	let repoSlug: string;
	if (slashIdx !== -1) {
		orgSlug = rawRepoSlug.slice(0, slashIdx);
		repoSlug = rawRepoSlug.slice(slashIdx + 1);
	} else {
		ctx.metrics.errorCode = "invalid_field";
		return json(
			{
				error: "invalid_field",
				field: "repoSlug",
				expected: "orgSlug/repoSlug",
			},
			400,
		);
	}

	// Step 1 — resolve repo and commit
	const repoCommit = await ctx.sql<
		{
			repo_id: number;
			embedding_dim: number;
			commit_id: number;
			status: string;
		}[]
	>`
		SELECT r.id AS repo_id, r.embedding_dim, c.id AS commit_id, c.status
		FROM repos r
		JOIN orgs o ON r.org_id = o.id
		JOIN commits c ON c.repo_id = r.id
		WHERE o.slug = ${orgSlug}
		  AND r.slug = ${repoSlug}
		  AND c.sha = ${commitSha}
		LIMIT 1
	`;

	if (repoCommit.length === 0) {
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.commitSha = commitSha;
		ctx.metrics.errorCode = "commit_not_found";
		return json({ error: "commit_not_found" }, 404);
	}

	const {
		repo_id: _repoId,
		embedding_dim: embeddingDim,
		commit_id: commitId,
		status,
	} = repoCommit[0]!;

	// Validate query vector dimension
	if (queryVector.length !== embeddingDim) {
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.commitSha = commitSha;
		ctx.metrics.queryDim = queryVector.length;
		ctx.metrics.errorCode = "dimension_mismatch";
		return json(
			{
				error: "dimension_mismatch",
				expected: embeddingDim,
				received: queryVector.length,
			},
			422,
		);
	}

	if (status !== "ready") {
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.commitSha = commitSha;
		ctx.metrics.errorCode = "commit_not_ready";
		return json({ error: "commit_not_ready", status }, 409);
	}

	const startMs = Date.now();

	// Format query vector for pgvector
	const vecStr = `[${queryVector.join(",")}]`;

	// Vector search combining commit_files and chunks
	const suppressPathsArray = suppressPaths.length > 0 ? suppressPaths : null;

	let rows: {
		content_hash: string;
		file_path: string;
		chunk_type: string;
		name: string | null;
		language: string;
		start_line: number;
		end_line: number;
		summary: string | null;
		score: number;
	}[];

	if (suppressPathsArray) {
		rows = await ctx.sql<typeof rows>`
			SELECT
				ch.content_hash,
				cf_map.file_path,
				COALESCE(ch.chunk_type, ch.kind, 'unknown') AS chunk_type,
				ch.name,
				COALESCE(ch.language, 'unknown') AS language,
				ch.start_line,
				ch.end_line,
				ed.content AS summary,
				1 - (ch.vector <=> ${vecStr}::vector) AS score
			FROM chunks ch
			JOIN (
				SELECT DISTINCT cf.file_path, UNNEST(cf.chunk_hashes) AS content_hash
				FROM commit_files cf
				WHERE cf.commit_id = ${commitId}
				  AND cf.file_path != ALL(${suppressPathsArray}::text[])
			) AS cf_map ON cf_map.content_hash = ch.content_hash
			LEFT JOIN enrichment_docs ed
				ON ed.content_hash = ch.content_hash AND ed.doc_type = 'symbol_summary'
			WHERE ch.vector IS NOT NULL
			  AND (${language ?? null}::text IS NULL OR ch.language = ${language ?? null})
			  AND (${chunkType ?? null}::text IS NULL OR ch.chunk_type = ${chunkType ?? null})
			ORDER BY ch.vector <=> ${vecStr}::vector
			LIMIT ${limit}
		`;
	} else {
		rows = await ctx.sql<typeof rows>`
			SELECT
				ch.content_hash,
				cf_map.file_path,
				COALESCE(ch.chunk_type, ch.kind, 'unknown') AS chunk_type,
				ch.name,
				COALESCE(ch.language, 'unknown') AS language,
				ch.start_line,
				ch.end_line,
				ed.content AS summary,
				1 - (ch.vector <=> ${vecStr}::vector) AS score
			FROM chunks ch
			JOIN (
				SELECT DISTINCT cf.file_path, UNNEST(cf.chunk_hashes) AS content_hash
				FROM commit_files cf
				WHERE cf.commit_id = ${commitId}
			) AS cf_map ON cf_map.content_hash = ch.content_hash
			LEFT JOIN enrichment_docs ed
				ON ed.content_hash = ch.content_hash AND ed.doc_type = 'symbol_summary'
			WHERE ch.vector IS NOT NULL
			  AND (${language ?? null}::text IS NULL OR ch.language = ${language ?? null})
			  AND (${chunkType ?? null}::text IS NULL OR ch.chunk_type = ${chunkType ?? null})
			ORDER BY ch.vector <=> ${vecStr}::vector
			LIMIT ${limit}
		`;
	}

	const searchDurationMs = Date.now() - startMs;

	// Suppress queryText warning — only used for BM25 which isn't implemented
	void queryText;

	const results: CloudSearchResult[] = rows.map((row) => ({
		contentHash: row.content_hash,
		filePath: row.file_path,
		startLine: row.start_line,
		endLine: row.end_line,
		language: row.language,
		chunkType: row.chunk_type,
		name: row.name ?? undefined,
		score:
			typeof row.score === "number"
				? row.score
				: Number.parseFloat(String(row.score)),
		summary: row.summary ?? undefined,
	}));

	// Populate telemetry before returning
	ctx.metrics.orgSlug = orgSlug;
	ctx.metrics.repoSlug = repoSlug;
	ctx.metrics.commitSha = commitSha;
	ctx.metrics.queryDim = queryVector.length;
	ctx.metrics.resultsReturned = results.length;
	ctx.metrics.searchMs = searchDurationMs;

	return json(results);
}

/**
 * GET /v1/commits/:sha/status?repo=orgSlug/repoSlug
 * Get the indexing status of a specific commit.
 */

import type { CommitStatus } from "../../types.js";
import type { RequestContext } from "../router.js";
import { json } from "../router.js";

export async function getStatus(ctx: RequestContext): Promise<Response> {
	const { sha } = ctx.params;

	if (!sha) {
		ctx.metrics.errorCode = "missing_param";
		return json({ error: "missing_param", param: "sha" }, 400);
	}

	const repoParam = ctx.query.get("repo");
	if (!repoParam) {
		ctx.metrics.errorCode = "missing_param";
		return json({ error: "missing_param", param: "repo" }, 400);
	}

	// repo is in "orgSlug/repoSlug" format
	const slashIdx = repoParam.indexOf("/");
	if (slashIdx === -1) {
		ctx.metrics.errorCode = "invalid_param";
		return json(
			{ error: "invalid_param", param: "repo", expected: "orgSlug/repoSlug" },
			400,
		);
	}

	const orgSlug = repoParam.slice(0, slashIdx);
	const repoSlug = repoParam.slice(slashIdx + 1);

	// Resolve repo
	const repos = await ctx.sql<{ repo_id: number }[]>`
		SELECT r.id AS repo_id
		FROM repos r
		JOIN orgs o ON r.org_id = o.id
		WHERE o.slug = ${orgSlug} AND r.slug = ${repoSlug}
		LIMIT 1
	`;

	if (repos.length === 0) {
		// Return not_found as a valid status (per architecture: HTTP 200 not 404)
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.commitSha = sha;
		ctx.metrics.commitStatus = "not_found";
		const response: CommitStatus = {
			commitSha: sha,
			status: "not_found",
		};
		return json(response);
	}

	const repoId = repos[0]?.repo_id;

	// Get commit status
	const commits = await ctx.sql<
		{
			status: string;
			indexed_at: Date | null;
			file_count: string;
			chunk_count: string;
		}[]
	>`
		SELECT
			c.status,
			c.indexed_at,
			(SELECT COUNT(*) FROM commit_files cf WHERE cf.commit_id = c.id)::text AS file_count,
			(
				SELECT COUNT(DISTINCT h)::text
				FROM commit_files cf,
				     LATERAL UNNEST(cf.chunk_hashes) AS h
				WHERE cf.commit_id = c.id
			) AS chunk_count
		FROM commits c
		WHERE c.repo_id = ${repoId} AND c.sha = ${sha}
		LIMIT 1
	`;

	if (commits.length === 0) {
		ctx.metrics.orgSlug = orgSlug;
		ctx.metrics.repoSlug = repoSlug;
		ctx.metrics.commitSha = sha;
		ctx.metrics.commitStatus = "not_found";
		const response: CommitStatus = {
			commitSha: sha,
			status: "not_found",
		};
		return json(response);
	}

	const commit = commits[0]!;
	ctx.metrics.orgSlug = orgSlug;
	ctx.metrics.repoSlug = repoSlug;
	ctx.metrics.commitSha = sha;
	ctx.metrics.commitStatus = commit.status;

	const response: CommitStatus = {
		commitSha: sha,
		status: commit.status as CommitStatus["status"],
		indexedAt: commit.indexed_at?.toISOString(),
		chunkCount: Number.parseInt(commit.chunk_count, 10),
	};

	return json(response);
}

/**
 * Entry point for the mnemex cloud test server.
 * Uses Bun.serve() for HTTP handling. No authentication.
 */

import { loadConfig, type ServerConfig } from "./config.js";
import { createDatabase, type Sql } from "./db.js";
import {
	authMiddleware,
	runMiddleware,
	versionMiddleware,
} from "./middleware.js";
import { type RequestContext, router } from "./router.js";

let server: ReturnType<typeof Bun.serve> | null = null;
let db: Sql | null = null;

/**
 * Start the HTTP server.
 * Returns the server instance and a base URL string.
 */
export async function startServer(
	config?: Partial<ServerConfig>,
): Promise<{ baseUrl: string; stop: () => Promise<void> }> {
	const fullConfig = { ...loadConfig(), ...config };
	db = createDatabase(fullConfig.databaseUrl);

	const sql = db;
	const cfg = fullConfig;

	server = Bun.serve({
		port: fullConfig.port,
		fetch: async (req: Request): Promise<Response> => {
			const url = new URL(req.url);
			const startMs = Date.now();

			const ctx: RequestContext = {
				req,
				method: req.method,
				pathname: url.pathname,
				params: {},
				query: url.searchParams,
				sql,
				config: cfg,
				metrics: {},
			};

			let response: Response;
			try {
				// Run middleware chain: auth first, then version check
				const middlewareResult = await runMiddleware(ctx, [
					authMiddleware,
					versionMiddleware,
				]);

				if (middlewareResult !== null) {
					response = middlewareResult;
				} else {
					response = await router(ctx);
				}
			} catch (err) {
				console.error("[server] Fatal error:", err);
				const message = err instanceof Error ? err.message : String(err);
				ctx.metrics.errorCode = "internal_error";
				response = new Response(
					JSON.stringify({ error: "internal_error", message }),
					{
						status: 500,
						headers: { "Content-Type": "application/json" },
					},
				);
			}

			// Fire-and-forget usage tracking for regular API keys
			if (ctx.metrics.apiKeyId !== undefined) {
				const endpoint = `${req.method} ${url.pathname}`;
				const keyId = ctx.metrics.apiKeyId;
				const responseStatus = response.status;
				sql`INSERT INTO api_key_usage (key_id, endpoint, status_code)
					VALUES (${keyId}, ${endpoint}, ${responseStatus})`
					.then(() => {
						return sql`UPDATE api_keys SET last_used_at = now()
							WHERE id = ${keyId}`.execute();
					})
					.catch(() => {}); // swallow errors — never block response
			}

			const durationMs = Date.now() - startMs;

			// Slow request detection — must run before primary log
			const slowThresholds: Record<string, number> = {
				"POST /v1/index": 5000,
				"POST /v1/search": 2000,
				"POST /v1/chunks/check": 1000,
			};
			const routeKey = `${req.method} ${url.pathname}`;
			const threshold = slowThresholds[routeKey];
			if (threshold !== undefined && durationMs > threshold) {
				ctx.metrics.slow = true;
			}

			const logEntry = {
				ts: new Date().toISOString(),
				method: req.method,
				path: url.pathname,
				status: response.status,
				ms: durationMs,
				...ctx.metrics,
			};
			console.log(JSON.stringify(logEntry));

			return response;
		},
	});

	const baseUrl = `http://localhost:${fullConfig.port}`;
	console.log(`[server] Started at ${baseUrl}`);

	return {
		baseUrl,
		stop: async () => {
			await stopServer();
		},
	};
}

/**
 * Stop the server and close the database connection.
 */
export async function stopServer(): Promise<void> {
	if (server) {
		server.stop();
		server = null;
	}
	if (db) {
		await db.end();
		db = null;
	}
}

/**
 * Get the current database connection (for test harness use).
 */
export function getDb(): Sql | null {
	return db;
}

/**
 * Standalone entry point for the mnemex cloud server.
 * Runs schema migration on boot, then starts the HTTP server.
 */

import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { loadConfig } from "./config.js";
import { createDatabase } from "./db.js";
import { startServer } from "./index.js";

async function main() {
	const config = loadConfig();

	// Run schema migration (retry up to 3 times for Neon cold-start)
	console.log("[boot] Running schema migration...");
	const schemaPath = resolve(
		dirname(new URL(import.meta.url).pathname),
		"schema.sql",
	);
	const schema = readFileSync(schemaPath, "utf-8");
	for (let attempt = 1; attempt <= 3; attempt++) {
		const migrationSql = createDatabase(config.databaseUrl);
		try {
			await migrationSql.unsafe(schema);
			console.log("[boot] Schema migration complete.");
			break;
		} catch (err) {
			console.error(`[boot] Migration attempt ${attempt}/3 failed:`, err);
			if (attempt === 3) {
				console.error(
					"[boot] All migration attempts failed, starting server anyway (tables may already exist).",
				);
			} else {
				await new Promise((r) => setTimeout(r, 3000));
			}
		} finally {
			await migrationSql.end();
		}
	}

	// Start server
	const { baseUrl } = await startServer(config);
	console.log(`[boot] Server ready at ${baseUrl}`);

	// Database usage snapshots — emit every 60 minutes as a structured log line
	const SNAPSHOT_INTERVAL_MS = 60 * 60 * 1000; // 1 hour

	async function emitDbSnapshot(): Promise<void> {
		const snapshotSql = createDatabase(config.databaseUrl);
		try {
			const rows = await snapshotSql<
				{
					total_chunks: string;
					total_commits: string;
					total_repos: string;
					total_orgs: string;
					total_enrichment_docs: string;
				}[]
			>`
				SELECT
					(SELECT COUNT(*) FROM chunks)::text AS total_chunks,
					(SELECT COUNT(*) FROM commits)::text AS total_commits,
					(SELECT COUNT(*) FROM repos)::text AS total_repos,
					(SELECT COUNT(*) FROM orgs)::text AS total_orgs,
					(SELECT COUNT(*) FROM enrichment_docs)::text AS total_enrichment_docs
			`;
			const snap = rows[0];
			if (snap) {
				console.log(
					JSON.stringify({
						type: "db_snapshot",
						ts: new Date().toISOString(),
						totalChunks: Number.parseInt(snap.total_chunks, 10),
						totalCommits: Number.parseInt(snap.total_commits, 10),
						totalRepos: Number.parseInt(snap.total_repos, 10),
						totalOrgs: Number.parseInt(snap.total_orgs, 10),
						totalEnrichmentDocs: Number.parseInt(
							snap.total_enrichment_docs,
							10,
						),
					}),
				);
			}
		} catch (err) {
			console.error("[snapshot] Failed to emit db snapshot:", err);
		} finally {
			await snapshotSql.end();
		}
	}

	// Emit once on startup, then every hour
	emitDbSnapshot().catch(() => {});
	const snapshotTimer = setInterval(() => {
		emitDbSnapshot().catch(() => {});
	}, SNAPSHOT_INTERVAL_MS);
	snapshotTimer.unref(); // Don't prevent process exit

	// Graceful shutdown
	const shutdown = async () => {
		console.log("[boot] Shutting down...");
		const { stopServer } = await import("./index.js");
		await stopServer();
		process.exit(0);
	};

	process.on("SIGTERM", shutdown);
	process.on("SIGINT", shutdown);
}

main().catch((err) => {
	console.error("[boot] Fatal:", err);
	process.exit(1);
});

/**
 * Middleware chain for the cloud test server.
 *
 * Auth middleware validates Authorization: Bearer <key> on all /v1/* endpoints.
 * When MASTER_API_KEY is not configured, auth is disabled (dev/test mode).
 */

import { createHash } from "node:crypto";
import type { RequestContext } from "./router.js";
import { json } from "./router.js";

// ============================================================================
// Auth middleware
// ============================================================================

/**
 * authMiddleware
 *
 * Validates Authorization: Bearer <key> header on all /v1/* endpoints.
 * Skips /v1/health unconditionally.
 * When MASTER_API_KEY is not set in config → auth disabled (dev/test mode).
 *
 * Sets ctx.metrics.apiKeyId on success for downstream usage tracking.
 */
export async function authMiddleware(
	ctx: RequestContext,
): Promise<Response | null> {
	// Auth disabled when no master key configured
	if (!ctx.config.masterApiKey) return null;

	// Always allow health check
	if (ctx.pathname === "/v1/health") return null;

	// Extract Bearer token
	const authHeader = ctx.req.headers.get("Authorization");
	const token = authHeader?.startsWith("Bearer ") ? authHeader.slice(7) : null;
	if (!token) {
		return json({ error: "unauthorized" }, 401);
	}

	// Master key: validate by direct comparison (not stored in DB)
	if (token === ctx.config.masterApiKey) {
		ctx.metrics.apiKeySource = "master";
		return null;
	}

	// Regular key: hash and look up in DB
	const hash = createHash("sha256").update(token).digest("hex");

	const rows = await ctx.sql<
		{ id: number; name: string; is_active: boolean }[]
	>`
		SELECT id, name, is_active
		FROM api_keys
		WHERE key_hash = ${hash}
		LIMIT 1
	`;

	if (rows.length === 0 || !rows[0]!.is_active) {
		return json({ error: "forbidden" }, 403);
	}

	// Key management endpoints require master key only
	if (ctx.pathname.startsWith("/v1/keys")) {
		return json({ error: "forbidden" }, 403);
	}

	ctx.metrics.apiKeyId = rows[0]!.id;
	ctx.metrics.apiKeySource = "key";
	return null;
}

// ============================================================================
// Version middleware
// ============================================================================

export async function versionMiddleware(
	ctx: RequestContext,
): Promise<Response | null> {
	// Skip version check for health endpoint
	if (ctx.pathname === "/v1/health") return null;

	// Prefer new X-Mnemex-* header; fall back to legacy X-ClaudeMem-* for
	// backward compatibility with clients that haven't upgraded yet.
	const version =
		ctx.req.headers.get("X-Mnemex-Version") ??
		ctx.req.headers.get("X-ClaudeMem-Version");
	if (!version || version !== "1") {
		return json({ error: "unsupported_version", supported: [1] }, 422);
	}

	// Extract anonymous machine ID for telemetry.
	// Gracefully absent for older clients — log null is fine.
	const machineId =
		ctx.req.headers.get("X-Mnemex-Machine-ID") ??
		ctx.req.headers.get("X-ClaudeMem-Machine-ID");
	if (machineId) {
		ctx.metrics.machineId = machineId;
	}

	return null;
}

// ============================================================================
// Middleware runner
// ============================================================================

type MiddlewareFn = (ctx: RequestContext) => Promise<Response | null>;

export async function runMiddleware(
	ctx: RequestContext,
	middlewares: MiddlewareFn[],
): Promise<Response | null> {
	for (const mw of middlewares) {
		const result = await mw(ctx);
		if (result !== null) return result;
	}
	return null;
}

/**
 * URL pattern router for the cloud test server.
 * Hand-written pattern matching — no framework dependency.
 */

import type { ServerConfig } from "./config.js";
import type { Sql } from "./db.js";

// ============================================================================
// Request metrics
// ============================================================================

export interface RequestMetrics {
	// --- Identity signals (set by middleware or handlers) ---

	/** The organisation slug from the route or request body (e.g., "acme") */
	orgSlug?: string;
	/** The repository slug from the route or request body (e.g., "backend") */
	repoSlug?: string;
	/** 40-char hex commit SHA — correlation key across the index pipeline */
	commitSha?: string;
	/** Anonymous machine UUID from X-Mnemex-Machine-ID header (or legacy X-ClaudeMem-Machine-ID) */
	machineId?: string;

	// --- Index upload (POST /v1/index) ---

	/** "thin" (vectors pre-computed by CLI) or "smart" (server embeds) */
	mode?: "thin" | "smart";
	/** Total chunks sent in this upload (chunksNew + chunksDeduped) */
	chunksTotal?: number;
	/** Chunks that were not already in the database (newly inserted) */
	chunksNew?: number;
	/** Chunks already present by content_hash (not re-stored) */
	chunksDeduped?: number;
	/** Unique file paths in the upload (changed files) */
	filesChanged?: number;
	/** Files inherited from parent commit unchanged */
	filesInherited?: number;

	// --- Chunk dedup check (POST /v1/chunks/check) ---

	/** Total hashes submitted to the check endpoint */
	hashesChecked?: number;
	/** Hashes that already exist in the database */
	hashesExisting?: number;
	/** Hashes that do not exist and must be uploaded */
	hashesMissing?: number;

	// --- Search (POST /v1/search) ---

	/** Dimension of the query vector (used to detect version skew) */
	queryDim?: number;
	/** Number of search results returned (0 indicates empty index or bad query) */
	resultsReturned?: number;
	/** Duration of the pgvector query only, in milliseconds */
	searchMs?: number;

	// --- Commit status (GET /v1/commits/:sha/status) ---

	/** Status string returned: "ready", "pending", "embedding", "not_found", "error" */
	commitStatus?: string;

	// --- Error tracking (all endpoints) ---

	/** Machine-readable error code, e.g. "repo_not_found", "dimension_mismatch" */
	errorCode?: string;

	// --- Slow request flag ---

	/** True if request exceeded the slow-request threshold for this endpoint */
	slow?: boolean;

	// --- Auth ---

	/** ID of the authenticated API key (undefined if master key or auth disabled) */
	apiKeyId?: number;
	/** Source of auth: "master" | "key" | "none" */
	apiKeySource?: "master" | "key" | "none";
}

// ============================================================================
// Request context
// ============================================================================

export interface RequestContext {
	req: Request;
	method: string;
	pathname: string;
	params: Record<string, string>;
	query: URLSearchParams;
	/** Database connection */
	sql: Sql;
	/** Server configuration */
	config: ServerConfig;
	/** Per-request telemetry bag — handlers write here; fetch wrapper reads for logging */
	metrics: Partial<RequestMetrics>;
}

// ============================================================================
// Route matching
// ============================================================================

interface RoutePattern {
	method: string;
	/** Pattern segments, e.g. ["v1", "repos", ":orgSlug", ":repoSlug", "register"] */
	segments: string[];
}

function parsePattern(pattern: string): string[] {
	return pattern.split("/").filter((s) => s.length > 0);
}

function matchRoute(
	pattern: RoutePattern,
	method: string,
	segments: string[],
): Record<string, string> | null {
	if (pattern.method !== method) return null;
	if (pattern.segments.length !== segments.length) return null;

	const params: Record<string, string> = {};
	for (let i = 0; i < pattern.segments.length; i++) {
		const pat = pattern.segments[i]!;
		const seg = segments[i]!;
		if (pat.startsWith(":")) {
			params[pat.slice(1)] = decodeURIComponent(seg);
		} else if (pat !== seg) {
			return null;
		}
	}
	return params;
}

// ============================================================================
// Handler imports
// ============================================================================

import { check } from "./handlers/chunks.js";
import { uploadIndex } from "./handlers/index-handler.js";
import { createKey, deleteKey, listKeys } from "./handlers/keys.js";
import { register } from "./handlers/repos.js";
import { search } from "./handlers/search.js";
import { getStatus } from "./handlers/status.js";

// ============================================================================
// Route table
// ============================================================================

type HandlerFn = (ctx: RequestContext) => Promise<Response>;

interface Route {
	pattern: RoutePattern;
	handler: HandlerFn;
}

const routes: Route[] = [
	{
		pattern: {
			method: "POST",
			segments: parsePattern("/v1/repos/:orgSlug/:repoSlug/register"),
		},
		handler: register,
	},
	{
		pattern: {
			method: "POST",
			segments: parsePattern("/v1/chunks/check"),
		},
		handler: check,
	},
	{
		pattern: {
			method: "POST",
			segments: parsePattern("/v1/index"),
		},
		handler: uploadIndex,
	},
	{
		pattern: {
			method: "GET",
			segments: parsePattern("/v1/commits/:sha/status"),
		},
		handler: getStatus,
	},
	{
		pattern: {
			method: "POST",
			segments: parsePattern("/v1/search"),
		},
		handler: search,
	},
	{
		pattern: {
			method: "GET",
			segments: parsePattern("/v1/health"),
		},
		handler: async (_ctx) => json({ ok: true }, 200),
	},
	{
		pattern: {
			method: "POST",
			segments: parsePattern("/v1/keys"),
		},
		handler: createKey,
	},
	{
		pattern: {
			method: "GET",
			segments: parsePattern("/v1/keys"),
		},
		handler: listKeys,
	},
	{
		pattern: {
			method: "DELETE",
			segments: parsePattern("/v1/keys/:keyId"),
		},
		handler: deleteKey,
	},
];

// ============================================================================
// Router dispatch
// ============================================================================

export async function router(ctx: RequestContext): Promise<Response> {
	const pathSegments = ctx.pathname.split("/").filter((s) => s.length > 0);

	for (const route of routes) {
		const params = matchRoute(route.pattern, ctx.method, pathSegments);
		if (params !== null) {
			ctx.params = params;
			try {
				return await route.handler(ctx);
			} catch (err) {
				console.error(
					`[server] Unhandled error in ${ctx.method} ${ctx.pathname}:`,
					err,
				);
				const message = err instanceof Error ? err.message : String(err);
				ctx.metrics.errorCode = "internal_error";
				return json({ error: "internal_error", message }, 500);
			}
		}
	}

	return json({ error: "not_found" }, 404);
}

// ============================================================================
// Helpers
// ============================================================================

export function json(data: unknown, status = 200): Response {
	return new Response(JSON.stringify(data), {
		status,
		headers: { "Content-Type": "application/json" },
	});
}

/**
 * SmartCloudClient — uploads raw text instead of vectors
 *
 * Extends ThinCloudClient with a single override: uploadIndex sends chunk
 * text fields (not vector fields) and sets mode to "smart" so the server
 * knows it must compute embeddings itself.
 *
 * All other methods (checkChunks, getCommitStatus, waitForCommit, search, …)
 * are inherited from ThinCloudClient unchanged.
 */

import type { ThinCloudClientOptions } from "./thin-client.js";
import { ThinCloudClient } from "./thin-client.js";
import type {
	ICloudIndexClient,
	UploadIndexRequest,
	UploadIndexResponse,
} from "./types.js";

// ============================================================================
// SmartCloudClient
// ============================================================================

/**
 * Cloud client for "smart" mode: uploads chunk text and lets the cloud
 * compute embeddings server-side with its best available model.
 *
 * Use this when you want to avoid running an embeddings model locally.
 * The trade-off is a small latency window where the commit is "pending"
 * until the server finishes embedding; call waitForCommit() if you need
 * to block until the commit is searchable.
 */
export class SmartCloudClient extends ThinCloudClient {
	/**
	 * Upload an index in smart mode.
	 *
	 * Key differences from ThinCloudClient.uploadIndex:
	 *  - Forces request.mode to "smart" (overrides whatever caller set)
	 *  - Strips vector fields from chunks (server ignores them in smart mode)
	 *  - Preserves text fields — these are required for server-side embedding
	 *
	 * The response may have status "pending" while the server embeds the text.
	 * Call waitForCommit() if you need to block until the commit is ready.
	 */
	override async uploadIndex(
		request: UploadIndexRequest,
	): Promise<UploadIndexResponse> {
		const smartRequest: UploadIndexRequest = {
			...request,
			mode: "smart",
			chunks: request.chunks.map((chunk) => {
				// In smart mode: include text, omit vector (save bandwidth)
				const { vector: _vector, ...rest } = chunk;
				return rest;
			}),
		};
		return this.post<UploadIndexResponse>("/v1/index", smartRequest);
	}
}

// ============================================================================
// Factory
// ============================================================================

/**
 * Create a new SmartCloudClient.
 * Accepts the same options as ThinCloudClient.
 */
export function createSmartCloudClient(
	options: ThinCloudClientOptions,
): ICloudIndexClient {
	return new SmartCloudClient(options);
}

/**
 * LocalCloudStub — in-memory ICloudIndexClient for testing
 *
 * Provides a complete, dependency-free implementation of ICloudIndexClient
 * backed by Maps and Sets. Use this in unit tests and integration tests
 * wherever a real HTTP cloud client would be needed.
 *
 * Key behaviours:
 * - checkChunks: returns previously uploaded hashes as "existing"
 * - uploadIndex: stores chunks by content hash, records commit mappings
 * - getCommitStatus: returns "ready" for uploaded commits, "not_found" otherwise
 * - waitForCommit: resolves immediately for ready commits
 * - search: naive text-contains match against stored chunk text/name
 * - all other methods return sensible empty defaults
 */

import type {
	ChunkCheckResult,
	CloudCalleeResult,
	CloudCallerResult,
	CloudGraphResult,
	CloudSearchRequest,
	CloudSearchResult,
	CloudSymbol,
	CommitStatus,
	ICloudIndexClient,
	RegisterRepoRequest,
	RegisterRepoResponse,
	UploadChunk,
	UploadIndexRequest,
	UploadIndexResponse,
} from "./types.js";

// ============================================================================
// Internal storage structures
// ============================================================================

interface StoredChunk extends UploadChunk {
	/** When this chunk was first stored (ISO 8601) */
	storedAt: string;
}

interface CommitRecord {
	commitSha: string;
	repoSlug: string;
	parentShas: string[];
	/** Content hashes of all chunks associated with this commit */
	chunkHashes: Set<string>;
	/** Paths of files deleted with this commit */
	deletedFiles: string[];
	indexedAt: string;
}

interface RepoRecord {
	repoSlug: string;
	orgSlug: string;
	displayName?: string;
	remoteUrl?: string;
	mode: "thin" | "smart";
}

// ============================================================================
// LocalCloudStub
// ============================================================================

export class LocalCloudStub implements ICloudIndexClient {
	/** All chunks ever uploaded, keyed by content hash */
	private readonly chunks = new Map<string, StoredChunk>();

	/** Commit records, keyed by `${repoSlug}::${commitSha}` */
	private readonly commits = new Map<string, CommitRecord>();

	/** Registered repos, keyed by `${orgSlug}::${repoSlug}` */
	private readonly repos = new Map<string, RepoRecord>();

	// --------------------------------------------------------------------------
	// ICloudIndexClient
	// --------------------------------------------------------------------------

	async checkChunks(
		_repoSlug: string,
		hashes: string[],
		_commitSha?: string,
	): Promise<ChunkCheckResult> {
		const existing: string[] = [];
		const missing: string[] = [];

		for (const hash of hashes) {
			if (this.chunks.has(hash)) {
				existing.push(hash);
			} else {
				missing.push(hash);
			}
		}

		return { existing, missing };
	}

	async uploadIndex(request: UploadIndexRequest): Promise<UploadIndexResponse> {
		const key = this.commitKey(request.repoSlug, request.commitSha);
		let chunksAdded = 0;
		let chunksDeduplicated = 0;

		const chunkHashes = new Set<string>();

		for (const chunk of request.chunks) {
			if (this.chunks.has(chunk.contentHash)) {
				chunksDeduplicated++;
			} else {
				this.chunks.set(chunk.contentHash, {
					...chunk,
					storedAt: new Date().toISOString(),
				});
				chunksAdded++;
			}
			chunkHashes.add(chunk.contentHash);
		}

		this.commits.set(key, {
			commitSha: request.commitSha,
			repoSlug: request.repoSlug,
			parentShas: request.parentShas,
			chunkHashes,
			deletedFiles: request.deletedFiles ?? [],
			indexedAt: new Date().toISOString(),
		});

		return {
			ok: true,
			chunksAdded,
			chunksDeduplicated,
			status: "ready",
		};
	}

	async getCommitStatus(
		repoSlug: string,
		commitSha: string,
	): Promise<CommitStatus> {
		const key = this.commitKey(repoSlug, commitSha);
		const record = this.commits.get(key);

		if (!record) {
			return { commitSha, status: "not_found" };
		}

		return {
			commitSha,
			status: "ready",
			indexedAt: record.indexedAt,
			chunkCount: record.chunkHashes.size,
		};
	}

	async waitForCommit(
		repoSlug: string,
		commitSha: string,
		_timeoutMs?: number,
	): Promise<CommitStatus> {
		// In the stub, commits are synchronously "ready" after upload
		return this.getCommitStatus(repoSlug, commitSha);
	}

	async search(request: CloudSearchRequest): Promise<CloudSearchResult[]> {
		const key = this.commitKey(request.repoSlug, request.commitSha);
		const record = this.commits.get(key);

		if (!record) {
			return [];
		}

		const query = request.queryText.toLowerCase();
		const limit = request.limit ?? 10;
		const results: CloudSearchResult[] = [];

		for (const hash of record.chunkHashes) {
			const chunk = this.chunks.get(hash);
			if (!chunk) continue;

			// Filter by language if specified
			if (request.language && chunk.language !== request.language) continue;

			// Filter by chunk type if specified
			if (request.chunkType && chunk.chunkType !== request.chunkType) continue;

			// Naive text match — check name, summary, and text fields
			const searchTarget = [
				chunk.name ?? "",
				chunk.summary ?? "",
				chunk.text ?? "",
			]
				.join(" ")
				.toLowerCase();

			if (query && !searchTarget.includes(query)) continue;

			// Score: 1.0 if name matches exactly, 0.5 for partial text match
			let score = 0.5;
			if (chunk.name?.toLowerCase() === query) {
				score = 1.0;
			} else if (chunk.name?.toLowerCase().includes(query)) {
				score = 0.8;
			}

			results.push({
				contentHash: chunk.contentHash,
				filePath: chunk.filePath,
				startLine: chunk.startLine,
				endLine: chunk.endLine,
				language: chunk.language,
				chunkType: chunk.chunkType,
				name: chunk.name,
				score,
				summary: chunk.summary,
			});

			if (results.length >= limit) break;
		}

		// Sort by score descending
		results.sort((a, b) => b.score - a.score);
		return results;
	}

	async registerRepo(
		request: RegisterRepoRequest,
	): Promise<RegisterRepoResponse> {
		const key = `${request.orgSlug}::${request.repoSlug}`;
		const existed = this.repos.has(key);

		this.repos.set(key, {
			repoSlug: request.repoSlug,
			orgSlug: request.orgSlug,
			displayName: request.displayName,
			remoteUrl: request.remoteUrl,
			mode: request.mode ?? "thin",
		});

		return {
			ok: true,
			created: !existed,
			repoSlug: request.repoSlug,
		};
	}

	async getSymbol(
		repoSlug: string,
		commitSha: string,
		name: string,
	): Promise<CloudSymbol[]> {
		const key = this.commitKey(repoSlug, commitSha);
		const record = this.commits.get(key);
		if (!record) return [];

		const results: CloudSymbol[] = [];
		const queryName = name.toLowerCase();

		for (const hash of record.chunkHashes) {
			const chunk = this.chunks.get(hash);
			if (!chunk?.name) continue;
			if (!chunk.name.toLowerCase().includes(queryName)) continue;

			results.push({
				name: chunk.name,
				kind: chunk.chunkType,
				filePath: chunk.filePath,
				startLine: chunk.startLine,
				endLine: chunk.endLine,
				pagerankScore: 0,
			});
		}

		return results;
	}

