 */
async function askQuestions(
	questions: SmartQuestion[],
	ctx: ReturnType<typeof gatherProjectContext>,
): Promise<GeneratorAnswers> {
	const rl = readline.createInterface({ input, output });

	const answers: GeneratorAnswers = {
