/**
 * Anti-Pattern Extractor
 *
 * Identifies code smells, anti-patterns, and potential issues.
 * Extracts: pattern description, bad example, reason, alternative, severity.
 */

import {
	buildAntiPatternPrompt,
	getSystemPrompt,
} from "../../../llm/prompts/enrichment.js";
