/**
 * Repo Map Generator
 *
 * Generates a token-budgeted structural overview of the codebase.
 * Uses PageRank scores to prioritize important symbols.
 *
 * Output format (example):
 *
 * src/core/indexer.ts:
 *   class Indexer
 *     async index(force?: boolean): Promise<EnrichedIndexResult>
 *     async search(query: string): Promise<SearchResult[]>
 *   function createIndexer(options): Indexer
 *
 * src/core/store.ts:
 *   class VectorStore
 *     async addChunks(chunks[]): Promise<void>
 *     async search(query, vector): Promise<SearchResult[]>
 */

import type {
	RepoMapEntry,
	RepoMapOptions,
	SymbolDefinition,
} from "../types.js";
import type { IFileTracker } from "./tracker.js";

// ============================================================================
// Constants
// ============================================================================

/** Characters per token estimate for code */
const CHARS_PER_TOKEN = 4;

/** Indentation for nested items */
const INDENT = "  ";

/** Maximum symbols per file in the map */
const MAX_SYMBOLS_PER_FILE = 20;

// ============================================================================
// Repo Map Generator Class
// ============================================================================

export class RepoMapGenerator {
	private tracker: IFileTracker;

	constructor(tracker: IFileTracker) {
		this.tracker = tracker;
	}

	/**
	 * Generate a text-based repo map within token budget
	 */
	generate(options: RepoMapOptions = {}): string {
		const {
			maxTokens = 2000,
			includeSignatures = true,
			pathPattern,
			topNByPagerank,
		} = options;

		// Get symbols sorted by PageRank
		let symbols = this.tracker.getTopSymbols(topNByPagerank || 5000);

		// Filter by path pattern if provided
		if (pathPattern) {
			const pattern = new RegExp(
				pathPattern.replace(/\*/g, ".*").replace(/\//g, "\\/"),
			);
			symbols = symbols.filter((s) => pattern.test(s.filePath));
		}

		// Group symbols by file
		const fileMap = this.groupByFile(symbols);

		// Sort files by total PageRank (importance)
		const sortedFiles = this.sortFilesByImportance(fileMap);

		// Build output with token budgeting
		const lines: string[] = [];
		let currentTokens = 0;
		const maxChars = maxTokens * CHARS_PER_TOKEN;

		for (const filePath of sortedFiles) {
			const fileSymbols = fileMap.get(filePath)!;
			const fileLines = this.formatFile(
				filePath,
				fileSymbols,
				includeSignatures,
			);
			const fileChars = fileLines.join("\n").length;
			const fileTokens = fileChars / CHARS_PER_TOKEN;

			// Check if we can fit this file
			if (currentTokens + fileTokens > maxTokens) {
				// Try to fit at least the file header
				const headerLine = `${filePath}: (${fileSymbols.length} symbols)`;
				const headerTokens = headerLine.length / CHARS_PER_TOKEN;

				if (currentTokens + headerTokens < maxTokens) {
					lines.push(headerLine);
					currentTokens += headerTokens;
				}
				continue;
			}

			lines.push(...fileLines);
			currentTokens += fileTokens;
		}

		return lines.join("\n");
	}

	/**
	 * Generate structured repo map data (for programmatic use)
	 */
	generateStructured(options: RepoMapOptions = {}): RepoMapEntry[] {
		const { pathPattern, topNByPagerank } = options;

		let symbols = this.tracker.getTopSymbols(topNByPagerank || 5000);

		if (pathPattern) {
			const pattern = new RegExp(
				pathPattern.replace(/\*/g, ".*").replace(/\//g, "\\/"),
			);
			symbols = symbols.filter((s) => pattern.test(s.filePath));
		}

		const fileMap = this.groupByFile(symbols);

		const entries: RepoMapEntry[] = [];

		for (const [filePath, fileSymbols] of fileMap) {
			entries.push({
				filePath,
				symbols: fileSymbols.slice(0, MAX_SYMBOLS_PER_FILE).map((s) => ({
					name: s.name,
					kind: s.kind,
					signature: s.signature,
					line: s.startLine,
					pagerankScore: s.pagerankScore,
				})),
			});
		}

		// Sort by total PageRank of symbols
		return entries.sort(
			(a, b) =>
				b.symbols.reduce((sum, s) => sum + s.pagerankScore, 0) -
				a.symbols.reduce((sum, s) => sum + s.pagerankScore, 0),
		);
	}

	/**
	 * Generate a focused repo map for a specific query
	 * Returns symbols most relevant to the query terms
	 */
	generateForQuery(query: string, options: RepoMapOptions = {}): string {
		const { maxTokens = 500 } = options;

		// Extract terms from query
		const terms = query
			.toLowerCase()
			.split(/\s+/)
			.filter((t) => t.length > 2);

		// Get all symbols and score by relevance
		const allSymbols = this.tracker.getTopSymbols(10000);

		const scoredSymbols = allSymbols.map((symbol) => {
			let relevance = 0;

			// Check name match
			const nameLower = symbol.name.toLowerCase();
			for (const term of terms) {
				if (nameLower.includes(term)) {
					relevance += 10;
				}
			}

			// Check signature match
			if (symbol.signature) {
				const sigLower = symbol.signature.toLowerCase();
				for (const term of terms) {
					if (sigLower.includes(term)) {
						relevance += 5;
					}
				}
			}

			// Check file path match
			const pathLower = symbol.filePath.toLowerCase();
			for (const term of terms) {
				if (pathLower.includes(term)) {
					relevance += 3;
				}
			}

			// Boost by PageRank
			relevance *= 1 + symbol.pagerankScore * 100;

			return { symbol, relevance };
		});

		// Sort by relevance
		scoredSymbols.sort((a, b) => b.relevance - a.relevance);

		// Take top relevant symbols
		const relevantSymbols = scoredSymbols
			.filter((s) => s.relevance > 0)
			.slice(0, 50)
			.map((s) => s.symbol);

		// Generate map for these symbols
		const fileMap = this.groupByFile(relevantSymbols);
		const sortedFiles = this.sortFilesByImportance(fileMap);

		const lines: string[] = [];
		let currentTokens = 0;

		for (const filePath of sortedFiles) {
			const fileSymbols = fileMap.get(filePath)!;
			const fileLines = this.formatFile(filePath, fileSymbols, true);
			const fileTokens = fileLines.join("\n").length / CHARS_PER_TOKEN;

			if (currentTokens + fileTokens > maxTokens) {
				break;
			}

			lines.push(...fileLines);
			currentTokens += fileTokens;
		}

		return lines.join("\n");
	}

	/**
	 * Group symbols by file path
	 */
	private groupByFile(
		symbols: SymbolDefinition[],
	): Map<string, SymbolDefinition[]> {
		const map = new Map<string, SymbolDefinition[]>();

		for (const symbol of symbols) {
			if (!map.has(symbol.filePath)) {
				map.set(symbol.filePath, []);
			}
			map.get(symbol.filePath)!.push(symbol);
		}

		// Sort symbols within each file by line number
		for (const [, fileSymbols] of map) {
			fileSymbols.sort((a, b) => a.startLine - b.startLine);
		}

		return map;
	}

	/**
	 * Sort files by total PageRank importance
	 */
	private sortFilesByImportance(
		fileMap: Map<string, SymbolDefinition[]>,
	): string[] {
		const fileScores = new Map<string, number>();

		for (const [filePath, symbols] of fileMap) {
			const totalScore = symbols.reduce((sum, s) => sum + s.pagerankScore, 0);
			fileScores.set(filePath, totalScore);
		}

		return [...fileMap.keys()].sort(
			(a, b) => (fileScores.get(b) || 0) - (fileScores.get(a) || 0),
		);
	}

	/**
	 * Format a single file's symbols for the repo map
	 */
	private formatFile(
		filePath: string,
		symbols: SymbolDefinition[],
		includeSignatures: boolean,
	): string[] {
		const lines: string[] = [`${filePath}:`];

		// Separate top-level and nested symbols
		const topLevel = symbols.filter((s) => !s.parentId);
		const nested = new Map<string, SymbolDefinition[]>();

		for (const s of symbols) {
			if (s.parentId) {
				if (!nested.has(s.parentId)) {
					nested.set(s.parentId, []);
				}
				nested.get(s.parentId)!.push(s);
			}
		}

		// Limit symbols per file
		const displaySymbols = topLevel.slice(0, MAX_SYMBOLS_PER_FILE);

		for (const symbol of displaySymbols) {
			lines.push(this.formatSymbol(symbol, 1, includeSignatures));

			// Add nested symbols (methods)
			const children = nested.get(symbol.id) || [];
			for (const child of children.sl

/**
 * SQLite Abstraction Layer
 *
 * Provides a unified interface that works with both:
 * - bun:sqlite (when running in Bun - dev mode or compiled binary)
 * - better-sqlite3 (when running in Node.js - npm install)
 */

// Detect if we're running in Bun
const isBun = typeof globalThis.Bun !== "undefined";

// Type definitions for our abstraction
export interface RunResult {
	changes: number;
	lastInsertRowid: number | bigint;
}

export interface Statement {
	run(...params: unknown[]): RunResult;
	get(...params: unknown[]): unknown;
	all(...params: unknown[]): unknown[];
}

export interface SQLiteDatabase {
	exec(sql: string): void;
	prepare(sql: string): Statement;
	close(): void;
	/** Execute a function within a transaction (auto-commits or rolls back) */
	transaction<T>(fn: () => T): T;
}

/**
 * Create a SQLite database connection (synchronous)
 * Uses bun:sqlite in Bun, better-sqlite3 in Node.js
 */
export function createDatabaseSync(path: string): SQLiteDatabase {
	if (isBun) {
		// Use Bun's built-in SQLite
		const { Database } = require("bun:sqlite");
		const db = new Database(path);

		return {
			exec: (sql: string) => db.exec(sql),
			prepare: (sql: string) => {
				const stmt = db.prepare(sql);
				return {
					run: (...params: unknown[]): RunResult => {
						stmt.run(...params);
						// Bun's sqlite doesn't return changes directly from run()
						// Use the database's changes() method
						return {
							changes: db.query("SELECT changes() as c").get().c as number,
							lastInsertRowid: db
								.query("SELECT last_insert_rowid() as id")
								.get().id as number,
						};
					},
					get: (...params: unknown[]) => stmt.get(...params),
					all: (...params: unknown[]) => stmt.all(...params),
				};
			},
			close: () => db.close(),
			transaction: <T>(fn: () => T): T => {
				db.exec("BEGIN");
				try {
					const result = fn();
					db.exec("COMMIT");
					return result;
				} catch (error) {
					db.exec("ROLLBACK");
					throw error;
				}
			},
		};
	} else {
		// Use better-sqlite3 for Node.js
		const BetterSqlite3 = require("better-sqlite3");
		const db = new BetterSqlite3(path);

		return {
			exec: (sql: string) => db.exec(sql),
			prepare: (sql: string) => {
				const stmt = db.prepare(sql);
				return {
					run: (...params: unknown[]): RunResult => {
						const result = stmt.run(...params);
						return {
							changes: result.changes,
							lastInsertRowid: result.lastInsertRowid,
						};
					},
					get: (...params: unknown[]) => stmt.get(...params),
					all: (...params: unknown[]) => stmt.all(...params),
				};
			},
			close: () => db.close(),
			transaction: <T>(fn: () => T): T => {
				// better-sqlite3 has native transaction support
				return db.transaction(fn)();
			},
		};
	}
}

/**
 * LanceDB Vector Store
 *
 * Handles vector storage and hybrid search (BM25 + vector similarity)
 * using LanceDB's embedded database.
 */

import { existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import * as lancedb from "@lancedb/lancedb";
import { getTestFileMode, type TestFileMode } from "../config.js";
import type {
	BaseDocument,
	ChunkWithEmbedding,
	CodeUnit,
	CodeUnitWithEmbedding,
	DocumentType,
	DocumentWithEmbedding,
	EnrichedSearchOptions,
	EnrichedSearchResult,
	SearchResult,
	SearchUseCase,
	UnitType,
} from "../types.js";
import {
	createTestFileDetector,
	type TestFileDetector,
} from "./analysis/test-detector.js";

// ============================================================================
// Constants
// ============================================================================

/** Table name for code chunks */
const CHUNKS_TABLE = "code_chunks";

/** Default search limit */
const DEFAULT_LIMIT = 10;

/** BM25 weight in hybrid search */
const BM25_WEIGHT = 0.4;

/** Vector weight in hybrid search */
const VECTOR_WEIGHT = 0.6;

/**
 * Watchdog timeout (ms) for LanceDB write operations (table.add / createTable).
 *
 * Generous on purpose: a legitimate write of a large batch can take a while, so
 * this is an upper bound on "one write should never exceed this" — it exists to
 * catch the LanceDB 0.13.0 deadlock (all tokio threads park in Condvar::wait,
 * 0% CPU, 0 bytes written, forever), NOT to bound normal latency.
 */
export const LANCEDB_WRITE_TIMEOUT_MS = 60000;

/**
 * Thrown when a write batch carries zero-dimension vectors.
 *
 * LanceDB infers the table schema from the first batch, so a batch whose
 * vectors are empty arrays creates a `vector` column typed
 * `FixedSizeList[0]<Float32>`. That column is permanently unusable: the table
 * opens and `countRows()` succeeds, but every read that touches `vector`
 * fails — LanceDB >= 0.20 raises `LanceError(Schema): dimension must be a
 * positive integer`, and 0.13 panics in Rust with "attempt to divide by zero".
 *
 * The schema is fixed at creation, so there is no repair short of a full
 * reindex. Failing the write is strictly better than silently producing an
 * index that can never answer a query.
 *
 * Empty vectors in practice mean the embedding provider returned nothing —
 * e.g. the configured Ollama endpoint is not running.
 */
export class ZeroDimensionVectorError extends Error {
	constructor(readonly label: string) {
		super(
			`Refusing to write '${label}': embedding vectors are empty (0 dimensions). ` +
				"This would create an unqueryable index. Check that the configured " +
				"embedding provider is reachable, then reindex.",
		);
		this.name = "ZeroDimensionVectorError";
	}
}

/**
 * Guard a batch's inferred vector dimension before it reaches LanceDB.
 * Exported for tests.
 * @returns the validated, non-zero dimension
 */
export function assertVectorDimension(
	dimension: number,
	label: string,
): number {
	if (!Number.isFinite(dimension) || dimension <= 0) {
		throw new ZeroDimensionVectorError(label);
	}
	return dimension;
}

/**
 * Thrown by `withTimeout` when a wrapped LanceDB write does not settle in time.
 * Carries the operation label and the timeout so the indexer can fail loudly and
 * its lock's finally/release can run (instead of the process parking forever).
 */
export class LanceWriteTimeoutError extends Error {
	constructor(
		readonly label: string,
		readonly timeoutMs: number,
	) {
		super(
			`LanceDB write '${label}' did not complete within ${timeoutMs}ms — ` +
				"the native write appears hung (LanceDB 0.13.0 Condvar deadlock).",
		);
		this.name = "LanceWriteTimeoutError";
	}
}

/**
 * Race a promise against a timeout.
 *
 * IMPORTANT — this CANNOT cancel the underlying operation. LanceDB's
 * `table.add()` / `createTable()` do NOT accept an AbortSignal, so there is no
 * way to abort the native call. When `ms` elapses, `withTimeout` only stops
 * AWAITING `p` and throws `LanceWriteTimeoutError`; the hung tokio thread keeps
 * running until the process exits. That is the intended, accepted behaviour: the
 * throw frees the JS process to release its index lock and fail loudly (rather
 * than parking forever), which pairs with the lock's progress-based auto-reclaim.
 * Do NOT mistake this for cancellation.
 *
 * The `p.finally(clearTimeout)` clears the timer on the normal (fast) path so a
 * 60s timer does not linger after a quick write; on the hang path `p` never
 * settles (again: we cannot cancel it), which is exactly the case this guards.
 */
export function withTimeout<T>(
	p: Promise<T>,
	ms: number,
	label: string,
): Promise<T> {
	let timer: ReturnType<typeof setTimeout> | undefined;
	const timeout = new Promise<never>((_, reject) => {
		timer = setTimeout(() => {
			reject(new LanceWriteTimeoutError(label, ms));
		}, ms);
	});
	return Promise.race([
		p.finally(() => {
			if (timer) clearTimeout(timer);
		}),
		timeout,
	]);
}

