// ============================================================================
// Configuration
// ============================================================================

/** Target chunk size in characters */
const TARGET_CHUNK_SIZE = 1500;

/** Maximum chunk size (hard limit) */
const MAX_CHUNK_SIZE = 2500;

/** Minimum chunk size (avoid tiny chunks) */
const MIN_CHUNK_SIZE = 200;

// ============================================================================
// Classification Patterns
// ============================================================================

/** Patterns indicating API reference documentation */
const API_REFERENCE_PATTERNS = [
	/\bfunction\s+\w+\s*\(/i,
	/\bclass\s+\w+/i,
	/\binterface\s+\w+/i,
	/\btype\s+\w+\s*=/i,
	/\bdef\s+\w+\s*\(/i,
	/\bfunc\s+\w+\s*\(/i,
	/\bfn\s+\w+\s*\(/i,
	/\bParameters\s*:/i,
	/\bReturns\s*:/i,
	/\bArguments\s*:/i,
	/\bReturn\s+value/i,
	/\|\s*Parameter\s*\|/i, // Markdown tables
	/\|\s*Name\s*\|\s*Type\s*\|/i,
	/@param\s+/i,
	/@returns?\s+/i,
	/@type\s+/i,
	/```\w+\n.*\n```/s, // Code blocks
];

/** Patterns indicating best practices documentation */
const BEST_PRACTICE_PATTERNS = [
	/\bshould\b/i,
	/\bshould\s+not\b/i,
	/\bavoid\b/i,
	/\bdon't\b/i,
	/\bdo\s+not\b/i,
	/\brecommend/i,
	/\bprefer\b/i,
	/\bbest\s+practice/i,
	/\bguideline/i,
	/\banti[- ]?pattern/i,
	/\bpit\s*fall/i,
	/\bcommon\s+mistake/i,
	/\binstead\s+of\b/i,
	/\brather\s+than\b/i,
	/\bbetter\s+to\b/i,
	/\bwarning\b/i,
	/\bcaution\b/i,
	/⚠️|❌|✅|💡/,
];

