/**
 * Types for external documentation fetching
 */

import type { DocProviderType, DocumentType } from "../types.js";

// ============================================================================
// Provider Types
// ============================================================================

/** A single fetched documentation entry */
export interface FetchedDoc {
	/** Unique identifier for this doc */
	id: string;
	/** Document title */
	title: string;
	/** Full content (markdown) */
	content: string;
	/** Section/category within the library docs */
	section?: string;
	/** Original source URL */
	url?: string;
	/** Tags/topics */
	tags?: string[];
}

/** Options for fetching documentation */
export interface FetchOptions {
	/** Specific version to fetch (e.g., "v18", "3.0") */
	version?: string;
	/** Topic to filter by */
	topic?: string;
	/** Maximum pages to fetch (for paginated APIs) */
	maxPages?: number;
	/** Progress callback */
	onProgress?: (current: number, total: number) => void;
}

/** Documentation provider interface */
export interface DocProvider {
	/** Provider name */
	name: DocProviderType;
	/** Priority for fallback chain (lower = try first) */
	priority: number;

	/** Check if this provider supports the given library */
	supports(library: string): Promise<boolean>;

	/** Fetch documentation for a library */
	fetch(library: string, options?: FetchOptions): Promise<FetchedDoc[]>;
}

// ============================================================================
// Library Mapping Types
// ============================================================================

/** Package ecosystem/registry */
export type PackageEcosystem = "npm" | "pypi" | "go" | "cargo";

/** Version constraint from package file */
export interface VersionConstraint {
	/** Original version string (e.g., "^18.2.0", ">=3.9,<4.0") */
	raw: string;
	/** Parsed major version */
	major: number;
	/** Parsed minor version (optional) */
	minor?: number;
	/** Parsed patch version (optional) */
	patch?: number;
	/** Version operator (^, ~, >=, etc.) */
	operator?: string;
}

/** Dependency detected from a project's manifest files */
export interface DetectedDependency {
	/** Package name as specified in manifest */
	name: string;
	/** Version constraint from manifest */
	version: string;
	/** Extracted major version for API calls (e.g., "v18") */
	majorVersion?: string;
	/** Package ecosystem */
	ecosystem: PackageEcosystem;
	/** Whether this is a dev dependency */
	isDev: boolean;
}

/** Documentation source mapping for a library */
export interface LibrarySource {
	/** Context7 library ID (e.g., "facebook/react") */
	context7?: string;
	/** llms.txt URL (e.g., "https://vuejs.org/llms-full.txt") */
	llmsTxt?: string;
	/** DevDocs doc name (e.g., "react", "vue~3") */
	devdocs?: string;
}

// ============================================================================
// Chunking Types
// ============================================================================

/** A chunk of documentation ready for embedding */
export interface DocChunk {
	/** Unique identifier (hash of content + metadata) */
	id: string;
	/** Chunk content */
	content: string;
	/** Document title */
	title: string;
	/** Section within the documentation */
	section?: string;
	/** Classified document type */
	documentType: DocumentType;
	/** Provider that fetched this */
	provider: DocProviderType;
	/** Library this documentation is for */
	library: string;
	/** Version of the library */
	version?: string;
	/** Source URL */
	sourceUrl?: string;
}

// ============================================================================
// Cache Types
// ============================================================================

/** State of indexed documentation for a library */
export interface IndexedDocState {
	/** Library identifier */
	library: string;
	/** Version indexed */
	version?: string;
	/** Provider used */
	provider: DocProviderType;
	/** Content hash for change detection */
	contentHash: string;
	/** When this was fetched */
	fetchedAt: string;
	/** Chunk IDs stored in vector store */
	chunkIds: string[];
}

/**
 * Version Parser
 *
 * Parses version constraints from package manifests (npm, pip, go, cargo)
 * and extracts the major version for documentation API calls.
 */

import type { VersionConstraint } from "./types.js";

// ============================================================================
// Semver Parsing
// ============================================================================

/**
 * Parse a semver version string into components
 * Handles: "18.2.0", "v18.2.0", "^18.2.0", "~18.2.0", ">=18.2.0", etc.
 */
export function parseVersion(versionStr: string): VersionConstraint | null {
	if (!versionStr || versionStr === "*" || versionStr === "latest") {
		return null;
	}

	// Remove leading "v" if present
	let raw = versionStr.trim();

	// Extract operator (^, ~, >=, <=, >, <, =)
	const operatorMatch = raw.match(/^([~^<>=]+)/);
	const operator = operatorMatch?.[1];
	if (operator) {
		raw = raw.slice(operator.length);
	}

	// Remove leading "v" after operator
	if (raw.startsWith("v")) {
		raw = raw.slice(1);
	}

	// Parse version numbers
	const parts = raw.split(".");
	const major = Number.parseInt(parts[0], 10);

	if (Number.isNaN(major)) {
		return null;
	}

	const minor =
		parts.length > 1 && parts[1] !== "*"
			? Number.parseInt(parts[1], 10)
			: undefined;
	const patch =
		parts.length > 2 && parts[2] !== "*"
			? Number.parseInt(parts[2].split("-")[0], 10) // Handle prerelease: 18.2.0-beta
			: undefined;

	return {
		raw: versionStr,
		major,
		minor: Number.isNaN(minor as number) ? undefined : minor,
		patch: Number.isNaN(patch as number) ? undefined : patch,
		operator,
	};
}

/**
 * Extract major version string for API calls
 * e.g., "^18.2.0" → "v18", "~3.9.0" → "v3"
 */
export function extractMajorVersion(versionStr: string): string | undefined {
	const parsed = parseVersion(versionStr);
	if (!parsed) return undefined;
	return `v${parsed.major}`;
}

// ============================================================================
// NPM Version Parsing
// ============================================================================

/**
 * Parse npm-style version constraint
 * Handles: "^18.2.0", "~18.2.0", ">=18.0.0 <19.0.0", "18.x", etc.
 */
export function parseNpmVersion(constraint: string): VersionConstraint | null {
	// Handle ranges like ">=18.0.0 <19.0.0" - use the first part
	const parts = constraint.split(/\s+/);
	const first = parts[0];

	// Handle x-ranges: "18.x", "18.2.x"
	const xRange = first.replace(/\.x/g, ".0");

	return parseVersion(xRange);
}

// ============================================================================
// Python Version Parsing
// ============================================================================

/**
 * Parse Python-style version constraint
 * Handles: ">=3.9,<4.0", "~=3.9.0", "==3.9.*", etc.
 */
export function parsePythonVersion(
	constraint: string,
): VersionConstraint | null {
	// Handle multiple constraints: ">=3.9,<4.0" - use first part
	const parts = constraint.split(",");
	const first = parts[0].trim();

	// Handle ~= (compatible release)
	if (first.startsWith("~=")) {
		return parseVersion(first.slice(2));
	}

	// Handle ==X.Y.*
	if (first.includes("*")) {
		return parseVersion(first.replace("*", "0"));
	}

	return parseVersion(first);
}

// ============================================================================
// Go Version Parsing
// ============================================================================

/**
 * Parse Go module version
 * Handles: "v1.21.0", "v1.21", etc.
 */
export function parseGoVersion(version: string): VersionConstraint | null {
	return parseVersion(version);
}

// ============================================================================
// Cargo (Rust) Version Parsing
// ============================================================================

/**
 * Parse Cargo-style version constraint
 * Handles: "1.0", "^1.0", "~1.0", ">=1.0, <2.0", etc.
 */
export function parseCargoVersion(
	constraint: string,
): VersionConstraint | null {
	// Cargo defaults to ^ if no operator specified
	const parts = constraint.split(",");
	const first = parts[0].trim();

	// If no operator, treat as ^
	if (!/^[~^<>=]/.test(first)) {
		return parseVersion(`^${first}`);
	}

	return parseVersion(first);
}

// ============================================================================
// Unified Parser
// ============================================================================

export type PackageEcosystem = "npm" | "pypi" | "go" | "cargo";

/**
 * Parse version constraint based on ecosystem
 */
export function parseVersionForEcosystem(
	constraint: string,
	ecosystem: PackageEcosystem,
): VersionConstraint | null {
	switch (ecosystem) {
		case "npm":
			return parseNpmVersion(constraint);
		case "pypi":
			return parsePythonVersion(constraint);
		case "go":
			return parseGoVersion(constraint);
		case "cargo":
			return parseCargoVersion(constraint);
		default:
			return parseVersion(constraint);
	}
}

/**
 * Symbol Editor
 *
 * Orchestrates code edits: locate symbol → validate → backup → write → reindex.
 * Provides both symbol-level and line-level editing with per-file locking.
 */

import { spawn } from "node:child_process";
import { randomBytes } from "node:crypto";
import { readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import type { LspManager } from "../lsp/manager.js";
import type { IndexCache } from "../mcp/cache.js";
import type { McpConfig } from "../mcp/config.js";
import { EditHistory } from "./history.js";
import { SymbolLocator } from "./locator.js";
import { EditValidator } from "./validator.js";

export type InsertMode = "replace" | "before" | "after";

export interface EditOptions {
	/** Dry run mode — validate and report what would change without writing */
	dryRun?: boolean;
	/** Session ID for grouping edits (auto-generated if not provided) */
	sessionId?: string;
	/** Skip syntax validation (for speed when caller knows content is valid) */
	skipSyntaxCheck?: boolean;
}

export interface EditResult {
	filePath: string;
	startLine: number;
	endLine: number;
	linesChanged: number;
	dryRun: boolean;
	sessionId: string;
	symbolName?: string;
}

/** Per-file lock chain */
const fileLocks = new Map<string, Promise<void>>();

/**
 * Acquire a per-file lock. Returns a release function.
 * Uses a promise chain so concurrent edits to the same file are serialized.
 */
function acquireFileLock(filePath: string): Promise<() => void> {
	const current = fileLocks.get(filePath) ?? Promise.resolve();
	let release: () => void;
	const next = new Promise<void>((resolve) => {
		release = resolve;
	});
	fileLocks.set(filePath, next);
	return current.then(() => release!);
}

export class SymbolEditor {
	private locator: SymbolLocator;
	private validator: EditValidator;
	private history: EditHistory;

	constructor(
		private cache: IndexCache,
		private config: McpConfig,
		private lspManager: LspManager | null = null,
	) {
		this.validator = new EditValidator();
		this.history = new EditHistory(config.indexDir);
		// Locator is created lazily when cache is loaded
		this.locator = null!;
	}

	private async ensureLocator(): Promise<SymbolLocator> {
		if (this.locator) return this.locator;
		const { graphManager, tracker } = await this.cache.get();
		this.locator = new SymbolLocator(graphManager, tracker, this.lspManager);
		return this.locator;
	}

	/**
	 * Edit a symbol's body by name.
	 */
	async editSymbol(
		symbolName: string,
		newContent: string,
		mode: InsertMode = "replace",
		options: EditOptions = {},
	): Promise<EditResult> {
		const locator = await this.ensureLocator();
		const location = locator.locate(symbolName);
		if (!location) {
			throw new Error(`Symbol '${symbolName}' not found in index`);
		}

		const absPath = resolve(this.config.workspaceRoot, location.filePath);
		const result = await this.editLines(
			absPath,
			location.startLine,
			location.endLine,
			newContent,
			{ ...options, _mode: mode },
		);

		return { ...result, symbolName };
	}

	/**
	 * Edit specific lines in a file.
	 */
	async editLines(
		filePath: string,
		startLine: number,
		endLine: number,
		newContent: string,
		options: EditOptions & { _mode?: InsertMode } = {},
	): Promise<EditResult> {
		const absPath = resolve(this.config.workspaceRoot, filePath);
		const dryRun = options.dryRun ?? false;
		const sessionId = options.sessionId ?? randomBytes(8).toString("hex");
		const mode = options._mode ?? "replace";

		// Validation
		this.validator.preCheck(absPath, this.config.workspaceRoot);
		this.validator.sizeCheck(newContent);

		if (dryRun) {
			return {
				filePath,
				startLine,
				endLine,
				linesChanged: newContent.split("\n").length,
				dryRun: true,
				sessionId,
			};
		}

		// Acquire file lock
		const release = await acquireFileLock(absPath);
		try {
			// Read current content inside lock
			const currentContent = readFileSync(absPath, "utf-8");
			const lines = currentContent.split("\n");

			// Validate line range
			if (startLine < 1 || endLine > lines.length || startLine > endLine) {
				throw new Error(
					`Invalid line range ${startLine}-${endLine} for file with ${lines.length} lines`,
				);
			}

			// TOCTOU guard: verify hash inside lock
			const { tracker } = await this.cache.get();
			const state = tracker.getFileState(filePath);
			if (state) {
				const { createHash } = await import("node:crypto");
				const currentHash = createHash("sha256")
					.update(currentContent)
					.digest("hex");
				if (currentHash !== state.contentHash) {
					throw new Error(
						`File ${filePath} changed between validation and write (TOCTOU). Retry the edit.`,
					);
				}
			}

			// Build new content based on mode
			const newLines = newContent.split("\n");
			let resultLines: string[];

			switch (mode) {
				case "replace":
					resultLines = [
						...lines.slice(0, startLine - 1),
						...newLines,
						...lines.slice(endLine),
					];
					break;
				case "before":
					resultLines = [
						...lines.slice(0, startLine - 1),
						...newLines,
						...lines.slice(startLine - 1),
					];
					break;
				case "after":
					resultLines = [
						...lines.slice(0, endLine),
						...newLines,
						...lines.slice(endLine),
					];
					break;
			}

			const finalContent = resultLines.join("\n");

			// Syntax check (before writing)
			if (!options.skipSyntaxCheck) {
				await this.validator.syntaxCheck(finalContent, absPath);
			}

			// Backup original
			await this.history.backup(sessionId, absPath, currentContent);

			// Atomic write
			atomicWrite(absPath, finalContent);

			// Notify LSP if available
			if (this.lspManager) {
				this.lspManager.notifyFileSaved(absPath, finalContent);
			}

			// Trigger immediate reindex for this file
			this.triggerReindex(absPath);

			return {
				filePath,
				startLine,
				endLine,
				linesChanged: newLines.length,
				dryRun: false,
				sessionId,
			};
		} finally {
			release();
		}
	}

	/**
	 * Restore all files from an edit session.
	 */
	async restoreSession(sessionId?: string): Promise<string[]> {
		if (sessionId) {
			return this.history.restoreAll(sessionId);
		}
		const latest = this.history.getLatestSession();
		if (!latest) {
			throw new Error("No edit sessions to restore");
		}
		return this.history.restoreAll(latest.sessionId);
	}

	/**
	 * List edit sessions.
	 */
	listSessions() {
		return this.history.listSessions();
	}

	/**
	 * Get the EditHistory instance (for WorkspaceEditApplier).
	 */
	getHistory(): EditHistory {
		return this.history;
	}

	/**
	 * Trigger immediate reindex for a specific file.
	 * Spawns a background process to avoid blocking.
	 */
	private triggerReindex(filePath: string): void {
		try {
			const child = spawn("mnemex", ["index", "--quiet", "--files", filePath], {
				cwd: this.config.workspaceRoot,
				stdio: "ignore",
				detached: true,
			});
			// spawn() reports a missing executable ASYNCHRONOUSLY via an 'error'
			// event — it does not throw — so the catch below never sees ENOENT.
			// Without a listener Node re-raises it as an unhandled 'error' and
			// takes the process down, which defeats the best-effort intent: the
			// edit itself succeeded and only the follow-up reindex is missing.
			// Happens whenever mnemex is not on PATH (library use, npx, a dev
			// checkout without `npm link`, CI).
			child.on("error", () => {});
			child.unref();
		} catch {
			// Synchronous spawn failures (e.g. unusable cwd) — also best-effort.
		}
	}
}

/**
 * Atomic write: write to temp file, then rename.
 * Uses crypto.randomBytes for unpredictable temp filenames.
 */
export function atomicWrite(filePath: string, content: string): void {
	const dir = dirname(filePath);
	const tmpName = `.mnemex-tmp-${randomBytes(8).toString("hex")}`;
