/**
 * Symbol Locator
 *
 * Finds symbol definitions by name using the AST reference graph and file tracker.
 * Supports optional LSP position refinement when an LspManager is available.
 */

import type { ReferenceGraphManager } from "../core/reference-graph.js";
import type { IFileTracker } from "../core/tracker.js";
import type { LspManager } from "../lsp/manager.js";
import type { SymbolDefinition } from "../types.js";

export interface SymbolLocation {
	filePath: string;
	startLine: number;
	endLine: number;
	source: "tree-sitter" | "lsp";
	symbol: SymbolDefinition;
}

/**
 * Convert a UTF-16 offset (LSP standard) to a byte offset in a string.
 * LSP uses UTF-16 code units for character positions; tree-sitter uses bytes.
 */
export function utf16ToByteOffset(line: string, utf16Offset: number): number {
	let utf16Count = 0;
	let byteCount = 0;
	for (const codePoint of line) {
		if (utf16Count >= utf16Offset) break;
		const charCode = codePoint.codePointAt(0)!;
		// Surrogate pairs count as 2 UTF-16 code units
		utf16Count += charCode > 0xffff ? 2 : 1;
		byteCount += Buffer.byteLength(codePoint, "utf-8");
	}
	return byteCount;
}

/**
 * Convert a byte offset to a UTF-16 offset (LSP standard).
 */
export function byteToUtf16Offset(line: string, byteOffset: number): number {
	let utf16Count = 0;
	let byteCount = 0;
	for (const codePoint of line) {
		if (byteCount >= byteOffset) break;
		const charCode = codePoint.codePointAt(0)!;
		utf16Count += charCode > 0xffff ? 2 : 1;
		byteCount += Buffer.byteLength(codePoint, "utf-8");
	}
	return utf16Count;
}

export class SymbolLocator {
	constructor(
		private graphManager: ReferenceGraphManager,
		private tracker: IFileTracker,
		private lspManager: LspManager | null = null,
	) {}

	/**
	 * Find a symbol by name, optionally scoped to a file.
	 */
	locate(
		symbolName: string,
		options: { file?: string; kind?: string } = {},
	): SymbolLocation | null {
		// Try reference graph first (most common path)
		const found = this.graphManager.findSymbol(symbolName, {
			preferExported: true,
			fileHint: options.file,
		});

		if (!found) return null;
		if (options.kind && options.kind !== "any" && found.kind !== options.kind) {
			return null;
		}

		return {
			filePath: found.filePath,
			startLine: found.startLine,
			endLine: found.endLine,
			source: "tree-sitter",
			symbol: found,
		};
	}

	/**
	 * Find all symbols in a file.
	 */
	locateByFile(filePath: string): SymbolLocation[] {
		const symbols = this.tracker.getSymbolsByFile(filePath);
		return symbols.map((s) => ({
			filePath: s.filePath,
			startLine: s.startLine,
			endLine: s.endLine,
			source: "tree-sitter" as const,
			symbol: s,
		}));
	}
}

/**
 * Edit Validator
 *
 * Pre-flight checks before any file edit: path traversal, hash freshness,
 * size limits, and syntax validation via tree-sitter.
 */

import { createHash } from "node:crypto";
import { readFileSync, realpathSync } from "node:fs";
import { extname } from "node:path";
import type { IFileTracker } from "../core/tracker.js";
import { getParserManager } from "../parsers/parser-manager.js";
import type { SupportedLanguage } from "../types.js";

const MAX_EDIT_SIZE = 1_000_000; // 1MB

/** Extension → SupportedLanguage for syntax checking */
const EXT_TO_LANG: Record<string, SupportedLanguage> = {
	".ts": "typescript",
	".mts": "typescript",
	".cts": "typescript",
	".tsx": "tsx",
	".js": "javascript",
	".mjs": "javascript",
	".cjs": "javascript",
	".jsx": "jsx",
	".py": "python",
	".go": "go",
	".rs": "rust",
	".c": "c",
	".h": "c",
	".cpp": "cpp",
	".java": "java",
};

export class EditValidator {
	/**
	 * Guard against path traversal and symlink escape.
	 * Uses fs.realpathSync to resolve symlinks before checking containment.
	 */
	preCheck(filePath: string, workspaceRoot: string): void {
		let resolvedPath: string;
		let resolvedRoot: string;
		try {
			resolvedPath = realpathSync(filePath);
			resolvedRoot = realpathSync(workspaceRoot);
		} catch {
			throw new Error(`Path resolution failed: ${filePath}`);
		}

		if (
			!resolvedPath.startsWith(`${resolvedRoot}/`) &&
			resolvedPath !== resolvedRoot
		) {
			throw new Error(
				`Path traversal blocked: ${filePath} resolves outside workspace`,
			);
		}
	}

	/**
	 * Compare current file hash with tracked hash to detect stale edits.
	 * Returns the current content hash for TOCTOU re-verification inside locks.
	 */
	hashCheck(filePath: string, tracker: IFileTracker): string {
		const state = tracker.getFileState(filePath);
		if (!state) {
			// File not indexed yet — allow edit but warn
			return "";
		}

		const currentContent = readFileSync(filePath, "utf-8");
		const currentHash = createHash("sha256")
			.update(currentContent)
			.digest("hex");

		if (currentHash !== state.contentHash) {
			throw new Error(
				`File ${filePath} has been modified since last index. ` +
					`Run 'mnemex index' or wait for auto-reindex.`,
			);
		}

		return currentHash;
	}

	/**
	 * Reject edits that would create files larger than 1MB.
	 */
	sizeCheck(newContent: string): void {
		const bytes = Buffer.byteLength(newContent, "utf-8");
		if (bytes > MAX_EDIT_SIZE) {
			throw new Error(
				`Edit result too large: ${bytes} bytes exceeds ${MAX_EDIT_SIZE} byte limit`,
			);
		}
	}

	/**
	 * Parse the new content with tree-sitter to verify syntax validity.
	 * Returns true if valid, throws on syntax errors for known languages.
	 * Silently returns true for unsupported languages.
	 */
	async syntaxCheck(content: string, filePath: string): Promise<boolean> {
		const ext = extname(filePath);
		const lang = EXT_TO_LANG[ext];
		if (!lang) return true; // Unknown language, skip check

		const pm = getParserManager();
		const tree = await pm.parse(content, lang);
		if (!tree) return true; // Parser not available

		// Check for ERROR nodes in the tree
		const hasError = tree.rootNode.hasError;
		if (hasError) {
			throw new Error(
				`Syntax error in edited content for ${filePath}. ` +
					`The edit would produce invalid ${lang} code.`,
			);
		}

		return true;
	}
}

/**
 * Workspace Edit Applier
 *
 * Applies LSP WorkspaceEdit objects atomically to disk.
 * Two-phase approach: backup all files, then apply all edits.
 * Rolls back on any failure.
 */

import { randomBytes } from "node:crypto";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import type {
	TextDocumentEdit,
	TextEdit,
	WorkspaceEdit,
} from "../lsp/protocol.js";
import { uriToPath } from "../lsp/protocol.js";
import { atomicWrite } from "./editor.js";
import type { EditHistory } from "./history.js";

export interface ApplyResult {
	filesChanged: string[];
	totalEdits: number;
	sessionId: string;
}

export class WorkspaceEditApplier {
	constructor(
		private workspaceRoot: string,
		private history: EditHistory,
	) {}

	/**
	 * Apply a WorkspaceEdit atomically.
	 * Handles both `changes` and `documentChanges` forms.
	 */
	async apply(
		edit: WorkspaceEdit,
		options: { dryRun?: boolean; sessionId?: string } = {},
	): Promise<ApplyResult> {
		const sessionId = options.sessionId ?? randomBytes(8).toString("hex");

		// Normalize both forms into a single map of filePath → TextEdit[]
		const editsByFile = this.normalizeEdits(edit);

		if (editsByFile.size === 0) {
			return { filesChanged: [], totalEdits: 0, sessionId };
		}

		const filePaths = Array.from(editsByFile.keys());
		let totalEdits = 0;

		for (const edits of editsByFile.values()) {
			totalEdits += edits.length;
		}

		if (options.dryRun) {
			return { filesChanged: filePaths, totalEdits, sessionId };
		}

		// Phase 1: Backup all files
		const backups: Array<{ filePath: string; content: string }> = [];
		for (const filePath of filePaths) {
			const content = readFileSync(filePath, "utf-8");
			backups.push({ filePath, content });
		}

		await this.history.backupAll(
			sessionId,
			backups.map((b) => ({ filePath: b.filePath, content: b.content })),
		);

		// Phase 2: Apply all edits
		try {
			for (const [filePath, edits] of editsByFile) {
				const original = readFileSync(filePath, "utf-8");
				const modified = applyTextEdits(original, edits);
				atomicWrite(filePath, modified);
			}

			return { filesChanged: filePaths, totalEdits, sessionId };
		} catch (err) {
			// Rollback: restore all files from backup
			try {
				await this.history.restoreAll(sessionId);
			} catch {
				// Rollback failure is catastrophic — nothing we can do
			}
			throw err;
		}
	}

	/**
	 * Normalize WorkspaceEdit into filePath → TextEdit[] map.
	 */
	private normalizeEdits(edit: WorkspaceEdit): Map<string, TextEdit[]> {
		const result = new Map<string, TextEdit[]>();

		// Handle `documentChanges` form (preferred, versioned)
		if (edit.documentChanges) {
			for (const docEdit of edit.documentChanges) {
				const te = docEdit as TextDocumentEdit;
				if (te.textDocument?.uri && te.edits) {
					const filePath = this.resolvePath(te.textDocument.uri);
					const existing = result.get(filePath) ?? [];
					existing.push(...te.edits);
					result.set(filePath, existing);
				}
			}
		}

		// Handle `changes` form (simple)
		if (edit.changes) {
			for (const [uri, edits] of Object.entries(edit.changes)) {
				const filePath = this.resolvePath(uri);
				const existing = result.get(filePath) ?? [];
				existing.push(...edits);
				result.set(filePath, existing);
			}
		}

		return result;
	}

	private resolvePath(uri: string): string {
		const path = uriToPath(uri);
		return resolve(this.workspaceRoot, path);
	}
}

/**
 * Apply a list of TextEdits to source text.
 * Edits are applied in reverse order (bottom-to-top) so line numbers stay valid.
 */
function applyTextEdits(source: string, edits: TextEdit[]): string {
	const lines = source.split("\n");

	// Sort edits by position, descending (apply from bottom to top)
	const sorted = [...edits].sort((a, b) => {
		if (a.range.start.line !== b.range.start.line) {
			return b.range.start.line - a.range.start.line;
		}
		return b.range.start.character - a.range.start.character;
	});

	for (const edit of sorted) {
		const startLine = edit.range.start.line;
		const startChar = edit.range.start.character;
		const endLine = edit.range.end.line;
		const endChar = edit.range.end.character;

		// Handle the edit
		const prefix = (lines[startLine] ?? "").substring(0, startChar);
		const suffix = (lines[endLine] ?? "").substring(endChar);
		const newText = prefix + edit.newText + suffix;

		const newLines = newText.split("\n");
		lines.splice(startLine, endLine - startLine + 1, ...newLines);
	}

	return lines.join("\n");
}

/**
 * Git Hook Manager
 *
 * Manages installation and removal of git hooks for auto-indexing.
 * Supports post-commit hook that runs mnemex index after each commit.
 */

import {
	chmodSync,
	existsSync,
	mkdirSync,
	readFileSync,
	unlinkSync,
	writeFileSync,
} from "node:fs";
import { join } from "node:path";

// ============================================================================
// Types
// ============================================================================

export interface HookStatus {
	installed: boolean;
	hookType?: "post-commit";
	path?: string;
	isMnemex?: boolean;
}

// ============================================================================
// Hook Template
// ============================================================================

const HOOK_MARKER = "# mnemex-auto-index";

const POST_COMMIT_HOOK = `#!/bin/sh
${HOOK_MARKER}
# Auto-index changed files after each commit
# Installed by: mnemex hooks install

# Run in background to not block git
(
  if command -v mnemex >/dev/null 2>&1; then
    mnemex index --quiet 2>&1 | logger -t mnemex-hook || true
  fi
) &
`;

// ============================================================================
// Git Hook Manager Class
// ============================================================================

export class GitHookManager {
	private projectPath: string;
	private gitDir: string;
	private hooksDir: string;

	constructor(projectPath: string) {
		this.projectPath = projectPath;
		this.gitDir = join(projectPath, ".git");
		this.hooksDir = join(this.gitDir, "hooks");
	}

	/**
	 * Install the post-commit hook
	 */
	async install(): Promise<void> {
		// Check if .git directory exists
		if (!existsSync(this.gitDir)) {
			throw new Error(
				"Not a git repository. Run 'git init' first or navigate to a git repository.",
			);
		}

		// Ensure hooks directory exists
		if (!existsSync(this.hooksDir)) {
			mkdirSync(this.hooksDir, { recursive: true });
		}

		const hookPath = join(this.hooksDir, "post-commit");

		// Check if hook already exists
		if (existsSync(hookPath)) {
			const existingContent = readFileSync(hookPath, "utf-8");

			// If it's our hook, update it
			if (existingContent.includes(HOOK_MARKER)) {
				writeFileSync(hookPath, POST_COMMIT_HOOK, { mode: 0o755 });
				return;
			}

			// If it's a different hook, append our script
			const newContent = `${existingContent}\n\n${POST_COMMIT_HOOK}`;
			writeFileSync(hookPath, newContent, { mode: 0o755 });
			return;
		}

		// Create new hook
		writeFileSync(hookPath, POST_COMMIT_HOOK, { mode: 0o755 });
		chmodSync(hookPath, 0o755);
	}

	/**
	 * Uninstall the post-commit hook
	 */
	async uninstall(): Promise<void> {
		const hookPath = join(this.hooksDir, "post-commit");

		if (!existsSync(hookPath)) {
			return; // Nothing to uninstall
		}

		const content = readFileSync(hookPath, "utf-8");

		// If it's only our hook, remove the file
		if (content.includes(HOOK_MARKER)) {
			// Check if there's other content besides our hook
			const lines = content.split("\n");
			const ourHookStart = lines.findIndex((l) => l.includes(HOOK_MARKER));

			if (ourHookStart === 1) {
				// Our hook is the only content (after shebang), remove file
				unlinkSync(hookPath);
				return;
			}

			// Remove only our section
			const newLines: string[] = [];
			let inOurSection = false;

			for (const line of lines) {
				if (line.includes(HOOK_MARKER)) {
					inOurSection = true;
					continue;
				}

				if (inOurSection) {
					// Skip until we hit a blank line followed by non-mnemex content
					if (
						line.trim() === "" ||
						line.startsWith("# ") ||
						line.includes("mnemex")
					) {
						continue;
					}
					inOurSection = false;
				}

				if (!inOurSection) {
					newLines.push(line);
				}
			}

			const newContent = newLines.join("\n").trim();
			if (newContent === "#!/bin/sh" || newContent === "") {
				unlinkSync(hookPath);
			} else {
				writeFileSync(hookPath, `${newContent}\n`, { mode: 0o755 });
			}
		}
	}

	/**
	 * Check if hook is installed
	 */
	async status(): Promise<HookStatus> {
		const hookPath = join(this.hooksDir, "post-commit");

		if (!existsSync(hookPath)) {
			return { installed: false };
		}

		const content = readFileSync(hookPath, "utf-8");
		const isMnemex = content.includes(HOOK_MARKER);

		return {
			installed: isMnemex,
			hookType: isMnemex ? "post-commit" : undefined,
			path: hookPath,
			isMnemex,
		};
	}

	/**
	 * Check if we're in a git repository
	 */
	isGitRepository(): boolean {
		return existsSync(this.gitDir);
	}
}

