// Stdin/Output Utilities
// ============================================================================

/**
 * Read JSON from stdin using Bun-compatible approach
 */
async function readStdin(): Promise<string> {
	// Check if running in Bun
	const isBun = typeof globalThis.Bun !== "undefined";

	if (isBun) {
		// Bun: use Bun.stdin directly
		const text = await Bun.stdin.text();
		return text;
	}

	// Node.js fallback
	const chunks: string[] = [];
	process.stdin.setEncoding("utf-8");

	for await (const chunk of process.stdin) {
		chunks.push(chunk as string);
	}

	return chunks.join("");
}

/**
 * Write output to fd 3 (Claude Code's expected output) or stdout
 */
function writeOutput(output: HookOutput): void {
	const json = JSON.stringify(output);

	try {
		// Try fd 3 first (Claude Code's hook output channel)
		writeFileSync(3, json);
	} catch {
		// Fall back to stdout
		console.log(json);
	}
}

// ============================================================================
// Main Dispatcher
// ============================================================================

/**
 * Main hook dispatcher - reads stdin, routes to handler, writes output
 */
export async function handleHook(options: HookOptions = {}): Promise<void> {
	const { debug = false } = options;

	// Read input
	const inputJson = await readStdin();
	if (!inputJson.trim()) {
		if (debug) console.error("Empty stdin");
		return;
	}

	// Parse input
	let input: HookInput;
	try {
		input = JSON.parse(inputJson);
	} catch (error) {
		throw new Error(`Failed to parse hook input: ${error}`);
	}

	if (debug) {
		console.error(`Hook: ${input.hook_event_name} ${input.tool_name || ""}`);
	}

	// Dispatch to handler (lazy imports for fast startup)
	let output: HookOutput | null = null;

	switch (input.hook_event_name) {
		case "SessionStart": {
			const { handleSessionStart } = await import(
				"./handlers/session-start.js"
			);
			output = await handleSessionStart(input);
			break;
		}

		case "PreToolUse": {
			const { handlePreToolUse } = await import("./handlers/pre-tool-use.js");
			output = await handlePreToolUse(input);
			break;
		}

		case "PostToolUse": {
			const { handlePostToolUse } = await import("./handlers/post-tool-use.js");
			output = await handlePostToolUse(input);
			break;
		}

		case "Stop":
		case "SubagentStop":
			// No action needed for these events currently
			break;

		default:
			if (debug) {
				console.error(`Unknown hook event: ${input.hook_event_name}`);
			}
	}

	// Write output if any
	if (output) {
		writeOutput(output);
	}
}

/**
 * InteractionLogger - Hook handler integration for interaction monitoring.
 *
 * This module provides a singleton InteractionSystem that can be used by
 * hook handlers to log user-agent interactions. It lazily initializes
 * the database connection on first use.
 */

import { existsSync } from "node:fs";
import { join } from "node:path";
import { createDatabaseSync, type SQLiteDatabase } from "../../core/sqlite.js";
import {
	createInteractionSystem,
	generateSessionId,
	type InteractionSystem,
} from "../../learning/interaction/index.js";
import type { HookInput, ToolInput, ToolResponse } from "../types.js";

// ============================================================================
// Singleton Management
// ============================================================================

/** Cached interaction systems by project path */
const systemCache: Map<string, InteractionSystem> = new Map();

/** Cached database connections by project path */
const dbCache: Map<string, SQLiteDatabase> = new Map();

/**
 * Get or create InteractionSystem for a project.
 */
function getInteractionSystem(projectPath: string): InteractionSystem | null {
	// Check if enabled
	const enabled = process.env.CLAUDE_LEARNING !== "off";
	if (!enabled) return null;

	// Return cached system
	if (systemCache.has(projectPath)) {
		return systemCache.get(projectPath)!;
	}

	// Check if project is indexed
	const indexDir = join(projectPath, ".mnemex");
	if (!existsSync(indexDir)) {
		return null;
	}

	// Open or create database
	const dbPath = join(indexDir, "index.db");
	let db = dbCache.get(projectPath);
	if (!db) {
		try {
			db = createDatabaseSync(dbPath);
			dbCache.set(projectPath, db);
		} catch {
			return null;
		}
	}

	// Create interaction system
	const system = createInteractionSystem(db);
	systemCache.set(projectPath, system);

	return system;
}

// ============================================================================
// Session Management
// ============================================================================

/** Active session IDs by project path */
const activeSessions: Map<string, string> = new Map();

/**
 * Get or create session ID for a project.
 */
function ensureSessionId(projectPath: string, hookSessionId: string): string {
	// Use hook's session_id if available
	if (hookSessionId) {
		activeSessions.set(projectPath, hookSessionId);
		return hookSessionId;
	}

	// Return existing session
	const existing = activeSessions.get(projectPath);
	if (existing) {
		return existing;
	}

	// Generate new session
	const newSessionId = generateSessionId(projectPath);
	activeSessions.set(projectPath, newSessionId);
	return newSessionId;
}

