/**
 * Handle PreToolUse hook events
 */
export async function handlePreToolUse(
	input: HookInput,
): Promise<HookOutput | null> {
	// Log tool start for interaction monitoring
	try {
		logToolStart(input);
	} catch {
		// Don't fail the hook if logging fails
	}

	switch (input.tool_name) {
		case "Grep":
			return handleGrepIntercept(input);
		case "Bash":
			return handleBashIntercept(input);
		case "Glob":
			return handleGlobIntercept(input);
		case "Read":
			return handleReadIntercept(input);
		default:
			return null;
	}
}

/**
 * SessionStart Hook Handler
 *
 * Runs when Claude Code session starts:
 * - Cleans up old temporary session directories
 * - Checks mnemex version and index status
 * - Initializes interaction monitoring
 * - Returns context about available features
 */

import { spawnSync } from "node:child_process";
import {
	existsSync,
	readdirSync,
	readFileSync,
	rmSync,
	statSync,
} from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { HookInput, HookOutput, IndexStatus } from "../types.js";
import { cleanupStaleSessions, logSessionStart } from "./interaction-logger.js";

// ============================================================================
// Version Utilities
// ============================================================================

/** Cached version */
let _version: string | null = null;

/**
 * Get mnemex version from package.json
 */
function getVersion(): string | null {
	if (_version) return _version;

	try {
		const __dirname = dirname(fileURLToPath(import.meta.url));
		const paths = [
			join(__dirname, "../../../package.json"),
			join(__dirname, "../../package.json"),
			join(process.cwd(), "package.json"),
		];

		for (const path of paths) {
			if (existsSync(path)) {
				const pkg = JSON.parse(readFileSync(path, "utf-8"));
				if (pkg.name === "mnemex" || pkg.name === "mnemex") {
					_version = pkg.version || null;
					return _version;
				}
			}
		}
	} catch {
		// Ignore errors
	}

	return null;
}

/**
 * Compare semantic versions (returns true if version >= required)
 */
function versionGte(version: string, required: string): boolean {
	const v1 = version.split(".").map(Number);
	const v2 = required.split(".").map(Number);

	for (let i = 0; i < Math.max(v1.length, v2.length); i++) {
		const a = v1[i] || 0;
		const b = v2[i] || 0;
		if (a > b) return true;
		if (a < b) return false;
	}
	return true;
}

// ============================================================================
// Index Status Utilities
// ============================================================================

/**
 * Check if project is indexed
 */
function isIndexed(cwd: string): IndexStatus {
	const indexDir = join(cwd, ".mnemex");
	if (!existsSync(indexDir)) {
		return { indexed: false };
	}

	const dbPath = join(indexDir, "index.db");
	if (!existsSync(dbPath)) {
		return { indexed: false };
	}

	// Try to get symbol count from status command
	try {
		const result = spawnSync(
			process.execPath,
			[process.argv[1], "status", "--nologo"],
			{
				cwd,
				encoding: "utf-8",
				timeout: 5000,
			},
		);

		if (result.status === 0 && result.stdout) {
			// Look for chunk/file count in output
			const match = result.stdout.match(/(\d+)\s+(chunks|files|symbols)/i);
			if (match) {
				return { indexed: true, symbolCount: match[0] };
			}
		}
		return { indexed: true, symbolCount: "available" };
	} catch {
		return { indexed: true, symbolCount: "available" };
	}
}

