/**
 * SafetyScorer - Compute final safety score for auto-deploy gating.
 *
 * Combines multiple signals:
 * - Red team vulnerability score
 * - Blue team defense report
 * - Pattern confidence
 * - Historical performance
 *
 * Determines whether an improvement can be auto-deployed
 * or requires human review.
 */

import type { Improvement } from "../interaction/types.js";
import type { DefenseReport } from "./blue-team.js";
import type { RedTeamReport } from "./red-team.js";

// ============================================================================
// Types
// ============================================================================

export interface SafetyScorerConfig {
	/** Weight for red team score */
	redTeamWeight: number;
	/** Weight for blue team score */
	blueTeamWeight: number;
	/** Weight for pattern confidence */
	patternWeight: number;
	/** Weight for historical performance */
	historyWeight: number;
	/** Threshold for auto-deploy */
	autoDeployThreshold: number;
	/** Threshold for human review */
	humanReviewThreshold: number;
	/** Require all components for auto-deploy */
	requireAllComponents: boolean;
}

export const DEFAULT_SCORER_CONFIG: SafetyScorerConfig = {
	redTeamWeight: 0.3,
	blueTeamWeight: 0.35,
	patternWeight: 0.2,
	historyWeight: 0.15,
	autoDeployThreshold: 0.9,
	humanReviewThreshold: 0.7,
	requireAllComponents: true,
};

export type DeploymentDecision = "auto_deploy" | "human_review" | "reject";

export interface SafetyScoreResult {
	/** Overall safety score (0-1) */
	overallScore: number;
	/** Component scores */
	componentScores: {
		redTeam: number;
		blueTeam: number;
		pattern: number;
		history: number;
	};
	/** Deployment decision */
	decision: DeploymentDecision;
	/** Confidence in decision (0-1) */
	confidence: number;
	/** Factors that influenced the decision */
	factors: SafetyFactor[];
	/** Recommendations */
	recommendations: string[];
	/** Timestamp */
	timestamp: number;
}

export interface SafetyFactor {
	/** Factor name */
	name: string;
	/** Factor type */
	type: "positive" | "negative" | "neutral";
	/** Impact on score */
	impact: number;
	/** Description */
	description: string;
}

export interface HistoricalData {
	/** Previous deployments of similar improvements */
	similarDeployments: number;
	/** Success rate of similar deployments */
	successRate: number;
	/** Rollback rate */
	rollbackRate: number;
	/** Average time before rollback (if any) */
	avgTimeToRollbackMs?: number;
}

export interface ScoringContext {
	/** Red team report (if available) */
	redTeamReport?: RedTeamReport;
	/** Defense report (if available) */
	defenseReport?: DefenseReport;
	/** Historical data (if available) */
	historicalData?: HistoricalData;
	/** Additional context */
	context?: Record<string, unknown>;
}

// ============================================================================
// SafetyScorer Class
// ============================================================================

export class SafetyScorer {
	private config: SafetyScorerConfig;
	private scoringHistory: Array<{
		improvementId: string;
		score: number;
		decision: DeploymentDecision;
		timestamp: number;
	}>;

	constructor(config: Partial<SafetyScorerConfig> = {}) {
		this.config = { ...DEFAULT_SCORER_CONFIG, ...config };
		this.scoringHistory = [];
	}

	/**
	 * Score an improvement for deployment.
	 */
	score(improvement: Improvement, context: ScoringContext): SafetyScoreResult {
		const factors: SafetyFactor[] = [];
		const componentScores = {
			redTeam: 0,
			blueTeam: 0,
			pattern: 0,
			history: 0,
		};

		// Red team score
		if (context.redTeamReport) {
			componentScores.redTeam = 1 - context.redTeamReport.vulnerabilityScore;
			factors.push(...this.analyzeRedTeamFactors(context.redTeamReport));
		} else {
			componentScores.redTeam = 0.5; // Unknown = neutral
			factors.push({
				name: "No Red Team Testing",
				type: "neutral",
				impact: 0,
				description: "No adversarial testing performed",
			});
		}

		// Blue team score
		if (context.defenseReport) {
			componentScores.blueTeam = context.defenseReport.safetyScore;
			factors.push(...this.analyzeBlueTeamFactors(context.defenseReport));
		} else {
			componentScores.blueTeam = 0.5;
			factors.push({
				name: "No Defense Validation",
				type: "neutral",
				impact: 0,
				description: "No defense validation performed",
			});
		}

		// Pattern confidence score
		componentScores.pattern = this.scorePatternConfidence(improvement);
		factors.push(...this.analyzePatternFactors(improvement));

		// Historical score
		if (context.historicalData) {
			componentScores.history = this.scoreHistoricalData(
				context.historicalData,
			);
			factors.push(...this.analyzeHistoricalFactors(context.historicalData));
		} else {
			componentScores.history = 0.5;
			factors.push({
				name: "No Historical Data",
				type: "neutral",
				impact: 0,
				description: "No historical data available",
			});
		}

		// Calculate weighted overall score
		const overallScore = this.calculateWeightedScore(componentScores);

		// Check if all components are present (if required)
		const allComponentsPresent =
			context.redTeamReport !== undefined &&
			context.defenseReport !== undefined &&
			context.historicalData !== undefined;

		// Determine decision
		const decision = this.determineDecision(
			overallScore,
			allComponentsPresent,
			factors,
		);

		// Calculate confidence
		const confidence = this.calculateConfidence(
			componentScores,
			allComponentsPresent,
		);

		// Generate recommendations
		const recommendations = this.generateRecommendations(
			decision,
			factors,
			componentScores,
		);

		const result: SafetyScoreResult = {
			overallScore,
			componentScores,
			decision,
			confidence,
			factors,
			recommendations,
			timestamp: Date.now(),
		};

		// Record in history
		this.scoringHistory.push({
			improvementId: improvement.improvementId,
			score: overallScore,
			decision,
			timestamp: Date.now(),
		});

		return result;
	}

	/**
	 * Quick check if improvement can be auto-deployed.
	 */
	canAutoDeploy(improvement: Improvement, context: ScoringContext): boolean {
		const result = this.score(improvement, context);
		return result.decision === "auto_deploy";
	}

	/**
	 * Get required actions before deployment.
	 */
	getRequiredActions(
		improvement: Improvement,
		context: ScoringContext,
	): string[] {
		const result = this.score(improvement, context);
		const actions: string[] = [];

		if (result.decision === "reject") {
			actions.push("Cannot deploy: too many safety concerns");
			actions.push(...result.recommendations);
			return actions;
		}

		if (result.decision === "human_review") {
			actions.push("Requires human review before deployment");
		}

		// Add specific actions based on missing components
		if (!context.redTeamReport) {
			actions.push("Run red team testing");
		}
		if (!context.defenseReport) {
			actions.push("Run blue team validation");
		}
		if (!context.historicalData) {
			actions.push("Consider A/B testing before full deployment");
		}

		return actions;
	}

	/**
	 * Get scoring statistics.
	 */
	getStatistics(): {
		totalScored: number;
		autoDeployed: number;
		humanReview: number;
		rejected: number;
		avgScore: number;
	} {
		const byDecision = {
			auto_deploy: 0,
			human_review: 0,
			reject: 0,
		};

		let totalScore = 0;

		for (const record of this.scoringHistory) {
			byDecision[record.decision]++;
			totalScore += record.score;
		}

		return {
			totalScored: this.scoringHistory.length,
			autoDeployed: byDecision.auto_deploy,
			humanReview: byDecision.human_review,
			rejected: byDecision.reject,
			avgScore:
				this.scoringHistory.length > 0
					? totalScore / this.scoringHistory.length
					: 0,
		};
	}

	/**
	 * Get scoring history.
	 */
	getHistory(limit: number = 20): typeof this.scoringHistory {
		return this.scoringHistory.slice(-limit);
	}

	// ===================================================================

/**
 * ErrorClusterer - Groups similar errors for pattern detection.
 *
 * Uses a combination of:
 * - Error type categorization
 * - Message similarity (Jaccard/cosine)
 * - Tool context clustering
 *
 * Clustered errors help identify:
 * - Repetitive agent mistakes
 * - Common failure modes
 * - Areas needing improvement
 */

import type { ToolEvent } from "../interaction/types.js";

// ============================================================================
// Types
// ============================================================================

export interface ErrorClusterConfig {
	/** Minimum similarity for clustering (0-1) */
	minSimilarity: number;
	/** Maximum number of clusters */
	maxClusters: number;
	/** Minimum errors per cluster */
	minClusterSize: number;
}

export const DEFAULT_CLUSTER_CONFIG: ErrorClusterConfig = {
	minSimilarity: 0.5,
	maxClusters: 50,
	minClusterSize: 2,
};

export interface ErrorInstance {
	toolUseId: string;
	sessionId: string;
	toolName: string;
	errorType?: string;
	errorMessage?: string;
	timestamp: number;
}

export interface ErrorCluster {
	clusterId: string;
	/** Representative error for the cluster */
	centroid: ErrorInstance;
	/** All errors in this cluster */
	members: ErrorInstance[];
	/** Dominant error type in cluster */
	errorType: string;
	/** Common tools involved */
	tools: string[];
	/** Cluster quality score (0-1) */
	cohesion: number;
	/** How often this error occurs */
	frequency: number;
	/** Suggested fix category */
	suggestedCategory:
		| "validation"
		| "logic"
		| "permission"
		| "timeout"
		| "unknown";
}

export interface ClusteringResult {
	clusters: ErrorCluster[];
	noise: ErrorInstance[];
	totalErrors: number;
	clusteringQuality: number;
}

// ============================================================================
// ErrorClusterer Class
// ============================================================================

export class ErrorClusterer {
	private config: ErrorClusterConfig;

	constructor(config: Partial<ErrorClusterConfig> = {}) {
		this.config = { ...DEFAULT_CLUSTER_CONFIG, ...config };
	}

	/**
	 * Cluster error events from tool executions.
	 */
	cluster(events: ToolEvent[]): ClusteringResult {
		// Extract failed events
		const errorInstances = this.extractErrors(events);

		if (errorInstances.length === 0) {
			return {
				clusters: [],
				noise: [],
				totalErrors: 0,
				clusteringQuality: 1,
			};
		}

		// Simple hierarchical clustering
		const clusters = this.hierarchicalClustering(errorInstances);

		// Calculate noise (unclustered errors)
		const clusteredIds = new Set(
			clusters.flatMap((c) => c.members.map((m) => m.toolUseId)),
		);
		const noise = errorInstances.filter((e) => !clusteredIds.has(e.toolUseId));

		// Calculate clustering quality
		const clusteringQuality = this.calculateQuality(
			clusters,
			errorInstances.length,
		);

		return {
			clusters,
			noise,
			totalErrors: errorInstances.length,
			clusteringQuality,
		};
	}

	/**
	 * Get top error clusters by frequency.
	 */
	getTopClusters(result: ClusteringResult, limit = 10): ErrorCluster[] {
		return result.clusters
			.sort((a, b) => b.frequency - a.frequency)
			.slice(0, limit);
	}

	/**
	 * Get clusters by error type.
	 */
	getClustersByType(
		result: ClusteringResult,
		errorType: string,
	): ErrorCluster[] {
		return result.clusters.filter((c) => c.errorType === errorType);
	}

	// ========================================================================
	// Private Methods
	// ========================================================================

	/**
	 * Extract error instances from tool events.
	 */
	private extractErrors(events: ToolEvent[]): ErrorInstance[] {
		return events
			.filter((e) => !e.success)
			.map((e) => ({
				toolUseId: e.toolUseId,
				sessionId: e.sessionId,
				toolName: e.toolName,
				errorType: e.errorType,
				errorMessage: e.error,
				timestamp: e.timestamp,
			}));
	}

	/**
	 * Hierarchical agglomerative clustering.
	 */
	private hierarchicalClustering(errors: ErrorInstance[]): ErrorCluster[] {
		// Initialize each error as its own cluster
		let clusters: ErrorInstance[][] = errors.map((e) => [e]);

		// Merge until we reach max clusters or no more similar pairs
		while (clusters.length > this.config.maxClusters) {
			const { i, j, similarity } = this.findMostSimilarPair(clusters);

			if (similarity < this.config.minSimilarity) {
				break;
			}

			// Merge clusters i and j
			const merged = [...clusters[i], ...clusters[j]];
			clusters = clusters.filter((_, idx) => idx !== i && idx !== j);
			clusters.push(merged);
		}

		// Filter small clusters and convert to ErrorCluster format
		return clusters
			.filter((c) => c.length >= this.config.minClusterSize)
			.map((members) => this.createCluster(members, errors.length));
	}

	/**
	 * Find the most similar pair of clusters.
	 */
	private findMostSimilarPair(clusters: ErrorInstance[][]): {
		i: number;
		j: number;
		similarity: number;
	} {
		let maxSimilarity = -1;
		let bestI = 0;
		let bestJ = 1;

		for (let i = 0; i < clusters.length; i++) {
			for (let j = i + 1; j < clusters.length; j++) {
				const similarity = this.clusterSimilarity(clusters[i], clusters[j]);
				if (similarity > maxSimilarity) {
					maxSimilarity = similarity;
					bestI = i;
					bestJ = j;
				}
			}
		}

		return { i: bestI, j: bestJ, similarity: maxSimilarity };
	}

	/**
	 * Calculate similarity between two clusters (average linkage).
	 */
	private clusterSimilarity(
		cluster1: ErrorInstance[],
		cluster2: ErrorInstance[],
	): number {
		let totalSimilarity = 0;
		let count = 0;

		for (const e1 of cluster1) {
			for (const e2 of cluster2) {
				totalSimilarity += this.errorSimilarity(e1, e2);
				count++;
			}
		}

		return count > 0 ? totalSimilarity / count : 0;
	}

	/**
	 * Calculate similarity between two error instances.
	 */
	private errorSimilarity(e1: ErrorInstance, e2: ErrorInstance): number {
		let score = 0;
		let weights = 0;

		// Same tool = high similarity
		if (e1.toolName === e2.toolName) {
			score += 0.4;
		}
		weights += 0.4;

		// Same error type = high similarity
		if (e1.errorType && e2.errorType && e1.errorType === e2.errorType) {
			score += 0.3;
		}
		weights += 0.3;

		// Error message similarity
		if (e1.errorMessage && e2.errorMessage) {
			const messageSim = this.stringSimilarity(
				e1.errorMessage,
				e2.errorMessage,
			);
			score += messageSim * 0.3;
		}
		weights += 0.3;

		return weights > 0 ? score / weights : 0;
	}

	/**
	 * Calculate string similarity using Jaccard index on tokens.
	 */
	private stringSimilarity(s1: string, s2: string): number {
		const tokens1 = this.tokenize(s1);
		const tokens2 = this.tokenize(s2);

		if (tokens1.size === 0 || tokens2.size === 0) {
			return 0;
		}

		let intersection = 0;
