}

export const DEFAULT_SYNC_CONFIG: SyncCoordinatorConfig = {
	enabled: false, // Opt-in
	syncIntervalMs: 24 * 60 * 60 * 1000, // Daily
	maxPatternsPerSync: 100,
	minLocalPatterns: 10,
	trustThreshold: 0.7,
	localWeight: 0.8,
	maxPatternAgeMs: 30 * 24 * 60 * 60 * 1000, // 30 days
};

export interface SyncPeer {
