	): void {
		const stmt = this.db.prepare(`
			UPDATE agent_sessions SET
				tool_count = tool_count + ?,
				intervention_count = intervention_count + ?,
				autonomous_count = autonomous_count + ?
			WHERE session_id = ?

/**
 * SessionTracker - Manages agent session lifecycle.
 *
 * Responsibilities:
 * - Track session start/end
 * - Maintain active session state
 * - Update session counters
 * - Detect session outcomes
 */

import { createHash } from "node:crypto";
import type { InteractionStore } from "./interaction-store.js";
import type {
	AgentSession,
	InteractionConfig,
	SessionOutcome,
} from "./types.js";
import { DEFAULT_INTERACTION_CONFIG } from "./types.js";

// ============================================================================
// SessionTracker Class
// ============================================================================

export class SessionTracker {
	private store: InteractionStore;
	private config: InteractionConfig;
	private activeSessions: Map<string, SessionState> = new Map();

	constructor(
		store: InteractionStore,
		config: Partial<InteractionConfig> = {},
	) {
		this.store = store;
		this.config = { ...DEFAULT_INTERACTION_CONFIG, ...config };
	}

	/**
	 * Start tracking a new session.
	 */
	startSession(sessionId: string, projectPath: string): void {
		if (!this.config.enabled) return;

		const session: AgentSession = {
			sessionId,
			timestamp: Date.now(),
			projectPath,
			toolCount: 0,
			interventionCount: 0,
			autonomousCount: 0,
		};

		this.store.upsertSession(session);

		this.activeSessions.set(sessionId, {
			session,
			startTime: Date.now(),
			lastActivity: Date.now(),
			toolExecutionOrder: 0,
			pendingTools: new Map(),
		});
	}

	/**
	 * Check if a session is active.
	 */
	isSessionActive(sessionId: string): boolean {
		return this.activeSessions.has(sessionId);
	}

	/**
	 * Get active session state.
	 */
	getSessionState(sessionId: string): SessionState | undefined {
		return this.activeSessions.get(sessionId);
	}

	/**
	 * Record tool start (for duration tracking).
	 */
	toolStarted(sessionId: string, toolUseId: string): void {
		const state = this.activeSessions.get(sessionId);
		if (!state) return;

		state.pendingTools.set(toolUseId, {
			startTime: Date.now(),
			executionOrder: ++state.toolExecutionOrder,
		});
		state.lastActivity = Date.now();
	}

	/**
	 * Record tool completion.
	 */
	toolCompleted(
		sessionId: string,
		toolUseId: string,
	): { durationMs: number; executionOrder: number } | undefined {
		const state = this.activeSessions.get(sessionId);
		if (!state) return undefined;

		const pending = state.pendingTools.get(toolUseId);
		if (!pending) {
			return {
				durationMs: 0,
				executionOrder: ++state.toolExecutionOrder,
			};
		}

		state.pendingTools.delete(toolUseId);
		state.lastActivity = Date.now();

		return {
			durationMs: Date.now() - pending.startTime,
			executionOrder: pending.executionOrder,
		};
	}

	/**
	 * Increment session counters.
	 */
	incrementCounters(
		sessionId: string,
		options: {
			tools?: number;
			interventions?: number;
			autonomous?: number;
		},
	): void {
		if (!this.config.enabled) return;

		const state = this.activeSessions.get(sessionId);
		if (state) {
			state.session.toolCount += options.tools || 0;
			state.session.interventionCount += options.interventions || 0;
			state.session.autonomousCount += options.autonomous || 0;
			state.lastActivity = Date.now();
		}

		this.store.incrementSessionCounters(
			sessionId,
			options.tools || 0,
			options.interventions || 0,
			options.autonomous || 0,
		);
	}

	/**
	 * End a session.
	 */
	endSession(
		sessionId: string,
		outcome?: SessionOutcome,
	): AgentSession | undefined {
		if (!this.config.enabled) return undefined;

		const state = this.activeSessions.get(sessionId);
		if (!state) {
			// Try to update stored session anyway
			if (outcome) {
				this.store.updateSessionOutcome(sessionId, outcome);
			}
			return this.store.getSession(sessionId) || undefined;
		}

		// Calculate duration
		const duration = Date.now() - state.startTime;
		state.session.duration = duration;

		// Determine outcome if not provided
		const finalOutcome = outcome || this.inferOutcome(state);
		state.session.outcome = finalOutcome;

		// Update store
		this.store.upsertSession(state.session);

		// Remove from active sessions
		this.activeSessions.delete(sessionId);

		return state.session;
	}

	/**
	 * Get or create session for a project.
	 * Useful when hooks fire without explicit session start.
	 */
	ensureSession(sessionId: string, projectPath: string): SessionState {
		let state = this.activeSessions.get(sessionId);
		if (!state) {
			this.startSession(sessionId, projectPath);
			state = this.activeSessions.get(sessionId)!;
		}
		return state;
	}

	/**
	 * Get all active sessions.
	 */
	getActiveSessions(): Map<string, SessionState> {
		return new Map(this.activeSessions);
	}

	/**
	 * Clean up stale sessions (no activity for specified duration).
	 */
	cleanupStaleSessions(maxInactiveMs = 3600000): number {
		const now = Date.now();
		let cleaned = 0;

		for (const [sessionId, state] of this.activeSessions) {
			if (now - state.lastActivity > maxInactiveMs) {
				this.endSession(sessionId, "abandoned");
				cleaned++;
			}
		}

		return cleaned;
	}

	/**
	 * Generate a session ID from project path and timestamp.
	 */
	static generateSessionId(projectPath: string): string {
		const timestamp = Date.now();
		const random = Math.random().toString(36).substring(2, 8);
		const hash = createHash("sha256")
			.update(`${projectPath}-${timestamp}-${random}`)
			.digest("hex")
			.substring(0, 12);
		return `sess_${hash}`;
	}

	// ========================================================================
	// Private Methods
	// ========================================================================

	/**
	 * Infer session outcome from state.
	 */
	private inferOutcome(state: SessionState): SessionOutcome {
		const { session } = state;

		// No tools used = abandoned
		if (session.toolCount === 0) {
			return "abandoned";
		}

		// High intervention rate = failure
		const interventionRate = session.interventionCount / session.toolCount;
		if (interventionRate > 0.5) {
			return "failure";
		}

		// Some interventions = partial
		if (session.interventionCount > 0) {
			return "partial";
		}

		// No interventions = success
		return "success";
	}
}

// ============================================================================
// Supporting Types
// ============================================================================

/**
 * Active session state (in-memory).
 */
export interface SessionState {
	session: AgentSession;
	startTime: number;
	lastActivity: number;
	toolExecutionOrder: number;
	pendingTools: Map<string, PendingTool>;
}

/**
 * Tool execution in progress.
 */
interface PendingTool {
	startTime: number;
	executionOrder: number;
}

// ============================================================================
// Factory
// ============================================================================

/**
 * Create a SessionTracker instance.
 */
export function createSessionTracker(
	store: InteractionStore,
	config?: Partial<InteractionConfig>,
): SessionTracker {
	return new SessionTracker(store, config);
}

/**
 * ToolEventLogger - Captures and logs tool execution events.
 *
 * Responsibilities:
 * - Log tool invocations with timing
 * - Hash tool inputs for privacy
 * - Classify tool errors
 * - Track code changes for Correction Gap analysis
 */

import { createHash } from "node:crypto";
import type { InteractionStore } from "./interaction-store.js";
import type { SessionTracker } from "./session-tracker.js";
import type {
	CodeChange,
	CorrectionType,
	InteractionConfig,
	ToolErrorType,
	ToolEvent,
} from "./types.js";
import { DEFAULT_INTERACTION_CONFIG } from "./types.js";

// ============================================================================
// ToolEventLogger Class
// ============================================================================

export class ToolEventLogger {
	private store: InteractionStore;
	private sessionTracker: SessionTracker;
	private config: InteractionConfig;

	constructor(
		store: InteractionStore,
		sessionTracker: SessionTracker,
		config: Partial<InteractionConfig> = {},
	) {
		this.store = store;
		this.sessionTracker = sessionTracker;
		this.config = { ...DEFAULT_INTERACTION_CONFIG, ...config };
	}

	/**
	 * Log a tool execution event.
	 */
	logToolEvent(options: {
		sessionId: string;
		toolUseId: string;
		toolName: string;
		toolInput?: Record<string, unknown>;
		success: boolean;
		error?: string;
	}): number | undefined {
		if (!this.config.enabled) return undefined;

		// Get timing from session tracker
		const timing = this.sessionTracker.toolCompleted(
			options.sessionId,
			options.toolUseId,
		);

		const event: Omit<ToolEvent, "id"> = {
			sessionId: options.sessionId,
			toolUseId: options.toolUseId,
			toolName: options.toolName,
			toolInputHash: this.config.hashToolInputs
				? this.hashInput(options.toolInput)
				: undefined,
			success: options.success,
			errorType: options.success
				? undefined
				: this.classifyError(options.error),
			durationMs: timing?.durationMs,
			executionOrder: timing?.executionOrder || 0,
			timestamp: Date.now(),
		};

		const eventId = this.store.recordToolEvent(event);

		// Update session counters
		this.sessionTracker.incrementCounters(options.sessionId, {
			tools: 1,
		});

		return eventId;
	}

	/**
	 * Log a code change from agent or user.
	 */
	logCodeChange(options: {
		sessionId: string;
		filePath: string;
		author: "agent" | "user";
		diff?: string;
		linesAdded: number;
		linesRemoved: number;
	}): number | undefined {
		if (!this.config.enabled) return undefined;

		// Check for Correction Gap (user editing agent's recent work)
		let agentChangeId: number | undefined;
		let correctionType: CorrectionType | undefined;

		if (options.author === "user") {
			const recentAgentChanges = this.store.getRecentAgentChanges(
				options.sessionId,
				options.filePath,
				300000, // 5 minute window
			);

			if (recentAgentChanges.length > 0) {
				// User is modifying agent's recent work
				agentChangeId = recentAgentChanges[0].id;
				correctionType = this.classifyCorrectionType(
					recentAgentChanges[0],
					options,
				);

				// Record as intervention
				this.sessionTracker.incrementCounters(options.sessionId, {
					interventions: 1,
				});
			}
		}

		const change: Omit<CodeChange, "id"> = {
			sessionId: options.sessionId,
			filePath: options.filePath,
			author: options.author,
			diffHash: options.diff ? this.hashDiff(options.diff) : undefined,
			linesAdded: options.linesAdded,
			linesRemoved: options.linesRemoved,
			timestamp: Date.now(),
			agentChangeId,
			correctionType,
		};

		return this.store.recordCodeChange(change);
	}

	/**
	 * Log PreToolUse event (tool is about to execute).
	 */
	logToolStart(sessionId: string, toolUseId: string): void {
		if (!this.config.enabled) return;
		this.sessionTracker.toolStarted(sessionId, toolUseId);
	}

	/**
	 * Check if a file path indicates code (not config, etc.).
	 */
	isCodeFile(filePath: string): boolean {
		const codeExtensions = [
			".ts",
			".tsx",
			".js",
			".jsx",
			".py",
			".go",
			".rs",
			".java",
			".kt",
			".swift",
			".c",
			".cpp",
			".h",
			".hpp",
			".cs",
			".rb",
			".php",
			".vue",
			".svelte",
		];

		const lowerPath = filePath.toLowerCase();
		return codeExtensions.some((ext) => lowerPath.endsWith(ext));
	}

	/**
	 * Get tool event history for a session.
	 */
	getToolHistory(sessionId: string): ToolEvent[] {
		return this.store.getToolEventsBySession(sessionId);
	}

	/**
	 * Get tool sequence for a session.
	 */
	getToolSequence(sessionId: string): string[] {
		return this.store.getToolSequence(sessionId);
	}

	/**
	 * Get error rates by tool.
	 */
	getErrorRates(): Array<{
		toolName: string;
		total: number;
		failures: number;
		rate: number;
	}> {
		return this.store.getToolErrorRates();
	}

	// ========================================================================
	// Private Methods
	// ========================================================================

	/**
	 * Hash tool input for privacy.
	 */
	private hashInput(input?: Record<string, unknown>): string | undefined {
		if (!input) return undefined;

		// Remove potentially sensitive fields before hashing
		const sanitized = this.sanitizeInput(input);
		const json = JSON.stringify(sanitized, Object.keys(sanitized).sort());

		return createHash("sha256").update(json).digest("hex").substring(0, 16);
	}

	/**
	 * Hash a diff for privacy.
	 */
	private hashDiff(diff: string): string {
		return createHash("sha256").update(diff).digest("hex").substring(0, 16);
	}

	/**
	 * Sanitize tool input by removing sensitive patterns.
	 */
	private sanitizeInput(
		input: Record<string, unknown>,
	): Record<string, unknown> {
		const sensitiveKeys = [
			"password",
			"token",
			"secret",
			"key",
			"auth",
			"credential",
			"api_key",
			"apiKey",
			"bearer",
		];

		const sanitized: Record<string, unknown> = {};

		for (const [key, value] of Object.entries(input)) {
			const lowerKey = key.toLowerCase();

			// Skip sensitive keys
			if (sensitiveKeys.some((s) => lowerKey.includes(s))) {
				sanitized[key] = "[REDACTED]";
				continue;
			}

			// Recursively sanitize nested objects
			if (
				typeof value === "object" &&
				value !== null &&
				!Array.isArray(value)
			) {
				sanitized[key] = this.sanitizeInput(value as Record<string, unknown>);
			} else if (typeof value === "string") {
				// Redact values that look like tokens/keys
				sanitized[key] = this.redactSensitiveValue(value);
			} else {
				sanitized[key] = value;
			}
		}

		return sanitized;
	}

	/**
	 * Redact values that look like secrets.
	 */
	private redactSensitiveValue(value: string): string {
		// Patterns that look like tokens, API keys, etc.
		const sensitivePatterns = [
			/^sk-[a-zA-Z0-9-_]{20,}$/, // OpenAI-style keys
			/^sk-ant-[a-zA-Z0-9-_]{20,}$/, // Anthropic keys
			/^ghp_[a-zA-Z0-9]{36,}$/, // GitHub tokens
			/^gho_[a-zA-Z0-9]{36,}$/, // GitHub OAuth
			/^glpat-[a-zA-Z0-9-_]{20,}$/, // GitLab tokens
			/^xox[baprs]-[a-zA-Z0-9-]+$/, // Slack tokens
			/^[a-zA-Z0-9-_]{30,}$/, // Generic long tokens
		];

		for (const pattern of sensitivePatterns) {
			if (pattern.test(value)) {
				return "[REDACTED]";
			}
		}

		return value;
	}

	/**
	 * Classify error type from error message.
	 */
	private classifyError(error?: string): ToolErrorType {
		if (!error) return "unknown";

		const lowerError = error.toLowerCase();

		if (
			lowerError.includes("timeout") ||
			lowerError.includes("timed out") ||
			lowerError.includes("exceeded")
		) {
			return "timeout";
		}

		if (
			lowerError.includes("permission") ||
			lowerError.includes("access denied") ||
			lowerError.includes("eperm") ||
			lowerError.includes("eacces") ||
			lowerError.includes("forbidden")
		) {
			return "permission";
		}

		if (
			lowerError.includes("invalid") ||
			lowerError.includes("validation") ||
