/**
 * AdaptiveRanker - Applies learned weights to search results.
 *
 * Responsibilities:
 * - Apply learned weights to RRF fusion
 * - Apply file boost factors to scores
 * - Fallback to static weights when no learned data
 * - Provide weight information for debugging
 */

import type { DocumentType, SearchUseCase } from "../../types.js";
import type { LearningEngine } from "../engine/learning-engine.js";
import type { WeightOptimizer } from "../engine/weight-optimizer.js";
import type { LearnedWeights, LearningConfig } from "../types.js";
import { DEFAULT_LEARNING_CONFIG } from "../types.js";

// ============================================================================
// Constants
// ============================================================================

/** Default static weights (fallback) */
const DEFAULT_WEIGHTS: LearnedWeights = {
	vectorWeight: 0.6,
	bm25Weight: 0.4,
	documentTypeWeights: {
		code_chunk: 0.25,
		file_summary: 0.12,
		symbol_summary: 0.15,
		idiom: 0.12,
		usage_example: 0.08,
		anti_pattern: 0.03,
		project_doc: 0.05,
		framework_doc: 0.1,
		best_practice: 0.05,
		api_reference: 0.05,
	},
	fileBoosts: new Map(),
	queryPatterns: new Map(),
	lastUpdated: new Date(),
	feedbackCount: 0,
	confidence: 0,
};

// ============================================================================
// Types
// ============================================================================

export interface RankingResult {
	id: string;
	originalScore: number;
	adjustedScore: number;
	fileBoost: number;
	typeBoost: number;
}

export interface RankingContext {
	query: string;
	useCase?: SearchUseCase;
	results: Array<{
		id: string;
		filePath: string;
		documentType: DocumentType;
		score: number;
	}>;
}

// ============================================================================
// AdaptiveRanker Class
// ============================================================================

export class AdaptiveRanker {
	private engine: LearningEngine;
	private optimizer: WeightOptimizer | null;
	private config: LearningConfig;

	constructor(
		engine: LearningEngine,
		optimizer?: WeightOptimizer,
		config: Partial<LearningConfig> = {},
	) {
		this.engine = engine;
		this.optimizer = optimizer || null;
		this.config = { ...DEFAULT_LEARNING_CONFIG, ...config };
	}

	// ========================================================================
	// Weight Retrieval
	// ========================================================================

	/**
	 * Get active weights for ranking.
	 * Returns learned weights if available, otherwise static defaults.
	 */
	getActiveWeights(useCase?: SearchUseCase): LearnedWeights {
		const learned = this.engine.getWeights(useCase);

		// If we have enough samples, use learned weights
		if (learned.feedbackCount >= this.config.minSamples) {
			// Optionally blend with defaults based on confidence
			if (this.optimizer && learned.confidence < 1.0) {
				return this.optimizer.blend(
					learned,
					DEFAULT_WEIGHTS,
					learned.confidence,
				);
			}
			return learned;
		}

		// Fall back to static defaults
		return DEFAULT_WEIGHTS;
	}

	/**
	 * Get RRF weights (vector and BM25).
	 */
	getRRFWeights(useCase?: SearchUseCase): {
		vectorWeight: number;
		bm25Weight: number;
	} {
		const weights = this.getActiveWeights(useCase);
		return {
			vectorWeight: weights.vectorWeight,
			bm25Weight: weights.bm25Weight,
		};
	}

	/**
	 * Get document type weights for a use case.
	 */
	getDocumentTypeWeights(
		useCase?: SearchUseCase,
	): Partial<Record<DocumentType, number>> {
		const weights = this.getActiveWeights(useCase);
		return weights.documentTypeWeights;
	}

	/**
	 * Get file boost factor for a specific file.
	 */
	getFileBoost(filePath: string): number {
		const weights = this.getActiveWeights();
		return weights.fileBoosts.get(filePath) ?? 1.0;
	}

	/**
	 * Get all file boosts.
	 */
	getAllFileBoosts(): Map<string, number> {
		const weights = this.getActiveWeights();
		return weights.fileBoosts;
	}

	// ========================================================================
	// Ranking Operations
	// ========================================================================

	/**
	 * Re-rank search results using learned weights.
	 * Applies file boosts and document type adjustments.
	 */
	rerank(context: RankingContext): RankingResult[] {
		const weights = this.getActiveWeights(context.useCase);

		const results: RankingResult[] = context.results.map((result) => {
			// Get file boost
			const fileBoost = weights.fileBoosts.get(result.filePath) ?? 1.0;

			// Get document type boost (relative to default)
			const defaultTypeWeight =
				DEFAULT_WEIGHTS.documentTypeWeights[result.documentType] ?? 0.1;
			const learnedTypeWeight =
				weights.documentTypeWeights[result.documentType] ?? 0.1;
			const typeBoost = learnedTypeWeight / defaultTypeWeight;

			// Calculate adjusted score
			const adjustedScore = result.score * fileBoost * typeBoost;

			return {
				id: result.id,
				originalScore: result.score,
				adjustedScore,
				fileBoost,
				typeBoost,
			};
		});

		// Sort by adjusted score (descending)
		results.sort((a, b) => b.adjustedScore - a.adjustedScore);

		return results;
	}

	/**
	 * Apply file boosts to a list of results in place.
	 * Returns the modified results.
	 */
	applyFileBoosts<T extends { filePath: string; fusedScore: number }>(
		results: T[],
	): T[] {
		const weights = this.getActiveWeights();

		for (const result of results) {
			const boost = weights.fileBoosts.get(result.filePath) ?? 1.0;
			result.fusedScore *= boost;
		}

		// Re-sort by fused score
		results.sort((a, b) => b.fusedScore - a.fusedScore);

		return results;
	}

	// ========================================================================
	// Diagnostics
	// ========================================================================

	/**
	 * Check if adaptive ranking is active (has learned data).
	 */
	isActive(useCase?: SearchUseCase): boolean {
		return this.engine.hasLearningData(useCase);
	}

	/**
	 * Get ranking diagnostics for debugging.
	 */
	getDiagnostics(useCase?: SearchUseCase): RankingDiagnostics {
		const weights = this.getActiveWeights(useCase);
		const isActive = this.isActive(useCase);

		return {
			isActive,
			usingLearned: weights.feedbackCount >= this.config.minSamples,
			confidence: weights.confidence,
			feedbackCount: weights.feedbackCount,
			lastUpdated: weights.lastUpdated,
			vectorWeight: weights.vectorWeight,
			bm25Weight: weights.bm25Weight,
			fileBoostCount: weights.fileBoosts.size,
			topBoostedFiles: this.getTopBoostedFiles(weights, 5),
		};
	}

	private getTopBoostedFiles(
		weights: LearnedWeights,
		limit: number,
	): Array<{ filePath: string; boost: number }> {
		const entries = Array.from(weights.fileBoosts.entries());
		entries.sort((a, b) => b[1] - a[1]);
		return entries
			.slice(0, limit)
			.map(([filePath, boost]) => ({ filePath, boost }));
	}
}

// ============================================================================
// Types
// ============================================================================

export interface RankingDiagnostics {
	isActive: boolean;
	usingLearned: boolean;
	confidence: number;
	feedbackCount: number;
	lastUpdated: Date;
	vectorWeight: number;
	bm25Weight: number;
	fileBoostCount: number;
	topBoostedFiles: Array<{ filePath: string; boost: number }>;
}

// ============================================================================
// Factory
// ============================================================================

/**
 * Create an AdaptiveRanker instance.
 */
export function createAdaptiveRanker(
	engine: LearningEngine,
	optimizer?: WeightOptimizer,
	config?: Partial<LearningConfig>,
): AdaptiveRanker {
	return new AdaptiveRanker(engine, optimizer, config);
}

/**
 * Ranking module - Applies learned weights to search results.
 */

export {
	AdaptiveRanker,
	createAdaptiveRanker,
	type RankingContext,
	type RankingDiagnostics,
	type RankingResult,
} from "./adaptive-ranker.js";

/**
 * DeviationDetector - Warn when agent behavior deviates from expectations.
 *
 * Works with ShadowPredictor to identify:
 * - Unexpected tool selections
 * - Unusual tool sequences
 * - Potential errors or mistakes
 * - Novel behaviors (might be good or bad)
 *
 * Deviation detection helps:
 * - Catch mistakes early
 * - Identify learning opportunities
 * - Track behavioral changes
 */

import type { PredictionResult, ShadowPredictor } from "./shadow-predictor.js";

// ============================================================================
// Types
// ============================================================================

export interface DeviationDetectorConfig {
	/** Probability threshold for low-probability warning */
	lowProbabilityThreshold: number;
	/** Entropy threshold for high-uncertainty warning */
	highEntropyThreshold: number;
	/** Consecutive deviations to trigger alert */
	consecutiveDeviationsThreshold: number;
	/** Time window for deviation rate calculation (ms) */
	deviationWindowMs: number;
	/** Maximum deviations per window before alert */
	maxDeviationsPerWindow: number;
}

export const DEFAULT_DEVIATION_CONFIG: DeviationDetectorConfig = {
	lowProbabilityThreshold: 0.1,
	highEntropyThreshold: 2.5,
	consecutiveDeviationsThreshold: 3,
	deviationWindowMs: 10 * 60 * 1000, // 10 minutes
	maxDeviationsPerWindow: 5,
};

export type DeviationType =
	| "low_probability"
	| "unexpected"
	| "sequence_break"
	| "novel"
	| "high_entropy";

export type DeviationSeverity = "info" | "warning" | "alert";

export interface Deviation {
	/** Unique deviation ID */
	deviationId: string;
	/** Type of deviation */
	type: DeviationType;
	/** Severity level */
	severity: DeviationSeverity;
	/** The tool that was actually used */
	actualTool: string;
	/** The tool that was expected */
	expectedTool: string | null;
	/** Probability of actual tool */
	actualProbability: number;
	/** Probability of expected tool */
	expectedProbability: number;
	/** Context at time of deviation */
	context: string[];
	/** Description of the deviation */
	description: string;
	/** When deviation occurred */
	timestamp: number;
	/** Session ID (if available) */
	sessionId?: string;
}

export interface DeviationAlert {
	/** Alert ID */
	alertId: string;
	/** Alert type */
	alertType: "consecutive" | "rate" | "pattern";
	/** Severity */
	severity: DeviationSeverity;
	/** Related deviations */
	deviations: Deviation[];
	/** Alert message */
	message: string;
	/** When alert was triggered */
	timestamp: number;
	/** Recommended action */
	recommendation: string;
}

export interface DeviationAnalysis {
	/** Is this a deviation? */
	isDeviation: boolean;
	/** Deviation details (if applicable) */
	deviation: Deviation | null;
	/** Alert triggered (if applicable) */
	alert: DeviationAlert | null;
	/** Raw prediction result */
	prediction: PredictionResult;
	/** Probability of the actual tool */
	actualProbability: number;
}

export interface DeviationStatistics {
	/** Total deviations detected */
	totalDeviations: number;
	/** Deviations by type */
	byType: Record<DeviationType, number>;
	/** Deviations by severity */
	bySeverity: Record<DeviationSeverity, number>;
	/** Deviation rate (per session) */
	deviationRate: number;
	/** Most common unexpected tools */
	commonUnexpectedTools: Array<{ tool: string; count: number }>;
	/** Most common expected tools that were skipped */
	commonSkippedTools: Array<{ tool: string; count: number }>;
}

// ============================================================================
// DeviationDetector Class
// ============================================================================

export class DeviationDetector {
	private config: DeviationDetectorConfig;
	private predictor: ShadowPredictor;
	private deviations: Deviation[];
	private alerts: DeviationAlert[];
	private consecutiveDeviations: number;
	private recentDeviationTimestamps: number[];
	private deviationCounter: number;
	private alertCounter: number;

	constructor(
		predictor: ShadowPredictor,
		config: Partial<DeviationDetectorConfig> = {},
	) {
		this.config = { ...DEFAULT_DEVIATION_CONFIG, ...config };
		this.predictor = predictor;
		this.deviations = [];
		this.alerts = [];
		this.consecutiveDeviations = 0;
		this.recentDeviationTimestamps = [];
		this.deviationCounter = 0;
		this.alertCounter = 0;
	}

	/**
	 * Analyze a tool selection for deviations.
	 */
	analyze(actualTool: string, sessionId?: string): DeviationAnalysis {
		// Get prediction
		const prediction = this.predictor.predict();

		// Calculate probability of actual tool
		const actualProbability = this.predictor.getProbability(actualTool);

		// Check for deviation
		const deviation = this.checkForDeviation(
			actualTool,
			prediction,
			actualProbability,
			sessionId,
		);

		// Check for alerts
		let alert: DeviationAlert | null = null;
		if (deviation) {
			this.deviations.push(deviation);
			this.consecutiveDeviations++;
			this.recentDeviationTimestamps.push(Date.now());

			// Clean old timestamps
			const cutoff = Date.now() - this.config.deviationWindowMs;
			this.recentDeviationTimestamps = this.recentDeviationTimestamps.filter(
				(t) => t > cutoff,
			);

			alert = this.checkForAlert(deviation);
		} else {
			this.consecutiveDeviations = 0;
		}

		// Update predictor with actual tool
		this.predictor.observe(actualTool);

		return {
			isDeviation: deviation !== null,
			deviation,
			alert,
			prediction,
			actualProbability,
		};
	}

	/**
	 * Get deviation statistics.
	 */
	getStatistics(): DeviationStatistics {
		const byType: Record<DeviationType, number> = {
			low_probability: 0,
			unexpected: 0,
			sequence_break: 0,
			novel: 0,
			high_entropy: 0,
		};

		const bySeverity: Record<DeviationSeverity, number> = {
			info: 0,
			warning: 0,
			alert: 0,
		};

		const unexpectedCounts = new Map<string, number>();
		const skippedCounts = new Map<string, number>();

		for (const deviation of this.deviations) {
			byType[deviation.type]++;
			bySeverity[deviation.severity]++;

			unexpectedCounts.set(
				deviation.actualTool,
				(unexpectedCounts.get(deviation.actualTool) ?? 0) + 1,
			);

			if (deviation.expectedTool) {
				skippedCounts.set(
					deviation.expectedTool,
					(skippedCounts.get(deviation.expectedTool) ?? 0) + 1,
				);
			}
		}

		// Convert to sorted arrays
		const commonUnexpectedTools = Array.from(unexpectedCounts.entries())
			.map(([tool, count]) => ({ tool, count }))
			.sort((a, b) => b.count - a.count)
			.slice(0, 10);

		const commonSkippedTools = Array.from(skippedCounts.entries())
			.map(([tool, count]) => ({ tool, count }))
			.sort((a, b) => b.count - a.count)
			.slice(0, 10);

		// Calculate deviation rate
		const stats = this.predictor.getStatistics();
		const deviationRate =
			stats.totalSequences > 0
				? this.deviations.length / stats.totalSequences
				: 0;

		return {
			totalDeviations: this.deviations.length,
			byType,
			bySeverity,
			deviationRate,
			commonUnexpectedTools,
			commonSkippedTools,
		};
	}

	/**
	 * Get recent deviations.
	 */
	getRecentDeviations(limit: number = 20): Deviation[] {
		return this.deviations.slice(-limit);
	}

	/**
	 * Get active alerts.
	 */
