					scenarioSessions.filter((s) => s.outcome === "success").length /
					scenarioSessions.length,
				avgCorrectionRate: this.average(
					scenarioSessions,
					(s) => s.metrics.correctionRate,
				),
				avgDurationMs: this.average(scenarioSessions, (s) => s.durationMs),
			});
		}

		return {
			totalRuns,
			successfulRuns,
			failedRuns,
