	}

	isCloud(): boolean {
		return CLOUD_LLM_PROVIDERS.has(this.provider);
	}

	/**
	 * Get model size in billions of parameters.
	 * Default implementation returns undefined (cloud providers).
	 * Overridden by LocalLLMClient to query Ollama/LM Studio API.
	 */
	async getModelSizeB(): Promise<number | undefined> {
		return undefined;
	}

	getAccumulatedUsage() {
		return { ...this.accumulatedUsage };
	}

	resetAccumulatedUsage(): void {
		this.accumulatedUsage = {
			inputTokens: 0,
			outputTokens: 0,
			cost: 0,
			calls: 0,
		};
	}

	protected accumulateUsage(usage?: {
		inputTokens: number;
		outputTokens: number;
		cost?: number;
	}): void {
		if (usage) {
			this.accumulatedUsage.inputTokens += usage.inputTokens;
			this.accumulatedUsage.outputTokens += usage.outputTokens;
			this.accumulatedUsage.cost += usage.cost || 0;
		}
		this.accumulatedUsage.calls++;
	}

	abstract complete(
		messages: LLMMessage[],
		options?: LLMGenerateOptions,
	): Promise<LLMResponse>;

	async completeJSON<T>(
		messages: LLMMessage[],
		options?: LLMGenerateOptions,
	): Promise<T> {
		// Add JSON instruction to system prompt
		const jsonOptions: LLMGenerateOptions = {
			...options,
			systemPrompt:
				`${options?.systemPrompt || ""}\n\nYou must respond with valid JSON only. No markdown, no explanation, just the JSON object.`.trim(),
		};

		const response = await this.complete(messages, jsonOptions);

		// Track usage
		this.accumulateUsage(response.usage);

		// Try to parse JSON from response
		try {
			const content = response.content.trim();
			const parsed = this.extractJSON(content);
			if (parsed === null) {
				throw new Error("No valid JSON found in response");
			}
			return parsed as T;
		} catch (error) {
			throw new Error(
				`Failed to parse LLM response as JSON: ${error instanceof Error ? error.message : String(error)}\nResponse: ${response.content.slice(0, 500)}`,
			);
		}
	}

	/**
	 * Extract JSON from a potentially messy LLM response.
	 * Handles: markdown code fences, nested fences, prefix text, suffix text,
	 * trailing commas, and responses with multiple JSON objects (picks the last
	 * complete top-level object, which is typically the LLM's actual output).
	 */
	private extractJSON(content: string): unknown {
		// Strategy 1: Try parsing as-is (fastest path for well-formed responses)
		try {
			return JSON.parse(content);
		} catch {
			// Continue to more complex extraction
		}

		// Strategy 2: Remove ALL markdown code fences (handles nested fences)
		// This removes ```json, ```typescript, ``` etc. that local models often include
		let cleaned = content
			.replace(/```(?:json|javascript|typescript|ts|js)?\s*/gi, "")
			.replace(/```/g, "")
			.trim();

		// Try parsing cleaned content
		try {
			return JSON.parse(cleaned);
		} catch {
			// Continue to bracket matching
		}

		// Strategy 3: Find ALL top-level JSON structures and try each
		// (last one is usually the LLM's actual output when the prompt contains JSON examples)
		const candidates = this.findAllTopLevelJSON(cleaned);

		// Try candidates in reverse order (last = most likely the real output)
		for (let i = candidates.length - 1; i >= 0; i--) {
			const candidate = candidates[i];
			try {
				return JSON.parse(candidate);
			} catch {
				// Try fixing trailing commas before giving up on this candidate
				const fixed = candidate.replace(/,\s*([}\]])/g, "$1");
				try {
					return JSON.parse(fixed);
				} catch {
					// Try next candidate
				}
			}
		}

		// Strategy 4: Last resort — find first { or [ and extract
		const jsonStartBrace = cleaned.indexOf("{");
		const jsonStartBracket = cleaned.indexOf("[");
		let jsonStart = -1;

		if (jsonStartBrace !== -1 && jsonStartBracket !== -1) {
			jsonStart = Math.min(jsonStartBrace, jsonStartBracket);
		} else if (jsonStartBrace !== -1) {
			jsonStart = jsonStartBrace;
		} else if (jsonStartBracket !== -1) {
			jsonStart = jsonStartBracket;
		}

		if (jsonStart === -1) {
			return null; // No JSON structure found
		}

		cleaned = cleaned.slice(jsonStart);

		// Try removing common trailing garbage
		const lastBrace = cleaned.lastIndexOf("}");
		const lastBracket = cleaned.lastIndexOf("]");
		const lastClose = Math.max(lastBrace, lastBracket);
		if (lastClose > 0) {
			const trimmed = cleaned.slice(0, lastClose + 1);
			try {
				return JSON.parse(trimmed);
			} catch {
				// Try fixing trailing commas
				try {
					return JSON.parse(trimmed.replace(/,\s*([}\]])/g, "$1"));
				} catch {
					// Give up
				}
			}
		}

		return null;
	}

	/**
	 * Find all top-level JSON objects/arrays in a string.
	 * Uses bracket/brace matching with string awareness.
	 */
	private findAllTopLevelJSON(content: string): string[] {
		const results: string[] = [];
		let i = 0;

		while (i < content.length) {
			const char = content[i];
			if (char !== "{" && char !== "[") {
				i++;
				continue;
			}

			const closeChar = char === "{" ? "}" : "]";
			let depth = 0;
			let inString = false;
			let escapeNext = false;
			let end = -1;

			for (let j = i; j < content.length; j++) {
				const c = content[j];

				if (escapeNext) {
					escapeNext = false;
					continue;
				}

				if (c === "\\") {
					escapeNext = true;
					continue;
				}

				if (c === '"') {
					inString = !inString;
					continue;
				}

				if (inString) continue;

				if (c === char) depth++;
				else if (c === closeChar) {
					depth--;
					if (depth === 0) {
						end = j + 1;
						break;
					}
				}
			}

			if (end > i) {
				results.push(content.slice(i, end));
				i = end;
			} else {
				i++;
			}
		}

		return results;
	}

