interface AnthropicBatchOptions {
	/** API key for Anthropic */
	apiKey?: string;
	/** Model to use */
	model?: string;
	/** Polling interval in ms (default: 5000) */
	pollInterval?: number;
	/** Maximum wait time in ms (default: 3600000 = 1 hour) */
	maxWaitTime?: number;
}

interface BatchRequest {
	custom_id: string;
	params: {
		model: string;
		max_tokens: number;
		messages: Array<{ role: "user" | "assistant"; content: string }>;
		system?: string;
		temperature?: number;
	};
}

interface BatchResponse {
	id: string;
	type: "message_batch";
	processing_status: "in_progress" | "canceling" | "ended";
	request_counts: {
		processing: number;
		succeeded: number;
		errored: number;
		canceled: number;
		expired: number;
	};
	ended_at?: string;
	created_at: string;
	expires_at: string;
	results_url?: string;
}

interface BatchResult {
	custom_id: string;
	result: {
		type: "succeeded" | "errored" | "canceled" | "expired";
		message?: {
			id: string;
			type: "message";
			role: "assistant";
			content: Array<{ type: "text"; text: string }>;
			model: string;
			stop_reason: string;
			usage: {
				input_tokens: number;
				output_tokens: number;
			};
		};
		error?: {
			type: string;
			message: string;
		};
	};
}

