/**
 * LSP Transport
 *
 * JSON-RPC over stdio with Content-Length framing.
 * Handles message serialization, request/response correlation, and timeouts.
 */

import type { ChildProcess } from "node:child_process";

const MAX_BUFFER_SIZE = 50 * 1024 * 1024; // 50MB safety cap

interface PendingRequest {
	resolve: (value: unknown) => void;
	reject: (reason: Error) => void;
	timer: ReturnType<typeof setTimeout>;
}

interface JsonRpcMessage {
	jsonrpc: "2.0";
	id?: number;
	method?: string;
	params?: unknown;
	result?: unknown;
	error?: { code: number; message: string; data?: unknown };
}

export class LspTransport {
	private buffer = Buffer.alloc(0);
	private contentLength = -1;
	private nextId = 1;
	private pending = new Map<number, PendingRequest>();

	/** Notification handler for server-initiated messages */
	onNotification?: (method: string, params: unknown) => void;

	/**
	 * Process incoming data from the LSP server's stdout.
	 */
	onData(chunk: Buffer): void {
		this.buffer = Buffer.concat([this.buffer, chunk]);

		// Safety: clear buffer if it grows too large
		if (this.buffer.length > MAX_BUFFER_SIZE) {
			this.buffer = Buffer.alloc(0);
			this.contentLength = -1;
			this.cancelAll(new Error("Buffer overflow — LSP transport reset"));
			return;
		}

		while (true) {
			if (this.contentLength === -1) {
				// Look for header boundary
				const headerEnd = this.buffer.indexOf("\r\n\r\n");
				if (headerEnd === -1) break;

				const header = this.buffer.subarray(0, headerEnd).toString("utf-8");
				const match = header.match(/Content-Length:\s*(\d+)/i);
				if (!match) {
					// Skip malformed header
					this.buffer = this.buffer.subarray(headerEnd + 4);
					continue;
				}

				this.contentLength = parseInt(match[1], 10);
				this.buffer = this.buffer.subarray(headerEnd + 4);
			}

			if (this.buffer.length < this.contentLength) break;

			const body = this.buffer
				.subarray(0, this.contentLength)
				.toString("utf-8");
			this.buffer = this.buffer.subarray(this.contentLength);
			this.contentLength = -1;

			try {
				const message = JSON.parse(body) as JsonRpcMessage;
				this.handleMessage(message);
			} catch {
				// Skip unparseable messages
			}
		}
	}

	/**
	 * Send a request and wait for the response.
	 */
	sendRequest<T>(
		process: ChildProcess,
		method: string,
		params: unknown,
		timeoutMs: number,
	): Promise<T> {
		const id = this.nextId++;

		return new Promise<T>((resolve, reject) => {
			const timer = setTimeout(() => {
				this.pending.delete(id);
				reject(
					new Error(`LSP request '${method}' timed out after ${timeoutMs}ms`),
				);
			}, timeoutMs);

			this.pending.set(id, {
				resolve: resolve as (value: unknown) => void,
				reject,
				timer,
			});

			this.writeMessage(process, { jsonrpc: "2.0", id, method, params });
		});
	}

	/**
	 * Send a notification (no response expected).
	 */
	sendNotification(
		process: ChildProcess,
		method: string,
		params: unknown,
	): void {
		this.writeMessage(process, { jsonrpc: "2.0", method, params });
	}

	/**
	 * Cancel all pending requests (e.g., on crash).
	 */
	cancelAll(reason: Error): void {
		for (const [id, pending] of this.pending) {
			clearTimeout(pending.timer);
			pending.reject(reason);
		}
		this.pending.clear();
	}

	/**
	 * Check if there are pending requests.
	 */
	hasPending(): boolean {
		return this.pending.size > 0;
	}

	private handleMessage(message: JsonRpcMessage): void {
		// Response to a request
		if (
			message.id !== undefined &&
			(message.result !== undefined || message.error)
		) {
			const pending = this.pending.get(message.id);
			if (pending) {
				this.pending.delete(message.id);
				clearTimeout(pending.timer);

				if (message.error) {
					pending.reject(
						new Error(
							`LSP error ${message.error.code}: ${message.error.message}`,
						),
					);
				} else {
					pending.resolve(message.result);
				}
			}
			return;
		}

		// Server notification
		if (message.method && message.id === undefined) {
			this.onNotification?.(message.method, message.params);
		}
	}

	private writeMessage(process: ChildProcess, message: JsonRpcMessage): void {
		if (!process.stdin || process.stdin.destroyed) {
			throw new Error("LSP process stdin is not available");
		}

		const body = JSON.stringify(message);
		const header = `Content-Length: ${Buffer.byteLength(body)}\r\n\r\n`;
		process.stdin.write(header + body);
	}
}

/**
 * Index Cache
 *
 * Lazy-loads the index resources (FileTracker + ReferenceGraphManager + RepoMapGenerator)
 * for the single project workspace. Invalidated when a reindex completes so the next
 * tool call gets fresh data.
 */

import { existsSync } from "node:fs";
import { getIndexDbPath } from "../config.js";
import {
	createReferenceGraphManager,
	type ReferenceGraphManager,
} from "../core/reference-graph.js";
import {
	createRepoMapGenerator,
	type RepoMapGenerator,
} from "../core/repo-map.js";
import { createFileTracker, type IFileTracker } from "../core/tracker.js";
import type { Logger } from "./logger.js";

export interface CachedIndex {
	tracker: IFileTracker;
	graphManager: ReferenceGraphManager;
	repoMapGen: RepoMapGenerator;
	loadedAt: number;
}

/**
 * Single-project lazy index cache.
 *
 * Call get() to obtain loaded resources; call invalidate() after reindex to
 * force a reload on the next get() call.
 */
export class IndexCache {
	private cache: CachedIndex | null = null;
	private loading: Promise<CachedIndex> | null = null;

	constructor(
		private projectPath: string,
		private indexDir: string,
		private maxMemoryMB: number,
		private logger: Logger,
	) {}

	/**
	 * Get cached index resources, loading them if not already loaded.
	 * Throws if no index exists at the project path.
	 */
	async get(): Promise<CachedIndex> {
		if (this.cache) {
			return this.cache;
		}

		// Avoid concurrent loads - reuse an in-flight load promise
		if (this.loading) {
			return this.loading;
		}

		this.loading = this.load();
		try {
			this.cache = await this.loading;
			return this.cache;
		} finally {
			this.loading = null;
		}
	}

	/**
	 * Invalidate the cached index. The next get() call will reload from disk.
	 */
	invalidate(): void {
		if (this.cache) {
			this.logger.debug("IndexCache: invalidating cached index");
			this.closeCache(this.cache);
			this.cache = null;
		}
	}

	/**
	 * Close all resources. Called on server shutdown.
	 */
	close(): void {
		this.invalidate();
	}

	private async load(): Promise<CachedIndex> {
		const dbPath = getIndexDbPath(this.projectPath);
		if (!existsSync(dbPath)) {
			throw new Error(
				`No index found at ${this.projectPath}. Run 'mnemex index' first.`,
			);
		}

		this.logger.debug(`IndexCache: loading index from ${dbPath}`);

		const tracker = createFileTracker(dbPath, this.projectPath);
		const graphManager = createReferenceGraphManager(tracker);
		const repoMapGen = createRepoMapGenerator(tracker);

		this.logger.debug("IndexCache: index loaded successfully");

		return {
			tracker,
			graphManager,
			repoMapGen,
			loadedAt: Date.now(),
		};
	}

	private closeCache(cached: CachedIndex): void {
		try {
			cached.tracker.close();
		} catch (err) {
			this.logger.warn("IndexCache: error closing tracker", err);
		}
	}
}

/**
 * Completion Detector
 *
 * Detects when a background reindex has finished by polling for:
 * 1. Lock file absence (indexing.lock removed)
 * 2. index.db mtime is newer than when polling started
 *
 * Used both for event-driven notification (watch) and blocking wait (waitForCompletion).
 */

import { existsSync, statSync } from "node:fs";
import { join } from "node:path";
import { INDEX_DB_FILE } from "../config.js";

const LOCK_FILENAME = ".indexing.lock";
const MAX_WAIT_MS = 300_000; // 5 minutes

/**
 * Polls for the completion of a background reindex.
 */
export class CompletionDetector {
	private pollTimer: ReturnType<typeof setInterval> | null = null;

	constructor(
		private indexDir: string,
		private pollIntervalMs: number,
	) {}

	/**
	 * Start polling and call onComplete when done.
	 * Automatically stops after MAX_WAIT_MS even if lock persists.
	 */
	watch(onComplete: () => void): void {
		// Stop any existing poll
		this.stop();

		const lockPath = join(this.indexDir, LOCK_FILENAME);
		const dbPath = join(this.indexDir, INDEX_DB_FILE);
		const startMtime = this.getMtime(dbPath);
		const deadline = Date.now() + MAX_WAIT_MS;

		this.pollTimer = setInterval(() => {
			const isComplete = this.checkComplete(lockPath, dbPath, startMtime);
			const timedOut = Date.now() >= deadline;

			if (isComplete || timedOut) {
				this.stop();
				onComplete();
			}
		}, this.pollIntervalMs);

		// Don't keep process alive just for polling
		if (this.pollTimer.unref) {
			this.pollTimer.unref();
		}
	}

	/**
	 * Stop polling.
	 */
	stop(): void {
		if (this.pollTimer !== null) {
			clearInterval(this.pollTimer);
			this.pollTimer = null;
		}
	}

	/**
	 * Block until reindex completes or timeout elapses.
	 * Returns true if completed, false if timed out.
	 */
	async waitForCompletion(timeoutMs = MAX_WAIT_MS): Promise<boolean> {
		const lockPath = join(this.indexDir, LOCK_FILENAME);
		const dbPath = join(this.indexDir, INDEX_DB_FILE);
		const startMtime = this.getMtime(dbPath);
		const deadline = Date.now() + timeoutMs;

		while (Date.now() < deadline) {
			if (this.checkComplete(lockPath, dbPath, startMtime)) {
				return true;
			}
			await sleep(this.pollIntervalMs);
		}

		return false;
	}

	/**
	 * Completion condition: lock absent AND db mtime newer than start.
	 */
	private checkComplete(
		lockPath: string,
		dbPath: string,
		startMtime: number,
	): boolean {
		if (existsSync(lockPath)) {
			return false;
		}
		const currentMtime = this.getMtime(dbPath);
		return currentMtime > startMtime;
	}

	private getMtime(path: string): number {
		try {
			return statSync(path).mtimeMs;
		} catch {
			return 0;
		}
	}
}

function sleep(ms: number): Promise<void> {
	return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * MCP Server Configuration
 *
 * Reads environment variables on startup. No hot-reload.
 */

import { join } from "node:path";
import {
	DEFAULT_PIPELINE_CONFIG,
	loadPipelineConfig,
	type PipelineConfig,
} from "../retrieval/pipeline/config.js";
import type { LogLevel } from "./logger.js";

export type { PipelineConfig };
export { DEFAULT_PIPELINE_CONFIG };

export interface McpConfig {
	/** Workspace root (CWD at startup) */
	workspaceRoot: string;
	/** Pipeline configuration */
	pipeline: PipelineConfig;
	/** Index directory (MNEMEX_INDEX_DIR relative to workspaceRoot, or ".mnemex") */
	indexDir: string;
	/** Debounce delay for reindexing in ms (MNEMEX_DEBOUNCE_MS, default 120000) */
	debounceMs: number;
	/** Glob patterns for files to watch (MNEMEX_WATCH_PATTERNS, comma-separated) */
	watchPatterns: string[];
	/** Glob patterns to ignore (MNEMEX_IGNORE_PATTERNS, comma-separated) */
	ignorePatterns: string[];
	/** Max memory usage in MB (MNEMEX_MAX_MEMORY_MB, default 500) */
	maxMemoryMB: number;
	/** Polling interval for completion detection in ms (MNEMEX_COMPLETION_POLL_MS, default 2000) */
	completionPollMs: number;
	/** Minimum log level (MNEMEX_LOG_LEVEL, default "warn") */
	logLevel: LogLevel;
	/** LSP configuration */
	lsp: LspConfig;
}

export interface LspConfig {
	/** Whether LSP integration is enabled (MNEMEX_LSP, default false) */
	enabled: boolean;
	/** Request timeout in ms (MNEMEX_LSP_TIMEOUT_MS, default 10000) */
	timeoutMs: number;
	/** Maximum concurrent language servers (MNEMEX_LSP_MAX_SERVERS, default 2) */
	maxServers: number;
	/** Languages to disable (MNEMEX_LSP_DISABLE, comma-separated) */
	disabledLanguages: string[];
	/** Per-language command overrides */
	tsCommand?: string;
	pyCommand?: string;
	goCommand?: string;
	rsCommand?: string;
}

const DEFAULT_WATCH_PATTERNS = [
	"**/*.{ts,tsx,js,jsx,go,py,rs,java,kt,swift,rb,php,c,cpp,h}",
];

const DEFAULT_IGNORE_PATTERNS = [
	"node_modules/**",
	".git/**",
	"dist/**",
	"build/**",
	".next/**",
	"coverage/**",
];

const DEFAULT_DEBOUNCE_MS = 120000;
const DEFAULT_MAX_MEMORY_MB = 500;
const DEFAULT_COMPLETION_POLL_MS = 2000;
const DEFAULT_LOG_LEVEL: LogLevel = "warn";

/**
 * Parse environment variables and return an McpConfig.
 * Invalid numeric values fall back to defaults.
 */
export function loadMcpConfig(): McpConfig {
	const workspaceRoot = process.cwd();

	const indexDirEnv = process.env.MNEMEX_INDEX_DIR;
	const indexDir = indexDirEnv
		? join(workspaceRoot, indexDirEnv)
		: join(workspaceRoot, ".mnemex");

	const debounceMs = parseIntWithDefault(
		process.env.MNEMEX_DEBOUNCE_MS,
		DEFAULT_DEBOUNCE_MS,
	);

	const watchPatterns = parsePatterns(
		process.env.MNEMEX_WATCH_PATTERNS,
		DEFAULT_WATCH_PATTERNS,
	);

	const ignorePatterns = parsePatterns(
		process.env.MNEMEX_IGNORE_PATTERNS,
		DEFAULT_IGNORE_PATTERNS,
	);

	const maxMemoryMB = parseIntWithDefault(
		process.env.MNEMEX_MAX_MEMORY_MB,
		DEFAULT_MAX_MEMORY_MB,
	);

	const completionPollMs = parseIntWithDefault(
		process.env.MNEMEX_COMPLETION_POLL_MS,
		DEFAULT_COMPLETION_POLL_MS,
	);

	const logLevel = parseLogLevel(process.env.MNEMEX_LOG_LEVEL);

	const lsp: LspConfig = {
		enabled: parseBool(process.env.MNEMEX_LSP, false),
		timeoutMs: parseIntWithDefault(process.env.MNEMEX_LSP_TIMEOUT_MS, 10000),
		maxServers: parseIntWithDefault(process.env.MNEMEX_LSP_MAX_SERVERS, 2),
		disabledLanguages: parsePatterns(process.env.MNEMEX_LSP_DISABLE, []),
		tsCommand: process.env.MNEMEX_LSP_TS_CMD,
		pyCommand: process.env.MNEMEX_LSP_PY_CMD,
		goCommand: process.env.MNEMEX_LSP_GO_CMD,
		rsCommand: process.env.MNEMEX_LSP_RS_CMD,
	};

	return {
		workspaceRoot,
		indexDir,
		debounceMs,
		watchPatterns,
		ignorePatterns,
		maxMemoryMB,
		completionPollMs,
		logLevel,
		lsp,
		pipeline: loadPipelineConfig(),
	};
}

function parseIntWithDefault(
	value: string | undefined,
	defaultValue: number,
): number {
	if (value === undefined || value === "") return defaultValue;
	const parsed = Number.parseInt(value, 10);
	return Number.isNaN(parsed) ? defaultValue : parsed;
}

function parsePatterns(
	value: string | undefined,
	defaultValue: string[],
): string[] {
	if (!value || value.trim() === "") return defaultValue;
	const patterns = value
		.split(",")
		.map((p) => p.trim())
		.filter((p) => p.length > 0);
	return patterns.length > 0 ? patterns : defaultValue;
}

function parseBool(value: string | undefined, defaultValue: boolean): boolean {
	if (value === undefined || value === "") return defaultValue;
	return value === "true" || value === "1";
}

function parseLogLevel(value: string | undefined): LogLevel {
	const validLevels: LogLevel[] = ["debug", "info", "warn", "error"];
	if (value && validLevels.includes(value as LogLevel)) {
		return value as LogLevel;
	}
	return DEFAULT_LOG_LEVEL;
}

/**
 * Structured Index State
 *
 * Pure, read-only inspector for the current indexing situation. Companion to
 * buildFreshness(): where buildFreshness() reports the six flat freshness keys
 * from the in-memory state manager, buildIndexState() returns a richer, structured
 * block derived from cross-process truth (the lock file) + index.db presence +
 * tracker stats + the state manager.
 *
 * Read-only invariants:
 *  - Never mutates or removes the lock file (uses inspectLock, a liveness-probe only).
 *  - Never calls indexer.getStatus() (that triggers initialize(true), spinning up the
 *    embeddings client / vector store, which can throw). Stats mirror status.ts.
 *  - Requires NO reindexer / completionDetector (they are undefined outside --watch).
 */

import { existsSync, statSync } from "node:fs";
import { join } from "node:path";
import { inspectLock } from "../core/lock.js";
import type { ToolDeps } from "./tools/deps.js";

/** One of six mutually-exclusive index situations. */
export type IndexStatus =
	| "indexing_in_progress" // live lock, pid alive AND making forward progress
	| "indexing_hung" // live lock, pid alive but NO forward progress (LanceDB write hang); auto-reclaimed by next index
	| "stale_lock" // lock present but pid DEAD
	| "no_index" // no index.db
	| "stale" // index.db present, freshness=stale, no live lock
	| "fresh"; // index.db present, freshness=fresh, no live lock

/** Stats about the on-disk index. Always present (best-effort; safe fallbacks). */
export interface IndexInfo {
	/** Absolute path to the index directory (config.indexDir). */
	path: string;
	/** Files tracked in index.db. 0 if index absent or tracker unloadable. */
	indexedFileCount: number;
	/**
	 * Chunk count. NOT available from tracker.getStats() (which returns only
	 * { totalFiles, lastIndexed }). Computing it requires the vector store, which is
	 * expensive and may throw. Safe fallback: 0.
	 */
	chunkCount: number;
	/** Languages present in the index. Fallback: [] (not cheaply available read-only). */
	languages: string[];
	/** Size of index.db on disk in bytes. 0 if absent/unstatable. */
	indexSizeBytes: number;
	/** ISO timestamp of last successful index completion, or null. */
	lastIndexed: string | null;
	/** ISO timestamp staleness began (from stateManager), or null. */
	staleSince: string | null;
	/** Relative paths of files changed since last index (from stateManager). */
	filesChanged: string[];
}

/** Live/stale indexer detail derived from the lock file. null when no lock present. */
export interface IndexingInfo {
	/** Holder PID from the lock file. */
	pid: number;
	/** Human-readable start time (ISO) from the lock file (startedAt). */
	startedAt: string;
	/** ms since the lock's startTime (Date.now() - startTime). */
	elapsedMs: number;
	/** ISO timestamp of the lock's last heartbeat. */
	lastHeartbeat: string;
	/** heartbeat within HEARTBEAT_FRESH_TIMEOUT of now. Informational only. */
	isHeartbeatFresh: boolean;
	/**
	 * ISO timestamp of the lock's last forward progress (real indexing work).
	 * Falls back to the heartbeat timestamp for locks written by an older binary.
	 */
	lastProgressAt: string;
	/**
	 * forward progress within the progress timeout of now. A live pid with
	 * isProgressing=false is the hung-indexer signal (=> status indexing_hung).
	 */
	isProgressing: boolean;
	/** Whether the holder PID is alive (process.kill(pid, 0)). */
	pidAlive: boolean;
	/**
	 * Short label of WHAT the holder is doing (e.g. "writing:lance"), set by the
	 * indexer at phase transitions. undefined for locks written by an older binary
	 * (or before the first setPhase). Reporting only — never affects the status
	 * decision (which is driven by isProgressing / lastProgressAt).
	 */
	phase?: string;
	/**
	 * ms the holder has been in the current phase (now - phaseStartedAt). Present
	 * only when the lock carries a phase timestamp; undefined otherwise. Lets the
	 * report say "hung in phase 'writing:lance' for 6m".
	 */
	phaseStuckMs?: number;
	/**
	 * Command that started the indexer. The lock file does NOT carry this today
	 * ({ pid, startTime, heartbeat, startedAt } only). Always null in this refactor;
	 * populating it requires the lock WRITER (acquire()) to record it — out of scope.
	 */
	command: string | null;
}

/** The single object returned by buildIndexState and spread into tool responses. */
export interface IndexState {
	status: IndexStatus;
	/** True whenever an index.db exists (so cached results are usable), in ALL branches. */
	canReturnCachedResults: boolean;
	index: IndexInfo;
	/** Non-null only when a lock file is present (live or stale). */
	indexing: IndexingInfo | null;
	/** Case-specific, conservative. stale_lock recommendation is informational only. */
	recommendations: string[];
	/** One-line human-readable summary of the current state. */
	message: string;
}

/**
 * Heartbeat-freshness window for the informational isHeartbeatFresh flag.
 * Deliberately LARGER than acquisition's 10s stale window (DEFAULT_STALE_TIMEOUT) because:
 *  - the flag is purely informational; pid-alive ALWAYS => indexing_in_progress, so a
 *    "not fresh" flag never changes the status verdict;
 *  - the detached reindex heartbeat is a 1s setInterval that can stall when the event
 *    loop is busy, so a tight window yields false "not fresh".
 * 30s satisfies the validation matrix: case 1 (just-written heartbeat) => true;
 * case 2b (60s-old heartbeat) => false.
 */
export const HEARTBEAT_FRESH_TIMEOUT = 30000;

/**
 * Companion to buildFreshness(). Read-only. Async (cache.get() is async).
 * Derives everything from: lock file (via inspectLock) + index.db presence + tracker
 * stats + stateManager.getFreshness(). Requires NO reindexer/completionDetector.
 *
 * Deliberately does NOT re-emit the six buildFreshness keys (freshness, lastIndexed,
 * staleSince, filesChanged, reindexingInProgress, responseTimeMs); callers spread BOTH
 * objects and the spreads must not collide. The lastIndexed/staleSince/filesChanged
 * values live here only NESTED under `index.*`.
 *
 * @param startTime accepted for symmetry with buildFreshness; timing lives in
 *                  buildFreshness's responseTimeMs, so this builder emits no timing field.
 */
export async function buildIndexState(
	deps: ToolDeps,
	_startTime: number,
): Promise<IndexState> {
	const { config, stateManager, cache } = deps;

	const freshness = stateManager.getFreshness();

	const indexDbPath = join(config.indexDir, "index.db");
	const hasIndex = existsSync(indexDbPath);

	// config.indexDir is already an ABSOLUTE, fully-resolved path (config.ts joins it
	// onto workspaceRoot and honors MNEMEX_INDEX_DIR). inspectLock takes that directory
	// directly and resolves join(indexDir, ".indexing.lock") — no double-join.
	const inspect = inspectLock(config.indexDir, HEARTBEAT_FRESH_TIMEOUT);

	// ── Read-only stats (mirror status.ts; never throws) ──────────────────────
	let indexSizeBytes = 0;
	let indexedFileCount = 0;
	let lastIndexed: string | null = freshness.lastIndexed; // authoritative (stateManager)
	const chunkCount = 0; // SAFE FALLBACK — not available from tracker.getStats()
	const languages: string[] = []; // SAFE FALLBACK — not cheaply available read-only

	if (hasIndex) {
		try {
			indexSizeBytes = statSync(indexDbPath).size;
		} catch {
			// Ignore stat errors
		}
		try {
			const { tracker } = await cache.get();
			const stats = tracker.getStats();
			indexedFileCount = stats.totalFiles;
			if (!lastIndexed && stats.lastIndexed) {
				lastIndexed = stats.lastIndexed;
			}
		} catch {
			// "index.db present but tracker unloadable" edge case: degrade counts to
			// fallbacks but KEEP canReturnCachedResults = true (driven by file existence).
		}
	}

	const index: IndexInfo = {
		path: config.indexDir,
		indexedFileCount,
		chunkCount,
		languages,
		indexSizeBytes,
		lastIndexed,
		staleSince: freshness.staleSince,
		filesChanged: freshness.filesChanged,
	};

	// canRetur

/**
 * MCP Server Logger
 *
 * All output goes to stderr (stdout is reserved for MCP protocol).
 * Supports configurable log levels: debug < info < warn < error.
 */

export type LogLevel = "debug" | "info" | "warn" | "error";

const LOG_LEVEL_ORDER: Record<LogLevel, number> = {
	debug: 0,
	info: 1,
	warn: 2,
	error: 3,
};

/**
 * Stderr logger with configurable minimum log level.
 * Format: [mnemex] [LEVEL] message
 */
export class Logger {
	private minLevel: number;

	constructor(private level: LogLevel) {
		this.minLevel = LOG_LEVEL_ORDER[level];
	}

	debug(msg: string, ...args: unknown[]): void {
		if (LOG_LEVEL_ORDER.debug >= this.minLevel) {
			this.write("DEBUG", msg, args);
		}
	}

	info(msg: string, ...args: unknown[]): void {
		if (LOG_LEVEL_ORDER.info >= this.minLevel) {
			this.write("INFO", msg, args);
		}
	}

	warn(msg: string, ...args: unknown[]): void {
		if (LOG_LEVEL_ORDER.warn >= this.minLevel) {
			this.write("WARN", msg, args);
		}
	}

	error(msg: string, ...args: unknown[]): void {
		// error always writes
		this.write("ERROR", msg, args);
	}

	private write(label: string, msg: string, args: unknown[]): void {
		const extra = args.length > 0 ? ` ${args.map(formatArg).join(" ")}` : "";
		process.stderr.write(`[mnemex] [${label}] ${msg}${extra}\n`);
	}
}

function formatArg(arg: unknown): string {
	if (typeof arg === "string") return arg;
	if (arg instanceof Error) return arg.message;
	try {
		return JSON.stringify(arg);
	} catch {
		return String(arg);
	}
}

/**
 * Create a Logger from a log level string.
 */
export function createLogger(level: LogLevel): Logger {
	return new Logger(level);
}

/**
 * Debounce Reindexer
 *
 * Schedules background reindex operations with debouncing so that rapid file
 * changes result in a single reindex. Spawns a detached child process running
 * `mnemex index --quiet` to avoid blocking the MCP stdio transport.
 */

import { spawn } from "node:child_process";
import { IndexLock } from "../core/lock.js";
import type { IndexCache } from "./cache.js";
import type { CompletionDetector } from "./completion-detector.js";
import type { Logger } from "./logger.js";
import type { IndexStateManager } from "./state-manager.js";

/**
 * Schedules and executes background reindex operations.
 */
export class DebounceReindexer {
	private timer: ReturnType<typeof setTimeout> | null = null;
	private running = false;

	constructor(
		private workspaceRoot: string,
		private indexDir: string,
		private debounceMs: number,
		private stateManager: IndexStateManager,
		private cache: IndexCache,
		private completionDetector: CompletionDetector,
		private logger: Logger,
	) {}

	/**
	 * Schedule a reindex. Multiple calls within the debounce window
	 * collapse into a single reindex.
	 */
	scheduleReindex(): void {
		if (this.timer !== null) {
			clearTimeout(this.timer);
		}
		this.timer = setTimeout(() => {
			this.timer = null;
			void this.triggerReindex();
		}, this.debounceMs);
		this.logger.debug(
			`DebounceReindexer: reindex scheduled in ${this.debounceMs}ms`,
		);
	}

	/**
	 * Cancel any pending scheduled reindex.
	 */
	cancelPending(): void {
		if (this.timer !== null) {
			clearTimeout(this.timer);
			this.timer = null;
			this.logger.debug("DebounceReindexer: pending reindex cancelled");
		}
	}

	/**
	 * Trigger an immediate reindex and wait for it to complete.
	 */
	async forceReindex(): Promise<void> {
		this.cancelPending();
		await this.triggerReindex();
	}

	/**
	 * Check whether a reindex is already running — either our own in-memory
	 * flag or an external process holding the disk lock.
	 */
	isRunning(): boolean {
		return this.running || this.isLocked();
	}

	/**
	 * Check whether an indexing lock is currently held (by any process).
	 */
	isLocked(): boolean {
		const lock = new IndexLock(this.workspaceRoot);
		return lock.isLocked().locked;
	}

	private async triggerReindex(): Promise<void> {
		if (this.running) {
			this.logger.debug(
				"DebounceReindexer: reindex already in progress, skipping",
			);
			return;
		}

		if (this.isLocked()) {
			this.logger.info(
				"DebounceReindexer: index lock held by another process, skipping",
			);
			return;
		}

		this.running = true;
		this.stateManager.onReindexStart();
		this.cache.invalidate();

		this.logger.info("DebounceReindexer: starting background reindex");

		try {
			// --if-idle: request machine-global try-acquire-bail. If a machine-wide
			// index is already running (any repo, any session), this background
			// reindex exits cleanly instead of piling up as an idle waiter competing
			// for the one shared embeddings API quota. The next debounce trigger
			// re-fires later.
			const child = spawn("mnemex", ["index", "--quiet", "--if-idle"], {
				cwd: this.workspaceRoot,
				detached: true,
				stdio: "ignore",
			});

			// A missing `mnemex` on PATH surfaces as an async 'error' event, not a
			// throw. Unhandled, Node re-raises it and kills the MCP server over a
			// background reindex that is explicitly best-effort.
			child.on("error", (err) => {
				this.logger.debug(
					`DebounceReindexer: could not spawn mnemex (${err.message}) — skipping background reindex`,
				);
			});

			child.unref();

			this.logger.debug(
				`DebounceReindexer: spawned mnemex index (pid ${child.pid})`,
			);

			// Start polling for completion - when done, update state and invalidate cache
			this.completionDetector.watch(() => {
				this.logger.info("DebounceReindexer: reindex complete");
				this.stateManager.onReindexComplete();
				this.cache.invalidate();
				this.running = false;
			});
		} catch (err) {
			this.logger.error(
				"DebounceReindexer: failed to spawn reindex process",
				err,
			);
			this.running = false;
			this.stateManager.onReindexComplete();
		}
	}
}

/**
 * MCP Server Entry Point
 *
 * Wires together all MCP infrastructure components and registers all tools.
 * Launched when mnemex is started with --mcp flag.
 *
 * Startup sequence:
 * 1. Parse env vars → loadMcpConfig()
 * 2. Create logger
 * 3. Initialize IndexStateManager
 * 4. Check index existence — run blocking initial index if missing
 * 5. Create IndexCache
 * 6. Create CompletionDetector
 * 7. Create DebounceReindexer
 * 8. Start FileWatcher
 * 9. Register all MCP tools
 * 10. Connect stdio transport
 * 11. Register SIGTERM/SIGINT shutdown handlers
 */

import { spawn } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { getIndexDbPath } from "../config.js";
import { SymbolEditor } from "../editor/editor.js";
import { LspManager } from "../lsp/manager.js";
import { MemoryStore } from "../memory/store.js";
import { IndexCache } from "./cache.js";
import { CompletionDetector } from "./completion-detector.js";
import { loadMcpConfig } from "./config.js";
import { createLogger } from "./logger.js";
import { DebounceReindexer } from "./reindexer.js";
import { IndexStateManager } from "./state-manager.js";
import {
	registerAnalysisTools,
	registerCalleesTools,
	registerCallersTools,
	registerContextTools,
	registerEditTools,
	registerLegacyTools,
	registerLspTools,
	registerMapTools,
