/**
 * Index State Manager
 *
 * Single source of truth for index freshness state.
 * Tracks which files have changed since last index, when staleness began,
 * and whether a reindex is currently in progress.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { IndexLock } from "../core/lock.js";
import type { FreshnessMetadata } from "./types.js";

const REINDEX_TIMESTAMP_FILE = ".reindex-timestamp";

/**
 * Manages index freshness state for a single workspace.
 */
export class IndexStateManager {
	/** When the index was last successfully completed */
	private lastIndexed: Date | null = null;

	/** Files that changed since the last index completion */
	private filesChangedSince: Set<string> = new Set();

	/** When the first file change was recorded after a fresh state */
	private staleSince: Date | null = null;

	/** Whether a reindex is currently running */
	private reindexInProgress = false;

	constructor(private indexDir: string) {}

	/**
	 * Initialize state by reading existing timestamp file and checking for stale locks.
	 */
	async initialize(): Promise<void> {
		// Read last reindex timestamp
		const timestampPath = join(this.indexDir, REINDEX_TIMESTAMP_FILE);
		if (existsSync(timestampPath)) {
			try {
				const content = readFileSync(timestampPath, "utf-8").trim();
				const date = new Date(content);
				if (!isNaN(date.getTime())) {
					this.lastIndexed = date;
				}
			} catch {
				// Ignore parse errors - treat as never indexed
			}
		}

		// Check if a stale lock is present and clear reindexInProgress
		// The IndexLock isLocked() call checks heartbeat freshness
		const projectPath = join(this.indexDir, "..");
		const lock = new IndexLock(projectPath);
		const lockStatus = lock.isLocked();
		// If there's an active (non-stale) lock, a reindex was in progress
		// when we started. Mark it but it will resolve when completion-detector fires.
		this.reindexInProgress = lockStatus.locked;
	}

	/**
	 * Get the current freshness metadata.
	 * Caller is responsible for filling in responseTimeMs.
	 */
	getFreshness(): Omit<FreshnessMetadata, "responseTimeMs"> {
		// Stale when: files changed OR never indexed OR reindex running
		const isStale =
			this.filesChangedSince.size > 0 ||
			this.lastIndexed === null ||
			this.reindexInProgress;
		return {
			freshness: isStale ? "stale" : "fresh",
			lastIndexed: this.lastIndexed?.toISOString() ?? null,
			staleSince: this.staleSince?.toISOString() ?? null,
			filesChanged: Array.from(this.filesChangedSince),
			reindexingInProgress: this.reindexInProgress,
		};
	}

	/**
	 * Record a file change. Transitions to stale state on first change.
	 */
	recordChange(filePath: string): void {
		if (this.filesChangedSince.size === 0 && !this.reindexInProgress) {
			// First change - record when staleness began
			this.staleSince = new Date();
		}
		this.filesChangedSince.add(filePath);
	}

	/**
	 * Called when a reindex operation begins.
	 */
	onReindexStart(): void {
		this.reindexInProgress = true;
	}

	/**
	 * Called when a reindex operation completes successfully.
	 * Clears changed files, resets stale state, writes timestamp.
	 */
	onReindexComplete(): void {
		this.reindexInProgress = false;
		this.filesChangedSince.clear();
		this.staleSince = null;
		this.lastIndexed = new Date();
		this.writeTimestamp();
	}

	/**
	 * Write the current timestamp to the .reindex-timestamp file.
	 */
	private writeTimestamp(): void {
		try {
			if (!existsSync(this.indexDir)) {
				mkdirSync(this.indexDir, { recursive: true });
			}
			const timestampPath = join(this.indexDir, REINDEX_TIMESTAMP_FILE);
			writeFileSync(timestampPath, new Date().toISOString(), "utf-8");
		} catch {
			// Non-fatal: timestamp is used for informational display only
		}
	}

	/** Whether a reindex is currently in progress */
	get isReindexing(): boolean {
		return this.reindexInProgress;
	}

	/** Number of files changed since last index */
	get changedFileCount(): number {
		return this.filesChangedSince.size;
	}
}

/**
 * Analysis Tools
 *
 * Three code analysis tools in one file:
 *   dead_code   - Find unreferenced exports with low PageRank
 *   test_gaps   - Find untested high-PageRank symbols
 *   impact      - Change blast radius analysis (transitive callers)
 */

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { createCodeAnalyzer } from "../../core/analysis/analyzer.js";
import { buildIndexState } from "../index-state.js";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerAnalysisTools(server: McpServer, deps: ToolDeps): void {
	const { cache, stateManager } = deps;

	// =========================================================================
	// dead_code
	// =========================================================================
	server.tool(
		"dead_code",
		"Find unreferenced symbols (zero callers and low PageRank). Useful for codebase cleanup.",
		{
			minReferences: z
				.number()
				.default(0)
				.describe(
					"Minimum reference count to consider dead (symbols with fewer are flagged). Default: 0",
				),
			filePattern: z
				.string()
				.optional()
				.describe("Glob pattern to restrict analysis to specific files"),
			limit: z
				.number()
				.max(200)
				.default(50)
				.describe("Maximum results to return (default: 50)"),
		},
		async ({ filePattern, limit }) => {
			const startTime = Date.now();

			try {
				const { tracker } = await cache.get();
				const analyzer = createCodeAnalyzer(tracker);

				const results = analyzer.findDeadCode({
					maxPageRank: 0.001,
					unexportedOnly: false,
					limit: limit ?? 50,
				});

				// Apply file pattern filter if provided
				const filtered = filePattern
					? results.filter((r) => {
							const pat = filePattern
								.replace(/\*\*/g, ".*")
								.replace(/\*/g, "[^/]*");
							return new RegExp(pat).test(r.symbol.filePath);
						})
					: results;

				const deadSymbols = filtered.map((r) => ({
					symbol: r.symbol.name,
					kind: r.symbol.kind,
					file: r.symbol.filePath,
					line: r.symbol.startLine,
					referenceCount: r.symbol.inDegree,
					pageRank: r.symbol.pagerankScore,
					reason: r.reason,
				}));

				const indexState = await buildIndexState(deps, startTime);

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								deadSymbols,
								totalAnalyzed: deadSymbols.length,
								...buildFreshness(stateManager, startTime),
								...indexState,
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);

	// =========================================================================
	// test_gaps
	// =========================================================================
	server.tool(
		"test_gaps",
		"Find high-importance symbols (by PageRank) that have no test coverage. Prioritizes what to test next.",
		{
			filePattern: z
				.string()
				.default("src/")
				.describe(
					"Restrict to source files matching this path prefix (default: 'src/')",
				),
			testPattern: z
				.string()
				.optional()
				.describe(
					"Override test file pattern (default: auto-detected per language)",
				),
			limit: z
				.number()
				.max(100)
				.default(30)
				.describe("Maximum results to return (default: 30)"),
		},
		async ({ filePattern, limit }) => {
			const startTime = Date.now();

			try {
				const { tracker } = await cache.get();
				const analyzer = createCodeAnalyzer(tracker);

				const results = analyzer.findTestGaps({
					minPageRank: 0.005,
					limit: limit ?? 30,
				});

				// Filter by file pattern
				const filtered = filePattern
					? results.filter((r) => r.symbol.filePath.includes(filePattern))
					: results;

				const untestedSymbols = filtered.map((r) => ({
					symbol: r.symbol.name,
					kind: r.symbol.kind,
					file: r.symbol.filePath,
					line: r.symbol.startLine,
					pageRank: r.symbol.pagerankScore,
					testReferences: r.testCallerCount,
					callerCount: r.callerCount,
				}));

				const totalSourceSymbols = tracker.getAllSymbols().length;
				const untestedCount = untestedSymbols.length;
				const coveragePercent =
					totalSourceSymbols > 0
						? Math.round(
								((totalSourceSymbols - untestedCount) / totalSourceSymbols) *
									100,
							)
						: 100;

				const indexState = await buildIndexState(deps, startTime);

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								untestedSymbols,
								summary: {
									totalSourceSymbols,
									untestedCount,
									coveragePercent,
								},
								...buildFreshness(stateManager, startTime),
								...indexState,
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);

	// =========================================================================
	// impact
	// =========================================================================
	server.tool(
		"impact",
		"Analyze the blast radius of changing a symbol. Returns all transitive callers grouped by file with a risk level.",
		{
			symbol: z.string().describe("Symbol name to analyze change impact for"),
			depth: z
				.number()
				.max(5)
				.default(3)
				.describe("Traversal depth for transitive callers (default: 3)"),
		},
		async ({ symbol: symbolName, depth }) => {
			const startTime = Date.now();

			try {
				const { tracker } = await cache.get();
				const analyzer = createCodeAnalyzer(tracker);
				const indexState = await buildIndexState(deps, startTime);

				const target = analyzer.findSymbolForImpact(symbolName);
				if (!target) {
					return {
						content: [
							{
								type: "text" as const,
								text: JSON.stringify({
									error: `Symbol "${symbolName}" not found in index.`,
									...buildFreshness(stateManager, startTime),
									...indexState,
								}),
							},
						],
					};
				}

				const result = analyzer.findImpact(target.id, {
					maxDepth: depth ?? 3,
				});

				if (!result) {
					return {
						content: [
							{
								type: "text" as const,
								text: JSON.stringify({
									error: `Could not analyze impact for "${symbolName}".`,
									...buildFreshness(stateManager, startTime),
									...indexState,
								}),
							},
						],
					};
				}

				const affectedFiles = Array.from(result.byFile.keys());
				const impactedSymbols = result.transitiveCallers.map((r) => ({
					symbol: r.symbol.name,
					file: r.symbol.filePath,
					line: r.symbol.startLine,
					depth: r.depth,
				}));

				// Risk level based on affected count
				const riskLevel =
					result.totalAffected > 20
						? "high"
						: result.totalAffected > 5
							? "medium"
							: "low";

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								directDependents: result.directCallers.length,
								transitiveDependents: result.totalAffected,
								affectedFiles,
								impactedSymbols,
								riskLevel,
								...buildFreshness(stateManager, startTime),
								...indexState,
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

/**
 * Callees Tool
 *
 * Traverse the call graph downward from a symbol, showing what it depends on.
 * When cloud deps are available (deps.cloudClient), uses cloudClient.getCallees()
 * which returns server-side call graph data. Cloud errors are returned directly.
 */

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerCalleesTools(server: McpServer, deps: ToolDeps): void {
	const { cache, stateManager, logger } = deps;

	server.tool(
		"callees",
		"Find all dependencies (callees) of a symbol, traversed downward through the call graph.",
		{
			symbol: z.string().describe("Symbol name to find dependencies of"),
			depth: z
				.number()
				.min(1)
				.max(5)
				.default(1)
				.describe("Traversal depth (default: 1, direct callees only)"),
			excludeExternal: z
				.boolean()
				.default(false)
				.describe("Exclude symbols from external packages (default: false)"),
		},
		async ({ symbol: symbolName, depth, excludeExternal }) => {
			const startTime = Date.now();

			try {
				// ── Cloud callees (when cloud deps are wired in) ─────────────────
				if (deps.cloudClient && deps.currentCommitSha && deps.teamConfig) {
					try {
						const orgSlug = deps.teamConfig.orgSlug;
						const repoSlug =
							deps.teamConfig.repoSlug ??
							`${orgSlug}/${
								deps.config.workspaceRoot.split("/").filter(Boolean).pop() ??
								"repo"
							}`;

						const calleesResult = await deps.cloudClient.getCallees(
							repoSlug,
							deps.currentCommitSha,
							symbolName,
						);

						const calleeItems = calleesResult.callees.map((c) => ({
							symbol: c.name,
							file: c.filePath,
							line: c.line,
							kind: c.kind,
							isExternal: false,
							depth: 1,
						}));

						const filtered = excludeExternal
							? calleeItems.filter((c) => !c.isExternal)
							: calleeItems;

						return {
							content: [
								{
									type: "text" as const,
									text: JSON.stringify({
										callees: filtered,
										...buildFreshness(stateManager, startTime),
									}),
								},
							],
						};
					} catch (cloudErr) {
						return errorResponse(cloudErr);
					}
				}

				// ── Local callees (default path) ─────────────────────────────────
				const { graphManager } = await cache.get();

				const target = graphManager.findSymbol(symbolName, {
					preferExported: true,
				});

				if (!target) {
					return {
						content: [
							{
								type: "text" as const,
								text: JSON.stringify({
									error: `Symbol "${symbolName}" not found in index.`,
									callees: [],
									...buildFreshness(stateManager, startTime),
								}),
							},
						],
					};
				}

				// BFS traversal downward up to `depth` levels
				const visited = new Set<string>([target.id]);
				const allCallees: Array<{
					symbol: string;
					file: string;
					line: number;
					isExternal: boolean;
					depth: number;
				}> = [];

				let frontier = [target.id];

				for (let d = 1; d <= (depth ?? 1); d++) {
					const nextFrontier: string[] = [];

					for (const id of frontier) {
						const callees = graphManager.getCallees(id);
						for (const callee of callees) {
							if (!visited.has(callee.id)) {
								visited.add(callee.id);
								nextFrontier.push(callee.id);

								// Heuristic: symbols from node_modules or without filePath are external
								const isExternal =
									callee.filePath.includes("node_modules") ||
									callee.filePath.startsWith("external:");

								if (excludeExternal && isExternal) {
									continue;
								}

								allCallees.push({
									symbol: callee.name,
									file: callee.filePath,
									line: callee.startLine,
									isExternal,
									depth: d,
								});
							}
						}
					}

					frontier = nextFrontier;
					if (frontier.length === 0) break;
				}

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								callees: allCallees,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

/**
 * Callers Tool
 *
 * Traverse the call graph upward from a symbol, showing what depends on it,
 * ranked by PageRank importance.
 * When cloud deps are available (deps.cloudClient), uses cloudClient.getCallers()
 * which returns server-side call graph data. Cloud errors are returned directly.
 */

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerCallersTools(server: McpServer, deps: ToolDeps): void {
	const { cache, stateManager, logger } = deps;

	server.tool(
		"callers",
		"Find all callers (dependents) of a symbol, traversed upward through the call graph, ranked by PageRank.",
		{
			symbol: z.string().describe("Symbol name to find callers of"),
			depth: z
				.number()
				.min(1)
				.max(5)
				.default(1)
				.describe("Traversal depth (default: 1, direct callers only)"),
			limit: z
				.number()
				.min(1)
				.max(100)
				.default(20)
				.describe("Maximum callers to return (default: 20)"),
		},
		async ({ symbol: symbolName, depth, limit }) => {
			const startTime = Date.now();

			try {
				// ── Cloud callers (when cloud deps are wired in) ─────────────────
				if (deps.cloudClient && deps.currentCommitSha && deps.teamConfig) {
					try {
						const orgSlug = deps.teamConfig.orgSlug;
						const repoSlug =
							deps.teamConfig.repoSlug ??
							`${orgSlug}/${
								deps.config.workspaceRoot.split("/").filter(Boolean).pop() ??
								"repo"
							}`;

						const callersResult = await deps.cloudClient.getCallers(
							repoSlug,
							deps.currentCommitSha,
							symbolName,
						);

						const callerItems = callersResult.callers
							.slice(0, limit ?? 20)
							.map((c) => ({
								symbol: c.name,
								file: c.filePath,
								line: c.line,
								kind: c.kind,
								depth: 1,
								pageRank: 0,
							}));

						return {
							content: [
								{
									type: "text" as const,
									text: JSON.stringify({
										totalDirectCallers: callersResult.callers.length,
										callers: callerItems,
										...buildFreshness(stateManager, startTime),
									}),
								},
							],
						};
					} catch (cloudErr) {
						return errorResponse(cloudErr);
					}
				}

				// ── Local callers (default path) ─────────────────────────────────
				const { graphManager } = await cache.get();

				const target = graphManager.findSymbol(symbolName, {
					preferExported: true,
				});

				if (!target) {
					return {
						content: [
							{
								type: "text" as const,
								text: JSON.stringify({
									error: `Symbol "${symbolName}" not found in index.`,
									totalDirectCallers: 0,
									callers: [],
									...buildFreshness(stateManager, startTime),
								}),
							},
						],
					};
				}

				// BFS traversal up to `depth` levels
				const visited = new Set<string>([target.id]);
				const allCallers: Array<{
					symbol: string;
					file: string;
					line: number;
					pageRank: number;
					depth: number;
				}> = [];

				let frontier = [target.id];
				const directCallers = graphManager.getCallers(target.id);

				for (let d = 1; d <= (depth ?? 1); d++) {
					const nextFrontier: string[] = [];

					for (const id of frontier) {
						const callers =
							d === 1
								? id === target.id
									? directCallers
									: graphManager.getCallers(id)
								: graphManager.getCallers(id);
						for (const caller of callers) {
							if (!visited.has(caller.id)) {
								visited.add(caller.id);
								nextFrontier.push(caller.id);
								allCallers.push({
									symbol: caller.name,
									file: caller.filePath,
									line: caller.startLine,
									pageRank: caller.pagerankScore,
									depth: d,
								});
							}
						}
					}

					frontier = nextFrontier;
					if (frontier.length === 0) break;
				}

				// Sort by PageRank descending, then truncate
				allCallers.sort((a, b) => b.pageRank - a.pageRank);
				const truncated = allCallers.slice(0, limit ?? 20);

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								totalDirectCallers: directCallers.length,
								callers: truncated,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

/**
 * Context Tool
 *
 * Provides rich context for a symbol or file location:
 * enclosing symbol, imports, related symbols via the reference graph.
 */

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { readSymbolBody } from "../../retrieval/backends/utils/read-body.js";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerContextTools(server: McpServer, deps: ToolDeps): void {
	const { cache, stateManager, config } = deps;

	server.tool(
		"context",
		"Get rich context for a file location: enclosing symbol with source body, imports, and related symbols via the reference graph.",
		{
			file: z
				.string()
				.describe("File path (relative to workspace root) to get context for"),
			line: z.coerce
				.number()
				.default(1)
				.describe("Line number within the file (default: 1)"),
			radius: z.coerce
				.number()
				.min(1)
				.max(10)
				.default(2)
				.describe("Number of related symbols to include (default: 2)"),
			includeBody: z
				.boolean()
				.default(true)
				.describe(
					"Include source code body of the enclosing symbol (default: true)",
				),
		},
		async ({ file, line, radius, includeBody }) => {
			const startTime = Date.now();

			try {
				const { graphManager, tracker } = await cache.get();

				// Find which symbol contains the given file:line
				const allSymbols = tracker.getAllSymbols();
				const atLocation = allSymbols.filter(
					(s) =>
						(s.filePath === file || s.filePath.endsWith(`/${file}`)) &&
						s.startLine <= (line ?? 1) &&
						s.endLine >= (line ?? 1),
				);

				// Pick the most specific (innermost) symbol
				atLocation.sort(
					(a, b) => b.startLine - a.startLine || a.endLine - b.endLine,
				);
				const enclosing = atLocation[0] ?? null;

				let callers: Array<{ name: string; file: string; line: number }> = [];
				let callees: Array<{ name: string; file: string; line: number }> = [];

				if (enclosing) {
					const ctx = graphManager.getSymbolContext(enclosing.id, {
						includeCallers: true,
						includeCallees: true,
						maxCallers: radius ?? 2,
						maxCallees: radius ?? 2,
					});
					callers = ctx.callers.map((s) => ({
						name: s.name,
						file: s.filePath,
						line: s.startLine,
					}));
					callees = ctx.callees.map((s) => ({
						name: s.name,
						file: s.filePath,
						line: s.startLine,
					}));
				}

				// Gather file-level imports by collecting callees from file symbols
				const fileSymbols = allSymbols.filter(
					(s) => s.filePath === file || s.filePath.endsWith(`/${file}`),
				);
				const importSet = new Set<string>();
				for (const sym of fileSymbols) {
					const symCallees = graphManager.getCallees(sym.id);
					for (const callee of symCallees) {
						if (
							callee.filePath !== file &&
							!callee.filePath.endsWith(`/${file}`)
						) {
							importSet.add(callee.filePath);
						}
					}
				}

				// Read body from disk if requested
				let body: string | null = null;
				let bodyStale = false;
				if (includeBody && enclosing) {
					const bodyResult = readSymbolBody(
						config.workspaceRoot,
						enclosing.filePath,
						enclosing.startLine,
						enclosing.endLine,
					);
					body = bodyResult.body;
					bodyStale = bodyResult.stale;
				}

				const enclosingPayload = enclosing
					? {
							name: enclosing.name,
							kind: enclosing.kind,
							file: enclosing.filePath,
							startLine: enclosing.startLine,
							endLine: enclosing.endLine,
							signature: enclosing.signature ?? null,
							...(includeBody ? { body, bodyStale } : {}),
						}
					: null;

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								enclosingSymbol: enclosingPayload,
								imports: Array.from(importSet),
								relatedSymbols: { callers, callees },
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

/**
 * Tool Dependencies
 *
 * Common dependency injection interface passed to all tool registration
 * functions, reducing boilerplate and centralizing infrastructure access.
 */

import type {
	ICloudIndexClient,
	IOverlayIndex,
	TeamConfig,
} from "../../cloud/types.js";
import type { SymbolEditor } from "../../editor/editor.js";
import type { LspManager } from "../../lsp/manager.js";
import type { MemoryStore } from "../../memory/store.js";
import type { IndexCache } from "../cache.js";
import type { CompletionDetector } from "../completion-detector.js";
import type { McpConfig } from "../config.js";
import type { Logger } from "../logger.js";
import type { DebounceReindexer } from "../reindexer.js";
import type { IndexStateManager } from "../state-manager.js";
import type { FreshnessMetadata } from "../types.js";

export interface ToolDeps {
	cache: IndexCache;
	stateManager: IndexStateManager;
	config: McpConfig;
	logger: Logger;
