import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerMapTools(server: McpServer, deps: ToolDeps): void {
	const { cache, stateManager, config } = deps;

	server.tool(
		"map",
		"Generate an architectural overview of the codebase, with symbols ranked by PageRank importance.",
		{
			root: z
				.string()
				.default(".")
				.describe(
					"Root directory to map, relative to workspace (default: '.')",
				),
			depth: z
				.number()
				.min(1)
				.max(8)
				.default(3)
				.describe(
					"Approximate token budget in thousands (default: 3 = 3000 tokens)",
				),
			includeSymbols: z
				.boolean()
				.default(true)
				.describe("Include symbol signatures in the map (default: true)"),
		},
		async ({ root, depth }) => {
			const startTime = Date.now();

			try {
				// depth is repurposed as token budget in thousands
				const maxTokens = (depth ?? 3) * 1000;

				// ── Cloud map (when cloud deps are wired in) ─────────────────────
				if (deps.cloudClient && deps.currentCommitSha && deps.teamConfig) {
					try {
						const orgSlug = deps.teamConfig.orgSlug;
						const repoSlug =
							deps.teamConfig.repoSlug ??
							`${orgSlug}/${
								config.workspaceRoot.split("/").filter(Boolean).pop() ?? "repo"
							}`;

						const mapText = await deps.cloudClient.getMap(
							repoSlug,
							deps.currentCommitSha,
							root && root !== "." ? root : undefined,
							maxTokens,
						);

						return {
							content: [
								{
									type: "text" as const,
									text: JSON.stringify({
										mapText,
										...buildFreshness(stateManager, startTime),
									}),
								},
							],
						};
					} catch (cloudErr) {
						return errorResponse(cloudErr);
					}
				}

				// ── Local map (default path) ─────────────────────────────────────
				const { repoMapGen } = await cache.get();

				const pathPattern = root && root !== "." ? root : undefined;

				const mapText = repoMapGen.generate({
					maxTokens,
					includeSignatures: true,
					pathPattern,
				});

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								mapText,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

/**
 * Memory Tools
 *
 * MCP tools for project memory: write, read, list, delete.
 */

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerMemoryTools(server: McpServer, deps: ToolDeps): void {
	const { stateManager, memoryStore } = deps;

	if (!memoryStore) return;

	server.tool(
		"memory_write",
		"Store a project memory (architectural decisions, patterns, preferences). " +
			"Memories persist across sessions in .mnemex/memories/.",
		{
			key: z
				.string()
				.describe(
					"Memory key (alphanumeric, hyphens, underscores, max 128 chars)",
				),
			content: z.string().describe("Memory content (markdown)"),
		},
		async ({ key, content }) => {
			const startTime = Date.now();

			try {
				const memory = memoryStore.write(key, content);

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								written: memory.key,
								createdAt: memory.createdAt,
								updatedAt: memory.updatedAt,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);

	server.tool(
		"memory_read",
		"Read a project memory by key.",
		{
			key: z.string().describe("Memory key to read"),
		},
		async ({ key }) => {
			const startTime = Date.now();

			try {
				const memory = memoryStore.read(key);

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								memory: memory
									? {
											key: memory.key,
											content: memory.content,
											createdAt: memory.createdAt,
											updatedAt: memory.updatedAt,
										}
									: null,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);

	server.tool(
		"memory_list",
		"List all project memories (keys and timestamps, no content).",
		{},
		async () => {
			const startTime = Date.now();

			try {
				const memories = memoryStore.list();

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
