		"memory_delete",
		"Delete a project memory by key.",
		{
			key: z.string().describe("Memory key to delete"),
		},
		async ({ key }) => {
			const startTime = Date.now();

			try {
				const deleted = memoryStore.delete(key);

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								deleted,
								key,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
