/**
 * Observe Tool
 *
 * MCP tool for recording session observations (cognitive memory).
 * Observations are embedded and stored alongside code chunks in LanceDB,
 * surfacing in future searches when semantically relevant.
 */

import { createHash } from "node:crypto";
import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { createEmbeddingsClient } from "../../core/embeddings.js";
import { createIndexer } from "../../core/indexer.js";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerObserveTools(server: McpServer, deps: ToolDeps): void {
	const { stateManager, config, logger } = deps;

	server.tool(
		"observe",
		"Record a session observation (gotcha, pattern, architecture note). " +
			"Observations are embedded and surface in future searches when relevant.",
		{
			content: z.string().min(5).max(2000).describe("The observation text"),
			affectedFiles: z
				.array(z.string())
				.default([])
				.describe("File paths this observation relates to"),
			observationType: z
				.enum(["gotcha", "pattern", "architecture", "procedure", "preference"])
				.default("pattern")
				.describe("Type of observation"),
			confidence: z
				.number()
				.min(0)
				.max(1)
				.default(0.7)
				.describe("Confidence level (0-1)"),
		},
		async ({ content, affectedFiles, observationType, confidence }) => {
			const startTime = Date.now();

			try {
				const embeddingsClient = createEmbeddingsClient();
				const embedding = await embeddingsClient.embedOne(content);

				const id = createHash("sha256")
					.update(`observation:${content}:${affectedFiles.join(",")}`)
					.digest("hex")
					.slice(0, 16);

				const now = new Date().toISOString();
				const doc = {
					id,
					content,
					documentType: "session_observation" as const,
					filePath: affectedFiles[0] || "",
					fileHash: "",
					createdAt: now,
					enrichedAt: now,
					sourceIds: [],
					metadata: {
						observationType,
						confidence,
						affectedFiles,
					},
					vector: embedding,
				};

				// Write to LanceDB
				const indexer = createIndexer({
					projectPath: config.workspaceRoot,
				});
				const store = (indexer as any).vectorStore;
				if (store) {
					await store.addDocuments([doc]);
				} else {
					// Fallback: create store directly
					const { createVectorStore } = await import("../../core/store.js");
					const vs = await createVectorStore(config.workspaceRoot);
					await vs.addDocuments([doc]);
					await vs.close();
				}
				await indexer.close();

				logger.info(`observe: recorded observation ${id} (${observationType})`);

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								observationId: id,
								observationType,
								confidence,
								affectedFiles,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

/**
 * Read File Tool
 *
 * Read file contents with optional line range. Uses workspace-relative
 * path resolution so agents don't need to know the absolute project path.
 *
 * Closes the gap where agents fall back to native Read() because the
 * context() tool returns a fixed symbol-scoped window.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerReadFileTools(server: McpServer, deps: ToolDeps): void {
	const { stateManager, config } = deps;

	server.tool(
		"read_file",
		"Read file contents with optional line range. Paths are relative to the workspace root.",
		{
			path: z.string().describe("File path relative to workspace root"),
			startLine: z
				.number()
				.int()
				.min(1)
				.optional()
				.describe("First line to read (1-based, inclusive)"),
			endLine: z
				.number()
				.int()
				.min(1)
				.optional()
				.describe("Last line to read (1-based, inclusive)"),
		},
		async ({ path, startLine, endLine }) => {
			const startTime = Date.now();

			try {
				const absPath = resolve(config.workspaceRoot, path);

				// Security: prevent path traversal outside workspace
				if (!absPath.startsWith(config.workspaceRoot)) {
					return {
						content: [
							{
								type: "text" as const,
								text: "Error: path traversal outside workspace root is not allowed",
							},
						],
						isError: true,
					};
				}

				const content = readFileSync(absPath, "utf-8");
				const allLines = content.split("\n");
				const totalLines = allLines.length;

				// Apply line range if specified
				const start = startLine ? Math.max(1, startLine) : 1;
				const end = endLine ? Math.min(totalLines, endLine) : totalLines;
				const selectedLines = allLines.slice(start - 1, end);

				// Format with line numbers
				const numbered = selectedLines
					.map((line, i) => `${start + i}\t${line}`)
					.join("\n");

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								path,
								totalLines,
								startLine: start,
								endLine: end,
								content: numbered,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

/**
 * Reindex Tool
 *
 * Triggers a background or blocking reindex of the workspace.
 * Does NOT include freshness metadata in its response (it changes the index state).
 */

import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { buildIndexState } from "../index-state.js";
import type { ToolDeps } from "./deps.js";
import { errorResponse } from "./deps.js";

/**
 * Cap blocking reindex waits BELOW the MCP client tool timeout (~60s) so we can
 * return structured diagnostics before the client aborts. waitForCompletion's
 * own default is 300s — far too long for a blocking tool call.
 */
const REINDEX_BLOCKING_TIMEOUT_MS = 45000;

export function registerReindexTools(server: McpServer, deps: ToolDeps): void {
	const { reindexer, completionDetector, logger } = deps;

	server.tool(
		"reindex",
		"Trigger a reindex of the workspace. Can be debounced (default) or forced immediately. Optionally block until complete.",
		{
			force: z
				.boolean()
				.default(false)
				.describe("Skip debounce and reindex immediately (default: false)"),
			blocking: z
				.boolean()
				.default(false)
				.describe(
					"Wait until reindex completes before returning (default: false)",
				),
		},
		async ({ force, blocking }) => {
			const startTime = Date.now();

			try {
				if (!reindexer) {
					return {
						content: [
							{
								type: "text" as const,
								text: JSON.stringify({
									status: "failed",
									message:
										"Reindexer not configured. The MCP server may not have been started with --watch mode.",
								}),
							},
						],
					};
				}

				// Check if already running (in-memory flag OR disk lock from any process)
				if (reindexer.isRunning()) {
					if (blocking && completionDetector) {
						logger.info("reindex: lock held, waiting for completion");
						const completed = await completionDetector.waitForCompletion(
							REINDEX_BLOCKING_TIMEOUT_MS,
						);
						if (completed) {
							return {
								content: [
									{
										type: "text" as const,
										text: JSON.stringify({
											status: "completed",
											durationMs: Date.now() - startTime,
											message: "Reindex completed (was already in progress)",
										}),
									},
								],
							};
						}
						// Timed out: return structured diagnostics instead of a bare
						// "timed out" string. status stays distinguishable ("timeout",
						// NOT spread from indexState.status — A7).
						const st = await buildIndexState(deps, startTime);
						return {
							content: [
								{
									type: "text" as const,
									text: JSON.stringify({
										status: "timeout",
										durationMs: Date.now() - startTime,
										message: `Reindex still running after ${
											REINDEX_BLOCKING_TIMEOUT_MS / 1000
										}s; returning diagnostics.`,
										indexing: st.indexing,
										index: st.index,
										canReturnCachedResults: st.canReturnCachedResults,
										recommendations: st.recommendations,
									}),
								},
							],
						};
					}

					// Enrich already_running with the structured indexing/index/recommendations
					// block. Keep the "already_running" discriminator (do NOT spread ...st
					// whole, which would clobber status with st.status — A7).
					const st = await buildIndexState(deps, startTime);
					return {
						content: [
							{
								type: "text" as const,
								text: JSON.stringify({
									status: "already_running",
									message: st.message,
									indexing: st.indexing,
									index: st.index,
									canReturnCachedResults: st.canReturnCachedResults,
									recommendations: st.recommendations,
								}),
							},
						],
					};
				}

				if (force) {
					await reindexer.forceReindex();
				} else {
					reindexer.scheduleReindex();
				}

				if (blocking && completionDetector) {
					logger.info("reindex: waiting for completion");
					const completed = await completionDetector.waitForCompletion(
						REINDEX_BLOCKING_TIMEOUT_MS,
					);
					if (completed) {
						return {
							content: [
								{
									type: "text" as const,
									text: JSON.stringify({
										status: "completed",
										durationMs: Date.now() - startTime,
										message: "Reindex completed successfully",
									}),
								},
							],
						};
					}
					// Timed out: structured diagnostics, distinguishable "timeout" status (A7).
					const st = await buildIndexState(deps, startTime);
					return {
						content: [
							{
								type: "text" as const,
								text: JSON.stringify({
									status: "timeout",
									durationMs: Date.now() - startTime,
									message: `Reindex still running after ${
										REINDEX_BLOCKING_TIMEOUT_MS / 1000
									}s; returning diagnostics.`,
									indexing: st.indexing,
									index: st.index,
									canReturnCachedResults: st.canReturnCachedResults,
									recommendations: st.recommendations,
								}),
							},
						],
					};
				}

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								status: "started",
								message: force
									? "Reindex started immediately."
									: "Reindex scheduled (debounced).",
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

/**
 * Rename Tool
 *
 * MCP tool for renaming symbols across the codebase.
 * Uses LSP textDocument/rename when available, falls back to text search.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { WorkspaceEditApplier } from "../../editor/workspace-edit.js";
import {
	LSP_METHODS,
	pathToUri,
	type WorkspaceEdit,
} from "../../lsp/protocol.js";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

export function registerRenameTools(server: McpServer, deps: ToolDeps): void {
	const { cache, stateManager, config, lspManager, editor } = deps;

	if (!editor) return;

	server.tool(
		"rename_symbol",
		"Rename a symbol across the codebase. Uses LSP textDocument/rename when available " +
			"for type-aware renaming. Falls back to text replacement with a warning.",
		{
			symbol: z.string().describe("Current symbol name"),
			newName: z.string().describe("New name for the symbol"),
			file: z
				.string()
				.optional()
				.describe("File containing the symbol (for LSP position-based rename)"),
			line: z.coerce
				.number()
				.int()
				.optional()
				.describe("Line number (1-indexed)"),
			column: z.coerce
				.number()
				.int()
				.optional()
				.describe("Column number (1-indexed)"),
			dryRun: z
				.boolean()
				.default(false)
				.describe("Preview changes without applying them"),
		},
		async ({ symbol: symbolName, newName, file, line, column, dryRun }) => {
			const startTime = Date.now();

			try {
				// Try LSP rename first
				if (lspManager && file && line !== undefined && column !== undefined) {
					const absPath = resolve(config.workspaceRoot, file);
					const lang = lspManager.detectServerLanguage(absPath);

					if (lang) {
						const client = await lspManager.getClient(lang);

						if (client) {
							const langId = lspManager.detectLanguageId(absPath) ?? lang;
							const content = readFileSync(absPath, "utf-8");
							client.openFile(absPath, langId, content);

							try {
								const wsEdit = await client.request<WorkspaceEdit | null>(
									LSP_METHODS.RENAME,
									{
										textDocument: { uri: pathToUri(absPath) },
										position: { line: line - 1, character: column - 1 },
										newName,
									},
								);

								if (wsEdit) {
									const applier = new WorkspaceEditApplier(
										config.workspaceRoot,
										editor.getHistory(),
									);

									const result = await applier.apply(wsEdit, { dryRun });

									return {
										content: [
											{
												type: "text" as const,
												text: JSON.stringify({
													renamed: symbolName,
													newName,
													method: "lsp",
													...result,
													...buildFreshness(stateManager, startTime),
												}),
											},
										],
									};
								}
							} catch {
								// Fall through to text-based rename
							}
						}
					}
				}

				// Fallback: text-based rename via AST index
				const { graphManager, tracker } = await cache.get();
				const found = graphManager.findSymbol(symbolName, {
					preferExported: true,
					fileHint: file,
				});

				if (!found) {
					throw new Error(`Symbol '${symbolName}' not found in index`);
				}

				// Get all callers to find reference locations
				const callers = graphManager.getCallers(found.id);
				const filesToEdit = new Set<string>();
				filesToEdit.add(found.filePath);
				for (const c of callers) {
					filesToEdit.add(c.filePath);
				}

				if (dryRun) {
					return {
						content: [
							{
								type: "text" as const,
								text: JSON.stringify({
									renamed: symbolName,
									newName,
									method: "text-search",
									warning:
										"Text-based rename — may miss type-resolved references. Review changes carefully.",
									filesAffected: Array.from(filesToEdit),
									dryRun: true,
									...buildFreshness(stateManager, startTime),
								}),
							},
						],
					};
				}

				// Apply text replacements
				const changedFiles: string[] = [];
				const history = editor.getHistory();
				const sessionId = require("node:crypto").randomBytes(8).toString("hex");

				for (const relPath of filesToEdit) {
					const absPath = resolve(config.workspaceRoot, relPath);
					const content = readFileSync(absPath, "utf-8");

					// Word-boundary replacement to avoid partial matches
					const regex = new RegExp(`\\b${escapeRegex(symbolName)}\\b`, "g");
					const newContent = content.replace(regex, newName);

					if (newContent !== content) {
						await history.backup(sessionId, absPath, content);
						writeFileSync(absPath, newContent, "utf-8");
						changedFiles.push(relPath);
					}
				}

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								renamed: symbolName,
								newName,
								method: "text-search",
								warning: "Text-based rename — review changes carefully.",
								renamedFiles: changedFiles,
								totalEdits: changedFiles.length,
								sessionId,
								dryRun: false,
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

function escapeRegex(str: string): string {
	return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Search Pattern Tool
 *
 * Regex/literal pattern search across the codebase, complementing the
 * semantic `search` tool with precise text matching. Uses ripgrep (rg)
 * when available, falling back to grep.
 *
 * Addresses the issue where agents send 16+ semantic search_code calls
 * rephrasing the same query — NL search against code text is unreliable
 * for exact patterns.
 */

import { execFileSync } from "node:child_process";
import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { ToolDeps } from "./deps.js";
import { buildFreshness, errorResponse } from "./deps.js";

/** Check if a binary is available on PATH */
function hasCommand(cmd: string): boolean {
	try {
		execFileSync("which", [cmd], { stdio: "pipe" });
		return true;
	} catch {
		return false;
	}
}

const HAS_RG = hasCommand("rg");

export function registerSearchPatternTools(
	server: McpServer,
	deps: ToolDeps,
): void {
	const { stateManager, config } = deps;

	server.tool(
		"search_pattern",
		"Search for a regex or literal pattern across the codebase. Returns matching lines with file paths and line numbers. Complements semantic search with precise text matching.",
		{
			pattern: z
				.string()
				.min(1)
				.max(500)
				.describe(
					"Search pattern (regex by default, or literal if fixedString is true)",
				),
			fixedString: z
				.boolean()
				.default(false)
				.describe("Treat pattern as a literal string instead of regex"),
			fileGlob: z
				.string()
				.optional()
				.describe("Glob pattern to filter files (e.g. '*.ts', '**/*.py')"),
			caseSensitive: z
				.boolean()
				.default(true)
				.describe("Case-sensitive search (default: true)"),
			limit: z
				.number()
				.int()
				.min(1)
				.max(200)
				.default(50)
				.describe("Maximum number of matching lines to return (default: 50)"),
		},
		async ({ pattern, fixedString, fileGlob, caseSensitive, limit }) => {
			const startTime = Date.now();

			try {
				let stdout: string;

				if (HAS_RG) {
					// Use ripgrep
					const args = [
						"--no-heading",
						"--line-number",
						"--color=never",
						`--max-count=${limit}`,
					];
					if (fixedString) args.push("--fixed-strings");
					if (!caseSensitive) args.push("--ignore-case");
					if (fileGlob) args.push(`--glob=${fileGlob}`);
					args.push("--", pattern, ".");

					try {
						stdout = execFileSync("rg", args, {
							cwd: config.workspaceRoot,
							encoding: "utf-8",
							maxBuffer: 10 * 1024 * 1024,
							timeout: 30_000,
						});
					} catch (err: unknown) {
						// rg exits with code 1 when no matches found
						if (
							err &&
							typeof err === "object" &&
							"status" in err &&
							(err as { status: number }).status === 1
						) {
							stdout = "";
						} else {
							throw err;
						}
					}
				} else {
					// Fallback to grep
					const args = ["-rn", "--color=never"];
					if (fixedString) args.push("-F");
					if (!caseSensitive) args.push("-i");
					if (fileGlob) args.push(`--include=${fileGlob}`);
					args.push("--", pattern, ".");

					try {
						stdout = execFileSync("grep", args, {
							cwd: config.workspaceRoot,
							encoding: "utf-8",
							maxBuffer: 10 * 1024 * 1024,
							timeout: 30_000,
						});
					} catch (err: unknown) {
						// grep exits with code 1 when no matches found
						if (
							err &&
							typeof err === "object" &&
							"status" in err &&
							(err as { status: number }).status === 1
						) {
							stdout = "";
						} else {
							throw err;
						}
					}
				}

				// Parse output into structured results
				const lines = stdout.trim().split("\n").filter(Boolean);
				const matches = lines.slice(0, limit).map((line) => {
					// Format: ./path/to/file:lineNum:content
					const match = line.match(/^\.\/(.+?):(\d+):(.*)$/);
					if (match) {
						return {
							file: match[1],
							line: parseInt(match[2], 10),
							content: match[3],
						};
					}
					// Fallback for unexpected format
					return { file: "", line: 0, content: line };
				});

				return {
					content: [
						{
							type: "text" as const,
							text: JSON.stringify({
								matches,
								totalMatches: matches.length,
								truncated: lines.length > limit,
								engine: HAS_RG ? "ripgrep" : "grep",
								...buildFreshness(stateManager, startTime),
							}),
						},
					],
				};
			} catch (err) {
				return errorResponse(err);
			}
		},
	);
}

