/**
 * Output Router
 *
 * Central abstraction for all CLI output. Creates either:
 *   - AgentOutput  (plain key=value text, for --agent mode and non-TTY)
 *   - TuiOutput    (ANSI progress rendering, for interactive TTY)
 *
 * Command handlers use OutputRouter instead of inline `if (agentMode)` branches:
 *
 *   const output = createOutput(agentMode)
 *   await output.start()
 *   const progress = output.renderProgress()
 *   // ... indexer runs, calls progress.update(...)
 *   progress.finish()
 *   await output.stop()
 */

import { AgentOutput } from "./agent-output.js";
import { TuiOutput } from "./tui-output.js";

// ============================================================================
// Interfaces
// ============================================================================

/**
 * Handle returned by renderProgress(). Wraps the indexer callback API.
 */
export interface ProgressHandle {
	/**
	 * Called by the indexer on each progress event.
	 *
	 * @param completed  - Items completed so far
	 * @param total      - Total items to process
	 * @param detail     - Detail string (may include "[phase]" prefix)
	 * @param inProgress - Items currently in-flight
	 */
	update(
		completed: number,
		total: number,
		detail: string,
		inProgress?: number,
	): void;

	/** Called when indexing completes successfully. */
	finish(): void;

	/** Called to stop rendering without marking complete (e.g. on error). */
	stop(): void;
}

/**
 * Output router interface. One instance per command invocation.
 *
 * Lifecycle:
 *   1. createOutput(agentMode) → OutputRouter
 *   2. await output.start()   → initialise renderer (no-op for agent mode)
 *   3. ... use output ...
 *   4. await output.stop()    → tear down renderer (no-op for agent mode)
 */
export interface OutputRouter {
	/** Initialise the renderer. Must be called before any other method. */
	start(): Promise<void>;

	/** Tear down the renderer. Call when the command is done. */
	stop(): Promise<void>;

	/**
	 * Return a ProgressHandle for the current indexing operation.
	 * In TUI mode this starts rendering an animated progress bar.
	 * In agent mode this is silent during updates; agent summary is written on finish().
	 */
	renderProgress(): ProgressHandle;

	/** Write a plain text line to stdout. No-op in TUI mode. */
	text(line: string): void;

	/** Write an error line to stderr. */
	error(line: string): void;
}

// ============================================================================
// Factory
// ============================================================================

/**
 * Create the appropriate OutputRouter for the current environment.
 *
 * Selection logic:
 *   - agentMode=true  → AgentOutput (structured key=value, no TTY required)
 *   - TTY available   → TuiOutput (ANSI animated progress)
 *   - non-TTY         → AgentOutput (plain text fallback)
 */
export function createOutput(agentMode: boolean): OutputRouter {
	if (agentMode || !process.stdout.isTTY) {
		return new AgentOutput();
	}
	return new TuiOutput();
}

// Re-export concrete classes for consumers that need them explicitly
export { AgentOutput } from "./agent-output.js";
export type { PhaseState, ProgressSnapshot } from "./progress-store.js";
export { ProgressStore } from "./progress-store.js";
export { TuiOutput } from "./tui-output.js";

/**
 * ProgressStore: bridges imperative indexer callbacks to React state.
 *
 * The indexer calls onProgress at a high rate. Rather than updating React state
 * on every callback (causing excessive re-renders), the store accumulates updates
 * as mutable state. React components poll via getSnapshot() at 100ms intervals.
 *
 * Phase parsing logic extracted from createProgressRenderer() in cli.ts.
 */

// ============================================================================
// Types
// ============================================================================

export interface PhaseState {
	name: string;
	completed: number;
	total: number;
	inProgress: number;
	detail: string;
	isComplete: boolean;
	startTime: number;
	/** Frozen elapsed time (ms) captured when phase completes */
	finalDuration?: number;
}

export interface ProgressSnapshot {
	phases: PhaseState[];
	phaseOrder: string[];
	finished: boolean;
	globalStartTime: number;
}

// ============================================================================
// ProgressStore
// ============================================================================

/**
 * Mutable store for indexing progress state.
 *
 * Phase names are parsed from the detail string using the bracket convention:
 *   "[parsing] src/foo.ts"  → phase "parsing", detail "src/foo.ts"
 *   "[embedding] batch 1/4" → phase "embedding", detail "batch 1/4"
 *   "some detail"           → phase "processing", detail "some detail"
 *
 * A phase is marked complete when:
 *   completed >= total && total > 0 && inProgress === 0
 *
 * Once complete, elapsed time is frozen in finalDuration so React can display
 * the stable duration even after subsequent renders.
 */
export class ProgressStore {
	private phases = new Map<string, PhaseState>();
	private phaseOrder: string[] = [];
	private finished = false;
	private globalStartTime = Date.now();

	/**
	 * Update progress state from an indexer callback.
	 *
	 * @param completed - Items completed so far
	 * @param total     - Total items to process
	 * @param detail    - Detail string, optionally prefixed with "[phase-name]"
	 * @param inProgress - Items currently in-flight (for animation)
	 */
	update(
		completed: number,
		total: number,
		detail: string,
		inProgress = 0,
	): void {
		// Parse phase name from detail: "[phase name] rest of detail"
		const phaseMatch = detail.match(/^\[([^\]]+)\]/);
		const phaseName = phaseMatch ? phaseMatch[1] : "processing";
		const cleanDetail = detail.replace(/^\[[^\]]+\]\s*/, "");

		// Create phase on first appearance
		if (!this.phases.has(phaseName)) {
			this.phases.set(phaseName, {
				name: phaseName,
				completed: 0,
				total: 0,
				inProgress: 0,
				detail: "",
				startTime: Date.now(),
				isComplete: false,
			});
			this.phaseOrder.push(phaseName);
		}

		const phase = this.phases.get(phaseName)!;

		// Only update if not already complete (never regress a completed phase)
		if (!phase.isComplete) {
			phase.completed = completed;
			phase.total = total;
			phase.inProgress = inProgress;
			phase.detail = cleanDetail;

			// Mark complete when 100% and no in-progress items remain
			if (completed >= total && total > 0 && inProgress === 0) {
				phase.isComplete = true;
				// Freeze elapsed time so React can display it after completion
				phase.finalDuration = Date.now() - phase.startTime;
			}
		}
	}

	/**
	 * Mark indexing as finished. Forces all phases to complete state.
	 * Called after the indexer resolves.
	 */
	finish(): void {
		for (const phase of this.phases.values()) {
			if (!phase.isComplete) {
				phase.finalDuration = Date.now() - phase.startTime;
			}
			phase.isComplete = true;
			phase.completed = phase.total;
			phase.inProgress = 0;
		}
		this.finished = true;
	}

	/**
	 * Returns an immutable snapshot of current state.
	 * React components call this to read state without subscribing to the store.
	 *
	 * Returns new array/object references on each call so React's shallow
	 * comparison detects changes during setInterval polling.
	 */
	getSnapshot(): ProgressSnapshot {
		return {
			// Spread each PhaseState to create new object references
			phases: this.phaseOrder.map((name) => ({ ...this.phases.get(name)! })),
			phaseOrder: [...this.phaseOrder],
			finished: this.finished,
			globalStartTime: this.globalStartTime,
		};
	}

	/** Read the global start time (ms since epoch). */
	getGlobalStartTime(): number {
		return this.globalStartTime;
	}
}

/**
 * TuiOutput: OutputRouter implementation for interactive TTY mode.
 *
 * Uses OpenTUI React (createCliRenderer + createRoot) to render an animated
 * IndexProgress component. The ProgressStore bridges the imperative indexer
 * callbacks to React state polled at 100ms intervals.
 *
 * Lifecycle:
 *   1. start()           → await createCliRenderer(...), store renderer
 *   2. renderProgress()  → create ProgressStore, mount IndexProgress via React root
 *                          return ProgressHandle delegating to store
 *   3. stop()            → unmount root, renderer.destroy(), remove signal handlers
 *
 * text() and error() delegate to console.log/console.error for non-progress
 * output like headers that appear before the progress bar.
 */

import { createCliRenderer } from "@opentui/core";
import { createRoot } from "@opentui/react";
import { IndexProgress } from "../tui/components/command/IndexProgress.js";
import type { OutputRouter, ProgressHandle } from "./index.js";
// CliRenderer type inferred from createCliRenderer return
import { ProgressStore } from "./progress-store.js";

// ============================================================================
// TuiOutput
// ============================================================================

/**
 * OutputRouter for interactive TTY mode.
 *
 * Renders IndexProgress via OpenTUI React. The renderer is created in start()
 * with useAlternateScreen: false so progress output stays visible after stop().
 */
export class TuiOutput implements OutputRouter {
	private renderer: Awaited<ReturnType<typeof createCliRenderer>> | null = null;
	private root: ReturnType<typeof createRoot> | null = null;
	private sigintHandler: (() => void) | null = null;

	async start(): Promise<void> {
		this.renderer = await createCliRenderer({
			screenMode: "main-screen",
			exitOnCtrlC: false,
			useMouse: false,
		});

		// Register SIGINT handler so Ctrl+C cleans up the renderer properly.
		this.sigintHandler = () => {
			void this.stop().then(() => {
				process.exit(0);
			});
		};
		process.on("SIGINT", this.sigintHandler);
	}

	async stop(): Promise<void> {
		// Remove SIGINT handler
		if (this.sigintHandler) {
			process.removeListener("SIGINT", this.sigintHandler);
			this.sigintHandler = null;
		}

		// Unmount React root
		if (this.root) {
			this.root.unmount();
			this.root = null;
		}

		// Destroy the terminal renderer
		if (this.renderer) {
			this.renderer.destroy();
			this.renderer = null;
		}
	}

	renderProgress(): ProgressHandle {
		if (!this.renderer) {
			throw new Error(
				"TuiOutput.start() must be called before renderProgress()",
			);
		}

		const renderer = this.renderer;
		const store = new ProgressStore();

		// Capture stop reference for the finish callback
		const self = this;

		// Mount IndexProgress component
		const root = createRoot(renderer);
		this.root = root;

		root.render(
			<IndexProgress
				store={store}
				globalStartTime={store.getGlobalStartTime()}
			/>,
		);

		return {
			update(
				completed: number,
				total: number,
				detail: string,
				inProgress?: number,
			): void {
				store.update(completed, total, detail, inProgress);
			},

			finish(): void {
				store.finish();
				// Wait 200ms for the final render to flush, then stop the renderer
				setTimeout(() => {
					void self.stop();
				}, 200);
			},

			stop(): void {
				void self.stop();
			},
		};
	}

	text(line: string): void {
		// Non-progress output (headers, summaries) goes directly to stdout.
		// console.log writes before the TUI renderer takes over the screen.
		console.log(line);
	}

	error(line: string): void {
		console.error(line);
	}
}

/**
 * Markdown Format
 *
 * Produces a Markdown document with:
 * - H1 title
 * - H2 directory structure section (fenced code block)
 * - H3 per-file sections with fenced code blocks + language detection
 */

import type { FileEntry, PackMeta } from "../types.js";

// ============================================================================
// Functions
// ============================================================================

/**
 * Format pack output as Markdown.
 *
 * Structure:
 * ```markdown
 * # Codebase: {name}
 *
 * Generated by mnemex pack on {date}. Files: {N}. Tokens (est.): {N}.
 *
 * ## Directory Structure
 *
 * ```
 * {tree}
 * ```
 *
 * ### File: src/cli.ts
 *
 * ```typescript
 * {content}
 * ```
 * ```
 *
 * @param entries - File entries to include
 * @param tree - Pre-built directory tree string
 * @param meta - Pack metadata
 * @returns Formatted Markdown string
 */
export function formatMarkdown(
	entries: FileEntry[],
	tree: string,
	meta: PackMeta,
): string {
	const textFiles = entries.filter((e) => !e.isBinary);
	const parts: string[] = [];

	// H1 title
	parts.push(`# Codebase: ${meta.projectName}`);
	parts.push("");
	parts.push(
		`Generated by mnemex pack on ${meta.generatedAt}. Files: ${meta.fileCount}. Tokens (est.): ${meta.estimatedTokens}.`,
	);
	parts.push("");

	// Directory structure
	parts.push("## Directory Structure");
	parts.push("");
	parts.push("```");
	parts.push(tree);
	parts.push("```");
	parts.push("");

	// Per-file sections
	for (const entry of textFiles) {
		parts.push(`### File: ${entry.relativePath}`);
		parts.push("");

		const lang = entry.language ?? "";
		const content = entry.content ?? "";

		// Use a fence longer than any backtick sequence in the content
		// to avoid breaking the code fence structure
		const backtickRuns = content.match(/`{3,}/g) ?? [];
		const maxBackticks = Math.max(3, ...backtickRuns.map((m) => m.length));
		const fence = "`".repeat(maxBackticks + 1);

		parts.push(`${fence}${lang}`);
		parts.push(content);
		parts.push(fence);
		parts.push("");
	}

	return parts.join("\n");
}

/**
 * Plain Text Format
 *
 * Produces a plain text document with:
 * - 64-char = section separators
 * - "File: path" headers
 * - File content
 * - "End of Codebase" sentinel at the end
 */

import type { FileEntry, PackMeta } from "../types.js";

// ============================================================================
// Constants
// ============================================================================

/** Section separator: 64 equals signs */
const SEPARATOR = "=".repeat(64);

// ============================================================================
// Functions
// ============================================================================

/**
 * Format pack output as plain text.
 *
 * Structure:
 * ```
 * ================================================================
 * mnemex pack - Codebase: {name}
 * Generated: {date} | Files: {N} | Tokens (est.): {N}
 * ================================================================
 *
 * Directory Structure:
 * ----------------------------------------------------------------
 * {tree}
 *
 * ================================================================
 * File: src/cli.ts
 * ================================================================
 * {content}
 *
 * ================================================================
 * End of Codebase
 * ================================================================
 * ```
 *
 * @param entries - File entries to include
 * @param tree - Pre-built directory tree string
 * @param meta - Pack metadata
 * @returns Formatted plain text string
 */
export function formatPlain(
	entries: FileEntry[],
	tree: string,
	meta: PackMeta,
): string {
	const textFiles = entries.filter((e) => !e.isBinary);
	const parts: string[] = [];

	// Header
	parts.push(SEPARATOR);
	parts.push(`mnemex pack - Codebase: ${meta.projectName}`);
	parts.push(
		`Generated: ${meta.generatedAt} | Files: ${meta.fileCount} | Tokens (est.): ${meta.estimatedTokens}`,
	);
	parts.push(SEPARATOR);
	parts.push("");

	// Directory structure
	parts.push("Directory Structure:");
	parts.push("-".repeat(64));
	parts.push(tree);
	parts.push("");

	// Per-file sections
	for (const entry of textFiles) {
		parts.push(SEPARATOR);
		parts.push(`File: ${entry.relativePath}`);
		parts.push(SEPARATOR);
		parts.push(entry.content ?? "");
		parts.push("");
	}

	// End sentinel
	parts.push(SEPARATOR);
	parts.push("End of Codebase");
	parts.push(SEPARATOR);

	return parts.join("\n");
}

/**
 * XML Format
 *
 * Produces repomix-compatible XML output.
 * Each file is wrapped in <file path="..."> tags.
 */

import type { FileEntry, PackMeta } from "../types.js";

// ============================================================================
// Functions
// ============================================================================

/**
 * Escape XML special characters in content.
 * Avoids breaking the XML structure when file content contains <, >, &, etc.
 */
function escapeXml(text: string): string {
	return text
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;");
}

/**
 * Format pack output as repomix-compatible XML.
 *
 * Structure:
 * ```
 * This file is a merged representation of the entire codebase...
 *
 * <file_summary>...</file_summary>
 *
 * <directory_structure>
 * {tree}
 * </directory_structure>
 *
 * <files>
 * <file path="...">
 * {content}
 * </file>
 * </files>
 * ```
 *
 * @param entries - File entries to include
 * @param tree - Pre-built directory tree string
 * @param meta - Pack metadata
 * @returns Formatted XML string
 */
export function formatXml(
	entries: FileEntry[],
	tree: string,
	meta: PackMeta,
): string {
	const textFiles = entries.filter((e) => !e.isBinary);
	const parts: string[] = [];

	// Preamble (repomix-compatible)
	parts.push(
		"This file is a merged representation of the entire codebase, combined into a single document by mnemex pack.",
	);
	parts.push("");

	// File summary
	parts.push("<file_summary>");
	parts.push(
		"  <purpose>This file contains a packed representation of the codebase for AI analysis.</purpose>",
	);
	parts.push(
		"  <file_format>Each file is wrapped in file tags with path attribute.</file_format>",
	);
	parts.push(
		"  <usage_guidelines>Use this for code review, analysis, or understanding the codebase.</usage_guidelines>",
	);
	parts.push(
		`  <notes>Generated by mnemex pack. Files: ${meta.fileCount}. Tokens (est.): ${meta.estimatedTokens}.</notes>`,
	);
	parts.push("</file_summary>");
	parts.push("");

	// Directory structure
	parts.push("<directory_structure>");
	parts.push(tree);
	parts.push("</directory_structure>");
	parts.push("");

	// Files
	parts.push("<files>");
	for (const entry of textFiles) {
		parts.push(`<file path="${escapeXml(entry.relativePath)}">`);
		parts.push(escapeXml(entry.content ?? ""));
		parts.push("</file>");
	}
	parts.push("</files>");

	return parts.join("\n");
}

/**
 * Pack Command Pipeline
 *
 * Orchestrates the pack operation:
 * 1. Load exclude patterns (config + gitignore)
 * 2. Walk files
 * 3. Read content
 * 4. Detect binary files
 * 5. Annotate token estimates
 * 6. Build directory tree
 * 7. Format output
 * 8. Write atomically (write .tmp, rename) or stdout
 */

import {
	existsSync,
	mkdirSync,
	readFileSync,
	renameSync,
	unlinkSync,
	writeFileSync,
} from "node:fs";
import { basename, dirname, extname, resolve } from "node:path";
import { getExcludePatterns } from "../config.js";
import {
	extensionToLanguage,
	isBinaryFile,
} from "../shared/binary-detector.js";
import { walkFiles } from "../shared/file-walker.js";
import { formatMarkdown } from "./formats/markdown.js";
import { formatPlain } from "./formats/plain.js";
import { formatXml } from "./formats/xml.js";
import { annotateTokenEstimates, buildTokenReport } from "./token-counter.js";
import { buildTree } from "./tree-builder.js";
import type { FileEntry, PackMeta, PackOptions, PackResult } from "./types.js";

// ============================================================================
// Constants
// ============================================================================

/** Default maximum file size to include (1 MB) */
const DEFAULT_MAX_FILE_SIZE = 1024 * 1024;

/** mnemex version - read from package.json at call time */
let _version: string | undefined;

function getVersion(): string {
	if (_version) return _version;
	try {
		// Walk up from this file's location to find package.json
		// In source: src/pack/index.ts → ../../package.json
		// In bundle: dist/index.js → ../package.json
		const base = dirname(new URL(import.meta.url).pathname);
		const pkgPath = existsSync(resolve(base, "../package.json"))
			? resolve(base, "../package.json")
			: resolve(base, "../../package.json");
		const pkg = JSON.parse(readFileSync(pkgPath, "utf-8")) as {
			version: string;
		};
		_version = pkg.version;
	} catch {
		_version = "0.0.0";
	}
	return _version;
}

// ============================================================================
// Progress Callback
// ============================================================================

/** Progress callback type */
export type ProgressCallback = (
	phase: string,
	current: number,
	total: number,
) => void;

// ============================================================================
// Main Pipeline
// ============================================================================

/**
 * Run the pack command pipeline.
 *
 * @param options - Pack options
 * @param onProgress - Optional progress callback
 * @returns PackResult with statistics about the operation
 */
export async function packCommand(
	options: PackOptions,
	onProgress?: ProgressCallback,
): Promise<PackResult> {
	const startTime = Date.now();

	const projectPath = resolve(options.projectPath);
	const format = options.format ?? "xml";
	const maxFileSize = options.maxFileSize ?? DEFAULT_MAX_FILE_SIZE;

	// ─── Phase 1: Load exclude patterns ─────────────────────────────────────
	onProgress?.("load-patterns", 0, 1);

	// Get default + config + gitignore patterns (honour --no-gitignore)
	const baseExcludePatterns = getExcludePatterns(
		projectPath,
		options.useGitignore,
	);

	// Merge with any extra patterns from options
	const allExcludePatterns = [
		...baseExcludePatterns,
		...options.excludePatterns,
	];

	onProgress?.("load-patterns", 1, 1);

	// ─── Phase 2: Walk files ─────────────────────────────────────────────────
	onProgress?.("walk-files", 0, 1);

	const walkEntries = walkFiles(projectPath, {
		excludePatterns: allExcludePatterns,
		includePatterns: options.includePatterns,
		// No onlyExtensions — pack includes all text files
	});

	onProgress?.("walk-files", walkEntries.length, walkEntries.length);

	// ─── Phase 3: Read content + detect binary + filter by size ─────────────
	const fileEntries: FileEntry[] = [];
	let binarySkipped = 0;
	let sizeSkipped = 0;

	const totalFiles = walkEntries.length;
	let processed = 0;

	for (const walkEntry of walkEntries) {
		onProgress?.("read-files", processed, totalFiles);
		processed++;

		const ext = extname(walkEntry.path).toLowerCase() || "";

		// Skip files that exceed the max size
		if (walkEntry.size > maxFileSize) {
			sizeSkipped++;
			continue;
		}

		const binary = isBinaryFile(walkEntry.path, ext);

		if (binary) {
			binarySkipped++;
			// Include binary entries in the tree but not in content
			fileEntries.push({
				path: walkEntry.path,
				relativePath: walkEntry.relativePath,
				size: walkEntry.size,
				ext,
				isBinary: true,
			});
			continue;
		}

		// Read text content
		let content: string;
		try {
			content = readFileSync(walkEntry.path, "utf-8");
		} catch {
			// Skip unreadable files
			binarySkipped++;
			continue;
		}

		const language = extensionToLanguage(ext);

		fileEntries.push({
			path: walkEntry.path,
			relativePath: walkEntry.relativePath,
			size: walkEntry.size,
			ext,
			isBinary: false,
			content,
			language,
		});
	}

	onProgress?.("read-files", totalFiles, totalFiles);

	// ─── Phase 4: Annotate token estimates ───────────────────────────────────
	onProgress?.("count-tokens", 0, 1);
	annotateTokenEstimates(fileEntries);
	onProgress?.("count-tokens", 1, 1);

	// ─── Phase 5: Build directory tree ───────────────────────────────────────
	onProgress?.("build-tree", 0, 1);
	const tree = buildTree(fileEntries);
	onProgress?.("build-tree", 1, 1);

	// ─── Phase 6: Build token report ─────────────────────────────────────────
	const tokenReport = buildTokenReport(fileEntries, tree);

	// ─── Phase 7: Format output ───────────────────────────────────────────────
	onProgress?.("format", 0, 1);

	const meta: PackMeta = {
		projectName: basename(projectPath),
		projectPath,
		generatedAt: new Date().toISOString(),
		version: getVersion(),
		fileCount: fileEntries.filter((e) => !e.isBinary).length,
		totalBytes: fileEntries.reduce((sum, e) => sum + e.size, 0),
		estimatedTokens: tokenReport.total,
		format,
	};

	let output: string;
	switch (format) {
		case "xml":
			output = formatXml(fileEntries, tree, meta);
			break;
		case "markdown":
			output = formatMarkdown(fileEntries, tree, meta);
			break;
		case "plain":
			output = formatPlain(fileEntries, tree, meta);
			break;
		default:
			output = formatXml(fileEntries, tree, meta);
	}

	onProgress?.("format", 1, 1);

	// ─── Phase 8: Write output ───────────────────────────────────────────────
	onProgress?.("write", 0, 1);

	if (options.stdout) {
		process.stdout.write(output);
		if (!output.endsWith("\n")) {
			process.stdout.write("\n");
		}
	} else if (options.outputPath) {
		const outputPath = resolve(options.outputPath);

		// Ensure output directory exists
		const outputDir = dirname(outputPath);
		if (!existsSync(outputDir)) {
			mkdirSync(outputDir, { recursive: true });
		}

		// Atomic write: write to .tmp then rename; clean up on error
		const tmpPath = `${outputPath}.tmp`;
		try {
			writeFileSync(tmpPath, output, "utf-8");
			renameSync(tmpPath, outputPath);
		} catch (err) {
			try {
				unlinkSync(tmpPath);
			} catch {
				// ignore cleanup errors
			}
			throw err;
		}
	}

	onProgress?.("write", 1, 1);

	const durationMs = Date.now() - startTime;

	return {
		outputPath: options.stdout ? undefined : options.outputPath,
		fileCount: meta.fileCount,
		binarySkipped,
		sizeSkipped,
		totalBytes: meta.totalBytes,
		estimatedTokens: tokenReport.total,
		durationMs,
		tokenReport: options.showTokens ? tokenReport : undefined,
	};
}

/**
 * Token Counter
 *
 * Estimates token counts for pack output using a simple chars/4 heuristic.
 * This is a fast approximation suitable for rough sizing estimates.
 */

import type { FileEntry, TokenReport } from "./types.js";

// ============================================================================
// Constants
// ============================================================================

/**
 * Approximate number of characters per token.
 * GPT-4 / Claude models average ~4 chars per token for English/code.
 */
const CHARS_PER_TOKEN = 4;

// ============================================================================
// Functions
// ============================================================================

/**
 * Estimate the number of tokens in a string using chars/4 heuristic.
 *
 * @param text - Text to estimate tokens for
 * @returns Estimated token count
 */
export function estimateTokens(text: string): number {
	return Math.ceil(text.length / CHARS_PER_TOKEN);
}

/**
 * Annotate file entries with estimated token counts.
 * Modifies entries in place, setting the `estimatedTokens` field.
 *
 * @param entries - File entries to annotate (binary entries get 0 tokens)
 */
export function annotateTokenEstimates(entries: FileEntry[]): void {
	for (const entry of entries) {
		if (entry.isBinary || !entry.content) {
			entry.estimatedTokens = 0;
		} else {
			entry.estimatedTokens = estimateTokens(entry.content);
		}
	}
}

/**
 * Build a token report from annotated file entries and structure text.
 *
 * @param entries - File entries (must have estimatedTokens set)
 * @param structureText - The tree/header text (not file content)
 * @returns Token report with per-file breakdown
 */
export function buildTokenReport(
	entries: FileEntry[],
	structureText: string,
): TokenReport {
	const structureTokens = estimateTokens(structureText);

	let contentTokens = 0;
	const byFile: Array<{ relativePath: string; tokens: number }> = [];

	for (const entry of entries) {
		const tokens = entry.estimatedTokens ?? 0;
		contentTokens += tokens;
		if (!entry.isBinary) {
			byFile.push({ relativePath: entry.relativePath, tokens });
		}
	}

	// Sort by token count descending
	byFile.sort((a, b) => b.tokens - a.tokens);

	return {
		total: structureTokens + contentTokens,
		contentTokens,
		structureTokens,
		byFile,
	};
}

/**
 * Tree Builder
 *
 * Builds an ASCII directory tree from a list of file entries.
 * Directories are sorted before files. Binary files get a [binary] suffix.
 */

import type { FileEntry } from "./types.js";

// ============================================================================
// Types
// ============================================================================

/** Internal tree node */
interface TreeNode {
	name: string;
	isDirectory: boolean;
	isBinary: boolean;
	children: Map<string, TreeNode>;
}

// ============================================================================
// Functions
// ============================================================================

/**
 * Build a tree node structure from a list of file entries.
 */
function buildTreeNodes(entries: FileEntry[]): Map<string, TreeNode> {
	const root = new Map<string, TreeNode>();

	for (const entry of entries) {
		const parts = entry.relativePath.split("/");
		let current = root;

		// Create directory nodes for each path segment
		for (let i = 0; i < parts.length - 1; i++) {
			const part = parts[i];
			if (!current.has(part)) {
				current.set(part, {
					name: part,
					isDirectory: true,
					isBinary: false,
					children: new Map(),
				});
			}
			const node = current.get(part)!;
			current = node.children;
		}

		// Create the file node
		const fileName = parts[parts.length - 1];
		current.set(fileName, {
			name: fileName,
			isDirectory: false,
			isBinary: entry.isBinary,
			children: new Map(),
		});
	}

	return root;
}

/**
 * Render a tree node and its children to lines.
 * Directories come before files (sorted alphabetically within each group).
 */
function renderNode(
	nodes: Map<string, TreeNode>,
	prefix: string,
	lines: string[],
): void {
	// Sort: directories first, then files, each group alphabetically
	const sorted = Array.from(nodes.values()).sort((a, b) => {
		if (a.isDirectory !== b.isDirectory) {
			return a.isDirectory ? -1 : 1;
		}
		return a.name.localeCompare(b.name);
	});

	for (let i = 0; i < sorted.length; i++) {
		const node = sorted[i];
		const isLast = i === sorted.length - 1;
		const connector = isLast ? "└── " : "├── ";
		const childPrefix = isLast ? "    " : "│   ";

		let label = node.name;
		if (node.isDirectory) {
			label += "/";
		} else if (node.isBinary) {
			label += " [binary]";
		}

		lines.push(`${prefix}${connector}${label}`);

		if (node.isDirectory && node.children.size > 0) {
			renderNode(node.children, prefix + childPrefix, lines);
		}
	}
}

/**
 * Build an ASCII directory tree from a list of file entries.
 *
 * Output format:
 * ```
 * ├── src/
 * │   ├── cli.ts
 * │   └── types.ts
 * └── package.json
 * ```
 *
 * @param entries - List of file entries to include in the tree
 * @returns Multi-line string representing the directory tree
 */
export function buildTree(entries: FileEntry[]): string {
	const nodes = buildTreeNodes(entries);
	const lines: string[] = [];
	renderNode(nodes, "", lines);
	return lines.join("\n");
}

