/**
 * Location Backend
 *
 * Glob-matches indexed files to find results by path pattern.
 * Activated for: location
 */

import type { IFileTracker } from "../../core/tracker.js";
import type { QueryClassification } from "../../types.js";
import type {
	BackendResult,
	ISearchBackend,
	SearchOptions,
} from "../pipeline/types.js";

export class LocationBackend implements ISearchBackend {
	readonly name = "location" as const;

	constructor(private tracker: IFileTracker) {}

	async search(
		query: string,
		intent: QueryClassification,
		options: SearchOptions,
		signal: AbortSignal,
	): Promise<BackendResult[]> {
		if (signal.aborted) return [];

		const limit = options.limit ?? 10;

		// Build pattern from: options.filePattern, extracted entities, or the query itself
		const pattern = buildPattern(
			options.filePattern,
			intent.extractedEntities,
			query,
		);
		if (!pattern) return [];

		// Get all indexed files
		const allFiles = this.tracker.getAllFiles();
		if (signal.aborted) return [];

		// Filter by pattern
		const regexPat = pattern
			.replace(/[.+^${}()|[\]\\]/g, "\\$&") // Escape special regex chars (except * and ?)
			.replace(/\\\*/g, "*") // Un-escape * for further processing
			.replace(/\*\*/g, ".*")
			.replace(/\*/g, "[^/]*")
			.replace(/\?/g, ".");

		let regex: RegExp;
		try {
			regex = new RegExp(regexPat, "i");
		} catch {
			return [];
		}

		const matched = allFiles.filter((f) => regex.test(f.path));

		// Sort by path length (shorter = more specific match)
		matched.sort((a, b) => a.path.length - b.path.length);

		const backendName = this.name;
		return matched.slice(0, limit).map((f, idx) => ({
			file: f.path,
			startLine: 1,
			snippet: f.path,
			// Score based on position in sorted list
			score: 1 - idx / Math.max(matched.length, 1),
			backend: backendName,
		}));
	}
}

/**
 * Build a glob pattern from available sources.
 */
function buildPattern(
	filePattern: string | undefined,
	extractedEntities: string[],
	query: string,
): string | null {
	if (filePattern) return filePattern;

	// Look for path-like entities
	for (const entity of extractedEntities) {
		if (entity.includes("/") || entity.includes(".")) {
			return `*${entity}*`;
		}
	}

	// Try to extract path fragment from query
	const pathMatch = query.match(/[\w/.-]+\.(ts|js|py|go|rs|java|cpp|c|h)\b/);
	if (pathMatch) return `*${pathMatch[0]}*`;

	// Use the query as a folder/name fragment
	const words = query
		.split(/\s+/)
		.filter(
			(w) => w.length > 2 && !/^(in|the|for|of|at|under|inside)$/i.test(w),
		);
	if (words.length > 0) {
		return `*${words[0]}*`;
	}

	return null;
}

/**
 * LSP Backend
 *
 * Uses the language server to find exact symbol definitions.
 * Sets isDefinitive=true for high-confidence results.
 * Activated for: symbol_lookup
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import type { ReferenceGraphManager } from "../../core/reference-graph.js";
import type { LspManager } from "../../lsp/manager.js";
import {
	type Location,
	LSP_METHODS,
	pathToUri,
	uriToPath,
} from "../../lsp/protocol.js";
import type { QueryClassification } from "../../types.js";
import type {
	BackendResult,
	ISearchBackend,
	SearchOptions,
} from "../pipeline/types.js";
import { readSymbolBody } from "./utils/read-body.js";

export class LspBackend implements ISearchBackend {
	readonly name = "lsp" as const;

	constructor(
		private lspManager: LspManager,
		private graphManager: ReferenceGraphManager,
		private workspaceRoot: string,
	) {}

	async search(
		query: string,
		intent: QueryClassification,
		_options: SearchOptions,
		signal: AbortSignal,
	): Promise<BackendResult[]> {
		if (signal.aborted) return [];

		// Get candidate symbol names from extracted entities or query
		const names =
			intent.extractedEntities.length > 0 ? intent.extractedEntities : [query];

		for (const name of names) {
			if (signal.aborted) return [];

			// Find a starting position using graph manager
			const found = this.graphManager.findSymbol(name, {
				preferExported: true,
			});
			if (!found) continue;

			const absPath = resolve(this.workspaceRoot, found.filePath);
			const lang = this.lspManager.detectServerLanguage(absPath);
			if (!lang) continue;

			try {
				const client = await this.lspManager.getClient(lang);
				if (!client || signal.aborted) continue;

				// Open the file in LSP
				const langId = this.lspManager.detectLanguageId(absPath) ?? lang;
				const content = readFileSync(absPath, "utf-8");
				client.openFile(absPath, langId, content);

				if (signal.aborted) return [];

				// Issue textDocument/definition request
				// Use a Promise.race so we respect AbortSignal
				const lspPromise = client.request<Location | Location[] | null>(
					LSP_METHODS.DEFINITION,
					{
						textDocument: { uri: pathToUri(absPath) },
						// Use the symbol's known position (0-indexed for LSP)
						position: {
							line: found.startLine - 1,
							character: 0,
						},
					},
				);

				const abortPromise = new Promise<never>((_, reject) => {
					const onAbort = () => reject(new Error("AbortSignal fired"));
					if (signal.aborted) {
						reject(new Error("AbortSignal fired"));
					} else {
						signal.addEventListener("abort", onAbort, { once: true });
					}
				});

				let lspResult: Location | Location[] | null;
				try {
					lspResult = await Promise.race([lspPromise, abortPromise]);
				} catch {
					return [];
				}

				if (signal.aborted) return [];

				const loc = Array.isArray(lspResult) ? lspResult[0] : lspResult;
				if (!loc?.uri) continue;

				const defPath = uriToPath(loc.uri);
				const relPath = defPath.startsWith(`${this.workspaceRoot}/`)
					? defPath.slice(this.workspaceRoot.length + 1)
					: defPath;

				const defStartLine = loc.range.start.line + 1;
				const defEndLine = loc.range.end.line + 1;

				// Read body from disk at the LSP-resolved location
				const bodyResult = readSymbolBody(
					this.workspaceRoot,
					relPath,
					defStartLine,
					defEndLine,
				);

				const snippet = bodyResult.body
					? bodyResult.body.slice(0, 800)
					: (found.signature ?? found.name).slice(0, 800);

				const result: BackendResult = {
					file: relPath,
					startLine: defStartLine,
					endLine: defEndLine,
					symbol: found.name,
					body: bodyResult.body ?? undefined,
					snippet,
					score: 1.0,
					backend: this.name,
					isDefinitive: true,
				};

				return [result];
			} catch {}
		}

		return [];
	}
}

/**
 * Semantic Backend
 *
 * Wraps the existing Indexer.search() (vector + BM25 hybrid) call.
 * Activated for: semantic, similarity, location
 */

import type { Indexer } from "../../core/indexer.js";
import type { QueryClassification } from "../../types.js";
import type {
	BackendName,
	BackendResult,
	ISearchBackend,
	SearchOptions,
} from "../pipeline/types.js";

export class SemanticBackend implements ISearchBackend {
	readonly name: BackendName = "semantic";

	constructor(private createIndexer: () => Indexer) {}

	async search(
		query: string,
		_intent: QueryClassification,
		options: SearchOptions,
		signal: AbortSignal,
	): Promise<BackendResult[]> {
		if (signal.aborted) return [];

		const limit = options.limit ?? 10;
		const indexer = this.createIndexer();
		const backendName = this.name;

		try {
			const searchResults = await indexer.search(query, {
				limit,
				useCase: "search",
			});

			if (signal.aborted) return [];

			// Filter by filePattern if provided
			const filePattern = options.filePattern;
			const filtered = filePattern
				? searchResults.filter((r) => {
						const pat = filePattern
							.replace(/\*\*/g, ".*")
							.replace(/\*/g, "[^/]*");
						return new RegExp(pat).test(r.chunk.filePath);
					})
				: searchResults;

			if (filtered.length === 0) return [];

			// Normalize scores to [0, 1] by dividing by max score
			const maxScore = Math.max(...filtered.map((r) => r.score));
			const normalizer = maxScore > 0 ? maxScore : 1;

			return filtered
				.map((r): BackendResult | null => {
					if (r.documentType === "session_observation") {
						// Skip observation results — they have no file location
						return null;
					}
					return {
						file: r.chunk.filePath,
						startLine: r.chunk.startLine,
						endLine: r.chunk.endLine,
						symbol: r.chunk.name ?? undefined,
						snippet: r.chunk.content.slice(0, 800),
						score: r.score / normalizer,
						backend: backendName,
					};
				})
				.filter((r): r is BackendResult => r !== null);
		} finally {
			await indexer.close().catch(() => {});
		}
	}
}

/**
 * Symbol Graph Backend
 *
 * Searches the AST reference graph for symbol definitions.
 * Activated for: symbol_lookup, structural
 */

import type { ReferenceGraphManager } from "../../core/reference-graph.js";
import type { QueryClassification } from "../../types.js";
import type {
	BackendResult,
	ISearchBackend,
	SearchOptions,
} from "../pipeline/types.js";
import { readSymbolBody } from "./utils/read-body.js";

export class SymbolGraphBackend implements ISearchBackend {
	readonly name = "symbol-graph" as const;

	constructor(
		private graphManager: ReferenceGraphManager,
		private workspaceRoot: string,
	) {}

	async search(
		query: string,
		intent: QueryClassification,
		options: SearchOptions,
		signal: AbortSignal,
	): Promise<BackendResult[]> {
		if (signal.aborted) return [];

		const limit = options.limit ?? 10;
		const results: BackendResult[] = [];

		// Try to find the symbol by name (use extracted entities or query itself)
		const names =
			intent.extractedEntities.length > 0 ? intent.extractedEntities : [query];

		for (const name of names) {
			if (signal.aborted) break;

			const found = this.graphManager.findSymbol(name, {
				preferExported: true,
			});
			if (!found) continue;

			// Read body from disk
			const bodyResult = readSymbolBody(
				this.workspaceRoot,
				found.filePath,
				found.startLine,
				found.endLine,
			);

			const snippet = (found.signature ?? found.name).slice(0, 800);

			results.push({
				file: found.filePath,
				startLine: found.startLine,
				endLine: found.endLine,
				symbol: found.name,
				body: bodyResult.body ?? undefined,
				snippet,
				score:
					found.pagerankScore > 0
						? Math.min(found.pagerankScore * 100, 1)
						: 0.5,
				backend: this.name,
			});

			if (results.length >= limit) break;
		}

		return results;
	}
}

/**
 * Tree-Sitter Structural Backend
 *
 * Parses source files at search time to find structural patterns.
 * Activated for: structural, symbol_lookup
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { Query } from "web-tree-sitter";
import type { IFileTracker } from "../../core/tracker.js";
import type { ParserManager } from "../../parsers/parser-manager.js";
import type { QueryClassification } from "../../types.js";
import type {
	BackendResult,
	ISearchBackend,
	SearchOptions,
} from "../pipeline/types.js";
import {
	buildStructuralQuery,
	detectLanguageFromPath,
} from "./utils/structural-query-builder.js";

export class TreeSitterBackend implements ISearchBackend {
	readonly name = "tree-sitter" as const;

	constructor(
		private parserManager: ParserManager,
		private tracker: IFileTracker,
		private workspaceRoot: string,
		private maxFilesToScan: number,
	) {}

	async search(
		_query: string,
		intent: QueryClassification,
		options: SearchOptions,
		signal: AbortSignal,
	): Promise<BackendResult[]> {
		if (signal.aborted) return [];

		const limit = options.limit ?? 10;

		// Need at least one entity name to build a structural query
		if (intent.extractedEntities.length === 0) return [];

		const entityName = intent.extractedEntities[0];

		// Get all indexed files
		const allFiles = this.tracker.getAllFiles();
		if (signal.aborted) return [];

		// Apply filePattern filter if provided
		let filesToScan = allFiles.map((f) => f.path);
		if (options.filePattern) {
			const pat = options.filePattern
				.replace(/\*\*/g, ".*")
				.replace(/\*/g, "[^/]*");
			const regex = new RegExp(pat, "i");
			filesToScan = filesToScan.filter((p) => regex.test(p));
		}

		// Limit to maxFilesToScan
		filesToScan = filesToScan.slice(0, this.maxFilesToScan);

		const results: BackendResult[] = [];

		for (const relPath of filesToScan) {
			if (signal.aborted) break;
			if (results.length >= limit) break;

			const lang = detectLanguageFromPath(relPath);
			if (!lang) continue;

			// Build structural query for this language
			const queryStr = buildStructuralQuery(intent.intent, entityName, lang);
			if (!queryStr) continue;

			try {
				const absPath = resolve(this.workspaceRoot, relPath);
				let source: string;
				try {
					source = readFileSync(absPath, "utf-8");
				} catch {
					continue;
				}

				const tree = await this.parserManager.parse(source, lang);
				if (!tree || signal.aborted) continue;

				const langObj = await this.parserManager.getLanguageObject(lang);
				if (!langObj || signal.aborted) continue;

				let tsQuery: Query;
				try {
					tsQuery = new Query(langObj, queryStr);
				} catch {
					// Invalid query for this language version — skip
					continue;
				}

				const captures = tsQuery.captures(tree.rootNode);
				if (captures.length === 0) continue;

				// Group captures by the outermost node (the @decl or @call or @class capture)
				// We want the node that wraps the match, not just the name node
				const outerCaptures = captures.filter(
					(c) =>
						c.name === "decl" ||
						c.name === "call" ||
						c.name === "class" ||
						c.name === "chunk",
				);

				// If no outer captures, use all captures as fallback
				const matchCaptures =
					outerCaptures.length > 0 ? outerCaptures : captures;

				for (const capture of matchCaptures) {
					if (results.length >= limit) break;

					const node = capture.node;
					const startLine = node.startPosition.row + 1;
					const endLine = node.endPosition.row + 1;
					const snippet = node.text.slice(0, 800);

					results.push({
						file: relPath,
						startLine,
						endLine,
						symbol: entityName,
						snippet,
						score: 1.0,
						backend: this.name,
					});
				}
			} catch {}
		}

		// Normalize scores
		if (results.length > 1) {
			results.forEach((r, idx) => {
				r.score = 1 - idx / results.length;
			});
		}

		return results;
	}
}

/**
 * Symbol Body Reader
 *
 * Reads symbol source code from disk given a file path and line range.
 * Shared between the symbol tool and search pipeline backends.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";

/**
 * Read the body of a symbol from disk.
 *
 * Returns `{ body: string, stale: false }` on success or
 * `{ body: null, stale: true }` if the file cannot be read.
 *
 * Throws on path traversal attempts.
 */
export function readSymbolBody(
	workspaceRoot: string,
	filePath: string,
	startLine: number,
	endLine: number,
): { body: string; stale: false } | { body: null; stale: true } {
	const absPath = resolve(workspaceRoot, filePath);
	if (!absPath.startsWith(`${workspaceRoot}/`)) {
		throw new Error(`Path traversal attempt: ${filePath}`);
	}

	try {
		const content = readFileSync(absPath, "utf-8");
		const lines = content.split("\n");
		// startLine and endLine are 1-indexed
		const body = lines.slice(startLine - 1, endLine).join("\n");
		return { body, stale: false };
	} catch {
		return { body: null, stale: true };
	}
}

/**
 * Structural Query Builder
 *
 * Builds tree-sitter s-expression queries from query intent + entity name.
 * Currently supports TypeScript/JavaScript. Other languages return null.
 */

import type { QueryIntent, SupportedLanguage } from "../../../types.js";

/**
 * Build a tree-sitter query string for the given intent, entity, and language.
 * Returns null if the combination is not supported.
 */
export function buildStructuralQuery(
	intent: QueryIntent,
	entityName: string,
	language: SupportedLanguage,
): string | null {
	if (
		language !== "typescript" &&
		language !== "javascript" &&
		language !== "tsx" &&
		language !== "jsx"
	) {
		return null;
	}

	// Escape entity name for use in #eq? predicates
	const safeName = entityName.replace(/"/g, '\\"');

	switch (intent) {
		case "structural":
			// Caller query: find call expressions referencing entityName
			return `(call_expression
  function: [
    (identifier) @name
    (member_expression
      property: (property_identifier) @name)
  ]
  (#eq? @name "${safeName}")) @call`;

		case "symbol_lookup": {
			// Look for class, function, interface, or type declarations
			const classDecl = `(class_declaration
  name: (type_identifier) @name
  (#eq? @name "${safeName}")) @decl`;

			const fnDecl = `(function_declaration
  name: (identifier) @name
  (#eq? @name "${safeName}")) @decl`;

			const interfaceDecl = `(interface_declaration
  name: (type_identifier) @name
  (#eq? @name "${safeName}")) @decl`;

			const typeDecl = `(type_alias_declaration
  name: (type_identifier) @name
  (#eq? @name "${safeName}")) @decl`;

			const methodDecl = `(method_definition
  name: (property_identifier) @name
  (#eq? @name "${safeName}")) @decl`;

			return [classDecl, fnDecl, interfaceDecl, typeDecl, methodDecl].join(
				"\n",
			);
		}

		default:
			return null;
	}
}

/**
 * Detect language from file extension.
 */
export function detectLanguageFromPath(
	filePath: string,
): SupportedLanguage | null {
	const ext = filePath.split(".").pop()?.toLowerCase();
	switch (ext) {
		case "ts":
		case "mts":
		case "cts":
			return "typescript";
		case "tsx":
			return "tsx";
		case "js":
		case "mjs":
		case "cjs":
			return "javascript";
		case "jsx":
			return "jsx";
		case "py":
		case "pyw":
		case "pyi":
			return "python";
		case "go":
			return "go";
		case "rs":
			return "rust";
		default:
			return null;
	}
}

/**
 * Enhanced Retriever
 *
 * Advanced retrieval pipeline that integrates:
 * - Query routing for optimal search strategy
 * - Hierarchical code unit search
 * - LLM-based reranking
 * - Context formatting with attention-aware positioning
 */

import type { IVectorStore } from "../core/store.js";
import type {
	CodeUnit,
	FormattedContext,
	IEmbeddingsClient,
	ILLMClient,
	QueryIntent,
	UnitType,
} from "../types.js";
import {
	type ContextFormatter,
	createContextFormatter,
	type FormatInput,
} from "./formatting/context-formatter.js";
import {
	createLLMReranker,
	type LLMReranker,
} from "./reranking/llm-reranker.js";
import {
	createQueryRouter,
	type QueryRouter,
	type RouteResult,
} from "./routing/query-router.js";

// ============================================================================
// Types
// ============================================================================

export interface EnhancedRetrieverOptions {
	/** Use query routing (default: true) */
	useQueryRouting?: boolean;
	/** Use LLM reranking (default: true when LLM available) */
	useReranking?: boolean;
	/** Maximum initial results before reranking (default: 30) */
	initialLimit?: number;
	/** Final results limit (default: 10) */
	finalLimit?: number;
	/** Minimum rerank score to include (default: 3) */
	minRerankScore?: number;
	/** Context format style */
	formatStyle?: "markdown" | "xml" | "plain";
	/** Maximum tokens for context (default: 8000) */
	maxContextTokens?: number;
}

export interface SearchOptions {
	/** Number of results (default: 10) */
	limit?: number;
	/** Filter by unit types */
	unitTypes?: UnitType[];
	/** Filter by file path pattern */
	pathPattern?: string;
	/** Force a specific intent (skip routing) */
	forceIntent?: QueryIntent;
	/** Include summaries in context (default: true) */
	includeSummaries?: boolean;
	/** Skip reranking for this query */
	skipReranking?: boolean;
}

export interface EnhancedSearchResult {
	/** Routed query classification */
	routing: RouteResult;
	/** Primary search results */
	results: Array<CodeUnit & { score: number; rerankScore?: number }>;
	/** Formatted context for LLM consumption */
	formattedContext: FormattedContext;
	/** Search metadata */
	metadata: {
		durationMs: number;
		initialResultCount: number;
		finalResultCount: number;
		usedReranking: boolean;
		queryIntent: QueryIntent;
	};
}

// ============================================================================
// Enhanced Retriever Class
// ============================================================================

export class EnhancedRetriever {
	private store: IVectorStore;
	private embeddings: IEmbeddingsClient;
	private llmClient: ILLMClient | null;
	private queryRouter: QueryRouter;
	private reranker: LLMReranker | null;
	private formatter: ContextFormatter;
	private options: Required<EnhancedRetrieverOptions>;

	constructor(
		store: IVectorStore,
		embeddings: IEmbeddingsClient,
		llmClient: ILLMClient | null,
		options: EnhancedRetrieverOptions = {},
	) {
		this.store = store;
		this.embeddings = embeddings;
		this.llmClient = llmClient;

		this.options = {
			useQueryRouting: options.useQueryRouting ?? true,
			useReranking: options.useReranking ?? llmClient !== null,
			initialLimit: options.initialLimit ?? 30,
			finalLimit: options.finalLimit ?? 10,
			minRerankScore: options.minRerankScore ?? 3,
			formatStyle: options.formatStyle ?? "markdown",
			maxContextTokens: options.maxContextTokens ?? 8000,
		};

		// Initialize components
		this.queryRouter = createQueryRouter(llmClient, {
			useLLM: this.options.useQueryRouting,
		});
		this.reranker = llmClient
			? createLLMReranker(llmClient, {
					maxCandidates: this.options.initialLimit,
					minScore: this.options.minRerankScore,
				})
			: null;
		this.formatter = createContextFormatter({
			maxTokens: this.options.maxContextTokens,
			style: this.options.formatStyle,
		});
	}

	/**
	 * Full pipeline search with routing, reranking, and formatting
	 */
	async search(
		query: string,
		options: SearchOptions = {},
	): Promise<EnhancedSearchResult> {
		const startTime = Date.now();
		const {
			limit = this.options.finalLimit,
			unitTypes,
			pathPattern,
			forceIntent,
			includeSummaries = true,
			skipReranking = false,
		} = options;

		// Step 1: Route query
		const routing = forceIntent
			? {
					classification: {
						intent: forceIntent,
						confidence: 1.0,
						extractedEntities: [],
						reasoning: "Forced intent",
					},
					strategy: this.queryRouter.buildStrategyForIntent(forceIntent),
				}
			: await this.queryRouter.route(query);

		// Step 2: Execute search based on strategy
		const initialResults = await this.executeSearch(query, routing, {
			limit: this.options.initialLimit,
			unitTypes,
			pathPattern,
		});

		// Step 3: Rerank if enabled
		let finalResults: Array<CodeUnit & { score: number; rerankScore?: number }>;
		let usedReranking = false;

		if (
			this.options.useReranking &&
			this.reranker &&
			!skipReranking &&
			initialResults.length > 0
		) {
			try {
				const reranked = await this.reranker.rerankCodeUnits(
					query,
					initialResults,
				);
				finalResults = reranked.slice(0, limit);
				usedReranking = true;
			} catch (error) {
				console.warn("Reranking failed, using initial results:", error);
				finalResults = initialResults.slice(0, limit);
			}
		} else {
			finalResults = initialResults.slice(0, limit);
		}

		// Step 4: Get summaries for context (if requested)
		const summaries: Array<{ name: string; summary: string; path: string }> =
			[];
		if (includeSummaries && finalResults.length > 0) {
			const uniqueFiles = [...new Set(finalResults.map((r) => r.filePath))];
			for (const filePath of uniqueFiles.slice(0, 5)) {
				const fileSummary = await this.getFileSummary(filePath);
				if (fileSummary) {
					summaries.push(fileSummary);
				}
			}
		}

		// Step 5: Format context
		const formatInput: FormatInput = {
			primary: finalResults.slice(0, Math.ceil(limit * 0.6)),
			supporting: finalResults.slice(Math.ceil(limit * 0.6)),
			summaries,
			queryIntent: routing.classification.intent,
		};

		const formattedContext = this.formatter.format(formatInput);

		return {
			routing,
			results: finalResults,
			formattedContext,
			metadata: {
				durationMs: Date.now() - startTime,
				initialResultCount: initialResults.length,
				finalResultCount: finalResults.length,
				usedReranking,
				queryIntent: routing.classification.intent,
			},
		};
	}

	/**
	 * Search and return formatted context string for direct LLM use
	 */
	async searchForLLM(
		query: string,
		options: SearchOptions = {},
	): Promise<string> {
		const result = await this.search(query, options);
		return this.formatter.formatForLLM({
			primary: result.results.slice(0, Math.ceil(result.results.length * 0.6)),
			supporting: result.results.slice(Math.ceil(result.results.length * 0.6)),
			summaries: [], // Already included in formattedContext
			queryIntent: result.routing.classification.intent,
		});
	}

	/**
	 * Execute search based on routing strategy
	 */
	private async executeSearch(
		query: string,
		routing: RouteResult,
		options: { limit: number; unitTypes?: UnitType[]; pathPattern?: string },
	): Promise<Array<CodeUnit & { score: number }>> {
		const { strategy } = routing;
		const { limit, unitTypes, pathPattern } = options;

		// Generate query embedding
		const queryVector = await this.embeddings.embedOne(query);

