			),
			location: parseBool(
				process.env.MNEMEX_PIPELINE_LOCATION,
				d.backends.location,
			),
		},
		routerMinConfidence: parseFloatEnv(
			process.env.MNEMEX_PIPELINE_ROUTER_CONFIDENCE,
			d.routerMinConfidence,
		),
