/**
 * rg argument parser
 *
 * Parses ripgrep CLI arguments to extract the search pattern, search path,
 * output mode, and passthrough flags.
 */

/** Output mode for rg command */
export type OutputMode = "content" | "files-with-matches" | "count";

/** Match semantics for mnemex-side pattern filtering */
export interface MatchFlags {
	/** `-F` / `--fixed-strings`: treat pattern as literal string, not regex */
	fixedStrings: boolean;
	/** `-w` / `--word-regexp`: require whole-word match */
	wordRegexp: boolean;
	/** `-x` / `--line-regexp`: require pattern to match entire line */
	lineRegexp: boolean;
	/** `-i` / `--ignore-case`: force case-insensitive */
	ignoreCase: boolean;
	/** `-s` / `--case-sensitive`: force case-sensitive */
	caseSensitive: boolean;
	/** `-S` / `--smart-case`: case-insensitive unless pattern has uppercase */
	smartCase: boolean;
}

/** Parsed rg arguments */
export interface ParsedRgArgs {
	/** The search pattern (may be undefined if not found) */
	pattern: string | undefined;
	/** The search path (defaults to ".") */
	searchPath: string;
	/** Output mode */
	mode: OutputMode;
	/** Match semantics flags for merger filtering */
	matchFlags: MatchFlags;
	/** Raw args to pass through to real rg */
	passthroughArgs: string[];
}

/** Flags that consume the next argument (value flags) */
const VALUE_FLAGS = new Set([
	"-e",
	"--regexp",
	"-f",
	"--file",
	"-A",
	"--after-context",
	"-B",
	"--before-context",
	"-C",
	"--context",
	"-g",
	"--glob",
	"-t",
	"--type",
	"-T",
	"--type-not",
	"--type-add",
	"--type-clear",
	"--color",
	"--colors",
	"--encoding",
	"-m",
	"--max-count",
	"--max-depth",
	"--max-filesize",
	"--pre",
	"--pre-glob",
	"--sort",
	"--sortr",
	"--field-match-separator",
	"--field-context-separator",
]);

/** Combined short flags that don't take values (single-char each) */
const BOOLEAN_SHORT_FLAGS = new Set([
	"i",
	"n",
	"N",
	"l",
	"c",
	"s",
	"S",
	"w",
	"x",
	"v",
	"h",
	"H",
	"p",
	"q",
	"u",
	"L",
	"z",
	"0",
	".",
]);

/**
 * Ensure `--line-number` is present in the args list.
 *
 * The result merger requires `file:line:content` format from rg, so we always
 * add `--line-number` unless the caller already passed `-n` or `--line-number`.
 * Returns a new array (does not mutate the input).
 */
export function ensureLineNumbers(args: string[]): string[] {
	if (args.includes("-n") || args.includes("--line-number")) return args;
	return ["--line-number", ...args];
}

/**
 * Parse ripgrep CLI arguments into structured form.
 *
 * Handles:
 * - `--` separator (end of flags)
 * - `-e`/`--regexp` pattern flag
 * - Combined short flags like `-in`, `-lc`
 * - `--files-with-matches`/`-l` output mode
 * - `--count`/`-c` output mode
 * - First and second positional args (pattern and path)
 */
export function parseRgArgs(args: string[]): ParsedRgArgs {
	let pattern: string | undefined;
	let searchPath = ".";
	let mode: OutputMode = "content";
	const matchFlags: MatchFlags = {
		fixedStrings: false,
		wordRegexp: false,
		lineRegexp: false,
		ignoreCase: false,
		caseSensitive: false,
		smartCase: false,
	};
	const positionals: string[] = [];
	let endOfFlags = false;

	let i = 0;
	while (i < args.length) {
		const arg = args[i];

		if (endOfFlags) {
			positionals.push(arg);
			i++;
			continue;
		}

		if (arg === "--") {
			endOfFlags = true;
			i++;
			continue;
		}

		// Long flags
		if (arg.startsWith("--")) {
			if (arg === "--files-with-matches") {
				mode = "files-with-matches";
				i++;
				continue;
			}
			if (arg === "--count" || arg === "--count-matches") {
				mode = "count";
				i++;
				continue;
			}
			if (arg === "--fixed-strings") {
				matchFlags.fixedStrings = true;
				i++;
				continue;
			}
			if (arg === "--word-regexp") {
				matchFlags.wordRegexp = true;
				i++;
				continue;
			}
			if (arg === "--line-regexp") {
				matchFlags.lineRegexp = true;
				i++;
				continue;
			}
			if (arg === "--ignore-case") {
				matchFlags.ignoreCase = true;
				i++;
				continue;
			}
			if (arg === "--case-sensitive") {
				matchFlags.caseSensitive = true;
				i++;
				continue;
			}
			if (arg === "--smart-case") {
				matchFlags.smartCase = true;
				i++;
				continue;
			}

			// Check if flag=value form (e.g. --glob=*.ts)
			const eqIdx = arg.indexOf("=");
			if (eqIdx !== -1) {
				// flag=value, no extra consumption
				i++;
				continue;
			}

			// -e / --regexp sets the pattern explicitly
			if (arg === "--regexp") {
				i++;
				if (i < args.length) {
					pattern = pattern ?? args[i];
					i++;
				}
				continue;
			}

			// Value-consuming long flags
			if (VALUE_FLAGS.has(arg)) {
				i += 2;
				continue;
			}

			// Boolean long flag
			i++;
			continue;
		}

		// Short flags (single dash)
		if (arg.startsWith("-") && arg.length > 1) {
			// Handle -e <pattern>
			if (arg === "-e") {
				i++;
				if (i < args.length) {
					pattern = pattern ?? args[i];
					i++;
				}
				continue;
			}

			// Check if this is a known value-consuming short flag (single char)
			const singleFlag = arg.slice(0, 2); // e.g. "-A"
			if (VALUE_FLAGS.has(singleFlag) && arg.length === 2) {
				// -A 3 style
				i += 2;
				continue;
			}
			if (VALUE_FLAGS.has(singleFlag) && arg.length > 2) {
				// -A3 style (value attached)
				i++;
				continue;
			}

			// Combined boolean short flags like -in, -lc, -Fw, -iS
			// Check each character after the dash
			let hasL = false;
			let hasC = false;
			for (const ch of arg.slice(1)) {
				if (ch === "l") hasL = true;
				else if (ch === "c") hasC = true;
				else if (ch === "F") matchFlags.fixedStrings = true;
				else if (ch === "w") matchFlags.wordRegexp = true;
				else if (ch === "x") matchFlags.lineRegexp = true;
				else if (ch === "i") matchFlags.ignoreCase = true;
				else if (ch === "s") matchFlags.caseSensitive = true;
				else if (ch === "S") matchFlags.smartCase = true;
			}
			if (hasL) mode = "files-with-matches";
			if (hasC) mode = "count";

			i++;
			continue;
		}

		// Positional argument
		positionals.push(arg);
		i++;
	}

	// First positional is pattern (unless set by -e)
	if (positionals.length >= 1 && pattern === undefined) {
		pattern = positionals[0];
		if (positionals.length >= 2) {
			searchPath = positionals[1];
		}
	} else if (positionals.length >= 1) {
		// Pattern was set by -e, first positional is search path
		searchPath = positionals[0];
	}

	return {
		pattern,
		searchPath,
		mode,
		matchFlags,
		passthroughArgs: args,
	};
}

/**
 * Shared File Walker
 *
 * Recursive file discovery with exclude/include pattern support.
 * Extracted from Indexer to be reusable across modules (indexer, pack, etc.).
 */

import { type Dirent, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { shouldExclude, shouldInclude } from "./pattern-matcher.js";

// ============================================================================
// Types
// ============================================================================

/**
 * A single file or directory entry discovered during walking.
 */
export interface WalkEntry {
	/** Absolute path to the file/directory */
	path: string;
	/** Path relative to the root directory */
	relativePath: string;
	/** Whether this entry is a directory */
	isDirectory: boolean;
	/** File size in bytes (0 for directories) */
	size: number;
}

/**
 * Options for the file walker.
 */
export interface WalkOptions {
	/** Glob patterns for paths to exclude */
	excludePatterns: string[];
	/** Glob patterns for paths to include (if empty, all non-excluded paths are included) */
	includePatterns?: string[];
	/**
	 * File extensions to include (e.g., [".ts", ".js"]).
	 * If not provided, all non-binary files are included.
	 * Each extension must start with a dot.
	 */
	onlyExtensions?: Set<string>;
}

// ============================================================================
// Functions
// ============================================================================

/**
 * Walk a directory tree and return all matching file entries.
 *
 * Directories that match exclude patterns are pruned entirely.
 * Files must pass exclude check and (if configured) include check and extension check.
 *
 * @param root - Absolute path to the root directory to walk
 * @param opts - Walk options
 * @returns Array of WalkEntry objects for matching files (not directories)
 */
export function walkFiles(root: string, opts: WalkOptions): WalkEntry[] {
	const entries: WalkEntry[] = [];
	const { excludePatterns, includePatterns = [], onlyExtensions } = opts;

	const walk = (dir: string): void => {
		let dirEntries: Dirent[];
		try {
			dirEntries = readdirSync(dir, { withFileTypes: true }) as Dirent[];
		} catch {
			// Skip unreadable directories
			return;
		}

		for (const entry of dirEntries) {
			const fullPath = join(dir, entry.name as string);
			const relativePath = relative(root, fullPath);

			// Check exclude patterns
			if (shouldExclude(relativePath, entry.isDirectory(), excludePatterns)) {
				continue;
			}

			if (entry.isDirectory()) {
				walk(fullPath);
			} else if (entry.isFile()) {
				// Check include patterns if specified
				if (
					includePatterns.length > 0 &&
					!shouldInclude(relativePath, includePatterns)
				) {
					continue;
				}

				// Check extension filter if specified
				if (onlyExtensions !== undefined) {
					const ext = `.${(entry.name as string).split(".").pop()?.toLowerCase()}`;
					if (!onlyExtensions.has(ext)) {
						continue;
					}
				}

				let size = 0;
				try {
					size = statSync(fullPath).size;
				} catch {
					// Use 0 for inaccessible files
				}

				entries.push({
					path: fullPath,
					relativePath,
					isDirectory: false,
					size,
				});
			}
		}
	};

	walk(root);
	return entries;
}

/**
 * Shared Pattern Matcher
 *
 * Pure functions for checking file/directory exclude and include patterns.
 * Extracted from Indexer to be reusable across modules (indexer, pack, etc.).
 */

import { minimatch } from "minimatch";

// ============================================================================
// Constants
// ============================================================================

/**
 * Directories to always exclude (fast path, no glob matching needed).
 * These are checked first before any glob patterns.
 */
export const ALWAYS_EXCLUDE_DIRS = new Set([
	"node_modules",
	".git",
	".svn",
	".hg",
	"dist",
	"build",
	"out",
	".next",
	".nuxt",
	"coverage",
	"__pycache__",
	"venv",
	".venv",
	"target",
	"vendor",
	".idea",
	".vscode",
	".cache",
	".mnemex",
	".turbo",
	".expo",
]);

// ============================================================================
// Functions
// ============================================================================

/**
 * Check if a path should be excluded based on exclude patterns.
 *
 * @param relativePath - Path relative to project root
 * @param isDirectory - Whether the path is a directory
 * @param excludePatterns - Glob patterns to match against
 * @returns true if the path should be excluded
 */
export function shouldExclude(
	relativePath: string,
	isDirectory: boolean,
	excludePatterns: string[],
): boolean {
	// Fast path: check if any path segment is in the always-exclude list
	const segments = relativePath.split("/");
	for (const segment of segments) {
		if (ALWAYS_EXCLUDE_DIRS.has(segment)) {
			return true;
		}
	}

	// Slow path: check glob patterns
	const pathToCheck = isDirectory ? `${relativePath}/` : relativePath;

	for (const pattern of excludePatterns) {
		if (minimatch(pathToCheck, pattern, { dot: true })) {
			return true;
		}
		// Also check without trailing slash
		if (minimatch(relativePath, pattern, { dot: true })) {
			return true;
		}
	}

	return false;
}

/**
 * Check if a path matches any of the include patterns.
 *
 * @param relativePath - Path relative to project root
 * @param includePatterns - Glob patterns to match against
 * @returns true if the path matches at least one include pattern
 */
export function shouldInclude(
	relativePath: string,
	includePatterns: string[],
): boolean {
	for (const pattern of includePatterns) {
		if (minimatch(relativePath, pattern, { dot: true })) {
			return true;
		}
	}
	return false;
}

/**
 * TUI Root App Component
 *
 * Provides AppContext, tab navigation, global keyboard handling,
 * and renders the active view with StatusBar.
 */

import { useKeyboard, useTerminalDimensions } from "@opentui/react";
import { ErrorBanner } from "./components/ErrorBanner.js";
import { HelpOverlay } from "./components/HelpOverlay.js";
import { StatusBar } from "./components/StatusBar.js";
import { TabBar } from "./components/TabBar.js";
import { AppProvider, type TabId, useAppContext } from "./context.js";
import { AnalysisView } from "./views/AnalysisView.js";
import { DoctorView } from "./views/DoctorView.js";
import { GraphView } from "./views/GraphView.js";
import { IndexNeededView } from "./views/IndexNeededView.js";
import { MapView } from "./views/MapView.js";
import { SearchView } from "./views/SearchView.js";

// ============================================================================
// App Props
// ============================================================================

export interface AppProps {
	projectPath: string;
	quit: () => void;
}

// ============================================================================
// Inner App (inside context)
// ============================================================================

function AppInner() {
	const {
		activeTab,
		setActiveTab,
		showHelp,
		toggleHelp,
		error,
		setError,
		inputFocused,
		quit,
		indexNeeded,
		indexing,
	} = useAppContext();
	const { height } = useTerminalDimensions();

	// Global keyboard handling - suppressed when an input field is focused
	// or when the index prompt / progress view is active (it handles its own keys)
	useKeyboard((key) => {
		// IndexNeededView handles its own keyboard — skip global shortcuts
		if (indexNeeded || indexing) return;

		// Escape always works: unfocus input is handled by the view itself
		// Ctrl+C always works: handled by renderer exitOnCtrlC

		// When input is focused, only handle Escape and Tab (for tab switching)
		if (inputFocused) {
			// Tab still switches views even when typing
			if (key.name === "tab" && !key.shift) {
				const tabs: TabId[] = ["search", "map", "graph", "analysis", "doctor"];
				const idx = tabs.indexOf(activeTab);
				setActiveTab(tabs[(idx + 1) % tabs.length]);
				return;
			}
			if (key.name === "tab" && key.shift) {
				const tabs: TabId[] = ["search", "map", "graph", "analysis", "doctor"];
				const idx = tabs.indexOf(activeTab);
				setActiveTab(tabs[(idx - 1 + tabs.length) % tabs.length]);
				return;
			}
			// All other keys go to the focused input - don't intercept
			return;
		}

		// --- Below here: only when NO input is focused ---

		// Tab / Shift+Tab to cycle through tabs
		if (key.name === "tab" && !key.shift) {
			const tabs: TabId[] = ["search", "map", "graph", "analysis", "doctor"];
			const idx = tabs.indexOf(activeTab);
			setActiveTab(tabs[(idx + 1) % tabs.length]);
			return;
		}
		if (key.name === "tab" && key.shift) {
			const tabs: TabId[] = ["search", "map", "graph", "analysis", "doctor"];
			const idx = tabs.indexOf(activeTab);
			setActiveTab(tabs[(idx - 1 + tabs.length) % tabs.length]);
			return;
		}

		// Number shortcuts 1-5 to jump to tabs
		if (key.name === "1") {
			setActiveTab("search");
			return;
		}
		if (key.name === "2") {
			setActiveTab("map");
			return;
		}
		if (key.name === "3") {
			setActiveTab("graph");
			return;
		}
		if (key.name === "4") {
			setActiveTab("analysis");
			return;
		}
		if (key.name === "5") {
			setActiveTab("doctor");
			return;
		}

		// ? to toggle help
		if (key.name === "?") {
			toggleHelp();
			return;
		}

		// q to quit
		if (key.name === "q" && !key.ctrl && !key.meta) {
			quit();
		}
	});

	// Show the index prompt / progress view when index is missing or being built
	if (indexNeeded || indexing) {
		return (
			<box flexDirection="column" width="100%" height="100%">
				<IndexNeededView />

				{error && (
					<ErrorBanner message={error} onDismiss={() => setError(null)} />
				)}
			</box>
		);
	}

	const mainHeight = height - 2; // subtract tab bar and status bar

	return (
		<box flexDirection="column" width="100%" height="100%">
			<TabBar />

			<box flexDirection="column" height={mainHeight} overflow="hidden">
				<ActiveView tab={activeTab} />
			</box>

			<StatusBar />

			{showHelp && <HelpOverlay view={activeTab} onClose={toggleHelp} />}

			{error && (
				<ErrorBanner message={error} onDismiss={() => setError(null)} />
			)}
		</box>
	);
}

// ============================================================================
// Active View Router
// ============================================================================

interface ActiveViewProps {
	tab: TabId;
}

function ActiveView({ tab }: ActiveViewProps) {
	switch (tab) {
		case "search":
			return <SearchView />;
		case "map":
			return <MapView />;
		case "graph":
			return <GraphView />;
		case "analysis":
			return <AnalysisView />;
		case "doctor":
			return <DoctorView />;
		default:
			return (
				<box flexDirection="column" width="100%" height="100%" padding={1}>
					<text fg="#6B7280">Unknown view: {tab}</text>
				</box>
			);
	}
}

// ============================================================================
// Root App Component
// ============================================================================

export function App({ projectPath, quit }: AppProps) {
	return (
		<AppProvider projectPath={projectPath} quit={quit}>
			<AppInner />
		</AppProvider>
	);
}

/**
 * Monitor Mode App
 *
 * Passive display that auto-updates when Claude Code uses mnemex MCP tools.
 * Unlike the interactive UI mode, monitor mode has no manual input — everything
 * is driven by activity recorded by the MCP server.
 *
 * Usage: mnemex monitor [path]
 */

import { useKeyboard, useTerminalDimensions } from "@opentui/react";
import { useCallback, useState } from "react";
import type { SearchResult } from "../types.js";
import { ResultDetailView } from "./components/ResultDetailView.js";
import { StatusBar } from "./components/StatusBar.js";
import { AppProvider, useAppContext } from "./context.js";
import {
	type ActivityRecord,
	useActivityMonitor,
} from "./hooks/useActivityMonitor.js";
import { theme } from "./theme.js";

// ============================================================================
// Monitor Inner (inside AppContext)
// ============================================================================

function MonitorInner() {
	const { tracker, projectPath, quit } = useAppContext();
	const { height } = useTerminalDimensions();

	const [currentResult, setCurrentResult] = useState<SearchResult | null>(null);
	const [activityInfo, setActivityInfo] = useState<{
		type: string;
		metadata: Record<string, unknown>;
		timestamp: string;
	} | null>(null);

	// Handle incoming activity — extract search result for direct rendering
	const handleActivity = useCallback((record: ActivityRecord) => {
		setActivityInfo({
			type: record.type,
			metadata: record.metadata,
			timestamp: record.timestamp,
		});

		if (record.type === "search_code" && record.metadata.topResult) {
			const top = record.metadata.topResult as any;
			if (top?.chunk) {
				setCurrentResult({
					chunk: top.chunk,
					score: top.score ?? 0,
					vectorScore: top.vectorScore ?? 0,
					keywordScore: top.keywordScore ?? 0,
					summary: top.summary,
					fileSummary: top.fileSummary,
				});
			}
		}
	}, []);

	useActivityMonitor(projectPath, tracker, handleActivity);

	// q or Ctrl+C to quit
	useKeyboard((key) => {
		if (key.name === "q" && !key.ctrl && !key.meta) {
			quit();
		}
	});

	const mainHeight = height - 1; // subtract StatusBar

	return (
		<box flexDirection="column" width="100%" height="100%">
			<box flexDirection="column" height={mainHeight} overflow="hidden">
				{currentResult ? (
					<ResultDetailView
						result={currentResult}
						allResults={[currentResult]}
						onClose={() => setCurrentResult(null)}
					/>
				) : (
					<WaitingView activityInfo={activityInfo} />
				)}
			</box>
			<StatusBar />
		</box>
	);
}

// ============================================================================
// Waiting View (shown when no search result to display)
// ============================================================================

function WaitingView({
	activityInfo,
}: {
	activityInfo: {
		type: string;
		metadata: Record<string, unknown>;
		timestamp: string;
	} | null;
}) {
	const { width, height } = useTerminalDimensions();

	if (activityInfo && activityInfo.type !== "search_code") {
		// Show non-search activity summary
		return (
			<box flexDirection="column" width="100%" height="100%" padding={2}>
				<box height={1}>
					<text fg={theme.primary}>{"  mnemex monitor"}</text>
				</box>
				<box height={1} />
				<box height={1}>
					<text fg={theme.info}>{`  Last activity: ${activityInfo.type}`}</text>
				</box>
				<box height={1}>
					<text fg={theme.muted}>
						{`  ${formatActivitySummary(activityInfo.type, activityInfo.metadata)}`}
					</text>
				</box>
				<box height={1} />
				<box height={1}>
					<text fg={theme.dimmed}>
						{"  Waiting for search_code to display detail view..."}
					</text>
				</box>
				<box height={1} />
				<box height={1}>
					<text fg={theme.dimmed}>{"  Press q to quit"}</text>
				</box>
			</box>
		);
	}

	return (
		<box flexDirection="column" width="100%" height="100%" padding={2}>
			<box height={1}>
				<text fg={theme.primary}>{"  mnemex monitor"}</text>
			</box>
			<box height={1} />
			<box height={1}>
				<text fg={theme.muted}>
					{"  Waiting for Claude Code to use mnemex..."}
				</text>
			</box>
			<box height={1} />
			<box height={1}>
				<text fg={theme.dimmed}>
					{"  This display updates automatically when Claude Code calls"}
				</text>
			</box>
			<box height={1}>
				<text fg={theme.dimmed}>
					{"  search_code, analyze_impact, or other MCP tools."}
				</text>
			</box>
			<box height={1} />
			<box height={1}>
				<text fg={theme.dimmed}>{"  Press q to quit"}</text>
			</box>
		</box>
	);
}

function formatActivitySummary(
	type: string,
	metadata: Record<string, unknown>,
): string {
	switch (type) {
		case "analyze_impact":
			return `Impact analysis for "${metadata.symbol}" — ${metadata.affectedCount} callers affected`;
		case "find_dead_code":
			return `Found ${metadata.count} potentially dead symbols`;
		case "find_test_gaps":
			return `Found ${metadata.count} symbols without test coverage`;
		case "index_codebase":
			return `Indexed ${metadata.filesIndexed} files, ${metadata.chunksCreated} chunks`;
		case "get_status":
			return `Status: ${metadata.totalFiles} files, ${metadata.totalChunks} chunks`;
		default:
			return JSON.stringify(metadata);
	}
}

// ============================================================================
// Root Monitor Component
// ============================================================================

export interface MonitorAppProps {
	projectPath: string;
	quit: () => void;
}

export function MonitorApp({ projectPath, quit }: MonitorAppProps) {
	return (
		<AppProvider projectPath={projectPath} quit={quit} monitorMode>
			<MonitorInner />
		</AppProvider>
	);
}

/**
 * HTTP client for the /v1/keys API endpoints.
 * All requests use the master key via Authorization: Bearer header.
 */

// ============================================================================
// Types
// ============================================================================

export interface ApiKey {
	id: number;
	name: string;
	prefix: string;
	createdAt: string;
	lastUsedAt: string | null;
	isActive: boolean;
	usage: {
		total: number;
		byEndpoint: Record<string, number>;
	};
}

// ============================================================================
// Client
// ============================================================================

export class AdminApiClient {
	constructor(
		private readonly endpoint: string,
		private readonly masterKey: string,
	) {}

	private headers(): HeadersInit {
		return {
			Authorization: `Bearer ${this.masterKey}`,
			"Content-Type": "application/json",
			"X-Mnemex-Version": "1",
		};
	}

	async listKeys(): Promise<ApiKey[]> {
		const res = await fetch(`${this.endpoint}/v1/keys`, {
			method: "GET",
			headers: this.headers(),
		});
		if (!res.ok) {
			const body = (await res.json().catch(() => ({}))) as {
				error?: string;
			};
			throw new Error(body.error ?? `HTTP ${res.status}`);
		}
		const body = (await res.json()) as { keys: ApiKey[] };
		return body.keys;
	}

	async createKey(name: string): Promise<{ key: ApiKey; secret: string }> {
		const res = await fetch(`${this.endpoint}/v1/keys`, {
			method: "POST",
			headers: this.headers(),
			body: JSON.stringify({ name }),
		});
		if (!res.ok) {
			const body = (await res.json().catch(() => ({}))) as {
				error?: string;
				field?: string;
			};
			const msg = body.field
				? `${body.error}: ${body.field}`
				: (body.error ?? `HTTP ${res.status}`);
			throw new Error(msg);
		}
		const body = (await res.json()) as {
			ok: boolean;
			key: ApiKey;
			secret: string;
		};
		return { key: body.key, secret: body.secret };
	}

	async deleteKey(id: number): Promise<void> {
		const res = await fetch(`${this.endpoint}/v1/keys/${id}`, {
			method: "DELETE",
			headers: this.headers(),
		});
		if (!res.ok) {
			const body = (await res.json().catch(() => ({}))) as {
				error?: string;
			};
			throw new Error(body.error ?? `HTTP ${res.status}`);
		}
	}
}

/**
 * AdminApp — root component for the mnemex admin TUI.
 *
 * State machine:
 *   "list"           — shows KeyListView
 *   "create"         — shows CreateKeyView (input form)
 *   "delete-confirm" — shows delete confirmation overlay over KeyListView
 */

import { useKeyboard } from "@opentui/react";
import { useCallback, useEffect, useState } from "react";
import { theme } from "../theme.js";
import { AdminApiClient, type ApiKey } from "./AdminApiClient.js";
import { CreateKeyView } from "./CreateKeyView.js";
import { KeyListView } from "./KeyListView.js";

// ============================================================================
// Types
// ============================================================================

type AdminView = "list" | "create" | "delete-confirm";

export interface AdminAppProps {
	endpoint: string;
	masterKey: string;
	quit: () => void;
}

// ============================================================================
// Component
// ============================================================================

export function AdminApp({ endpoint, masterKey, quit }: AdminAppProps) {
	const [client] = useState(() => new AdminApiClient(endpoint, masterKey));

	const [view, setView] = useState<AdminView>("list");
	const [keys, setKeys] = useState<ApiKey[]>([]);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [newSecret, setNewSecret] = useState<string | null>(null);
	const [newKeyName, setNewKeyName] = useState("");
	const [selectedIndex, setSelectedIndex] = useState(0);
	const [createLoading, setCreateLoading] = useState(false);
	const [createError, setCreateError] = useState<string | null>(null);

	const loadKeys = useCallback(async () => {
		setLoading(true);
		setError(null);
		try {
			const list = await client.listKeys();
			setKeys(list);
			setSelectedIndex((prev) => Math.min(prev, Math.max(list.length - 1, 0)));
		} catch (err) {
			setError(err instanceof Error ? err.message : String(err));
		} finally {
			setLoading(false);
		}
	}, [endpoint, masterKey]);

	// Load keys on mount
	useEffect(() => {
		loadKeys();
	}, [loadKeys]);

	// Delete confirmation keyboard
	useKeyboard((key) => {
		if (view !== "delete-confirm") return;

		if (key.name === "y") {
			const selectedKey = keys[selectedIndex];
			if (!selectedKey) return;
			setView("list");
			client
				.deleteKey(selectedKey.id)
				.then(() => loadKeys())
				.catch((err: unknown) => {
					setError(err instanceof Error ? err.message : String(err));
				});
			return;
		}

		if (key.name === "n" || key.name === "escape") {
			setView("list");
			return;
		}
	});

	const handleCreate = async (name: string) => {
		setCreateLoading(true);
		setCreateError(null);
		try {
			const result = await client.createKey(name);
			setNewSecret(result.secret);
			setNewKeyName(result.key.name);
			await loadKeys();
		} catch (err) {
			setCreateError(err instanceof Error ? err.message : String(err));
		} finally {
			setCreateLoading(false);
		}
	};

	const handleDismissSecret = () => {
		setNewSecret(null);
		setNewKeyName("");
		setView("list");
	};

	const selectedKey = keys[selectedIndex];

	// Delete confirmation — standalone screen
	if (view === "delete-confirm" && selectedKey) {
		return (
			<box flexDirection="column" width="100%" height="100%" padding={2}>
				{/* Title bar */}
				<box flexDirection="row">
					<text fg={theme.dangerBorder}>{"┌─"}</text>
					<text fg={theme.error}>{" ! "}</text>
					<text fg={theme.dangerText}>{" Delete API Key "}</text>
					<text fg={theme.dangerBorder}>{"─┐"}</text>
				</box>

				{/* Dialog body */}
				<box
					flexDirection="column"
					marginTop={1}
					borderStyle="double"
					borderColor={theme.dangerBorder}
					paddingLeft={3}
					paddingRight={3}
					paddingTop={1}
					paddingBottom={1}
				>
					<box>
						<text fg={theme.text}>
							{"Are you sure you want to delete this key?"}
						</text>
					</box>

					<box marginTop={1} flexDirection="row">
						<text fg={theme.labelDim}>{"  name    "}</text>
						<text fg={theme.valueBright}>{selectedKey.name}</text>
					</box>
					<box flexDirection="row">
						<text fg={theme.labelDim}>{"  prefix  "}</text>
						<text fg={theme.muted}>{selectedKey.prefix}</text>
					</box>

					<box marginTop={1} flexDirection="row">
						<text fg={theme.error}>{"  ! "}</text>
						<text fg={theme.dimmed}>
							{"This action cannot be undone. All usage data will be lost."}
						</text>
					</box>
				</box>

				{/* Choices */}
				<box flexDirection="row" marginTop={2} paddingLeft={1}>
					<text fg={theme.dangerBorder}>{"└─ "}</text>
					<text fg={theme.shortcutBracket}>{"["}</text>
					<text fg={theme.error}>{"y"}</text>
					<text fg={theme.shortcutBracket}>{"]"}</text>
					<text fg={theme.dangerText}>{" yes, delete  "}</text>
					<text fg={theme.shortcutBracket}>{"["}</text>
					<text fg={theme.shortcutKey}>{"n"}</text>
					<text fg={theme.shortcutBracket}>{"]"}</text>
					<text fg={theme.muted}>{" cancel  "}</text>
					<text fg={theme.shortcutBracket}>{"["}</text>
					<text fg={theme.shortcutKey}>{"Esc"}</text>
					<text fg={theme.shortcutBracket}>{"]"}</text>
					<text fg={theme.muted}>{" cancel"}</text>
					<text fg={theme.dangerBorder}>{" ─┘"}</text>
				</box>
			</box>
		);
	}

	if (view === "create") {
		return (
			<CreateKeyView
				newSecret={newSecret}
				newKeyName={newKeyName}
				loading={createLoading}
				error={createError}
				onCreate={handleCreate}
				onCancel={() => {
					setCreateError(null);
					setView("list");
				}}
				onDismissSecret={handleDismissSecret}
			/>
		);
	}

	return (
		<KeyListView
			endpoint={endpoint}
			keys={keys}
			selectedIndex={selectedIndex}
			loading={loading}
			error={error}
			onSelect={setSelectedIndex}
			onNew={() => {
				setCreateError(null);
				setNewSecret(null);
				setView("create");
			}}
			onDelete={() => {
				if (keys.length > 0) setView("delete-confirm");
			}}
			onRefresh={loadKeys}
			onQuit={quit}
		/>
	);
}

/**
 * CreateKeyView — name input form + secret display after creation.
 *
 * Two sub-states:
 *   "input"  — text field for key name; Enter to create, Esc to cancel
 *   "secret" — shows the secret once; Enter or Escape to return to list
 */

import { execSync } from "node:child_process";
import { useKeyboard } from "@opentui/react";
import { useEffect, useState } from "react";
import { theme } from "../theme.js";

function copyToClipboard(text: string): boolean {
	try {
		execSync("pbcopy", { input: text });
		return true;
	} catch {
		return false;
	}
}

// ============================================================================
// Types
// ============================================================================

export interface CreateKeyViewProps {
	/** Secret shown after creation (null = still in input state) */
	newSecret: string | null;
	/** Name of the newly created key (for display) */
	newKeyName: string;
	loading: boolean;
	error: string | null;
	onCreate: (name: string) => void;
	onCancel: () => void;
	onDismissSecret: () => void;
}

// ============================================================================
// Component
// ============================================================================

export function CreateKeyView({
	newSecret,
	newKeyName,
	loading,
	error,
	onCreate,
	onCancel,
	onDismissSecret,
}: CreateKeyViewProps) {
	const [name, setName] = useState("");
	const [copied, setCopied] = useState(false);

	// Auto-copy secret to clipboard when it appears
	useEffect(() => {
		if (newSecret) {
			setCopied(copyToClipboard(newSecret));
		}
	}, [newSecret]);

	useKeyboard((key) => {
		// If showing secret, only Enter or Escape dismisses
		if (newSecret !== null) {
			if (
				key.name === "return" ||
				key.name === "enter" ||
				key.name === "escape"
			) {
				onDismissSecret();
			}
			return;
		}

		if (key.name === "escape") {
			onCancel();
			return;
		}

		if (key.name === "return" || key.name === "enter") {
			if (name.trim()) {
				onCreate(name.trim());
			}
			return;
		}

		if (key.name === "backspace" || key.name === "delete") {
			setName((prev) => prev.slice(0, -1));
			return;
		}

		// Printable characters
		if (key.sequence && key.sequence.length === 1 && !key.ctrl && !key.meta) {
			setName((prev) => prev + key.sequence);
		}
	});

	// ── Secret display state ────────────────────────────────────────────────
	if (newSecret !== null) {
		return (
			<box flexDirection="column" width="100%" height="100%" padding={2}>
				{/* Section title */}
				<box flexDirection="row">
					<text fg={theme.borderDim}>{"┌─"}</text>
					<text fg={theme.primary}>{" Admin "}</text>
					<text fg={theme.borderDim}>{"─"}</text>
					<text fg={theme.muted}>{" Key Created "}</text>
					<text fg={theme.borderDim}>{"─┐"}</text>
				</box>

				{/* Key name confirmation */}
				<box flexDirection="row" marginTop={1} paddingLeft={2}>
					<text fg={theme.muted}>{"key  "}</text>
					<text fg={theme.valueBright}>{newKeyName}</text>
					<text fg={theme.accentGreen}>{"  created"}</text>
				</box>

				{/* Warning box for secret */}
				<box
					flexDirection="column"
					marginTop={2}
					borderStyle="double"
					borderColor={theme.warning}
					paddingLeft={2}
					paddingRight={2}
					paddingTop={1}
					paddingBottom={1}
				>
					<box flexDirection="row">
						<text fg={theme.warning}>{"! WARNING  "}</text>
						<text fg={theme.dangerText}>
							{"This secret will NOT be shown again"}
						</text>
					</box>

					<box marginTop={1} flexDirection="row">
						<text fg={theme.muted}>{"secret  "}</text>
						<text fg={theme.secretBright}>{newSecret}</text>
					</box>

					{copied && (
						<box marginTop={1} flexDirection="row">
							<text fg={theme.accentGreen}>{"  copied to clipboard"}</text>
						</box>
					)}
					{!copied && (
						<box marginTop={1} flexDirection="row">
							<text fg={theme.dimmed}>
								{"  clipboard unavailable — copy manually"}
							</text>
						</box>
					)}
				</box>

				{/* Dismiss hint — very dim */}
				<box marginTop={2} paddingLeft={1}>
					<text fg={theme.borderDim}>{"└─ "}</text>
					<text fg={theme.dimmed}>{"press "}</text>
					<text fg={theme.labelDim}>{"Enter"}</text>
					<text fg={theme.dimmed}>{" or "}</text>
					<text fg={theme.labelDim}>{"Esc"}</text>
					<text fg={theme.dimmed}>{" to return to list"}</text>
					<text fg={theme.borderDim}>{" ─┘"}</text>
				</box>
			</box>
		);
	}

	// ── Input state ─────────────────────────────────────────────────────────
	return (
		<box flexDirection="column" width="100%" height="100%" padding={2}>
			{/* Section title */}
			<box flexDirection="row">
				<text fg={theme.borderDim}>{"┌─"}</text>
				<text fg={theme.primary}>{" Admin "}</text>
				<text fg={theme.borderDim}>{"─"}</text>
				<text fg={theme.muted}>{" Create API Key "}</text>
				<text fg={theme.borderDim}>{"─┐"}</text>
			</box>

			{/* Input field */}
			<box
				flexDirection="column"
				marginTop={2}
				borderStyle="single"
				borderColor={name.length > 0 ? theme.primary : theme.border}
				paddingLeft={2}
				paddingRight={2}
				paddingTop={1}
				paddingBottom={1}
			>
				<box flexDirection="row">
					<text fg={theme.labelDim}>{"key name  "}</text>
					<text fg={theme.valueBright}>{name}</text>
					<text fg={theme.primary}>{"_"}</text>
				</box>
			</box>

			{/* Error */}
			{error && (
				<box flexDirection="row" marginTop={1} paddingLeft={1}>
					<text fg={theme.error}>{"! "}</text>
					<text fg={theme.dangerText}>{error}</text>
				</box>
			)}

			{/* Loading */}
			{loading && (
				<box marginTop={1} paddingLeft={1}>
					<text fg={theme.muted}>{"  creating..."}</text>
				</box>
			)}

			{/* Spacer */}
			<box flexGrow={1} />

			{/* Footer */}
			<box flexDirection="row" paddingLeft={1}>
				<text fg={theme.borderDim}>{"└─ "}</text>
				<text fg={theme.shortcutBracket}>{"["}</text>
				<text fg={theme.shortcutKey}>{"Enter"}</text>
				<text fg={theme.shortcutBracket}>{"]"}</text>
				<text fg={theme.muted}>{" create  "}</text>
				<text fg={theme.shortcutBracket}>{"["}</text>
				<text fg={theme.shortcutKey}>{"Esc"}</text>
				<text fg={theme.shortcutBracket}>{"]"}</text>
				<text fg={theme.muted}>{" cancel"}</text>
				<text fg={theme.borderDim}>{" ─┘"}</text>
			</box>
		</box>
	);
}

/**
 * KeyListView — displays API keys in a table with keyboard navigation.
 *
 * Shortcuts:
 *   j / ArrowDown  — move selection down
 *   k / ArrowUp    — move selection up
 *   n              — create new key
 *   d              — delete selected key
 *   r              — refresh
 *   q              — quit
 */

import { useKeyboard } from "@opentui/react";
import { theme } from "../theme.js";
import type { ApiKey } from "./AdminApiClient.js";

// ============================================================================
// Types
// ============================================================================

export interface KeyListViewProps {
	endpoint: string;
	keys: ApiKey[];
	selectedIndex: number;
	loading: boolean;
	error: string | null;
	onSelect: (index: number) => void;
	onNew: () => void;
	onDelete: () => void;
	onRefresh: () => void;
	onQuit: () => void;
}

// ============================================================================
// Helpers
// ============================================================================

function formatDate(iso: string | null): string {
	if (!iso) return "never";
	const d = new Date(iso);
	return d.toLocaleDateString("en-US", {
		month: "short",
		day: "2-digit",
		year: "numeric",
	});
}

// ============================================================================
// Sub-components
// ============================================================================

/** btop-style footer shortcut item: [key] label */
function ShortcutItem({ letter, label }: { letter: string; label: string }) {
	return (
		<box flexDirection="row">
			<text fg={theme.shortcutBracket}>{"["}</text>
			<text fg={theme.shortcutKey}>{letter}</text>
			<text fg={theme.shortcutBracket}>{"]"}</text>
			<text fg={theme.muted}>{` ${label}  `}</text>
		</box>
	);
}

// ============================================================================
// Component
// ============================================================================

export function KeyListView({
	endpoint,
	keys,
	selectedIndex,
	loading,
	error,
	onSelect,
	onNew,
	onDelete,
	onRefresh,
	onQuit,
}: KeyListViewProps) {
	useKeyboard((key) => {
		if (key.name === "j" || key.name === "down") {
			onSelect(Math.min(selectedIndex + 1, keys.length - 1));
			return;
		}
		if (key.name === "k" || key.name === "up") {
			onSelect(Math.max(selectedIndex - 1, 0));
			return;
		}
		if (key.name === "n") {
			onNew();
			return;
		}
		if (key.name === "d" && keys.length > 0) {
			onDelete();
			return;
		}
		if (key.name === "r") {
			onRefresh();
			return;
		}
		if (key.name === "q") {
			onQuit();
			return;
		}
	});

	// Logo lines: CLAUDE part (orange) + MEM part (green)
	const logoLines = [
		[
			"   ██████╗██╗      █████╗ ██╗   ██╗██████╗ ███████╗",
			"███╗   ███╗███████╗███╗   ███╗",
		],
		[
			"  ██╔════╝██║     ██╔══██╗██║   ██║██╔══██╗██╔════╝",
			"████╗ ████║██╔════╝████╗ ████║",
		],
		[
			"  ██║     ██║     ███████║██║   ██║██║  ██║█████╗  ",
			"██╔████╔██║█████╗  ██╔████╔██║",
		],
		[
			"  ██║     ██║     ██╔══██║██║   ██║██║  ██║██╔══╝  ",
			"██║╚██╔╝██║██╔══╝  ██║╚██╔╝██║",
		],
		[
			"  ╚██████╗███████╗██║  ██║╚██████╔╝██████╔╝███████╗",
			"██║ ╚═╝ ██║███████╗██║ ╚═╝ ██║",
		],
		[
			"   ╚═════╝╚══════╝╚═╝  ╚═╝ ╚═════╝ ╚═════╝ ╚══════╝",
			"╚═╝     ╚═╝╚══════╝╚═╝     ╚═╝",
		],
	];

	const keyCount = keys.length;
	const countLabel = keyCount === 1 ? "1 key" : `${keyCount} keys`;

	// Column widths (characters)
	const COL_NAME = 20;
	const COL_PREF = 10;
	const COL_CREATED = 13;
	const COL_LASTUSED = 13;

	const headerRow =
		"NAME".padEnd(COL_NAME) +
		"PREFIX".padEnd(COL_PREF) +
		"CREATED".padEnd(COL_CREATED) +
		"LAST USED".padEnd(COL_LASTUSED) +
		"REQ";

	const dividerRow =
		"─".repeat(COL_NAME - 1).padEnd(COL_NAME) +
		"─".repeat(COL_PREF - 1).padEnd(COL_PREF) +
		"─".repeat(COL_CREATED - 1).padEnd(COL_CREATED) +
		"─".repeat(COL_LASTUSED - 1).padEnd(COL_LASTUSED) +
		"───";

	return (
		<box flexDirection="column" width="100%" height="100%">
			{/* Logo */}
			<box flexDirection="column" paddingTop={1} paddingBottom={0}>
				{logoLines.map((parts, i) => (
					<box key={i} flexDirection="row">
						<text fg="#e67e22">{parts[0]}</text>
						<text fg="#2ecc71">{parts[1]}</text>
					</box>
				))}
			</box>

			{/* btop-style titled header bar */}
			<box flexDirection="row" paddingLeft={1} paddingTop={1} paddingBottom={0}>
				<text fg={theme.borderDim}>{"┌─"}</text>
				<text fg={theme.primary}>{" Admin "}</text>
				<text fg={theme.borderDim}>{"─"}</text>
				<text fg={theme.muted}>{" API Keys "}</text>
				<text fg={theme.borderDim}>{"─"}</text>
				<text fg={theme.labelDim}>{` ${endpoint} `}</text>
				<text fg={theme.borderDim}>{"─"}</text>
				<text fg={theme.dimmed}>{` ${countLabel} `}</text>
				<text fg={theme.borderDim}>{"─┐"}</text>
			</box>

			{/* Column headers */}
			<box paddingLeft={3} paddingRight={2} paddingTop={1}>
				<text fg={theme.labelDim}>{`  ${headerRow}`}</text>
			</box>
			<box paddingLeft={3} paddingRight={2}>
				<text fg={theme.borderDim}>{`  ${dividerRow}`}</text>
			</box>

			{/* Error banner */}
			{error && (
				<box paddingLeft={3} paddingTop={1}>
					<text fg={theme.error}>{"  ! "}</text>
					<text fg={theme.dangerText}>{error}</text>
				</box>
			)}

			{/* Loading */}
			{loading && (
				<box paddingLeft={3} paddingTop={1}>
					<text fg={theme.muted}>{"  loading..."}</text>
				</box>
			)}

			{/* Empty state */}
			{!loading && keys.length === 0 && !error && (
				<box paddingLeft={3} paddingTop={1}>
					<text fg={theme.dimmed}>{"  No API keys — press "}</text>
					<text fg={theme.shortcutKey}>{"[n]"}</text>
					<text fg={theme.dimmed}>{" to create one."}</text>
				</box>
			)}

			{/* Key rows */}
			{keys.map((k, i) => {
				const isSelected = i === selectedIndex;
				const name = k.name.padEnd(COL_NAME).slice(0, COL_NAME);
				const prefix = k.prefix.padEnd(COL_PREF);
				const created = formatDate(k.createdAt).padEnd(COL_CREATED);
				const lastUsed = formatDate(k.lastUsedAt).padEnd(COL_LASTUSED);
				const requests = String(k.usage.total).padStart(3);

				if (isSelected) {
					return (
						<box
							key={k.id}
							paddingLeft={3}
							paddingRight={2}
							flexDirection="row"
						>
							<text fg={theme.primary}>{">"}</text>
							<text fg={theme.valueBright}> </text>
							<text fg={theme.primary}>{name}</text>
							<text fg={theme.accentCyan}>{prefix}</text>
							<text fg={theme.text}>{created}</text>
							<text fg={theme.muted}>{lastUsed}</text>
							<text fg={theme.valueBright}>{requests}</text>
						</box>
					);
				}

				return (
					<box key={k.id} paddingLeft={3} paddingRight={2} flexDirection="row">
						<text fg={theme.dimmed}> </text>
						<text fg={theme.text}> </text>
						<text fg={theme.text}>{name}</text>
						<text fg={theme.muted}>{prefix}</text>
						<text fg={theme.dimmed}>{created}</text>
						<text fg={theme.dimmed}>{lastUsed}</text>
						<text fg={theme.muted}>{requests}</text>
					</box>
				);
			})}

			{/* Spacer */}
			<box flexGrow={1} />

			{/* btop-style footer bar */}
			<box flexDirection="row" paddingLeft={1} paddingBottom={1}>
				<text fg={theme.borderDim}>{"└─ "}</text>
				<ShortcutItem letter="n" label="new" />
				<ShortcutItem letter="d" label="delete" />
				<ShortcutItem letter="r" label="refresh" />
				<ShortcutItem letter="j/k" label="navigate" />
				<ShortcutItem letter="q" label="quit" />
				<text fg={theme.borderDim}>{" ─┘"}</text>
			</box>
		</box>
	);
}

/**
 * Admin TUI Entry Point
 *
 * Starts the mnemex admin panel for API key management.
 * Mirrors the pattern of src/tui/index.tsx.
 */

import { createCliRenderer } from "@opentui/core";
import { createRoot } from "@opentui/react";
import { AdminApp } from "./AdminApp.js";

// ============================================================================
// Types
// ============================================================================

export interface AdminOptions {
	/** Cloud server URL, e.g. "https://cloud.mnemex.dev" */
	endpoint: string;
	/** Master API key value */
	masterKey: string;
}

// ============================================================================
// Entry
// ============================================================================

export async function startAdminTUI(options: AdminOptions): Promise<void> {
	if (!process.stdout.isTTY) {
		console.error("mnemex admin requires a TTY terminal");
		process.exit(1);
	}

	const renderer = await createCliRenderer({
		exitOnCtrlC: true,
		screenMode: "main-screen",
		useMouse: false,
		onDestroy: () => {
			process.exit(0);
		},
	});

	const quit = () => {
		root.unmount();
		renderer.destroy();
	};

	const root = createRoot(renderer);
	root.render(
		<AdminApp
			endpoint={options.endpoint}
			masterKey={options.masterKey}
			quit={quit}
		/>,
	);
}

