/**
 * TUI App Context
 *
 * Provides shared state for the entire TUI application:
 * - FileTracker singleton
 * - Active tab
 * - Navigation history (for graph drill-in/back)
 * - Error state
 * - Last MCP activity (for StatusBar monitor indicator)
 */

import { existsSync, mkdirSync, statSync } from "node:fs";
import { join } from "node:path";
import {
	createContext,
	type ReactNode,
	useCallback,
	useContext,
	useRef,
	useState,
} from "react";
import { getIndexVersion, needsUpgrade } from "../core/index-version.js";
import { Indexer } from "../core/indexer.js";
import { FileTracker } from "../core/tracker.js";
import { ProgressStore } from "../output/progress-store.js";
import {
	type ActivityRecord,
	useActivityMonitor,
} from "./hooks/useActivityMonitor.js";

// ============================================================================
// Types
// ============================================================================

export type TabId = "search" | "map" | "graph" | "analysis" | "doctor";

export interface AppContextValue {
	/** FileTracker singleton for the current project */
	tracker: FileTracker;
	/** The project root path */
	projectPath: string;
	/** Currently active tab */
	activeTab: TabId;
	/** Switch to a different tab */
	setActiveTab: (tab: TabId) => void;
	/** Navigation history for graph drill-in */
	navHistory: string[];
	/** Push a symbol name to navigation history */
	pushNav: (symbolName: string) => void;
	/** Go back in navigation history */
	popNav: () => string | undefined;
	/** Current error message, if any */
	error: string | null;
	/** Set global error message */
	setError: (msg: string | null) => void;
	/** Whether help overlay is visible */
	showHelp: boolean;
	/** Toggle help overlay */
	toggleHelp: () => void;
	/** Whether an input field is focused (suppresses global shortcuts) */
	inputFocused: boolean;
	/** Set input focus state */
	setInputFocused: (focused: boolean) => void;
	/** Index format version (1 = legacy, 2 = with code units) */
	indexVersion: number;
	/** Cleanly shut down the TUI (unmount + renderer destroy) */
	quit: () => void;
	/** Most recent MCP activity record — used by StatusBar indicator */
	lastActivity: ActivityRecord | null;
	/** Whether running in passive monitor mode (affects StatusBar hints) */
	monitorMode: boolean;
	/** True when no index exists or the index is outdated */
	indexNeeded: boolean;
	/** Why the index is needed: "missing" or "outdated" */
	indexReason: "missing" | "outdated" | null;
	/** True while indexing is actively running */
	indexing: boolean;
	/** ProgressStore for the active indexing run (null when not indexing) */
	progressStore: ProgressStore | null;
	/** Trigger the indexing process */
	startIndexing: () => void;
}

// ============================================================================
// Context
// ============================================================================

const AppContext = createContext<AppContextValue | null>(null);

// ============================================================================
// Index Detection
// ============================================================================

/**
 * Returns why the index is needed, or null if the index is ready.
 * Checks for the DB file existence/size and version.
 */
function checkIndexReason(projectPath: string): "missing" | "outdated" | null {
	const dbPath = join(projectPath, ".mnemex", "index.db");
	if (!existsSync(dbPath)) return "missing";
	try {
		const stat = statSync(dbPath);
		if (stat.size < 1024) return "missing"; // basically empty
	} catch {
		return "missing";
	}
	if (needsUpgrade(projectPath)) return "outdated";
	return null;
}

// ============================================================================
// Provider
// ============================================================================

export interface AppProviderProps {
	projectPath: string;
	quit: () => void;
	monitorMode?: boolean;
	children: ReactNode;
}

export function AppProvider({
	projectPath,
	quit,
	monitorMode = false,
	children,
}: AppProviderProps) {
	const [activeTab, setActiveTab] = useState<TabId>("search");
	const [navHistory, setNavHistory] = useState<string[]>([]);
	const [error, setError] = useState<string | null>(null);
	const [showHelp, setShowHelp] = useState(false);
	const [inputFocused, setInputFocused] = useState(false);
	const [indexVersion, setIndexVersion] = useState(() =>
		getIndexVersion(projectPath),
	);
	const [lastActivity, setLastActivity] = useState<ActivityRecord | null>(null);
	const [indexReason, setIndexReason] = useState(() =>
		checkIndexReason(projectPath),
	);
	const indexNeeded = indexReason !== null;
	const [indexing, setIndexing] = useState(false);
	const [progressStore, setProgressStore] = useState<ProgressStore | null>(
		null,
	);
	// Keep a stable ref to avoid stale closure issues in startIndexing
	const progressStoreRef = useRef<ProgressStore | null>(null);

	// Create FileTracker singleton — memoized so it survives re-renders.
	// Without memoization, every state change creates a new tracker instance,
	// which cascades through useCallback/useEffect dependencies and causes
	// useActivityMonitor to re-run (truncating JSONL + resetting byte offsets).
	const [tracker] = useState(() => {
		const dbDir = join(projectPath, ".mnemex");
		if (!existsSync(dbDir)) {
			mkdirSync(dbDir, { recursive: true });
		}
		const dbPath = join(dbDir, "index.db");
		return new FileTracker(dbPath, projectPath);
	});

	const pushNav = useCallback((symbolName: string) => {
		setNavHistory((prev: string[]) => [...prev, symbolName]);
	}, []);

	const popNav = useCallback((): string | undefined => {
		let popped: string | undefined;
		setNavHistory((prev: string[]) => {
			const copy = [...prev];
			popped = copy.pop();
			return copy;
		});
		return popped;
	}, []);

	const toggleHelp = useCallback(() => {
		setShowHelp((prev: boolean) => !prev);
	}, []);

	const startIndexing = useCallback(() => {
		if (indexing) return;

		const store = new ProgressStore();
		progressStoreRef.current = store;
		setProgressStore(store);
		setIndexing(true);

		const indexer = new Indexer({
			projectPath,
			onProgress: (current, total, detail, inProgress) => {
				store.update(current, total, detail, inProgress);
			},
		});

		indexer
			.index(true)
			.then(() => {
				store.finish();
				// Re-read the version from config after indexing completes
				setIndexVersion(getIndexVersion(projectPath));
				setIndexReason(null);
				setIndexing(false);
			})
			.catch((err: unknown) => {
				store.finish();
				setIndexing(false);
				setError(err instanceof Error ? err.message : "Indexing failed");
			});
	}, [indexing, projectPath]);

	// In UI mode, activity monitor only updates the StatusBar indicator
	const handleActivity = useCallback((record: ActivityRecord) => {
		setLastActivity(record);
	}, []);

	// Mount the activity monitor (feeds StatusBar in UI mode)
	useActivityMonitor(projectPath, tracker, handleActivity);

	const value: AppContextValue = {
		tracker,
		projectPath,
		activeTab,
		setActiveTab,
		navHistory,
		pushNav,
		popNav,
		error,
		setError,
		showHelp,
		toggleHelp,
		inputFocused,
		setInputFocused,
		indexVersion,
		quit,
		lastActivity,
		monitorMode,
		indexNeeded,
		indexReason,
		indexing,
		progressStore,
		startIndexing,
	};

	return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

// ============================================================================
// Hook
// ============================================================================

export function useAppContext(): AppContextValue {
	const ctx = useContext(AppContext);
	if (!ctx) {
		throw new Error("useAppContext must be used inside AppProvider");
	}
	return ctx;
}

/**
 * useActivityMonitor Hook
 *
 * Watches activity.jsonl for notifications from the MCP server and polls
 * SQLite for full activity details. This is the TUI side of the self-recording
 * activity monitor system.
 *
 * Design:
 *   - activity.jsonl is a "doorbell" — it signals that SQLite has a new row.
 *   - TUI truncates activity.jsonl on startup before watching it.
 *   - MCP server is append-only; TUI owns truncation.
 *   - 500ms polling fallback for fs.watch reliability on all platforms.
 *   - Startup replay deferred by one tick (setTimeout) so child view effects
 *     can register their handlers before replay fires.
 */

import { existsSync, statSync, watch, writeFileSync } from "node:fs";
import { join } from "node:path";
import { useCallback, useEffect, useRef } from "react";
import type { ActivityRow, FileTracker } from "../../core/tracker.js";

// ============================================================================
// Types
// ============================================================================

export interface ActivityRecord {
	id: number;
	type: string;
	metadata: Record<string, unknown>;
	timestamp: string;
}

// ============================================================================
// Hook
// ============================================================================

export function useActivityMonitor(
	projectPath: string,
	tracker: FileTracker | null,
	onActivity: (record: ActivityRecord) => void,
): void {
	const lastSeenIdRef = useRef(0);
	const byteOffsetRef = useRef(0);
	const onActivityRef = useRef(onActivity);
	onActivityRef.current = onActivity;

	// Read new activities from SQLite since lastSeenId
	const pollActivities = useCallback(() => {
		if (!tracker) return;
		try {
			const rows: ActivityRow[] = tracker.getActivity(lastSeenIdRef.current);
			for (const row of rows) {
				try {
					const record: ActivityRecord = {
						id: row.id,
						type: row.type,
						metadata: JSON.parse(row.metadata) as Record<string, unknown>,
						timestamp: row.timestamp,
					};
					onActivityRef.current(record);
				} catch {
					// Skip malformed row but don't lose other events
				}
				// Always advance cursor — even for malformed rows, to avoid
				// re-processing the same broken record on every poll cycle
				lastSeenIdRef.current = row.id;
			}
		} catch {
			// Silent — DB may be locked by MCP server momentarily
		}
	}, [tracker]);

	// Check activity.jsonl for new bytes — use file size as a signal
	const readNotifications = useCallback(() => {
		const jsonlPath = join(projectPath, ".mnemex", "activity.jsonl");
		try {
			const stat = statSync(jsonlPath);
			if (stat.size < byteOffsetRef.current) {
				// File was truncated (shouldn't happen since TUI owns truncation,
				// but handle it gracefully)
				byteOffsetRef.current = 0;
			}
			if (stat.size <= byteOffsetRef.current) {
				return; // No new data
			}
			// New bytes arrived — update offset and poll SQLite for new rows
			byteOffsetRef.current = stat.size;
			pollActivities();
		} catch {
			// File doesn't exist yet — that's fine, polling will catch up
		}
	}, [projectPath, pollActivities]);

	// Main effect: set up file watch + polling fallback + startup replay
	useEffect(() => {
		const jsonlPath = join(projectPath, ".mnemex", "activity.jsonl");

		// Truncate activity.jsonl on startup (TUI owns truncation, MCP is append-only)
		try {
			if (existsSync(jsonlPath)) {
				writeFileSync(jsonlPath, "");
			}
		} catch {
			// Silent — file may not be writable; not critical
		}
		byteOffsetRef.current = 0;

		// Deferred startup replay: load recent activity from SQLite.
		// Defer by one tick so child view effects have registered before replay.
		const replayTimer = setTimeout(() => pollActivities(), 0);

		// Watch the .mnemex directory for changes to activity.jsonl
		let watcher: ReturnType<typeof watch> | null = null;
		try {
			const dir = join(projectPath, ".mnemex");
			if (existsSync(dir)) {
				watcher = watch(dir, (_eventType, filename) => {
					if (filename === "activity.jsonl") {
						readNotifications();
					}
				});
			}
		} catch {
			// Silent — directory may not exist; polling fallback covers this
		}

		// 500ms polling fallback for fs.watch reliability
		const pollInterval = setInterval(readNotifications, 500);

		return () => {
			clearTimeout(replayTimer);
			watcher?.close();
			clearInterval(pollInterval);
		};
	}, [projectPath, pollActivities, readNotifications]);

	// Prune old activity rows every 5 minutes to prevent unbounded growth
	useEffect(() => {
		if (!tracker) return;
		const pruneInterval = setInterval(
			() => {
				try {
					tracker.pruneActivity(200);
				} catch {
					// Silent — pruning is a maintenance operation
				}
			},
			5 * 60 * 1000,
		);
		return () => clearInterval(pruneInterval);
	}, [tracker]);
}

/**
 * useAnalysis Hook
 *
 * Manages code analysis state: dead code, test gaps, and impact analysis.
 */

import { useCallback, useEffect, useState } from "react";
import {
	createCodeAnalyzer,
	type DeadCodeResult,
	type ImpactAnalysis,
	type TestGapResult,
} from "../../core/analysis/analyzer.js";
import type { FileTracker } from "../../core/tracker.js";

// ============================================================================
// Types
// ============================================================================

export type AnalysisTab = "dead-code" | "test-gaps" | "impact";

export interface UseAnalysisReturn {
	deadCode: DeadCodeResult[];
	testGaps: TestGapResult[];
	impact: ImpactAnalysis | null;
	activeTab: AnalysisTab;
	setActiveTab: (tab: AnalysisTab) => void;
	loading: boolean;
	error: string | null;
	analyzeImpact: (symbolName: string, maxDepth?: number) => void;
	refreshDeadCode: () => void;
	refreshTestGaps: () => void;
}

// ============================================================================
// Hook
// ============================================================================

export function useAnalysis(tracker: FileTracker): UseAnalysisReturn {
	const [deadCode, setDeadCode] = useState<DeadCodeResult[]>([]);
	const [testGaps, setTestGaps] = useState<TestGapResult[]>([]);
	const [impact, setImpact] = useState<ImpactAnalysis | null>(null);
	const [activeTab, setActiveTab] = useState<AnalysisTab>("dead-code");
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [deadCodeTick, setDeadCodeTick] = useState(0);
	const [testGapsTick, setTestGapsTick] = useState(0);

	// Load dead code on mount/refresh
	const loadDeadCode = useCallback(async () => {
		setLoading(true);
		setError(null);
		try {
			const analyzer = createCodeAnalyzer(tracker);
			const results = analyzer.findDeadCode({ limit: 100 });
			setDeadCode(results);
		} catch (err) {
			setError(err instanceof Error ? err.message : String(err));
		} finally {
			setLoading(false);
		}
	}, [tracker, deadCodeTick]);

	// Load test gaps on mount/refresh
	const loadTestGaps = useCallback(async () => {
		setLoading(true);
		setError(null);
		try {
			const analyzer = createCodeAnalyzer(tracker);
			const results = analyzer.findTestGaps({ limit: 50 });
			setTestGaps(results);
		} catch (err) {
			setError(err instanceof Error ? err.message : String(err));
		} finally {
			setLoading(false);
		}
	}, [tracker, testGapsTick]);

	useEffect(() => {
		if (activeTab === "dead-code") {
			loadDeadCode();
		} else if (activeTab === "test-gaps") {
			loadTestGaps();
		}
	}, [activeTab, loadDeadCode, loadTestGaps]);

	const analyzeImpact = useCallback(
		(symbolName: string, maxDepth = 10) => {
			setLoading(true);
			setError(null);
			try {
				const analyzer = createCodeAnalyzer(tracker);
				// Find the symbol first, then analyze impact
				const symbol = analyzer.findSymbolForImpact(symbolName);
				if (!symbol) {
					setError(`Symbol not found: ${symbolName}`);
					setLoading(false);
					return;
				}
				const result = analyzer.findImpact(symbol.id, { maxDepth });
				setImpact(result);
			} catch (err) {
				setError(err instanceof Error ? err.message : String(err));
			} finally {
				setLoading(false);
			}
		},
		[tracker],
	);

	const refreshDeadCode = useCallback(() => {
		setDeadCodeTick((n: number) => n + 1);
	}, []);

	const refreshTestGaps = useCallback(() => {
		setTestGapsTick((n: number) => n + 1);
	}, []);

	return {
		deadCode,
		testGaps,
		impact,
		activeTab,
		setActiveTab,
		loading,
		error,
		analyzeImpact,
		refreshDeadCode,
		refreshTestGaps,
	};
}

/**
 * useDoctor Hook
 *
 * Manages doctor diagnostics state for context file analysis.
 */

import { useCallback, useEffect, useState } from "react";
import {
	analyzeContextFile,
	scanForContextFiles,
} from "../../core/doctor/index.js";
import type {
	ContextFile,
	ContextFileDiagnosis,
} from "../../core/doctor/types.js";

// ============================================================================
// Types
// ============================================================================

export interface DoctorDiagnostics {
	files: ContextFile[];
	diagnoses: ContextFileDiagnosis[];
	overallHealth: number;
}

export interface UseDoctorReturn {
	diagnostics: DoctorDiagnostics | null;
	loading: boolean;
	error: string | null;
	selectedFile: string | null;
	setSelectedFile: (path: string | null) => void;
	refresh: () => void;
}

// ============================================================================
// Hook
// ============================================================================

export function useDoctor(projectPath: string): UseDoctorReturn {
	const [diagnostics, setDiagnostics] = useState<DoctorDiagnostics | null>(
		null,
	);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [selectedFile, setSelectedFile] = useState<string | null>(null);
	const [refreshTick, setRefreshTick] = useState(0);

	const loadDiagnostics = useCallback(async () => {
		setLoading(true);
		setError(null);

		try {
			const files = scanForContextFiles(projectPath);

			const diagnoses: ContextFileDiagnosis[] = files.map((file) =>
				analyzeContextFile(file, null, projectPath),
			);

			const overallHealth =
				diagnoses.length > 0
					? diagnoses.reduce((sum, d) => sum + d.overallScore, 0) /
						diagnoses.length
					: 0;

			setDiagnostics({
				files,
				diagnoses,
				overallHealth,
			});

			// Auto-select first file
			if (!selectedFile && files.length > 0) {
				setSelectedFile(files[0]?.path ?? null);
			}
		} catch (err) {
			setError(err instanceof Error ? err.message : String(err));
		} finally {
			setLoading(false);
		}
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [projectPath, refreshTick]);

	useEffect(() => {
		loadDiagnostics();
	}, [loadDiagnostics]);

	const refresh = useCallback(() => {
		setRefreshTick((n: number) => n + 1);
	}, []);

	return {
		diagnostics,
		loading,
		error,
		selectedFile,
		setSelectedFile,
		refresh,
	};
}

/**
 * useGraph Hook
 *
 * Manages the symbol reference graph state.
 * Supports drill-in navigation with history (back/forward).
 */

import { useCallback, useState } from "react";
import { createReferenceGraphManager } from "../../core/reference-graph.js";
import type { FileTracker } from "../../core/tracker.js";
import type { SymbolDefinition } from "../../types.js";

// ============================================================================
// Types
// ============================================================================

export interface UseGraphReturn {
	focusedSymbol: SymbolDefinition | null;
	callers: SymbolDefinition[];
	callees: SymbolDefinition[];
	loading: boolean;
	error: string | null;
	/** Navigate to a symbol by name */
	focusSymbol: (name: string) => Promise<void>;
	/** Go back in history */
	goBack: () => void;
	/** Go forward in history */
	goForward: () => void;
	canGoBack: boolean;
	canGoForward: boolean;
	historyLength: number;
}

// ============================================================================
// Hook
// ============================================================================

export function useGraph(tracker: FileTracker): UseGraphReturn {
	const [navHistory, setNavHistory] = useState<SymbolDefinition[]>([]);
	const [navIndex, setNavIndex] = useState(-1);
	const [callers, setCallers] = useState<SymbolDefinition[]>([]);
	const [callees, setCallees] = useState<SymbolDefinition[]>([]);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);

	const loadSymbolInfo = useCallback(
		async (symbol: SymbolDefinition) => {
			setLoading(true);
			setError(null);
			try {
				const graphManager = createReferenceGraphManager(tracker);
				await graphManager.buildGraph();

				// Get callers and callees by symbol ID
				const callerSymbols = graphManager.getCallers(symbol.id);
				const calleeSymbols = graphManager.getCallees(symbol.id);

				setCallers(callerSymbols);
				setCallees(calleeSymbols);
			} catch (err) {
				setError(err instanceof Error ? err.message : String(err));
			} finally {
				setLoading(false);
			}
		},
		[tracker],
	);

	const focusedSymbol = navIndex >= 0 ? (navHistory[navIndex] ?? null) : null;

	const focusSymbol = useCallback(
		async (name: string) => {
			setLoading(true);
			setError(null);

			try {
				const graphManager = createReferenceGraphManager(tracker);
				await graphManager.buildGraph();
				const found = graphManager.findSymbol(name);

				if (!found) {
					setError(`Symbol not found: ${name}`);
					setLoading(false);
					return;
				}

				// Truncate forward history when navigating to a new symbol
				setNavHistory((prev: SymbolDefinition[]) => {
					const newHistory = prev.slice(0, navIndex + 1);
					return [...newHistory, found];
				});
				setNavIndex((prev: number) => prev + 1);

				await loadSymbolInfo(found);
			} catch (err) {
				setError(err instanceof Error ? err.message : String(err));
				setLoading(false);
			}
		},
		[navIndex, loadSymbolInfo, tracker],
	);

	const goBack = useCallback(() => {
		if (navIndex <= 0) return;
		const newIndex = navIndex - 1;
		setNavIndex(newIndex);
		const symbol = navHistory[newIndex];
		if (symbol) {
			loadSymbolInfo(symbol);
		}
	}, [navIndex, navHistory, loadSymbolInfo]);

	const goForward = useCallback(() => {
		if (navIndex >= navHistory.length - 1) return;
		const newIndex = navIndex + 1;
		setNavIndex(newIndex);
		const symbol = navHistory[newIndex];
		if (symbol) {
			loadSymbolInfo(symbol);
		}
	}, [navIndex, navHistory, loadSymbolInfo]);

	return {
		focusedSymbol,
		callers,
		callees,
		loading,
		error,
		focusSymbol,
		goBack,
		goForward,
		canGoBack: navIndex > 0,
		canGoForward: navIndex < navHistory.length - 1,
		historyLength: navHistory.length,
	};
}

/**
 * useRepoMap Hook
 *
 * Loads and manages the structured repository map.
 * Supports filtering and expanding/collapsing file paths.
 */

import { useCallback, useEffect, useState } from "react";
import { createRepoMapGenerator } from "../../core/repo-map.js";
import type { FileTracker } from "../../core/tracker.js";
import type { RepoMapEntry } from "../../types.js";

// ============================================================================
// Types
// ============================================================================

export interface UseRepoMapReturn {
	entries: RepoMapEntry[];
	filter: string;
	setFilter: (f: string) => void;
	expandedPaths: Set<string>;
	togglePath: (path: string) => void;
	loading: boolean;
	error: string | null;
	refresh: () => void;
}

// ============================================================================
// Hook
// ============================================================================

export function useRepoMap(tracker: FileTracker): UseRepoMapReturn {
	const [entries, setEntries] = useState<RepoMapEntry[]>([]);
	const [filter, setFilter] = useState("");
	const [expandedPaths, setExpandedPaths] = useState<Set<string>>(new Set());
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [refreshTick, setRefreshTick] = useState(0);

	const loadMap = useCallback(async () => {
		setLoading(true);
		setError(null);

		try {
			const generator = createRepoMapGenerator(tracker);
			const allEntries = generator.generateStructured({
				pathPattern: filter || undefined,
				topNByPagerank: 5000,
			});
			setEntries(allEntries);
		} catch (err) {
			setError(err instanceof Error ? err.message : String(err));
		} finally {
			setLoading(false);
		}
	}, [tracker, filter, refreshTick]);

	useEffect(() => {
		loadMap();
	}, [loadMap]);

	const togglePath = useCallback((path: string) => {
		setExpandedPaths((prev: Set<string>) => {
			const next = new Set(prev);
			if (next.has(path)) {
				next.delete(path);
			} else {
				next.add(path);
			}
			return next;
		});
	}, []);

	const refresh = useCallback(() => {
		setRefreshTick((n: number) => n + 1);
	}, []);

	return {
		entries,
		filter,
		setFilter,
		expandedPaths,
		togglePath,
		loading,
		error,
		refresh,
	};
}

/**
 * useSearch Hook
 *
 * Manages semantic search state with debouncing.
 * Lazy-loads the indexer on first search to avoid startup overhead.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import type { SearchResult } from "../../types.js";

// ============================================================================
// Types
// ============================================================================

export type SortOrder = "score" | "file" | "name";

export interface UseSearchReturn {
	query: string;
	setQuery: (q: string) => void;
	results: SearchResult[];
	loading: boolean;
	error: string | null;
	selectedIndex: number;
	setSelectedIndex: (idx: number) => void;
	expandedIndex: number | null;
	toggleExpanded: (idx: number) => void;
	sortOrder: SortOrder;
	setSortOrder: (order: SortOrder) => void;
	language: string | null;
	setLanguage: (lang: string | null) => void;
}

// ============================================================================
// Hook
// ============================================================================

export function useSearch(projectPath: string): UseSearchReturn {
	const [query, setQuery] = useState("");
	const [results, setResults] = useState<SearchResult[]>([]);
	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [selectedIndex, setSelectedIndex] = useState(0);
	const [expandedIndex, setExpandedIndex] = useState<number | null>(null);
	const [sortOrder, setSortOrder] = useState<SortOrder>("score");
	const [language, setLanguage] = useState<string | null>(null);

	// Keep reference to debounce timer
	const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

	// Perform search
	const performSearch = useCallback(
		async (q: string) => {
			if (!q.trim()) {
				setResults([]);
				setLoading(false);
				return;
			}

			setLoading(true);
			setError(null);

			try {
				// Lazy-load the indexer to avoid loading LanceDB at startup
				const { createIndexer } = await import("../../core/indexer.js");
				const indexer = createIndexer({ projectPath });
				const rawResults = await indexer.search(q, {
					limit: 50,
					language: language ?? undefined,
				});

				// Sort results
				const sorted = [...rawResults];
				if (sortOrder === "file") {
					sorted.sort((a, b) =>
						a.chunk.filePath.localeCompare(b.chunk.filePath),
					);
				} else if (sortOrder === "name") {
					sorted.sort((a, b) =>
						(a.chunk.name ?? "").localeCompare(b.chunk.name ?? ""),
					);
				}
				// "score" order is default from the indexer

				setResults(sorted);
				setSelectedIndex(0);
			} catch (err) {
				setError(err instanceof Error ? err.message : String(err));
				setResults([]);
			} finally {
				setLoading(false);
			}
		},
		[projectPath, language, sortOrder],
	);

	// Debounce search on query change
	useEffect(() => {
		if (debounceTimer.current) {
			clearTimeout(debounceTimer.current);
		}

		debounceTimer.current = setTimeout(() => {
			performSearch(query);
		}, 150);

		return () => {
			if (debounceTimer.current) {
				clearTimeout(debounceTimer.current);
			}
		};
	}, [query, performSearch]);

	const toggleExpanded = useCallback((idx: number) => {
		setExpandedIndex((prev: number | null) => (prev === idx ? null : idx));
	}, []);

	return {
		query,
		setQuery,
		results,
		loading,
		error,
		selectedIndex,
		setSelectedIndex,
		expandedIndex,
		toggleExpanded,
		sortOrder,
		setSortOrder,
		language,
		setLanguage,
	};
}

/**
 * TUI Entry Point
 *
 * Initializes the terminal renderer and mounts the React root.
 */

import { resolve } from "node:path";
import { createCliRenderer } from "@opentui/core";
import { createRoot } from "@opentui/react";
import { App } from "./App.js";
import { MonitorApp } from "./MonitorApp.js";

// ============================================================================
// Entry Function
// ============================================================================

/** Alias for startTUI – used by CLI handler */
export async function startTui(projectPath?: string): Promise<void> {
	return startTUI(projectPath);
}

export async function startTUI(projectPath?: string): Promise<void> {
	// Ensure we have a TTY
	if (!process.stdout.isTTY) {
		console.error("mnemex tui requires a TTY terminal");
		process.exit(1);
	}

	const resolvedPath = resolve(projectPath ?? process.cwd());

	// Create terminal renderer
	// OpenTUI handles exit signals (SIGINT, SIGTERM, etc.) internally via exitOnCtrlC
	// and its own signal handlers, which call renderer.destroy(). The Zig native
	// destroyRenderer runs performShutdownSequence to properly disable mouse tracking,
	// alternate screen, etc. The onDestroy callback fires after all native cleanup
	// is complete, so process.exit(0) here is safe.
	const renderer = await createCliRenderer({
		exitOnCtrlC: true,
		screenMode: "alternate-screen",
		onDestroy: () => {
			process.exit(0);
		},
	});

	// Quit callback for the app to trigger clean shutdown (e.g. pressing 'q').
	// Unmounts React tree then destroys the renderer, which triggers the full
	// Zig native cleanup (mouse tracking disable, alternate screen exit, etc.)
	// before onDestroy fires process.exit(0).
	const quit = () => {
		root.unmount();
		renderer.destroy();
	};

	// Create React root and render App
	const root = createRoot(renderer);
	root.render(<App projectPath={resolvedPath} quit={quit} />);
}

// ============================================================================
// Monitor Mode Entry
// ============================================================================

/** Start monitor mode — passive display of MCP activity */
export async function startMonitor(projectPath?: string): Promise<void> {
	if (!process.stdout.isTTY) {
		console.error("mnemex monitor requires a TTY terminal");
		process.exit(1);
	}

	const resolvedPath = resolve(projectPath ?? process.cwd());

	const renderer = await createCliRenderer({
		exitOnCtrlC: true,
		screenMode: "alternate-screen",
		onDestroy: () => {
			process.exit(0);
		},
	});

	const quit = () => {
		root.unmount();
		renderer.destroy();
	};

	const root = createRoot(renderer);
	root.render(<MonitorApp projectPath={resolvedPath} quit={quit} />);
}

