			setSelectedIndex(0);
			return;
		}
		if (key.name === "2") {
			setSelectedIndex(1);
			return;
		}
		if (key.name === "3") {
			setSelectedIndex(2);
			return;
		}
		if (key.name === "return" || key.name === "enter") {
			const selected = SCOPES[selectedIndex];
			if (selected) {
				onUpdate({ scope: selected.scope });
				onNext();
			}
			return;
		}
		if (key.name === "escape") {
			onBack();
			return;
		}
		if (key.name === "q") {
			onQuit();
			return;
		}
	});

	const selected = SCOPES[selectedIndex];

	return (
		<box flexDirection="column" width="100%" height="100%">
