				</text>
			</box>

			{/* Scope list */}
			<box flexDirection="column" paddingLeft={3} paddingTop={2}>
				{SCOPES.map((opt, i) => {
					const isSelected = i === selectedIndex;
					return (
						<box key={opt.scope} flexDirection="column" marginBottom={1}>
							<box flexDirection="row">
								<text fg={isSelected ? theme.primary : theme.dimmed}>
									{isSelected ? "> " : "  "}
								</text>
								<text fg={isSelected ? theme.valueBright : theme.text}>
									{`[${i + 1}] ${opt.label}`}
								</text>
							</box>
							{isSelected && (
								<box flexDirection="column" paddingLeft={6}>
									<box>
										<text fg={theme.dimmed}>{opt.description}</text>
									</box>
									<box marginTop={1}>
										<text fg={theme.labelDim}>{"Files to write:"}</text>
									</box>
									{opt.files.map((f, fi) => (
										<box key={fi} flexDirection="row">
											<text fg={theme.accentCyan}>{"  • "}</text>
											<text fg={theme.muted}>{f}</text>
										</box>
									))}
								</box>
							)}
						</box>
					);
				})}
			</box>

			{/* Merge notice */}
			{wizardState.projectConfigExists &&
				selected &&
				(selected.scope === "project" || selected.scope === "both") && (
					<box
						flexDirection="column"
						paddingLeft={3}
						paddingTop={1}
						marginLeft={2}
						borderStyle="single"
						borderColor={theme.warning}
						paddingRight={2}
						paddingBottom={1}
					>
						<box flexDirection="row">
							<text fg={theme.warning}>{"! "}</text>
							<text fg={theme.dangerText}>
								{"Existing project config found"}
							</text>
						</box>
						<box>
							<text fg={theme.muted}>
								{"Settings will be merged with existing values."}
							</text>
						</box>
					</box>
				)}

			{/* Spacer */}
			<box flexGrow={1} />

			{/* Footer */}
			<box flexDirection="row" paddingLeft={1} paddingBottom={1}>
				<text fg={theme.borderDim}>{"└─ "}</text>
				<ShortcutItem letter="1/2/3" label="select" />
				<ShortcutItem letter="Enter" label="confirm" />
				<ShortcutItem letter="Esc" label="back" />
				<ShortcutItem letter="q" label="quit" />
				<text fg={theme.borderDim}>{" ─┘"}</text>
			</box>
		</box>
	);
}

/**
 * Setup TUI Wizard Types
 *
 * All wizard state, step definitions, and shared screen props.
 */

import type { EmbeddingProvider } from "../../types.js";
import type { HardwareProfile } from "./hardware.js";

// ============================================================================
// Wizard Step and Mode Types
// ============================================================================

/**
 * All valid screen names for the wizard history stack.
 */
export type WizardStep =
	| "mode-select"
	| "hardware-detect"
	| "provider-select"
	| "model-select"
	| "cloud-warning"
	| "cloud-setup"
	| "enrichment-setup"
	| "scope-select"
	| "review"
	| "saving"
	| "done";

/** Deployment mode chosen on the first screen. */
export type DeploymentMode = "local" | "shared" | "full-cloud";

/** Scope for config file writes. */
export type ConfigScope = "global" | "project" | "both";

// ============================================================================
// Wizard State
// ============================================================================

/**
 * Complete wizard state — single object, passed down and updated via onUpdate.
 * All fields are optional or have sensible defaults. Filled progressively.
 */
export interface WizardState {
	// Mode
	mode: DeploymentMode | null;

	// Hardware (Local mode)
	hardware: HardwareProfile | "detecting" | null;

	// Embedding Provider (Local + Shared modes)
	provider: EmbeddingProvider | null;
	ollamaEndpoint: string;
	lmstudioEndpoint: string;
	localEndpoint: string;
	model: string;
	pullProgress: string | null;
	pullComplete: boolean;

	// Cloud (Shared + Full Cloud modes)
	cloudEndpoint: string;
	cloudApiKey: string;
	orgSlug: string;
	repoSlug: string;

	// Enrichment (All modes)
	llm: string | null;
	llmApiKey: string | null;
	enrichmentSkipped: boolean;
	llmEndpoint: string | null;

	// Scope
	scope: ConfigScope;
	mergeExisting: boolean;
	projectConfigExists: boolean;

	// Post-save
	runIndexAfterSave: boolean | null;
}

// ============================================================================
// Screen Props
// ============================================================================

/** Props shared by all screen components. */
export interface ScreenProps {
	wizardState: WizardState;
	onUpdate: (partial: Partial<WizardState>) => void;
	onNext: (override?: WizardStep) => void;
	onBack: () => void;
	onQuit: () => void;
}

