	lmstudioEndpoint: "http://localhost:1234/v1",
	localEndpoint: "",
	model: "",
	pullProgress: null,
	pullComplete: false,
	cloudEndpoint: "https://mem.madappgang.com",
	cloudApiKey: "",
	orgSlug: "",
	repoSlug: "",
	llm: "cc/sonnet",
	llmApiKey: null,
	enrichmentSkipped: false,
	llmEndpoint: null,
	scope: "global",
	mergeExisting: true,
	projectConfigExists: false,
	runIndexAfterSave: null,
};

/** Mode to ordered screen list (for step count display). */
export const STEP_LISTS: Record<DeploymentMode, WizardStep[]> = {
	local: [
		"mode-select",
		"hardware-detect",
		"provider-select",
		"model-select",
		"enrichment-setup",
		"scope-select",
		"review",
	],
	shared: [
		"mode-select",
		"cloud-setup",
		"provider-select",
		"model-select",
		"enrichment-setup",
		"scope-select",
		"review",
	],
	"full-cloud": [
		"mode-select",
		"cloud-warning",
		"cloud-setup",
		"enrichment-setup",
		"scope-select",
		"review",
	],
};

export function getStepLabel(
	step: WizardStep,
	mode: DeploymentMode | null,
): string {
	if (!mode) return "Step 1 of 5";
	const list = STEP_LISTS[mode];
	const idx = list.indexOf(step);
	if (idx < 0) return "";
	return `Step ${idx + 1} of ${list.length}`;
}

