				{type}
			</text>
			<text fg={theme.muted} width={10}>
				{`${tokenEstimate} tok`}
			</text>
			<ScoreBar score={normalizedScore} width={8} showPercent={false} />
			<text fg={getScoreColor(normalizedScore)}>{` ${score}/100`}</text>
