/**
 * IndexNeededView
 *
 * Shown when the project has no index or an outdated index.
 * Offers the user a choice to start indexing or quit.
 *
 * States:
 *   1. Prompt — "Press Enter to index, q to quit"
 *   2. Indexing — shows live IndexProgress component
 *   3. Done — transitions back to normal tabs (handled by App.tsx)
 */

import { basename } from "node:path";
import { useKeyboard } from "@opentui/react";
import { getEmbeddingModel } from "../../config.js";
import { IndexProgress } from "../components/command/IndexProgress.js";
import { useAppContext } from "../context.js";
import { theme } from "../theme.js";

// ============================================================================
// Component
// ============================================================================

export function IndexNeededView() {
	const {
		projectPath,
		indexing,
		indexReason,
		progressStore,
		startIndexing,
		quit,
	} = useAppContext();

	// Keyboard: Enter to index, q to quit (only when not actively indexing)
	useKeyboard((key) => {
		if (indexing) return;

		if (key.name === "return" || key.name === "enter") {
			startIndexing();
			return;
		}

		if (key.name === "q" && !key.ctrl && !key.meta) {
			quit();
		}
	});

	// While indexing, show the progress display
	if (indexing && progressStore) {
		const projectName = basename(projectPath);
		const model = getEmbeddingModel(projectPath);
		const isForce = indexReason === "outdated";

		return (
			<box
				flexDirection="column"
				width="100%"
				height="100%"
				justifyContent="center"
				alignItems="center"
			>
				<box flexDirection="column" paddingLeft={4}>
					<box flexDirection="row" height={1}>
						<text fg={theme.primary}>
							{isForce
								? `Re-indexing ${projectName} (version upgrade)`
								: `Indexing ${projectName}`}
						</text>
					</box>
					<box flexDirection="row" height={1}>
						<text fg={theme.dimmed}>{`  Model: ${model}`}</text>
					</box>
					<box flexDirection="row" height={1}>
						<text fg={theme.muted}> </text>
					</box>
					<IndexProgress
						store={progressStore}
						globalStartTime={progressStore.getGlobalStartTime()}
					/>
				</box>
			</box>
		);
	}

	// Prompt state
	const reason = indexReason ?? "missing";
	const projectName = basename(projectPath);

	return (
		<box
			flexDirection="column"
			width="100%"
			height="100%"
			justifyContent="center"
			alignItems="center"
		>
			<box flexDirection="column" paddingLeft={2} paddingRight={2}>
				<box flexDirection="row" height={1}>
					<text fg={theme.primary}>{"Index Required"}</text>
				</box>

				<box flexDirection="row" height={1}>
					<text fg={theme.muted}> </text>
				</box>

				<box flexDirection="row" height={1}>
					<text fg={theme.text}>
						{reason === "missing"
							? `No index found for ${projectName}.`
							: `Index for ${projectName} is outdated (full re-index needed).`}
					</text>
				</box>

				{reason === "outdated" && (
					<box flexDirection="row" height={1}>
						<text fg={theme.dimmed}>
							{"  New version adds AST metadata and hierarchical code units."}
						</text>
					</box>
				)}

				<box flexDirection="row" height={1}>
					<text fg={theme.muted}> </text>
				</box>

				<box flexDirection="row" height={1}>
					<text fg={theme.muted}>{"Indexing enables:"}</text>
				</box>
				<box flexDirection="row" height={1}>
					<text fg={theme.dimmed}>{"  • Semantic code search"}</text>
				</box>
				<box flexDirection="row" height={1}>
					<text fg={theme.dimmed}>{"  • Symbol graph with PageRank"}</text>
				</box>
				<box flexDirection="row" height={1}>
					<text fg={theme.dimmed}>{"  • Dead code & test gap analysis"}</text>
				</box>

				<box flexDirection="row" height={1}>
					<text fg={theme.muted}> </text>
				</box>

				<box height={1}>
					<text fg={theme.dimmed}>
						{reason === "outdated"
							? "Press [Enter] to re-index (force)"
							: "Press [Enter] to start indexing"}
					</text>
				</box>
				<box height={1}>
					<text fg={theme.dimmed}>{"Press [q] to quit"}</text>
				</box>
			</box>
		</box>
	);
}

/**
 * MapView
 *
 * Repository map with collapsible file/symbol tree.
 * Shows PageRank scores for each symbol.
 *
 * Layout:
 *   Row 1: filter input
 *   Main:  SymbolTree (scrollable)
 */

import { useKeyboard } from "@opentui/react";
import { useEffect, useState } from "react";
import { SymbolTree } from "../components/SymbolTree.js";
import { useAppContext } from "../context.js";
import { useRepoMap } from "../hooks/useRepoMap.js";
import { theme } from "../theme.js";

// ============================================================================
// Component
// ============================================================================

export function MapView() {
	const {
		tracker,
		setActiveTab,
		pushNav,
		inputFocused,
		setInputFocused,
		activeTab,
	} = useAppContext();
	const {
		entries,
		filter,
		setFilter,
		expandedPaths,
		togglePath,
		loading,
		error,
		refresh,
	} = useRepoMap(tracker);

	const [selectedPath, setSelectedPath] = useState<string | null>(null);
	const [filterFocused, setFilterFocused] = useState(false);

	// Sync inputFocused state
	useEffect(() => {
		if (activeTab === "map") {
			setInputFocused(filterFocused);
		}
		return () => {
			if (activeTab === "map") setInputFocused(false);
		};
	}, [filterFocused, activeTab, setInputFocused]);

	// Build flat list of navigable items for keyboard nav
	const navItems: Array<{ path: string; isFile: boolean }> = [];
	for (const entry of entries) {
		navItems.push({ path: entry.filePath, isFile: true });
		if (expandedPaths.has(entry.filePath)) {
			for (const sym of entry.symbols) {
				navItems.push({
					path: `${entry.filePath}:${sym.name}`,
					isFile: false,
				});
			}
		}
	}

	const currentNavIdx = navItems.findIndex(
		(item) => item.path === selectedPath,
	);

	useKeyboard((key) => {
		if (key.name === "escape") {
			if (filterFocused) {
				setFilterFocused(false);
			}
			return;
		}
		if (!filterFocused && key.name === "/") {
			setFilterFocused(true);
			return;
		}
		// When filter input is focused, let it handle keys
		if (filterFocused) return;

		if (key.name === "j" || key.name === "down") {
			const nextIdx = Math.min(currentNavIdx + 1, navItems.length - 1);
			setSelectedPath(navItems[nextIdx]?.path ?? null);
			return;
		}
		if (key.name === "k" || key.name === "up") {
			const prevIdx = Math.max(currentNavIdx - 1, 0);
			setSelectedPath(navItems[prevIdx]?.path ?? null);
			return;
		}
		// g: go to top
		if (key.name === "g") {
			setSelectedPath(navItems[0]?.path ?? null);
			return;
		}
		// G: go to bottom
		if (key.name === "G" || (key.shift && key.name === "g")) {
			setSelectedPath(navItems[navItems.length - 1]?.path ?? null);
			return;
		}
		// Enter or Right: expand file
		if (key.name === "return" || key.name === "right") {
			if (selectedPath) {
				// Only expand file-level paths
				const item = navItems[currentNavIdx];
				if (item?.isFile) {
					togglePath(selectedPath);
				} else if (selectedPath.includes(":")) {
					// It's a symbol, navigate to graph
					const symName = selectedPath.split(":").pop();
					if (symName) {
						pushNav(symName);
						setActiveTab("graph");
					}
				}
			}
			return;
		}
		// Left: collapse
		if (key.name === "left") {
			if (selectedPath && expandedPaths.has(selectedPath)) {
				togglePath(selectedPath);
			}
			return;
		}
		// s: navigate to graph for symbol
		if (key.name === "s") {
			const item = navItems[currentNavIdx];
			if (item && !item.isFile) {
				const symName = item.path.split(":").pop();
				if (symName) {
					pushNav(symName);
					setActiveTab("graph");
				}
			}
			return;
		}
		// r: refresh
		if (key.name === "r") {
			refresh();
			return;
		}
	});

	return (
		<box flexDirection="column" width="100%" height="100%">
			{/* Filter row */}
			<box flexDirection="row" height={1} paddingLeft={1} paddingRight={1}>
				<text fg={filterFocused ? theme.primary : theme.muted}>
					{"Filter: "}
				</text>
				<input
					value={filter}
					placeholder="path pattern..."
					onChange={setFilter}
					focused={filterFocused}
					width={30}
					textColor={theme.text}
				/>
				{!filterFocused && (
					<text fg={theme.dimmed}>{"  / filter  r refresh"}</text>
				)}
				{filterFocused && <text fg={theme.dimmed}>{"  Esc to navigate"}</text>}
				{loading && <text fg={theme.info}>{"  Loading..."}</text>}
			</box>

			{/* Error */}
			{error && (
				<box paddingLeft={1} height={1}>
					<text fg={theme.error}>{`Error: ${error}`}</text>
				</box>
			)}

			{/* Tree */}
			<box flexDirection="column" flexGrow={1} overflow="hidden">
				<SymbolTree
					entries={entries}
					expandedPaths={expandedPaths}
					onToggle={togglePath}
					selectedPath={selectedPath}
					onSelect={setSelectedPath}
				/>
			</box>
		</box>
	);
}

/**
 * SearchView
 *
 * Main search interface with live query input, filter options,
 * and expandable result cards.
 *
 * Focus model:
 *   - Input starts focused (ready to type)
 *   - Escape unfocuses input (enables j/k/o/l shortcuts)
 *   - / or Enter refocuses input
 *
 * Layout:
 *   Row 1: search input
 *   Row 2: options bar (language, sort)
 *   Main:  ResultList (scrollable)
 */

import { useKeyboard } from "@opentui/react";
import { useEffect, useState } from "react";
import { ResultDetailView } from "../components/ResultDetailView.js";
import { ResultList } from "../components/ResultList.js";
import { useAppContext } from "../context.js";
import { useSearch } from "../hooks/useSearch.js";
import { theme } from "../theme.js";

// ============================================================================
// Component
// ============================================================================

export function SearchView() {
	const {
		projectPath,
		setActiveTab,
		pushNav,
		inputFocused,
		setInputFocused,
		activeTab,
	} = useAppContext();
	const {
		query,
		setQuery,
		results,
		loading,
		error,
		selectedIndex,
		setSelectedIndex,
		expandedIndex,
		toggleExpanded,
		sortOrder,
		setSortOrder,
		language,
		setLanguage,
	} = useSearch(projectPath);

	const [detailIndex, setDetailIndex] = useState<number | null>(null);

	// Auto-focus input when entering search tab
	useEffect(() => {
		if (activeTab === "search") {
			setInputFocused(true);
		}
		return () => {
			// Unfocus when leaving this tab
			setInputFocused(false);
		};
	}, [activeTab, setInputFocused]);

	// Keyboard navigation
	useKeyboard((key) => {
		// Escape: unfocus input to enable shortcuts
		if (key.name === "escape") {
			if (inputFocused) {
				setInputFocused(false);
			}
			return;
		}

		// / or i: focus input for typing
		if (!inputFocused && (key.name === "/" || key.name === "i")) {
			setInputFocused(true);
			return;
		}

		// Arrow keys: auto-unfocus input and navigate results
		if (
			inputFocused &&
			results.length > 0 &&
			(key.name === "down" || key.name === "up")
		) {
			setInputFocused(false);
			if (key.name === "down") {
				setSelectedIndex(Math.min(selectedIndex + 1, results.length - 1));
			} else {
				setSelectedIndex(Math.max(selectedIndex - 1, 0));
			}
			return;
		}

		// When input is focused, let the <input> handle everything else
		if (inputFocused) {
			return;
		}

		// --- Shortcuts only work when input is NOT focused ---

		if (key.name === "j" || key.name === "down") {
			setSelectedIndex(Math.min(selectedIndex + 1, results.length - 1));
			return;
		}
		if (key.name === "k" || key.name === "up") {
			setSelectedIndex(Math.max(selectedIndex - 1, 0));
			return;
		}
		if (key.name === "return" || key.name === "space") {
			if (results.length > 0) {
				setDetailIndex(selectedIndex);
			}
			return;
		}
		// s: navigate to Graph view for selected symbol
		if (key.name === "s") {
			const result = results[selectedIndex];
			if (result?.chunk.name) {
				pushNav(result.chunk.name);
				setActiveTab("graph");
			}
			return;
		}
		// cycle sort orders with o
		if (key.name === "o") {
			const orders = ["score", "file", "name"] as const;
			const idx = orders.indexOf(sortOrder);
			setSortOrder(orders[(idx + 1) % orders.length]);
			return;
		}
		// clear language filter with l
		if (key.name === "l") {
			setLanguage(language ? null : "typescript");
			return;
		}
	});

	// When a result is selected for detail view, render the detail component
	if (detailIndex !== null && results[detailIndex]) {
		return (
			<ResultDetailView
				result={results[detailIndex]}
				allResults={results}
				onClose={() => setDetailIndex(null)}
				onNavigate={(newIndex) => setDetailIndex(newIndex)}
			/>
		);
	}

	return (
		<box flexDirection="column" width="100%" height="100%">
			{/* Search input row */}
			<box flexDirection="row" height={1} paddingLeft={1} paddingRight={1}>
				<text fg={inputFocused ? theme.primary : theme.muted}>
					{inputFocused ? "/ " : "> "}
				</text>
				<input
					value={query}
					placeholder="search query..."
					onChange={setQuery}
					focused={inputFocused}
					width="100%"
					textColor={theme.text}
				/>
				{!inputFocused && <text fg={theme.dimmed}>{"  (/ to type)"}</text>}
			</box>

			{/* Options row */}
			<box flexDirection="row" height={1} paddingLeft={1} paddingRight={1}>
				<text fg={theme.muted}>{"Sort: "}</text>
				<text fg={theme.info}>{sortOrder}</text>
				{!inputFocused && <text fg={theme.dimmed}>{"  (o)  "}</text>}
				{inputFocused && <text fg={theme.dimmed}>{"       "}</text>}
				<text fg={theme.muted}>{"  Lang: "}</text>
				<text fg={language ? theme.warning : theme.dimmed}>
					{language ?? "any"}
				</text>
				{!inputFocused && <text fg={theme.dimmed}>{"  (l)  "}</text>}
				{loading && <text fg={theme.info}>{"  Searching..."}</text>}
				{!loading && results.length > 0 && (
					<text fg={theme.muted}>{`  Results: ${results.length}`}</text>
				)}
			</box>

			{/* Mode indicator */}
			{inputFocused && (
				<box paddingLeft={1} height={1}>
					<text fg={theme.dimmed}>
						{"Type to search • Esc to navigate results • Tab to switch view"}
					</text>
				</box>
			)}

			{/* Error display */}
			{error && (
				<box paddingLeft={1} height={1}>
					<text fg={theme.error}>{`Error: ${error}`}</text>
				</box>
			)}

			{/* Results */}
			{!loading && !error && query.trim() === "" && (
				<box padding={2}>
					<text fg={theme.muted}>
						{inputFocused
							? "Start typing to search indexed code..."
							: "Press / to start searching..."}
					</text>
				</box>
			)}

			{!loading && !error && query.trim() !== "" && results.length === 0 && (
				<box padding={2}>
					<text fg={theme.muted}>{"No results found."}</text>
				</box>
			)}

			{results.length > 0 && (
				<box flexDirection="column" flexGrow={1} overflow="hidden">
					<ResultList
						results={results}
						query={query}
						selectedIndex={selectedIndex}
						expandedIndex={expandedIndex}
						onSelect={setSelectedIndex}
						onToggleExpand={toggleExpanded}
					/>
				</box>
			)}
		</box>
	);
}

