export interface TableColumn {
	header: string;
	width: number;
	align?: "left" | "right";
}

/** Cell value with optional highlighting */
export interface CellValue {
	value: string;
	highlight?: "best" | "worst" | "neutral";
}

/**
 * Truncate string with ellipsis
 */
export function truncate(s: string, max: number): string {
	return s.length > max ? `${s.slice(0, max - 1)}…` : s;
}

/**
 * Format number as percentage
 */
export function formatPercent(value: number, decimals = 0): string {
	return `${value.toFixed(decimals)}%`;
}

/**
 * Format duration in seconds
 */
export function formatDuration(ms: number): string {
	return `${(ms / 1000).toFixed(1)}s`;
}

/**
 * Format cost in dollars
 */
export function formatCost(cost: number | undefined | null): string {
	if (cost === undefined || cost === null) return "N/A";
	if (cost === 0) return "FREE";
	return `$${cost.toFixed(5)}`;
}

/**
 * Format context length (e.g., 32000 -> "32K")
 */
export function formatContextLength(ctx: number): string {
	return ctx >= 1000 ? `${Math.round(ctx / 1000)}K` : String(ctx);
}

/**
 * Apply cell highlighting based on best/worst
 */
function applyCellHighlight(
	value: string,
	highlight?: "best" | "worst" | "neutral",
): string {
	if (highlight === "best") return `${c.green}${value}${c.reset}`;
	if (highlight === "worst") return `${c.red}${value}${c.reset}`;
	return value;
}

/**
 * Render a results table
 */
export function renderTable(
	columns: TableColumn[],
	rows: Array<{ cells: CellValue[]; error?: string }>,
): void {
	// Calculate total width
	const totalWidth = columns.reduce((sum, col) => sum + col.width + 1, 0) - 1;

	// Print header
	const headerLine = columns
		.map((col) => col.header.padEnd(col.width))
		.join(" ");
	console.log(`  ${headerLine}`);
	console.log(`  ${"─".repeat(totalWidth)}`);

	// Print rows
	for (const row of rows) {
		if (row.error) {
			const firstCell = row.cells[0]?.value || "Unknown";
			console.log(
				`  ${c.red}${truncate(firstCell, columns[0]?.width || 28).padEnd(columns[0]?.width || 28)} ERROR${c.reset}`,
			);
			console.log(`    ${c.dim}${row.error}${c.reset}`);
			continue;
		}

		const cells = row.cells.map((cell, i) => {
			const col = columns[i];
			const value =
				col.align === "right"
					? cell.value.padStart(col.width)
					: cell.value.padEnd(col.width);
			return applyCellHighlight(value, cell.highlight);
		});

		console.log(`  ${cells.join(" ")}`);
	}
}

/**
 * Determine highlight based on ranking
 */
export function getHighlight(
	value: number,
	min: number,
	max: number,
	higherIsBetter: boolean,
): "best" | "worst" | "neutral" {
	if (min === max) return "neutral";
	const best = higherIsBetter ? max : min;
	const worst = higherIsBetter ? min : max;
	if (value === best) return "best";
	if (value === worst) return "worst";
	return "neutral";
}

/**
 * Print a summary section
 */
export function renderSummary(
	items: Array<{ emoji: string; label: string; value: string }>,
): void {
	console.log(`\n${c.bold}Summary:${c.reset}`);
	for (const item of items) {
		console.log(
			`  ${c.green}${item.emoji} ${item.label}:${c.reset} ${item.value}`,
		);
	}
}

/**
 * Print section header
 */
export function renderHeader(title: string): void {
	console.log(`\n${c.bold}${title}${c.reset}\n`);
}

/**
 * Print info line
 */
export function renderInfo(text: string): void {
	console.log(`${c.dim}${text}${c.reset}`);
}

/**
 * Print benchmark title banner
 */
export function renderBenchmarkBanner(title: string, subtitle?: string): void {
	console.log(`\n${c.orange}${c.bold}${title}${c.reset}`);
	if (subtitle) {
		console.log(`${c.dim}${subtitle}${c.reset}`);
	}
	console.log();
}

/**
 * Print success message
 */
export function renderSuccess(message: string): void {
	console.log(`${c.green}${c.bold}✓ ${message}${c.reset}`);
}

/**
 * Print error message
 */
export function renderError(message: string): void {
	console.log(`${c.red}${c.bold}✗ ${message}${c.reset}`);
}

/**
 * Cache management for update checks
 * Cache location: ~/.mnemex/update-cache.json
 * TTL: 24 hours
 */

import {
	existsSync,
	mkdirSync,
	readFileSync,
	unlinkSync,
	writeFileSync,
} from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

export interface UpdateCacheEntry {
	latestVersion: string;
	checkedAt: number;
	publishedAt?: string;
}

const CACHE_DIR = join(homedir(), ".mnemex");
const CACHE_FILE = join(CACHE_DIR, "update-cache.json");

export function getCacheFilePath(): string {
	return CACHE_FILE;
}

export function readCache(): UpdateCacheEntry | null {
	try {
		if (!existsSync(CACHE_FILE)) return null;

		const content = readFileSync(CACHE_FILE, "utf-8");
		const parsed = JSON.parse(content);

		// Validate structure
		if (!parsed.latestVersion || typeof parsed.checkedAt !== "number") {
			return null;
		}

		return parsed;
	} catch {
		return null;
	}
}

export function writeCache(entry: UpdateCacheEntry): void {
	try {
		if (!existsSync(CACHE_DIR)) {
			mkdirSync(CACHE_DIR, { recursive: true });
		}

		writeFileSync(CACHE_FILE, JSON.stringify(entry, null, 2), "utf-8");
	} catch {
		// Silently ignore write errors
	}
}

export function isCacheValid(
	entry: UpdateCacheEntry,
	maxAgeMs: number,
): boolean {
	const age = Date.now() - entry.checkedAt;
	return age < maxAgeMs;
}

export function clearCache(): void {
	try {
		if (existsSync(CACHE_FILE)) {
			unlinkSync(CACHE_FILE);
		}
	} catch {
		// Silently ignore
	}
}

/**
 * GitHub release changelog helpers for the update command.
 */

import { compareVersions } from "./version.js";

const RESET = "\x1b[0m";
const BOLD = "\x1b[1m";
const GREEN = "\x1b[32m";
const YELLOW = "\x1b[33m";
const CYAN = "\x1b[36m";
const MAGENTA = "\x1b[35m";
const DIM = "\x1b[2m";

export interface GitHubRelease {
	tag_name: string;
	name?: string;
	body?: string;
}

export type ChangelogItemType = "feat" | "fix" | "breaking" | "perf" | "chore";

export interface ChangelogItem {
	type: ChangelogItemType;
	text: string;
}

export interface ChangelogEntry {
	version: string;
	title: string;
	items: ChangelogItem[];
}

export interface FetchChangelogOptions {
	repo?: string;
	timeoutMs?: number;
}

export interface DisplayChangelogOptions {
	compact?: boolean;
	productName?: string;
	showEmptyMessage?: boolean;
}

const SECTION_TYPE_MAP: Record<string, ChangelogItemType | null> = {
	"new features": "feat",
	features: "feat",
	"bug fixes": "fix",
	fixes: "fix",
	"breaking changes": "breaking",
	performance: "perf",
	"other changes": "chore",
	chore: "chore",
	refactor: "chore",
	documentation: null,
	docs: null,
};

function normalizeVersion(version: string): string {
	const withoutPrefix = version.replace(/^v/, "");
	const match = withoutPrefix.match(/\d+\.\d+\.\d+/);
	return match ? match[0] : withoutPrefix;
}

function extractReleaseTitle(name: string): string {
	const dashMatch = name.match(/\s[—–-]\s(.+)$/);
	return dashMatch ? dashMatch[1].trim() : "";
}

/**
 * Parse one GitHub release body into a display-friendly changelog entry.
 */
export function parseRelease(release: GitHubRelease): ChangelogEntry {
	const version = normalizeVersion(release.tag_name);
	const title = extractReleaseTitle(release.name ?? "");
	const items: ChangelogItem[] = [];

	if (!release.body) {
		return { version, title, items };
	}

	const lines = release.body.split("\n");
	let currentType: ChangelogItemType | null = "feat";

	for (const line of lines) {
		if (/^##\s+Install/i.test(line)) break;

		const sectionMatch = line.match(/^###\s+(.+)$/);
		if (sectionMatch) {
			const sectionName = sectionMatch[1].trim().toLowerCase();
			const mapped = SECTION_TYPE_MAP[sectionName];
			currentType = mapped === undefined ? "chore" : mapped;
			continue;
		}

		if (currentType === null) continue;

		const bulletMatch = line.match(/^[\s]*[-*]\s+(.+)$/);
		if (!bulletMatch) continue;

		let text = bulletMatch[1].trim();
		text = text.replace(/\(\[`[a-f0-9]+`\]\([^)]*\)\)\s*$/, "").trim();
		text = text.replace(/^v\d+\.\d+\.\d+\s*[—–-]\s*/, "").trim();

		if (/^bump\s+to\s+v/i.test(text)) continue;
		if (/^update\s+CHANGELOG/i.test(text)) continue;
		if (!text) continue;

		items.push({ type: currentType, text });
	}

	return { version, title, items };
}

/**
 * Fetch GitHub releases between currentVersion (exclusive) and latestVersion
 * (inclusive). Network errors return an empty changelog.
 */
export async function fetchChangelog(
	currentVersion: string,
	latestVersion: string,
	options: FetchChangelogOptions = {},
): Promise<ChangelogEntry[]> {
	const repo = options.repo ?? "MadAppGang/mnemex";
	const timeoutMs = options.timeoutMs ?? 5000;
	let timeout: ReturnType<typeof setTimeout> | undefined;

	try {
		const controller = new AbortController();
		timeout = setTimeout(() => controller.abort(), timeoutMs);

		const response = await fetch(
			`https://api.github.com/repos/${repo}/releases`,
			{
				signal: controller.signal,
				headers: {
					Accept: "application/vnd.github+json",
					"User-Agent": "mnemex-updater",
				},
			},
		);

		if (!response.ok) {
			return [];
		}

		const releases = (await response.json()) as GitHubRelease[];
		const current = normalizeVersion(currentVersion);
		const latest = normalizeVersion(latestVersion);

		const relevant = releases.filter((release) => {
			const version = normalizeVersion(release.tag_name);
			return (
				compareVersions(version, current) > 0 &&
				compareVersions(version, latest) <= 0
			);
		});

		relevant.sort((a, b) =>
			compareVersions(
				normalizeVersion(b.tag_name),
				normalizeVersion(a.tag_name),
			),
		);

		return relevant.map((release) => parseRelease(release));
	} catch {
		return [];
	} finally {
		if (timeout) clearTimeout(timeout);
	}
}

function itemStyle(type: ChangelogItemType): { symbol: string; color: string } {
	switch (type) {
		case "feat":
			return { symbol: "*", color: GREEN };
		case "fix":
			return { symbol: "*", color: YELLOW };
		case "breaking":
			return { symbol: "*", color: MAGENTA };
		case "perf":
			return { symbol: "*", color: CYAN };
		case "chore":
			return { symbol: "-", color: DIM };
	}
}

/**
 * Display changelog entries with ANSI formatting.
 */
export function displayChangelog(
	entries: ChangelogEntry[],
	options: DisplayChangelogOptions = {},
): void {
	const {
		compact = false,
		productName = "mnemex",
		showEmptyMessage = false,
	} = options;

	if (entries.length === 0) {
		if (showEmptyMessage) {
			console.log("");
			console.log(`${DIM}No changelog entries found for this update.${RESET}`);
		}
		return;
	}

	if (compact) {
		console.log(`Changelog: ${entries.length} release(s)`);
		for (const entry of entries) {
			const title = entry.title ? ` - ${entry.title}` : "";
			console.log(`v${entry.version}${title}`);
			for (const item of entry.items) {
				console.log(`- ${item.text}`);
			}
		}
		return;
	}

	console.log("");
	console.log(`${CYAN}${BOLD}What's New${RESET}`);
	console.log(`${DIM}${"=".repeat(32)}${RESET}`);
	console.log("");

	for (const entry of entries) {
		const title = entry.title ? `  ${entry.title}` : "";
		console.log(`  ${BOLD}${GREEN}v${entry.version}${RESET}${title}`);
		console.log(`  ${DIM}${"-".repeat(30)}${RESET}`);

		for (const item of entry.items) {
			const { symbol, color } = itemStyle(item.type);
			console.log(`    ${color}${symbol}${RESET} ${item.text}`);
		}

		console.log("");
	}

	console.log(
		`${CYAN}Please restart any running ${productName} sessions.${RESET}`,
	);
}

/**
 * Auto-update manager for mnemex CLI
 *
 * Features:
 * - Check npm registry for latest version
 * - Cache version checks (24h TTL)
 * - Perform self-update via npm/bun
 * - Handle offline/network failures gracefully
 */

import { spawn } from "node:child_process";
import { clearCache, isCacheValid, readCache, writeCache } from "./cache.js";
import { fetchLatestVersion } from "./registry.js";
import { isNewerVersion } from "./version.js";

export interface UpdateCheckResult {
	currentVersion: string;
	latestVersion: string;
	isUpdateAvailable: boolean;
	publishedAt?: string;
}

export interface UpdateOptions {
	/** Auto-approve update (skip prompt) */
	autoApprove?: boolean;

	/** Verbose output */
	verbose?: boolean;
}

export interface UpdateResult {
	success: boolean;
	newVersion?: string;
	error?: string;
}

const CACHE_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24 hours

export class UpdateManager {
	private currentVersion: string;

	constructor(
		currentVersion: string,
		private packageName = "mnemex",
	) {
		this.currentVersion = currentVersion;
	}

	/**
	 * Get current installed version
	 */
	getCurrentVersion(): string {
		return this.currentVersion;
	}

	/**
	 * Get cached version info (if valid)
	 */
	getCachedVersionInfo(): UpdateCheckResult | null {
		const cache = readCache();
		if (!cache) return null;

		if (!isCacheValid(cache, CACHE_MAX_AGE_MS)) return null;

		const current = this.getCurrentVersion();
		return {
			currentVersion: current,
			latestVersion: cache.latestVersion,
			isUpdateAvailable: isNewerVersion(current, cache.latestVersion),
			publishedAt: cache.publishedAt,
		};
	}

	/**
	 * Check for available updates (uses cache if fresh)
	 */
	async checkForUpdate(): Promise<UpdateCheckResult> {
		const current = this.getCurrentVersion();

		// Try cache first
		const cached = this.getCachedVersionInfo();
		if (cached) return cached;

		// Fetch from registry
		try {
			const info = await fetchLatestVersion(this.packageName);

			// Update cache
			writeCache({
				latestVersion: info.version,
				checkedAt: Date.now(),
				publishedAt: info.publishedAt,
			});

			return {
				currentVersion: current,
				latestVersion: info.version,
				isUpdateAvailable: isNewerVersion(current, info.version),
				publishedAt: info.publishedAt,
			};
		} catch (error) {
			// If fetch fails, return current version (no update available)
			return {
				currentVersion: current,
				latestVersion: current,
				isUpdateAvailable: false,
			};
		}
	}

	/**
	 * Detect how the package was installed (brew, bun, or npm)
	 */
	private detectPackageManager(): "brew" | "bun" | "npm" {
		const scriptPath = process.argv[1] || "";

		// Priority 1: Homebrew
		if (
			scriptPath.includes("/opt/homebrew/") ||
			scriptPath.includes("/usr/local/Cellar/")
		) {
			return "brew";
		}

		// Priority 2: Bun
		if (scriptPath.includes("/.bun/") || scriptPath.includes("/bun/")) {
			return "bun";
		}

		// Check Bun runtime as fallback
		const isBunRuntime =
			typeof (globalThis as { Bun?: unknown }).Bun !== "undefined";
		const isBunExec = process.execPath.toLowerCase().includes("bun");
		if (isBunRuntime || isBunExec) {
			return "bun";
		}

		return "npm";
	}

	async performUpdate(options: UpdateOptions = {}): Promise<UpdateResult> {
		const check = await this.checkForUpdate();

		if (!check.isUpdateAvailable) {
			return { success: false, error: "Already on latest version" };
		}

		// Detect package manager based on installation method
		const packageManager = this.detectPackageManager();
		let args: string[];
		if (packageManager === "brew") {
			args = ["upgrade", "mnemex"];
		} else {
			const subcommand = packageManager === "bun" ? "add" : "install";
			args = [subcommand, "-g", `${this.packageName}@latest`];
		}

		if (options.verbose) {
			console.log(`Running: ${packageManager} ${args.join(" ")}`);
		}

		return new Promise((resolve) => {
			const proc = spawn(packageManager, args, {
				stdio: options.verbose ? "inherit" : "pipe",
			});

			proc.on("error", (error) => {
				resolve({
					success: false,
					error: `Failed to spawn ${packageManager}: ${error.message}`,
				});
			});

			proc.on("close", (code) => {
				if (code !== 0) {
					resolve({
						success: false,
						error: `${packageManager} exited with code ${code}`,
					});
					return;
				}

				// Trust the package manager exit code (like claudish does).
				// We can't verify the new version in-process because
				// this.currentVersion is frozen at process start.
				clearCache();
				resolve({ success: true, newVersion: check.latestVersion });
			});
		});
	}

	/**
	 * Clear update cache (for testing)
	 */
	clearCache(): void {
		clearCache();
	}
}

/**
 * NPM registry client for fetching package information
 */

export interface RegistryPackageInfo {
	name: string;
	version: string;
	publishedAt?: string;
}

/**
 * Fetch latest version from npm registry
 * @param packageName Package name (e.g., "mnemex")
 * @param timeout Timeout in milliseconds (default: 5000)
 */
export async function fetchLatestVersion(
	packageName: string,
	timeout = 5000,
): Promise<RegistryPackageInfo> {
	const url = `https://registry.npmjs.org/${packageName}/latest`;

	const controller = new AbortController();
	const timeoutId = setTimeout(() => controller.abort(), timeout);

	try {
		const response = await fetch(url, { signal: controller.signal });

		if (!response.ok) {
			throw new Error(`Registry returned ${response.status}`);
		}

		const data = await response.json();

		return {
			name: data.name,
			version: data.version,
			publishedAt: data.time?.[data.version],
		};
	} finally {
		clearTimeout(timeoutId);
	}
}

/**
 * Version comparison utilities for semantic versioning
 */

/**
 * Compare two semantic versions
 * @returns -1 if v1 < v2, 0 if v1 === v2, 1 if v1 > v2
 */
export function compareVersions(v1: string, v2: string): number {
	const a = v1.split(".").map(Number);
	const b = v2.split(".").map(Number);

	for (let i = 0; i < Math.max(a.length, b.length); i++) {
		const na = a[i] || 0;
		const nb = b[i] || 0;
		if (na > nb) return 1;
		if (na < nb) return -1;
	}
	return 0;
}

/**
 * Check if latest version is newer than current version
 */
export function isNewerVersion(current: string, latest: string): boolean {
	return compareVersions(latest, current) > 0;
}

/**
 * E2E tests for API key management.
 *
 * Uses a dedicated server on port 4516 with MASTER_API_KEY enabled.
 * Tests creation, listing, deletion, usage tracking, and auth enforcement.
 */

import {
	afterAll,
	beforeAll,
	beforeEach,
	describe,
	expect,
	it,
} from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import postgres from "postgres";
import { startServer } from "../../../src/cloud/server/index.js";

// ============================================================================
// Constants
// ============================================================================

const MASTER_KEY = "test-master-key-12345";
const PORT = 4516;
const BASE_URL = `http://localhost:${PORT}`;

// Read from the environment — never hardcode a real connection string in a
// committed test (it leaks the credential to git history and every fork).
const NEON_DB_URL = process.env.NEON_DB_URL ?? process.env.DATABASE_URL ?? "";

/** See setup.ts — these suites need a real PostgreSQL instance. */
const HAS_CLOUD_DB = NEON_DB_URL.length > 0;

const PROJECT_ROOT = join(import.meta.dir, "../../..");
const SCHEMA_PATH = join(PROJECT_ROOT, "src/cloud/server/schema.sql");

// ============================================================================
// Test infra
// ============================================================================

interface AuthTestContext {
	stop: () => Promise<void>;
	resetDb: () => Promise<void>;
}

async function startAuthTestInfra(): Promise<AuthTestContext> {
	const sql = postgres(NEON_DB_URL, { max: 5 });

	// Verify connectivity
	await sql`SELECT 1`;

	// Run schema migration
	const schema = readFileSync(SCHEMA_PATH, "utf-8");
	const statements = schema
		.split(";")
		.map((s) => s.trim())
		.filter((s) => s.length > 0);

	for (const stmt of statements) {
		await sql.unsafe(`${stmt};`);
	}

	// Clean slate
	await sql`TRUNCATE TABLE enrichment_docs, commit_files, commits, chunks, repos, orgs RESTART IDENTITY CASCADE`;
	await sql`TRUNCATE TABLE api_key_usage, api_keys RESTART IDENTITY CASCADE`;

	// Start server with auth enabled
	const { stop: serverStop } = await startServer({
		port: PORT,
		databaseUrl: NEON_DB_URL,
		embeddingDim: 8,
		masterApiKey: MASTER_KEY,
	});

	await new Promise((resolve) => setTimeout(resolve, 100));

	return {
		async stop() {
			await serverStop();
			await sql.end();
		},
		async resetDb() {
			await sql`TRUNCATE TABLE enrichment_docs, commit_files, commits, chunks, repos, orgs RESTART IDENTITY CASCADE`;
			await sql`TRUNCATE TABLE api_key_usage, api_keys RESTART IDENTITY CASCADE`;
		},
	};
}

// ============================================================================
// HTTP helper
// ============================================================================

function apiRequest(
	path: string,
	opts: { method?: string; body?: unknown; apiKey?: string } = {},
): Promise<Response> {
	const headers: Record<string, string> = {
		"X-Mnemex-Version": "1",
		"Content-Type": "application/json",
	};
	if (opts.apiKey) headers.Authorization = `Bearer ${opts.apiKey}`;
	return fetch(`${BASE_URL}${path}`, {
		method: opts.method ?? "GET",
		headers,
		body: opts.body ? JSON.stringify(opts.body) : undefined,
	});
}

/** Create a synthetic 8-dimensional unit vector */
function syntheticVector(seed: number): number[] {
	const v = Array.from({ length: 8 }, (_, i) => Math.sin(seed * 1.7 + i * 0.5));
	const norm = Math.sqrt(v.reduce((s, x) => s + x * x, 0));
	return v.map((x) => x / norm);
}

/** Generate a fake 40-char hex SHA */
function fakeSha(n: number): string {
	return n.toString(16).padStart(40, "0");
}

/** Generate a fake content hash */
function fakeHash(n: number): string {
	return `hash_${n.toString(16).padStart(62, "0")}`;
}

