			"export const b = 2;",
			"export const c = 3;",
			"export const d = 4;",
			"export const e = 5;",
			"",
		].join("\n");
		ws.writeFile("src/file.ts", fileContent);
		await ws.index();
		const editor = ws.createEditor();

		const absPath = join(ws.root, "src/file.ts");
		// Replace lines 2-3 (b and c) with two new const declarations
		await editor.editLines(
			absPath,
