		const editor = ws.createEditor();

		await expect(
			editor.editSymbol("nonExistentSymbol", "// new", "replace"),
		).rejects.toThrow(/not found/);
	});

	// FR-1.9: multiple symbols
	test("editSymbol: handles multiple symbols in same file", async () => {
