// Fixed-dimension vectors for testing (4D for simplicity)
const DIM = 4;

function makeVector(seed: number): number[] {
	// Simple deterministic pseudo-vector
	const v = [
		Math.sin(seed),
		Math.cos(seed),
		Math.sin(seed * 2),
		Math.cos(seed * 2),
	];
	// Normalize
	const norm = Math.sqrt(v.reduce((s, x) => s + x * x, 0));
	return v.map((x) => x / norm);
}

// Create a code chunk with embedding
function makeChunk(opts: {
	id: string;
	content: string;
	filePath: string;
	startLine: number;
	endLine: number;
	name?: string;
	language?: string;
	seed: number;
}): ChunkWithEmbedding {
	return {
		id: opts.id,
		contentHash: `hash-${opts.id}`,
		content: opts.content,
		filePath: opts.filePath,
		startLine: opts.startLine,
		endLine: opts.endLine,
		language: opts.language || "typescript",
		chunkType: "function",
		name: opts.name,
		fileHash: `fhash-${opts.filePath}`,
		vector: makeVector(opts.seed),
	};
}

// Create an enriched document with embedding
function makeDocument(opts: {
	id: string;
	content: string;
	documentType: string;
	filePath?: string;
	sourceIds?: string[];
	seed: number;
}): DocumentWithEmbedding {
	return {
		id: opts.id,
		content: opts.content,
		documentType: opts.documentType as any,
		filePath: opts.filePath,
		sourceIds: opts.sourceIds,
		createdAt: new Date().toISOString(),
		vector: makeVector(opts.seed),
	};
}

