			durationMs: 50,
		});

		// Correction followed by tool = not autonomous
		recorder.recordCorrection({ type: "wrong_tool", tool: "Read" }, "Use Grep");

		// Small delay to ensure timestamp difference
		recorder.recordToolEvent({
			toolName: "Grep",
			args: {},
