// Tests
// ---------------------------------------------------------------------------

describe("ReferenceGraphManager.findSymbol — dot-path resolution", () => {
	let cleanup: () => void;

	afterEach(() => {
		if (cleanup) cleanup();
	});

	it("returns the class method when queried as 'Class.method'", () => {
		const { tracker, cleanup: c } = makeTempTracker();
		cleanup = c;

		// Insert the Tensor class
		const tensorClass = makeSymbol({
			id: "sym-tensor-class",
			name: "Tensor",
			kind: "class",
			filePath: "src/tensor.py",
			startLine: 1,
			endLine: 200,
			pagerankScore: 0.5,
		});

		// Insert the realize method (child of Tensor)
		const realizeMethod = makeSymbol({
			id: "sym-tensor-realize",
			name: "realize",
			kind: "method",
			filePath: "src/tensor.py",
			startLine: 50,
			endLine: 60,
			parentId: "sym-tensor-class",
			pagerankScore: 0.3,
		});

		// Insert a standalone function also named "realize" with higher PageRank
		// (this is the symbol that incorrectly wins when using flat name lookup)
		const standaloneRealize = makeSymbol({
			id: "sym-standalone-realize",
			name: "realize",
			kind: "function",
			filePath: "src/helpers.py",
			startLine: 1,
			endLine: 20,
			parentId: undefined,
			pagerankScore: 0.9, // higher PageRank — wins flat lookup
		});

		tracker.insertSymbols([tensorClass, realizeMethod, standaloneRealize]);

		const graph = new ReferenceGraphManager(tracker);

		// Dot-path lookup must return the method on Tensor, not the standalone fn
		const result = graph.findSymbol("Tensor.realize");
		expect(result).not.toBeNull();
		expect(result?.id).toBe("sym-tensor-realize");
		expect(result?.kind).toBe("method");
		expect(result?.parentId).toBe("sym-tensor-class");
	});

	it("returns something for flat 'realize' lookup (backward compat)", () => {
		const { tracker, cleanup: c } = makeTempTracker();
		cleanup = c;

		const tensorClass = makeSymbol({
			id: "sym-tensor-class",
			name: "Tensor",
			kind: "class",
			filePath: "src/tensor.py",
			startLine: 1,
			endLine: 200,
			pagerankScore: 0.5,
		});

		const realizeMethod = makeSymbol({
			id: "sym-tensor-realize",
			name: "realize",
			kind: "method",
			filePath: "src/tensor.py",
			startLine: 50,
			endLine: 60,
			parentId: "sym-tensor-class",
			pagerankScore: 0.3,
		});

		const standaloneRealize = makeSymbol({
			id: "sym-standalone-realize",
			name: "realize",
			kind: "function",
			filePath: "src/helpers.py",
			startLine: 1,
			endLine: 20,
			pagerankScore: 0.9,
		});

		tracker.insertSymbols([tensorClass, realizeMethod, standaloneRealize]);

		const graph = new ReferenceGraphManager(tracker);

		// Flat lookup must still return something (we don't care which one)
		const result = graph.findSymbol("realize");
		expect(result).not.toBeNull();
	});

	it("returns null for a dot-path whose class does not exist", () => {
		const { tracker, cleanup: c } = makeTempTracker();
		cleanup = c;

		const fn = makeSymbol({
			id: "sym-foo",
			name: "bar",
			kind: "function",
			filePath: "src/utils.py",
			startLine: 1,
			endLine: 5,
		});

		tracker.insertSymbols([fn]);

		const graph = new ReferenceGraphManager(tracker);

		// NonExistentClass.bar — class not in index, should return null
		const result = graph.findSymbol("NonExistentClass.bar");
		expect(result).toBeNull();
	});
});

/**
 * Unit tests for the MACHINE-GLOBAL single-indexer lock.
 *
 * The global lock reuses the SAME IndexLock machinery as the per-project lock
 * (heartbeat, lastProgressAt/recordProgress, setPhase, progress-based staleness,
 * inspectLock). What is new here is:
 *  - createGlobalIndexLock() points at a machine-global path (~/.mnemex/...),
 *    overridable via MNEMEX_GLOBAL_LOCK_PATH.
 *  - IndexLock.fromLockPath() builds a lock from an explicit absolute path without
 *    breaking the (projectPath, indexDir) constructor.
 *
 * These tests prove:
 *  - getGlobalLockPath honors the env override and defaults under the home dir.
 *  - acquire/release round-trips on the global lock.
 *  - a second try-acquire while held => not acquired (already_running).
 *  - a WEDGED global holder (stale lastProgressAt, fresh heartbeat) is RECLAIMED
 *    by the next acquire (mirrors the per-project reclaim test).
 *  - global + per-project locks are INDEPENDENT files, so holding one does not
 *    block the other — the basis for the deadlock-safe global-before-project order.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import {
	existsSync,
	mkdirSync,
	mkdtempSync,
	readFileSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import {
	createGlobalIndexLock,
	createIndexLock,
	getGlobalLockPath,
	IndexLock,
} from "../../../src/core/lock.js";

const DEAD_PID = 2_000_000_000; // almost certainly not a live process
const tempDirs: string[] = [];
const savedEnv = process.env.MNEMEX_GLOBAL_LOCK_PATH;

/** Create an isolated temp dir and return the path to a global lock file inside it. */
function makeGlobalLockPath(): string {
	const dir = mkdtempSync(join(tmpdir(), "global-lock-test-"));
	tempDirs.push(dir);
	return join(dir, ".global-indexing.lock");
}

/** Read the raw global lock file JSON for assertions. */
function readLock(lockPath: string): {
	pid: number;
	startTime: number;
	heartbeat: number;
	lastProgressAt?: number;
	startedAt: string;
} {
	return JSON.parse(readFileSync(lockPath, "utf-8"));
}

beforeEach(() => {
	// Every test isolates the global lock to its own tmp file.
	process.env.MNEMEX_GLOBAL_LOCK_PATH = makeGlobalLockPath();
});

afterEach(() => {
	if (savedEnv === undefined) {
		delete process.env.MNEMEX_GLOBAL_LOCK_PATH;
	} else {
		process.env.MNEMEX_GLOBAL_LOCK_PATH = savedEnv;
	}
	while (tempDirs.length > 0) {
		const dir = tempDirs.pop();
		if (dir) {
			try {
				rmSync(dir, { recursive: true, force: true });
			} catch {
				// best effort
			}
		}
	}
});

