/**
 * Regression tests for two enrichment defects found while reindexing.
 *
 * 1. `enableEnrichment: false` in config was silently ignored by `mnemex index`.
 *    cli.ts passed `enableEnrichment: !noLlm` — an explicit boolean on EVERY run —
 *    so the Indexer's `options.enableEnrichment ?? isEnrichmentEnabled(path)`
 *    fallback never ran. Only `--no-llm` could disable enrichment.
 *
 * 2. The enrichment/AST phase never called `reportProgress()`, so `lastProgressAt`
 *    froze for the whole phase while `heartbeat` kept ticking. Past
 *    DEFAULT_PROGRESS_TIMEOUT (5 min) the lock reads as hung and the next
 *    acquire() reclaims it — letting a second indexer run against the same store.
 *    Observed live: 1216s with no progress tick.
 */

import { describe, expect, test } from "bun:test";
import {
	DEFAULT_PROGRESS_TIMEOUT,
	isLockStale,
} from "../../../src/core/lock.js";

describe("enrichment flag plumbing (bug 1)", () => {
	// Mirrors the Indexer's resolution:
	//   options.enableEnrichment ?? isEnrichmentEnabled(projectPath)
	function resolve(
		optionValue: boolean | undefined,
		configSaysEnabled: boolean,
	): boolean {
		return optionValue ?? configSaysEnabled;
	}

	test("an explicit boolean always wins, which is what masked the config", () => {
		// The old cli.ts passed `!noLlm`, i.e. `true` whenever --no-llm was absent.
		expect(resolve(true, false)).toBe(true); // config said false, ignored
	});

	test("undefined lets config decide — the fixed behaviour", () => {
		expect(resolve(undefined, false)).toBe(false);
		expect(resolve(undefined, true)).toBe(true);
	});

	test("--no-llm still forces enrichment off regardless of config", () => {
		expect(resolve(false, true)).toBe(false);
	});

	test("the fixed cli.ts expression yields undefined unless --no-llm", () => {
		const fromCli = (noLlm: boolean) => (noLlm ? false : undefined);
		expect(fromCli(false)).toBeUndefined(); // config decides
		expect(fromCli(true)).toBe(false); // explicit opt-out
	});
});

describe("progress staleness during long phases (bug 2)", () => {
	const now = Date.now();
	const staleTimeout = 10_000;

	test("a fresh heartbeat does NOT save a lock whose progress has stalled", () => {
		// This is the exact shape observed: heartbeat current, lastProgressAt old.
		const lock = {
			pid: process.pid,
			startTime: now - 1_800_000,
			heartbeat: now,
			lastProgressAt: now - 1_216_000, // 1216s, as measured live
			phase: "enriching",
		};
		expect(
			isLockStale(lock as any, staleTimeout, DEFAULT_PROGRESS_TIMEOUT),
		).toBe(true);
	});

	test("progress ticks inside the phase keep the lock alive", () => {
		// With reportProgress() wired into the enrichment/AST loops, lastProgressAt
		// advances and the lock is correctly held.
		const lock = {
			pid: process.pid,
			startTime: now - 1_800_000,
			heartbeat: now,
			lastProgressAt: now - 1_000,
			phase: "analyzing+enriching",
		};
		expect(
			isLockStale(lock as any, staleTimeout, DEFAULT_PROGRESS_TIMEOUT),
		).toBe(false);
	});

	test("the observed stall exceeded the hung threshold several times over", () => {
		expect(DEFAULT_PROGRESS_TIMEOUT).toBe(300_000);
		expect(1_216_000).toBeGreaterThan(DEFAULT_PROGRESS_TIMEOUT);
	});
});

/**
 * Unit tests for inspectLock — the read-only lock inspector.
 *
 * Proves: parsing (present/absent/corrupt/partial), liveness probe, and most
 * importantly that inspection NEVER mutates or removes the lock file (R5).
 *
 * Black-box: written against the public inspectLock contract only.
 */

import { afterEach, describe, expect, test } from "bun:test";
import { existsSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { inspectLock } from "../../../src/core/lock.js";

const LOCK_FILENAME = ".indexing.lock";
const tempDirs: string[] = [];

function makeTempDir(): string {
	const dir = mkdtempSync(join(tmpdir(), "inspect-lock-test-"));
	tempDirs.push(dir);
	return dir;
}

/**
 * Write a lock file with the canonical
 * { pid, startTime, heartbeat, lastProgressAt, startedAt } shape. Pass
 * `omitLastProgressAt: true` to simulate a lock written by an OLDER binary.
 */
function writeLock(
	indexDir: string,
	overrides: Partial<{
		pid: number;
		startTime: number;
		heartbeat: number;
		lastProgressAt: number;
		startedAt: string;
		omitLastProgressAt: boolean;
	}> = {},
): string {
	const now = Date.now();
	const data: Record<string, unknown> = {
		pid: overrides.pid ?? process.pid,
		startTime: overrides.startTime ?? now,
		heartbeat: overrides.heartbeat ?? now,
		startedAt: overrides.startedAt ?? new Date(now).toISOString(),
	};
	if (!overrides.omitLastProgressAt) {
		data.lastProgressAt = overrides.lastProgressAt ?? now;
	}
	const lockPath = join(indexDir, LOCK_FILENAME);
	writeFileSync(lockPath, JSON.stringify(data, null, 2));
	return lockPath;
}

afterEach(() => {
	while (tempDirs.length > 0) {
		const dir = tempDirs.pop();
		if (dir) {
			try {
				rmSync(dir, { recursive: true, force: true });
			} catch {
				// best effort
			}
		}
	}
});

describe("inspectLock", () => {
	// R1: no lock file => { present: false }
	test("R1: returns { present: false } when no lock file exists", () => {
		const dir = makeTempDir();
		const result = inspectLock(dir);
		expect(result.present).toBe(false);
	});

	// R2: corrupt/partial JSON => { present: false }
	test("R2: returns { present: false } for corrupt JSON", () => {
		const dir = makeTempDir();
		writeFileSync(join(dir, LOCK_FILENAME), "{ this is not json");
		const result = inspectLock(dir);
		expect(result.present).toBe(false);
	});

	// R2b: valid JSON missing required heartbeat field => { present: false } (A3)
	test("R2b: returns { present: false } for valid JSON missing heartbeat", () => {
		const dir = makeTempDir();
		writeFileSync(
			join(dir, LOCK_FILENAME),
			JSON.stringify({ pid: process.pid, startTime: Date.now() }),
		);
		const result = inspectLock(dir);
		expect(result.present).toBe(false);
	});

	// R2c: empty object {} => { present: false } (A3 — no process.kill(undefined,0))
	test("R2c: returns { present: false } for empty object {}", () => {
		const dir = makeTempDir();
		writeFileSync(join(dir, LOCK_FILENAME), "{}");
		const result = inspectLock(dir);
		expect(result.present).toBe(false);
	});

	// R3: valid lock with live pid + fresh heartbeat
	test("R3: live pid + fresh heartbeat => present, pidAlive, fresh, elapsed>=0", () => {
		const dir = makeTempDir();
		writeLock(dir, { pid: process.pid });
		const result = inspectLock(dir);
		expect(result.present).toBe(true);
		if (result.present) {
			expect(result.pidAlive).toBe(true);
			expect(result.isHeartbeatFresh).toBe(true);
			expect(result.elapsedMs).toBeGreaterThanOrEqual(0);
			expect(result.pid).toBe(process.pid);
		}
	});

	// R4: valid lock with dead pid
	test("R4: dead pid => pidAlive false", () => {
		const dir = makeTempDir();
		writeLock(dir, { pid: 2_000_000_000 });
		const result = inspectLock(dir);
		expect(result.present).toBe(true);
		if (result.present) {
			expect(result.pidAlive).toBe(false);
		}
	});

	// R4b: old heartbeat => isHeartbeatFresh false (informational, independent of liveness)
	test("R4b: old heartbeat => isHeartbeatFresh false even with live pid", () => {
		const dir = makeTempDir();
		writeLock(dir, {
			pid: process.pid,
			heartbeat: Date.now() - 60_000, // 60s old
		});
		const result = inspectLock(dir, 30_000);
		expect(result.present).toBe(true);
		if (result.present) {
			expect(result.pidAlive).toBe(true);
			expect(result.isHeartbeatFresh).toBe(false);
		}
	});

	// R7: exposes lastProgressAt + isProgressing for a fresh, progressing lock
	test("R7: exposes lastProgressAt + isProgressing=true for fresh progress", () => {
		const dir = makeTempDir();
		writeLock(dir, { pid: process.pid });
		const result = inspectLock(dir);
		expect(result.present).toBe(true);
		if (result.present) {
			expect(typeof result.lastProgressAt).toBe("number");
			expect(result.lastProgressAt).toBeGreaterThan(0);
			expect(result.isProgressing).toBe(true);
		}
	});

	// R7b: stalled progress (fresh heartbeat) => isProgressing=false (the hang signal)
	test("R7b: old lastProgressAt + fresh heartbeat => isProgressing false", () => {
		const dir = makeTempDir();
		writeLock(dir, {
			pid: process.pid,
			heartbeat: Date.now(), // timer still stamping (looks alive)
			lastProgressAt: Date.now() - 600_000, // no real work for 10 min
		});
		const result = inspectLock(dir, 30_000, 300_000);
		expect(result.present).toBe(true);
		if (result.present) {
			expect(result.pidAlive).toBe(true);
			expect(result.isHeartbeatFresh).toBe(true); // heartbeat masks the hang
			expect(result.isProgressing).toBe(false); // progress reveals it
		}
	});

	// R7c: backward compat — old-binary lock (no lastProgressAt) falls back to heartbeat
	test("R7c: missing lastProgressAt falls back to heartbeat (not Invalid Date / NaN)", () => {
		const dir = makeTempDir();
		const now = Date.now();
		writeLock(dir, {
			pid: process.pid,
			heartbeat: now,
			omitLastProgressAt: true,
		});
		const result = inspectLock(dir);
		expect(result.present).toBe(true);
		if (result.present) {
			// lastProgressAt mirrors heartbeat, so it is a usable timestamp.
			expect(result.lastProgressAt).toBe(now);
			// Fresh heartbeat => treated as progressing (not instantly hung).
			expect(result.isProgressing).toBe(true);
			// ISO conversion of the fallback value must be valid (no Invalid Date).
			expect(new Date(result.lastProgressAt).toISOString()).not.toContain(
				"Invalid",
			);
		}
	});

	// R5: read-only proof — lock file STILL present after inspect
	test("R5: inspecting does NOT remove the lock file (read-only)", () => {
		const dir = makeTempDir();
		const lockPath = writeLock(dir, { pid: 2_000_000_000 }); // dead pid (stale-looking)
		expect(existsSync(lockPath)).toBe(true);
		inspectLock(dir);
		// A naive cleanup would unlink a stale lock; inspectLock must not.
		expect(existsSync(lockPath)).toBe(true);
		// Inspect again to be sure repeated reads are non-destructive.
		inspectLock(dir);
		expect(existsSync(lockPath)).toBe(true);
	});

	// R6: custom index dir (simulating MNEMEX_INDEX_DIR) — no double-join / basename assumption
	test("R6: resolves lock under a custom (non-.mnemex) index dir", () => {
		const dir = makeTempDir();
		const customIndexDir = join(dir, "custom-index-dir");
		require("node:fs").mkdirSync(customIndexDir, { recursive: true });
		writeLock(customIndexDir, { pid: process.pid });
		const result = inspectLock(customIndexDir);
		expect(result.present).toBe(true);
		if (result.present) {
			expect(result.pid).toBe(process.pid);
		}
		// And the SAME basename under a different parent must NOT be found.
		const empty = inspectLock(dir);
		expect(empty.present).toBe(false);
	});
});

/**
 * Unit tests for the dual-liveness + progress hang detection on the index lock.
 *
 * The lock carries TWO timestamps:
 *  - `heartbeat` — stamped every 1s by a timer; means "process alive". Stays
 *    fresh even when indexing is wedged (the LanceDB write hang), so it CANNOT
 *    detect a hang.
 *  - `lastProgressAt` — stamped only when real indexing work completes
 *    (recordProgress()). Stops advancing when the indexer hangs, which is how a
 *    hung-but-alive holder is detected and reclaimed.
 *
 * These tests prove:
 *  - recordProgress() advances lastProgressAt (only for the owning pid).
 *  - isLockStale: live pid + fresh progress => NOT stale.
 *  - isLockStale: live pid + OLD progress (fresh heartbeat) => STALE (the hang).
 *  - backward compat: a lock with heartbeat but NO lastProgressAt falls back to
 *    heartbeat — it is NOT treated as instantly stale.
 *  - acquire() RECLAIMS a hung-but-alive lock (the end-to-end auto-reclaim).
 */

import { afterEach, describe, expect, test } from "bun:test";
import {
	existsSync,
	mkdirSync,
	mkdtempSync,
	readFileSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
	createIndexLock,
	DEFAULT_PROGRESS_TIMEOUT,
	IndexLock,
	inspectLock,
	isLockStale,
} from "../../../src/core/lock.js";

const LOCK_FILENAME = ".indexing.lock";
const DEAD_PID = 2_000_000_000; // almost certainly not a live process
const tempDirs: string[] = [];

/** Create a temp project root with a `.mnemex` index dir (the default IndexLock dir). */
function makeProject(): { projectPath: string; indexDir: string } {
	const projectPath = mkdtempSync(join(tmpdir(), "lock-test-"));
	tempDirs.push(projectPath);
	const indexDir = join(projectPath, ".mnemex");
	mkdirSync(indexDir, { recursive: true });
	return { projectPath, indexDir };
}

/** Read the raw lock file JSON for assertions. */
function readLock(indexDir: string): {
	pid: number;
	startTime: number;
	heartbeat: number;
	lastProgressAt?: number;
	phase?: string;
	phaseStartedAt?: number;
	startedAt: string;
} {
	return JSON.parse(readFileSync(join(indexDir, LOCK_FILENAME), "utf-8"));
}

/** Write a lock file directly (lets us forge specific timestamps / omit fields). */
function writeLock(
	indexDir: string,
	overrides: Partial<{
		pid: number;
		startTime: number;
		heartbeat: number;
		lastProgressAt: number;
		phase: string;
		phaseStartedAt: number;
		startedAt: string;
		omitLastProgressAt: boolean;
	}> = {},
): void {
	const now = Date.now();
	const data: Record<string, unknown> = {
		pid: overrides.pid ?? process.pid,
		startTime: overrides.startTime ?? now,
		heartbeat: overrides.heartbeat ?? now,
		startedAt: overrides.startedAt ?? new Date(now).toISOString(),
	};
	if (!overrides.omitLastProgressAt) {
		data.lastProgressAt = overrides.lastProgressAt ?? now;
	}
	if (overrides.phase !== undefined) {
		data.phase = overrides.phase;
	}
	if (overrides.phaseStartedAt !== undefined) {
		data.phaseStartedAt = overrides.phaseStartedAt;
	}
	writeFileSync(join(indexDir, LOCK_FILENAME), JSON.stringify(data, null, 2));
}

afterEach(() => {
	while (tempDirs.length > 0) {
		const dir = tempDirs.pop();
		if (dir) {
			try {
				rmSync(dir, { recursive: true, force: true });
			} catch {
				// best effort
			}
		}
	}
});

describe("DEFAULT_PROGRESS_TIMEOUT", () => {
	test("is 5 minutes and much larger than the 10s stale window", () => {
		expect(DEFAULT_PROGRESS_TIMEOUT).toBe(300000);
	});
});

describe("recordProgress", () => {
	test("advances lastProgressAt when this process owns the lock", async () => {
		const { projectPath, indexDir } = makeProject();
		const lock = createIndexLock(projectPath);
		const acquired = await lock.acquire();
		expect(acquired.acquired).toBe(true);

		try {
			const before = readLock(indexDir).lastProgressAt as number;
			// Force the clock to move so the new timestamp is strictly greater.
			await new Promise((r) => setTimeout(r, 5));
			lock.recordProgress();
			const after = readLock(indexDir).lastProgressAt as number;

			expect(after).toBeGreaterThan(before);
			// Heartbeat is independent; recordProgress must not touch it.
			expect(typeof readLock(indexDir).heartbeat).toBe("number");
		} finally {
			lock.release();
		}
	});

	test("is a no-op when another pid owns the lock (does not steal it)", () => {
		const { projectPath, indexDir } = makeProject();
		// A lock owned by a different (dead) pid with an OLD progress timestamp.
		const old = Date.now() - 600_000;
		writeLock(indexDir, { pid: DEAD_PID, lastProgressAt: old });

		const lock = new IndexLock(projectPath);
		lock.recordProgress(); // we don't own it => must not write

		expect(readLock(indexDir).pid).toBe(DEAD_PID);
		expect(readLock(indexDir).lastProgressAt).toBe(old);
	});
});

describe("isLockStale", () => {
	const STALE = 10_000; // DEFAULT_STALE_TIMEOUT
	const PROGRESS = 300_000; // DEFAULT_PROGRESS_TIMEOUT

	test("live pid + fresh progress => NOT stale", () => {
		const now = Date.now();
		const lock = {
			pid: process.pid,
			startTime: now,
			heartbeat: now,
			lastProgressAt: now,
			startedAt: new Date(now).toISOString(),
		};
		expect(isLockStale(lock, STALE, PROGRESS)).toBe(false);
	});

	// THE KEY NEW TEST: the hang signature — fresh heartbeat, stalled progress.
	test("live pid + fresh heartbeat + OLD lastProgressAt => STALE (the hang)", () => {
		const now = Date.now();
		const lock = {
			pid: process.pid, // alive
			startTime: now - 700_000,
			heartbeat: now, // timer kept stamping => looks alive
			lastProgressAt: now - 600_000, // no real work for 10 min
			startedAt: new Date(now - 700_000).toISOString(),
		};
		// Heartbeat alone (the old logic) would say NOT stale; progress says STALE.
		expect(isLockStale(lock, STALE, PROGRESS)).toBe(true);
	});

	test("dead pid => STALE regardless of timestamps", () => {
		const now = Date.now();
		const lock = {
			pid: DEAD_PID,
			startTime: now,
			heartbeat: now,
			lastProgressAt: now,
			startedAt: new Date(now).toISOString(),
		};
		expect(isLockStale(lock, STALE, PROGRESS)).toBe(true);
	});

	// BACKWARD COMPAT: an old-binary lock has heartbeat but no lastProgressAt.
	test("no lastProgressAt + fresh heartbeat => NOT stale (falls back to heartbeat)", () => {
		const now = Date.now();
		const lock = {
			pid: process.pid,
			startTime: now,
			heartbeat: now, // fresh
			startedAt: new Date(now).toISOString(),
		} as {
			pid: number;
			startTime: number;
			heartbeat: number;
			startedAt: string;
		};
		// Must NOT be treated as instantly stale just because lastProgressAt is missing.
		expect(isLockStale(lock, STALE, PROGRESS)).toBe(false);
	});

	test("no lastProgressAt + OLD heartbeat => STALE via heartbeat fallback", () => {
		const now = Date.now();
		const lock = {
			pid: process.pid,
			startTime: now - 700_000,
			heartbeat: now - 600_000, // old heartbeat, no progress field at all
			startedAt: new Date(now - 700_000).toISOString(),
		};
		expect(isLockStale(lock, STALE, PROGRESS)).toBe(true);
	});

	test("secondary heartbeat check still trips when progress is fresh but heartbeat is old", () => {
		const now = Date.now();
		const lock = {
			pid: process.pid,
			startTime: now,
			heartbeat: now - 20_000, // older than 10s stale window
			lastProgressAt: now, // progress fresh
			startedAt: new Date(now).toISOString(),
		};
		expect(isLockStale(lock, STALE, PROGRESS)).toBe(true);
	});
});

describe("acquire() auto-reclaim", () => {
	// END-TO-END: the actual mission. A hung-but-alive holder must be reclaimed.
	test("reclaims a lock held by a LIVE pid with stalled progress", async () => {
		const { projectPath, indexDir } = makeProject();
		// Forge a lock owned by THIS (alive) process, fresh heartbeat, but no
		// progress for 10 min — exactly the hung-indexer signature.
		const now = Date.now();
		writeLock(indexDir, {
			pid: process.pid,
			heartbeat: now,
			lastProgressAt: now - 600_000,
			startTime: now - 700_000,
		})

/**
 * Regression test: background `mnemex` spawns must not crash the process when
 * the binary is absent from PATH.
 *
 * `child_process.spawn()` does NOT throw when the executable is missing — it
 * emits an asynchronous 'error' event. With no listener, Node re-raises it as
 * an unhandled 'error' and takes the process down, so a surrounding try/catch
 * never sees the ENOENT.
 *
 * This took down 15 CI tests across four unrelated suites from a single cause,
 * and the runner misattributed the crash to whichever test happened to be
 * running (a network docs test got blamed for a spawn ENOENT). It reproduces
 * for any user without mnemex on PATH: library use, npx, a dev checkout without
 * `npm link`, or CI.
 *
 * Sites that spawn "mnemex": src/editor/editor.ts, src/mcp/reindexer.ts,
 * src/mcp/server.ts.
 */

import { describe, expect, test } from "bun:test";
import { spawn } from "node:child_process";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const SRC = join(import.meta.dir, "../../../src");

describe("spawn() ENOENT semantics", () => {
	test("does not throw synchronously for a missing executable", () => {
		// The behaviour the old try/catch wrongly assumed.
		let threw = false;
		let child: ReturnType<typeof spawn> | undefined;
		try {
			child = spawn("definitely-not-a-real-binary-xyz", [], {
				stdio: "ignore",
			});
			child.on("error", () => {});
		} catch {
			threw = true;
		}
		expect(threw).toBe(false);
		child?.kill();
	});

	test("surfaces the failure asynchronously as an 'error' event", async () => {
		const err = await new Promise<NodeJS.ErrnoException>((resolve) => {
			const child = spawn("definitely-not-a-real-binary-xyz", [], {
				stdio: "ignore",
			});
			child.on("error", resolve);
		});
		expect(err.code).toBe("ENOENT");
	});
});

describe("every background mnemex spawn attaches an 'error' listener", () => {
	const sites = [
		"editor/editor.ts",
		"mcp/reindexer.ts",
		"mcp/server.ts",
	] as const;

	for (const rel of sites) {
		test(`${rel} handles spawn errors`, () => {
			const src = readFileSync(join(SRC, rel), "utf-8");

			// Only meaningful while the file still spawns mnemex.
			expect(src).toContain('spawn("mnemex"');

			// An 'error' listener must exist; without it a missing binary is fatal.
			expect(src).toMatch(/\.on\(\s*["']error["']/);
		});
	}
});

/**
 * Unit tests for the LanceDB write watchdog (`withTimeout`) in store.ts.
 *
 * The LanceDB 0.13.0 write path (table.add / createTable) can deadlock forever
 * (all tokio threads park in Condvar::wait, 0% CPU). `withTimeout` races the
 * write against a timer so a hung write THROWS instead of parking — which frees
 * the JS process to release its index lock and fail loudly.
 *
 * IMPORTANT: `withTimeout` cannot CANCEL the native call (LanceDB has no
 * AbortSignal); it only stops AWAITING it. These tests verify the await-side
 * behaviour: fast promises resolve through it; a never-resolving promise rejects
 * with LanceWriteTimeoutError after the (tiny, test-only) timeout.
 */

import { describe, expect, test } from "bun:test";
import {
	LANCEDB_WRITE_TIMEOUT_MS,
	LanceWriteTimeoutError,
	withTimeout,
} from "../../../src/core/store.js";

describe("LANCEDB_WRITE_TIMEOUT_MS", () => {
	test("is a generous 60s default", () => {
		expect(LANCEDB_WRITE_TIMEOUT_MS).toBe(60000);
	});
});

describe("withTimeout", () => {
	test("resolves with the value of a fast-settling promise", async () => {
		const fast = Promise.resolve(42);
		await expect(withTimeout(fast, 1000, "fast")).resolves.toBe(42);
	});

	test("resolves a promise that settles just before the timeout", async () => {
		const p = new Promise<string>((resolve) =>
			setTimeout(() => resolve("done"), 10),
		);
		await expect(withTimeout(p, 1000, "soon")).resolves.toBe("done");
	});

	test("throws LanceWriteTimeoutError on a promise that never resolves", async () => {
		// A never-resolving promise stands in for the hung native LanceDB write.
		// withTimeout must reject after `ms` even though `p` stays pending forever
		// (it cannot be cancelled — that is the documented limitation).
		const never = new Promise<void>(() => {});
		await expect(withTimeout(never, 50, "addChunks:table.add")).rejects.toThrow(
			LanceWriteTimeoutError,
		);
	});

	test("the thrown error carries the label and timeout ms", async () => {
		const never = new Promise<void>(() => {});
		try {
			await withTimeout(never, 50, "addCodeUnits:createTable");
			throw new Error("expected withTimeout to throw");
		} catch (err) {
			expect(err).toBeInstanceOf(LanceWriteTimeoutError);
			const e = err as LanceWriteTimeoutError;
			expect(e.label).toBe("addCodeUnits:createTable");
			expect(e.timeoutMs).toBe(50);
			expect(e.message).toContain("addCodeUnits:createTable");
			expect(e.message).toContain("50ms");
		}
	});

	test("propagates a rejection from the wrapped promise (not a timeout)", async () => {
		const boom = Promise.reject(new Error("native add failed"));
		await expect(withTimeout(boom, 1000, "rejecting")).rejects.toThrow(
			"native add failed",
		);
	});
});

/**
 * Regression tests for the zero-dimension vector guard in store.ts.
 *
 * LanceDB infers the table schema from the first written batch. A batch whose
 * vectors are empty arrays produces a `vector` column typed
 * `FixedSizeList[0]<Float32>`, which is permanently unqueryable: the table
 * opens and countRows() works, but every read touching `vector` fails.
 * Observed on a real 28,653-row index — LanceDB 0.33 raises
 * `LanceError(Schema): dimension must be a positive integer`, and 0.13 panics
 * in Rust with "attempt to divide by zero".
 *
 * The schema is immutable after creation, so the only recovery is a full
 * reindex. These tests pin the fail-fast behaviour that prevents it.
 */

import { describe, expect, test } from "bun:test";
import {
	assertVectorDimension,
	ZeroDimensionVectorError,
} from "../../../src/core/store.js";

describe("assertVectorDimension", () => {
	test("passes through a normal embedding dimension", () => {
		expect(assertVectorDimension(768, "addChunks")).toBe(768);
		expect(assertVectorDimension(1536, "addChunks")).toBe(1536);
	});

	test("passes through a dimension of 1", () => {
		expect(assertVectorDimension(1, "addChunks")).toBe(1);
	});

	test("rejects dimension 0 — the corruption case", () => {
		expect(() => assertVectorDimension(0, "addChunks")).toThrow(
			ZeroDimensionVectorError,
		);
	});

	test("rejects negative and non-finite dimensions", () => {
		expect(() => assertVectorDimension(-1, "addChunks")).toThrow(
			ZeroDimensionVectorError,
		);
		expect(() => assertVectorDimension(Number.NaN, "addChunks")).toThrow(
			ZeroDimensionVectorError,
		);
	});

	test("names the offending write path so the failure is actionable", () => {
		expect(() => assertVectorDimension(0, "addCodeUnits")).toThrow(
			/addCodeUnits/,
		);
	});

	test("error explains the likely cause and the required action", () => {
		let caught: Error | undefined;
		try {
			assertVectorDimension(0, "addDocuments");
		} catch (err) {
			caught = err as Error;
		}
		expect(caught).toBeInstanceOf(ZeroDimensionVectorError);
		expect(caught?.name).toBe("ZeroDimensionVectorError");
		expect(caught?.message).toContain("embedding provider");
		expect(caught?.message).toContain("reindex");
	});

	test("an empty vector array yields dimension 0 and is rejected", () => {
		// Mirrors the real call: assertVectorDimension(data[0].vector.length, ...)
		const batch = [{ vector: [] as number[] }];
		expect(() =>
			assertVectorDimension(batch[0].vector.length, "addChunks"),
		).toThrow(ZeroDimensionVectorError);
	});
});

/**
 * Tests for LLM JSON extraction logic.
 *
 * The extractJSON method must handle messy LLM responses including:
 * - Markdown code fences
 * - Multiple JSON objects (prompt echoing + actual output)
 * - Trailing commas
 * - Prefix/suffix text around JSON
 */

import { describe, expect, it } from "bun:test";

// Re-implement the extractJSON logic from client.ts for isolated testing
function findAllTopLevelJSON(content: string): string[] {
	const results: string[] = [];
	let i = 0;

	while (i < content.length) {
		const char = content[i];
		if (char !== "{" && char !== "[") {
			i++;
			continue;
		}

		const closeChar = char === "{" ? "}" : "]";
		let depth = 0;
		let inString = false;
		let escapeNext = false;
		let end = -1;

		for (let j = i; j < content.length; j++) {
			const c = content[j];

			if (escapeNext) {
				escapeNext = false;
				continue;
			}

			if (c === "\\") {
				escapeNext = true;
				continue;
			}

			if (c === '"') {
				inString = !inString;
				continue;
			}

			if (inString) continue;

			if (c === char) depth++;
			else if (c === closeChar) {
				depth--;
				if (depth === 0) {
					end = j + 1;
					break;
				}
			}
		}

		if (end > i) {
			results.push(content.slice(i, end));
			i = end;
		} else {
			i++;
		}
	}

	return results;
}

function extractJSON(content: string): unknown {
	// Strategy 1: Try parsing as-is
	try {
		return JSON.parse(content);
	} catch {
		// continue
	}

	// Strategy 2: Remove markdown code fences
	let cleaned = content
		.replace(/```(?:json|javascript|typescript|ts|js)?\s*/gi, "")
		.replace(/```/g, "")
		.trim();

	try {
		return JSON.parse(cleaned);
	} catch {
		// continue
	}

	// Strategy 3: Find ALL top-level JSON structures and try each
	const candidates = findAllTopLevelJSON(cleaned);

	for (let i = candidates.length - 1; i >= 0; i--) {
		const candidate = candidates[i];
		try {
			return JSON.parse(candidate);
		} catch {
			const fixed = candidate.replace(/,\s*([}\]])/g, "$1");
			try {
				return JSON.parse(fixed);
			} catch {
				// next
			}
		}
	}

	// Strategy 4: Last resort
	const jsonStartBrace = cleaned.indexOf("{");
	const jsonStartBracket = cleaned.indexOf("[");
	let jsonStart = -1;

	if (jsonStartBrace !== -1 && jsonStartBracket !== -1) {
		jsonStart = Math.min(jsonStartBrace, jsonStartBracket);
	} else if (jsonStartBrace !== -1) {
		jsonStart = jsonStartBrace;
	} else if (jsonStartBracket !== -1) {
		jsonStart = jsonStartBracket;
	}

	if (jsonStart === -1) return null;

	cleaned = cleaned.slice(jsonStart);

	const lastBrace = cleaned.lastIndexOf("}");
	const lastBracket = cleaned.lastIndexOf("]");
	const lastClose = Math.max(lastBrace, lastBracket);
	if (lastClose > 0) {
		const trimmed = cleaned.slice(0, lastClose + 1);
		try {
			return JSON.parse(trimmed);
		} catch {
			try {
				return JSON.parse(trimmed.replace(/,\s*([}\]])/g, "$1"));
			} catch {
				// give up
			}
		}
	}

	return null;
}

describe("JSON Extraction", () => {
	it("should parse clean JSON", () => {
		const result = extractJSON('{"summary": "hello"}');
		expect(result).toEqual({ summary: "hello" });
	});

	it("should handle markdown code fences", () => {
		const result = extractJSON('```json\n{"summary": "hello"}\n```');
		expect(result).toEqual({ summary: "hello" });
	});

	it("should handle prefix text before JSON", () => {
		const result = extractJSON(
			'Here is the JSON summary:\n{"summary": "hello"}',
		);
		expect(result).toEqual({ summary: "hello" });
	});

	it("should handle suffix text after JSON", () => {
		const result = extractJSON('{"summary": "hello"}\n\nI hope this helps!');
		expect(result).toEqual({ summary: "hello" });
	});

	it("should handle trailing commas", () => {
		const result = extractJSON('{"summary": "hello", "items": ["a", "b",],}');
		expect(result).toEqual({ summary: "hello", items: ["a", "b"] });
	});

	it("should handle multiple JSON objects (pick last)", () => {
		// Simulates when the LLM echoes prompt JSON templates then outputs its own
		const response = `The file contains this JSON template:
{"template": "example", "fields": ["a", "b"]}

Here is my analysis:
{"summary": "This file defines enrichment prompts", "responsibilities": ["Prompt generation"]}`;

		const result = extractJSON(response) as any;
		expect(result.summary).toBe("This file defines enrichment prompts");
	});

	it("should handle JSON with nested braces in strings", () => {
		const result = extractJSON(
			'{"summary": "Uses pattern {key: value}", "count": 1}',
		);
		expect(result).toEqual({
			summary: "Uses pattern {key: value}",
			count: 1,
		});
	});

	it("should handle JSON arrays", () => {
		const result = extractJSON('[{"name": "a"}, {"name": "b"}]');
		expect(result).toEqual([{ name: "a" }, { name: "b" }]);
	});

	it("should handle response with echoed prompt JSON + actual output JSON", () => {
		// This is the enrichment.ts failure case: the LLM sees JSON templates
		// in the source code and may echo them before producing its own output
		const response = `\`\`\`json
{
  "summary": "One paragraph describing the file's main purpose",
  "responsibilities": ["Main responsibility 1"],
  "exports": ["exportedFunction1"],
  "dependencies": ["imported/module"],
  "patterns": ["Pattern used 1"]
}
\`\`\`

Actually, here is the correct analysis:

{
  "summary": "Defines prompt templates for LLM-based code enrichment",
  "responsibilities": ["Define system prompts for each document type", "Build user prompts for file and symbol summaries"],
  "exports": ["SYSTEM_PROMPTS", "buildFileSummaryPrompt", "buildSymbolSummaryPrompt"],
  "dependencies": ["../../types.js"],
  "patterns": ["Template pattern", "String interpolation"]
}`;

		const result = extractJSON(response) as any;
		// Should pick the last (more specific) JSON object
		expect(result.summary).toContain("prompt templates");
	});

	it("should return null for non-JSON content", () => {
		const result = extractJSON("This is just plain text with no JSON.");
		expect(result).toBeNull();
	});

	it("should handle escaped quotes in strings", () => {
		const result = extractJSON('{"summary": "Uses \\"quoted\\" values"}');
		expect(result).toEqual({ summary: 'Uses "quoted" values' });
	});
});

/**
 * Auth header behaviour for the OpenAI-compatible local LLM client.
 *
 * Local Ollama (http://localhost:11434/v1) and LM Studio accept unauthenticated
 * requests. Ollama Cloud (https://ollama.com/v1) rejects them with HTTP 401.
 * The client must therefore send `Authorization: Bearer …` when a key is
 * configured and send no such header when one is not, so local setups keep
 * working unchanged.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { LocalLLMClient } from "../../../src/llm/providers/local.js";

const originalFetch = globalThis.fetch;
const originalKey = process.env.OLLAMA_API_KEY;

/** Capture headers of the next chat/completions request. */
function captureHeaders(): { get: () => Record<string, string> } {
	let seen: Record<string, string> = {};
	globalThis.fetch = (async (url: any, init: any) => {
		if (String(url).includes("/chat/completions")) {
			seen = { ...(init?.headers ?? {}) };
		}
		return new Response(
			JSON.stringify({
				id: "1",
				model: "m",
				choices: [
					{
						message: { role: "assistant", content: "ok" },
						finish_reason: "stop",
					},
				],
			}),
			{ status: 200, headers: { "Content-Type": "application/json" } },
		);
	}) as unknown as typeof fetch;
	return { get: () => seen };
}

afterEach(() => {
	globalThis.fetch = originalFetch;
	if (originalKey === undefined) delete process.env.OLLAMA_API_KEY;
	else process.env.OLLAMA_API_KEY = originalKey;
});

beforeEach(() => {
	delete process.env.OLLAMA_API_KEY;
});

describe("LocalLLMClient auth headers", () => {
	test("sends no Authorization header when no key is configured", async () => {
		const cap = captureHeaders();
		const client = new LocalLLMClient({
			endpoint: "http://localhost:11434/v1",
		});
		await client.complete([{ role: "user", content: "hi" }]);

		expect(cap.get()["Content-Type"]).toBe("application/json");
		expect(cap.get().Authorization).toBeUndefined();
	});

	test("sends Bearer auth when apiKey is passed explicitly", async () => {
		const cap = captureHeaders();
		const client = new LocalLLMClient({
			endpoint: "https://ollama.com/v1",
			apiKey: "test-key-123",
		});
		await client.complete([{ role: "user", content: "hi" }]);

		expect(cap.get().Authorization).toBe("Bearer test-key-123");
	});

	test("falls back to OLLAMA_API_KEY from the environment", async () => {
		process.env.OLLAMA_API_KEY = "env-key-456";
		const cap = captureHeaders();
		const client = new LocalLLMClient({ endpoint: "https://ollama.com/v1" });
		await client.complete([{ role: "user", content: "hi" }]);

		expect(cap.get().Authorization).toBe("Bearer env-key-456");
	});

	test("explicit apiKey wins over the environment variable", async () => {
		process.env.OLLAMA_API_KEY = "env-key-456";
		const cap = captureHeaders();
		const client = new LocalLLMClient({
			endpoint: "https://ollama.com/v1",
			apiKey: "explicit-key",
		});
		await client.complete([{ role: "user", content: "hi" }]);

		expect(cap.get().Authorization).toBe("Bearer explicit-key");
	});
});

/**
 * Spec resolution for hosted Ollama (`ollama-cloud/...`).
 *
 * Ollama Cloud speaks the same OpenAI-compatible protocol as local Ollama, so
 * it reuses the "local" provider — but it must resolve to https://ollama.com/v1
 * rather than localhost, otherwise the request silently goes to a local daemon
 * that is usually not running.
 */

import { describe, expect, test } from "bun:test";
import { LLMResolver } from "../../../src/llm/resolver.js";

describe("LLMResolver: ollama-cloud spec", () => {
	test("resolves to the hosted endpoint, not localhost", () => {
		const spec = LLMResolver.parseSpec("ollama-cloud/gemma4:31b");
		expect(spec.provider).toBe("local");
		expect(spec.endpoint).toBe("https://ollama.com/v1");
		expect(spec.model).toBe("gemma4:31b");
	});

	test("keeps plain `ollama` pointed at localhost", () => {
		const spec = LLMResolver.parseSpec("ollama/llama3.2");
		expect(spec.provider).toBe("local");
		expect(spec.endpoint).toBe("http://localhost:11434/v1");
	});

	test("bare `ollama-cloud` falls back to a sensible default model", () => {
		const spec = LLMResolver.parseSpec("ollama-cloud");
		expect(spec.endpoint).toBe("https://ollama.com/v1");
		expect(spec.model).toBe("gemma4:31b");
	});

	test("preserves model names containing slashes", () => {
		const spec = LLMResolver.parseSpec("ollama-cloud/library/qwen3.5:397b");
		expect(spec.model).toBe("library/qwen3.5:397b");
		expect(spec.endpoint).toBe("https://ollama.com/v1");
	});

	test("cloud and local specs do not collide", () => {
		const cloud = LLMResolver.parseSpec("ollama-cloud/gemma4:31b");
		const local = LLMResolver.parseSpec("ollama/gemma4:31b");
		expect(cloud.endpoint).not.toBe(local.endpoint);
		expect(cloud.model).toBe(local.model);
	});
});

/**
 * Tool-level tests for the analysis + search index-state wiring.
 *
 * Asserts dead_code / test_gaps still return their domain results AND carry the
 * additive index-state block: canReturnCachedResults, an indexing{} block when a
 * live lock is present, and a caveat (recommendations non-empty) when stale.
 */

import { afterEach, describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { IndexStateManager } from "../../../src/mcp/state-manager.js";
import { registerAnalysisTools } from "../../../src/mcp/tools/analysis.js";
import type { ToolDeps } from "../../../src/mcp/tools/deps.js";

const LOCK_FILENAME = ".indexing.lock";
const tempDirs: string[] = [];

interface CapturedTool {
	handler: (args: Record<string, unknown>) => Promise<{
		content: Array<{ type: string; text: string }>;
	}>;
}

function makeCapturingServer(): {
	server: unknown;
	tools: Map<string, CapturedTool>;
} {
	const tools = new Map<string, CapturedTool>();
	const server = {
		tool(
			name: string,
			_desc: string,
			_schema: unknown,
			handler: CapturedTool["handler"],
		) {
			tools.set(name, { handler });
		},
	};
	return { server, tools };
}

function makeIndexDir(): string {
	const root = mkdtempSync(join(tmpdir(), "analysis-state-test-"));
	tempDirs.push(root);
	const indexDir = join(root, ".mnemex");
	mkdirSync(indexDir, { recursive: true });
	return indexDir;
}

function writeIndexDb(indexDir: string): void {
	writeFileSync(join(indexDir, "index.db"), "fake sqlite bytes");
}

function writeLiveLock(indexDir: string): void {
	const now = Date.now();
	writeFileSync(
		join(indexDir, LOCK_FILENAME),
		JSON.stringify({
			pid: process.pid,
			startTime: now,
			heartbeat: now,
			startedAt: new Date(now).toISOString(),
		}),
	);
}

async function makeDeps(indexDir: string): Promise<ToolDeps> {
	const stateManager = new IndexStateManager(indexDir);
	await stateManager.initialize();
	// Empty-symbol tracker double: analyzer returns empty result sets, which is
	// fine — we are testing the additive index-state envelope, not analysis logic.
	const tracker = {
		getAllSymbols: () => [],
		getSymbol: () => null,
		getStats: () => ({ totalFiles: 5, lastIndexed: null }),
	};
	const cache = { get: async () => ({ tracker }) };
	return {
		// biome-ignore lint/suspicious/noExplicitAny: minimal test double
		cache: cache as any,
		stateManager,
		// biome-ignore lint/suspicious/noExplicitAny: only indexDir/workspaceRoot used
		config: { indexDir, workspaceRoot: join(indexDir, "..") } as any,
		// biome-ignore lint/suspicious/noExplicitAny: logger stub
		logger: { info() {}, warn() {}, debug() {}, error() {} } as any,
		serverStartTime: Date.now(),
		watcherActive: false,
	};
}

function parse(result: {
	content: Array<{ type: string; text: string }>;
}): Record<string, unknown> {
	return JSON.parse(result.content[0].text);
}

afterEach(() => {
	while (tempDirs.length > 0) {
		const dir = tempDirs.pop();
		if (dir) {
			try {
				rmSync(dir, { recursive: true, force: true });
			} catch {
				// best effort
			}
		}
	}
});

describe("analysis tools index-state wiring", () => {
	test("dead_code: returns results + canReturnCachedResults + caveat when stale", async () => {
		const indexDir = makeIndexDir();
		writeIndexDb(indexDir);
		const deps = await makeDeps(indexDir);
		deps.stateManager.recordChange("src/foo.ts"); // stale

		const { server, tools } = makeCapturingServer();
		// biome-ignore lint/suspicious/noExplicitAny: fake server
		registerAnalysisTools(server as any, deps);
		const result = await tools.get("dead_code")!.handler({ limit: 50 });
		const json = parse(result);

		// Domain results still present
		expect(json.deadSymbols).toBeDefined();
		expect(json.totalAnalyzed).toBeDefined();
		// Additive index-state envelope
		expect(json.canReturnCachedResults).toBe(true);
		expect(json.status).toBe("stale");
		expect(Array.isArray(json.recommendations)).toBe(true);
		expect((json.recommendations as unknown[]).length).toBeGreaterThan(0);
		// Existing freshness preserved
		expect(json.freshness).toBe("stale");
		expect(json.reindexingInProgress).toBe(false);
	});

	test("test_gaps: includes indexing{} block when a live lock is present", async () => {
		const indexDir = makeIndexDir();
		writeIndexDb(indexDir);
		writeLiveLock(indexDir);
		const deps = await makeDeps(indexDir);

		const { server, tools } = makeCapturingServer();
		// biome-ignore lint/suspicious/noExplicitAny: fake server
		registerAnalysisTools(server as any, deps);
		const result = await tools.get("test_gaps")!.handler({ limit: 30 });
		const json = parse(result);

		expect(json.untestedSymbols).toBeDefined();
		expect(json.status).toBe("indexing_in_progress");
		expect(json.indexing).not.toBeNull();
		expect(json.canReturnCachedResults).toBe(true);
	});

	test("freshness keys appear exactly once (no duplicate-key collision)", async () => {
		const indexDir = makeIndexDir();
		writeIndexDb(indexDir);
		const deps = await makeDeps(indexDir);

		const { server, tools } = makeCapturingServer();
		// biome-ignore lint/suspicious/noExplicitAny: fake server
		registerAnalysisTools(server as any, deps);
		const result = await tools.get("dead_code")!.handler({ limit: 50 });
		const raw = result.content[0].text;

		// responseTimeMs is owned solely by buildFreshness; assert it appears once.
		const occurrences = raw.split('"responseTimeMs"').length - 1;
		expect(occurrences).toBe(1);
		// And the JSON parses (no structural issue from the double spread).
		expect(() => JSON.parse(raw)).not.toThrow();
	});
});

/**
 * Unit tests for IndexCache
 *
 * IndexCache requires an actual .mnemex/index.db to load the full resource
 * graph.  In a unit test environment we do not have a real indexed project,
 * so tests focus on the observable structural behaviour:
 *
 * 1. get() throws a descriptive error when no index.db exists
 * 2. invalidate() causes the next get() to re-attempt loading (verified via
 *    counting load attempts through thrown errors)
 * 3. Concurrent get() calls deduplicate: only one load is attempted even when
 *    multiple callers await simultaneously
 *
 * If the test environment has a real index at the project root the tests that
 * check error behaviour will still exercise the correct code paths because they
 * point at a temp directory that has no index.
 *
 * Black-box: tests operate through the public IndexCache API only.
 */

import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { IndexCache } from "../../../src/mcp/cache.js";
import { Logger } from "../../../src/mcp/logger.js";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Silent logger for test use */
function makeLogger(): Logger {
	return new Logger("error"); // suppress all non-error output during tests
}

/**
 * Create a temp project directory without any .mnemex/index.db.
 * IndexCache will throw when get() is called on this path.
 */
function makeTempProject(): string {
	return mkdtempSync(join(tmpdir(), "mcp-cache-test-"));
}

/**
 * Create a temp project directory structure that looks like a valid project
 * but has an index.db that is actually a stub file. This makes existsSync
 * return true so load() proceeds — but it will fail when createFileTracker
 * tries to open it as a real LanceDB database.
 *
 * We use this only to verify that get() DOES attempt a load when the file
 * exists, rather than short-circuiting before that point.
 */
function makeTempProjectWithStubIndex(): {
	projectPath: string;
	indexDir: string;
} {
	const projectPath = mkdtempSync(join(tmpdir(), "mcp-cache-stub-test-"));
	const indexDir = join(projectPath, ".mnemex");
	mkdirSync(indexDir, { recursive: true });
	// Write a stub db file - not a real LanceDB database, but existsSync passes
	writeFileSync(join(indexDir, "index.db"), "stub", "utf-8");
	return { projectPath, indexDir };
}

function cleanup(path: string): void {
	try {
		require("node:fs").rmSync(path, { recursive: true, force: true });
	} catch {
		// best effort
	}
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe("IndexCache", () => {
	let projectPath: string;

	afterEach(() => {
		if (projectPath) cleanup(projectPath);
	});

	// -------------------------------------------------------------------------
	// get() - no index.db exists
	// -------------------------------------------------------------------------

	describe("get() when no index.db exists", () => {
		beforeEach(() => {
			projectPath = makeTempProject();
		});

		test("throws an error describing where to find the missing index", async () => {
			const indexDir = join(projectPath, ".mnemex");
			const cache = new IndexCache(projectPath, indexDir, 500, makeLogger());

			await expect(cache.get()).rejects.toThrow();
		});

		test("thrown error mentions the project path or instructs user to index", async () => {
			const indexDir = join(projectPath, ".mnemex");
			const cache = new IndexCache(projectPath, indexDir, 500, makeLogger());

			let errorMessage = "";
			try {
				await cache.get();
			} catch (err) {
				errorMessage = err instanceof Error ? err.message : String(err);
			}

			// Requirements: error should mention indexing or the project path
			const mentionsIndex =
				errorMessage.toLowerCase().includes("index") ||
				errorMessage.toLowerCase().includes("mnemex") ||
				errorMessage.includes(projectPath);
			expect(mentionsIndex).toBe(true);
		});
	});

	// -------------------------------------------------------------------------
	// invalidate() - causes next get() to reload
	// -------------------------------------------------------------------------

	describe("invalidate()", () => {
		beforeEach(() => {
			projectPath = makeTempProject();
		});

		test("after invalidate(), get() re-attempts loading (throws again)", async () => {
			const indexDir = join(projectPath, ".mnemex");
			const cache = new IndexCache(projectPath, indexDir, 500, makeLogger());

			// First call throws (no index)
			await expect(cache.get()).rejects.toThrow();

			// invalidate() on a cache that never loaded successfully is a no-op
			// (no cached value to clear) - this should not throw
			expect(() => cache.invalidate()).not.toThrow();

			// Second call also throws - it re-attempted loading
			await expect(cache.get()).rejects.toThrow();
		});

		test("close() does not throw when cache was never loaded", () => {
			const indexDir = join(projectPath, ".mnemex");
			const cache = new IndexCache(projectPath, indexDir, 500, makeLogger());
			expect(() => cache.close()).not.toThrow();
		});
	});

	// -------------------------------------------------------------------------
	// Concurrent get() calls - deduplication
	// -------------------------------------------------------------------------

	describe("concurrent get() calls deduplicate load attempts", () => {
		beforeEach(() => {
			projectPath = makeTempProject();
		});

		test("multiple simultaneous get() calls all reject with the same error type", async () => {
			const indexDir = join(projectPath, ".mnemex");
			const cache = new IndexCache(projectPath, indexDir, 500, makeLogger());

			// Fire multiple concurrent gets
			const promises = [cache.get(), cache.get(), cache.get()];

			const results = await Promise.allSettled(promises);

			// All should have been rejected (no index exists)
			for (const result of results) {
				expect(result.status).toBe("rejected");
			}
		});

		test("concurrent get() calls share the same load attempt (not N separate loads)", async () => {
			// We verify this behaviourally: if each call triggered a separate load,
			// race conditions between them would make them behave differently.
			// Since they all fail with the same error (from one shared load),
			// the error messages should be identical.
			const indexDir = join(projectPath, ".mnemex");
			const cache = new IndexCache(projectPath, indexDir, 500, makeLogger());

			const results = await Promise.allSettled([
				cache.get(),
				cache.get(),
