			let fired = false;
			detector.watch(() => {
				fired = true;
			});

			// Simulate a reindex: remove lock then update db mtime
			await sleep(POLL_MS * 2);
			removeLock(indexDir);
			touchDb(indexDir, Date.now() + 100); // definitely newer

			// Wait long enough for at least two poll cycles
			await sleep(POLL_MS * 6);
