		test("does NOT fire if lock is still present", async () => {
			createOldDb(indexDir);
			createLock(indexDir);

			const detector = new CompletionDetector(indexDir, POLL_MS);
			let fired = false;
			detector.watch(() => {
				fired = true;
			});

			// Update mtime but keep lock
			await sleep(POLL_MS * 2);
