function restoreEnv(snap: EnvSnapshot): void {
	for (const key of ENV_KEYS) {
		if (snap[key] === undefined) {
			delete process.env[key];
		} else {
			process.env[key] = snap[key];
		}
	}
}

function clearMcpEnv(): void {
	for (const key of ENV_KEYS) {
		delete process.env[key];
	}
}

