import * as vscode from "vscode";

/**
 * Resolves the cursor position to a symbol name using VS Code's
 * DocumentSymbolProvider. Returns null if no symbol is found at the cursor.
 */
export class CursorTracker {
	private _debounceTimer: ReturnType<typeof setTimeout> | undefined;
	private _lastSymbolName = "";
	private _pinned = false;
	private readonly _disposables: vscode.Disposable[] = [];

	constructor(
		private readonly _onSymbolChange: (symbolName: string | null) => void,
	) {}

	/**
	 * Start tracking cursor movements. Calls onSymbolChange when the symbol
	 * under the cursor changes (debounced 500ms, deduplicated).
	 */
	start(): void {
		this._disposables.push(
			vscode.window.onDidChangeTextEditorSelection((e) => {
				if (this._pinned) {
					return;
				}
				this._scheduleResolve(e.textEditor);
			}),
			vscode.window.onDidChangeActiveTextEditor((editor) => {
				if (this._pinned || !editor) {
					return;
				}
				this._scheduleResolve(editor);
			}),
		);
	}

	togglePin(): boolean {
		this._pinned = !this._pinned;
		return this._pinned;
	}

	get pinned(): boolean {
		return this._pinned;
	}

	dispose(): void {
		if (this._debounceTimer) {
			clearTimeout(this._debounceTimer);
		}
		for (const d of this._disposables) {
			d.dispose();
		}
		this._disposables.length = 0;
	}

	private _scheduleResolve(editor: vscode.TextEditor): void {
		if (this._debounceTimer) {
			clearTimeout(this._debounceTimer);
		}
		this._debounceTimer = setTimeout(() => {
			void this._resolveSymbol(editor);
		}, 500);
	}

	private async _resolveSymbol(editor: vscode.TextEditor): Promise<void> {
		const position = editor.selection.active;
		const uri = editor.document.uri;

		// Only process file:// URIs (skip output panels, git diffs, etc.)
		if (uri.scheme !== "file") {
			return;
		}

		try {
			const symbols = await vscode.commands.executeCommand<
				vscode.DocumentSymbol[]
			>("vscode.executeDocumentSymbolProvider", uri);

			if (!symbols || symbols.length === 0) {
				if (this._lastSymbolName !== "") {
					this._lastSymbolName = "";
					this._onSymbolChange(null);
				}
				return;
			}

			const symbolName = this._findSymbolAtPosition(symbols, position);

			if (symbolName !== this._lastSymbolName) {
				this._lastSymbolName = symbolName;
				this._onSymbolChange(symbolName || null);
			}
		} catch {
			// DocumentSymbolProvider not available for this language — silently ignore
		}
	}

	/**
	 * Walk the DocumentSymbol tree to find the innermost symbol containing the position.
	 * Returns the symbol name, or empty string if the cursor is not inside any symbol.
	 */
	private _findSymbolAtPosition(
		symbols: vscode.DocumentSymbol[],
		position: vscode.Position,
	): string {
		for (const symbol of symbols) {
			if (symbol.range.contains(position)) {
				// Check children first for a more specific match
				const childName = this._findSymbolAtPosition(symbol.children, position);
				if (childName) {
					return childName;
				}
				// Only return function/class/method/interface-level symbols, not variables
				if (this._isTrackableKind(symbol.kind)) {
					return symbol.name;
				}
			}
		}
		return "";
	}

	private _isTrackableKind(kind: vscode.SymbolKind): boolean {
		return (
			kind === vscode.SymbolKind.Function ||
			kind === vscode.SymbolKind.Method ||
			kind === vscode.SymbolKind.Class ||
			kind === vscode.SymbolKind.Interface ||
			kind === vscode.SymbolKind.Enum ||
			kind === vscode.SymbolKind.Constructor ||
			kind === vscode.SymbolKind.Struct
		);
	}
}

import * as vscode from "vscode";
import { getNonce } from "./util/nonce.js";
import { CliBridge } from "./CliBridge.js";
import { log } from "./log.js";
import type {
	WebviewToHostMessage,
	HostToWebviewMessage,
} from "./types/messages.js";

/**
 * SearchProvider implements the VS Code WebviewViewProvider for the mnemex
 * sidebar panel. It manages the React webview, routes messages from the webview
 * to the CliBridge, and posts results back.
 *
 * retainContextWhenHidden: true — React state is preserved when panel is hidden.
 */
export class SearchProvider implements vscode.WebviewViewProvider {
	public static readonly viewId = "mnemexSearch";

	private _view?: vscode.WebviewView;
	private readonly _bridge: CliBridge;

	constructor(
		private readonly _extensionUri: vscode.Uri,
		private readonly _context: vscode.ExtensionContext,
	) {
		this._bridge = new CliBridge();
	}

	resolveWebviewView(
		webviewView: vscode.WebviewView,
		_context: vscode.WebviewViewResolveContext,
		_token: vscode.CancellationToken,
	): void {
		this._view = webviewView;

		webviewView.webview.options = {
			enableScripts: true,
			localResourceRoots: [
				vscode.Uri.joinPath(this._extensionUri, "dist", "webview-ui"),
			],
		};

		webviewView.webview.html = this._getHtmlForWebview(webviewView.webview);

		webviewView.webview.onDidReceiveMessage(
			(message: WebviewToHostMessage) => this._handleMessage(message),
			undefined,
			this._context.subscriptions,
		);
	}

	/**
	 * Public method called by the mnemex.reindex command.
	 */
	async reindex(): Promise<void> {
		const requestId = `reindex-${Date.now()}`;
		const projectPath = this._getProjectPath();
		if (!projectPath) {
			void vscode.window.showErrorMessage(
				"mnemex: No workspace folder open.",
			);
			return;
		}

		this._postMessage({ type: "loading", requestId });

		try {
			await this._bridge.index(
				projectPath,
				(line) => {
					this._postMessage({ type: "reindexLine", requestId, line });
				},
				requestId,
			);
			this._postMessage({ type: "reindexComplete", requestId });
		} catch (err) {
			const msg = err instanceof Error ? err.message : String(err);
			this._postMessage({ type: "error", requestId, message: msg });
		}
	}

	private async _handleMessage(message: WebviewToHostMessage): Promise<void> {
		const projectPath = this._getProjectPath();
		log(`handleMessage: type=${message.type} projectPath=${projectPath}`);

		if (message.type === "ready") {
			// Send init state. If the webview missed a previous init, this re-sends it.
			if (!projectPath) {
				// No workspace open
				this._postMessage({
					type: "init",
					projectPath: "",
					indexExists: false,
				});
				return;
			}

			try {
				const status = await this._bridge.status(projectPath);
				this._postMessage({
					type: "init",
					projectPath,
					indexExists: status.exists,
				});
				// Also send the full status for the StatusBar
				const statusRequestId = `init-status-${Date.now()}`;
				this._postMessage({
					type: "statusResult",
					requestId: statusRequestId,
					status,
				});
			} catch {
				this._postMessage({ type: "init", projectPath, indexExists: false });
			}
			return;
		}

		if (!projectPath) {
			if (
				"requestId" in message &&
				typeof (message as { requestId?: string }).requestId === "string"
			) {
				this._postMessage({
					type: "error",
					requestId: (message as { requestId: string }).requestId,
					message: "No workspace folder open. Open a folder to use mnemex.",
				});
			}
			return;
		}

		if (message.type === "cancel") {
			this._bridge.cancel(message.requestId);
			return;
		}

		if (message.type === "openFile") {
			await this._openFile(message.filePath, message.line, message.endLine);
			return;
		}

		// Companion messages are handled by CompanionPanelProvider, not here
		if (
			message.type === "companionReady" ||
			message.type === "companionOpenFile" ||
			message.type === "companionTogglePin"
		) {
			return;
		}

		const { requestId } = message;
		this._postMessage({ type: "loading", requestId });

		try {
			switch (message.type) {
				case "search": {
					const results = await this._bridge.search(
						message.query,
						projectPath,
						requestId,
					);
					this._postMessage({
						type: "searchResults",
						requestId,
						results,
						query: message.query,
					});
					break;
				}

				case "getMap": {
					const entries = await this._bridge.map(projectPath, requestId);
					this._postMessage({ type: "mapResult", requestId, entries });
					break;
				}

				case "getSymbol": {
					const symbol = await this._bridge.symbol(
						message.name,
						projectPath,
						requestId,
					);
					this._postMessage({ type: "symbolResult", requestId, symbol });
					break;
				}

				case "getCallers": {
					const data = await this._bridge.callers(
						message.name,
						projectPath,
						requestId,
					);
					this._postMessage({ type: "callersResult", requestId, data });
					break;
				}

				case "getCallees": {
					const data = await this._bridge.callees(
						message.name,
						projectPath,
						requestId,
					);
					this._postMessage({ type: "calleesResult", requestId, data });
					break;
				}

				case "getContext": {
					const data = await this._bridge.context(
						message.name,
						projectPath,
						requestId,
					);
					this._postMessage({ type: "contextResult", requestId, data });
					break;
				}

				case "getDeadCode": {
					const items = await this._bridge.deadCode(projectPath, requestId);
					this._postMessage({ type: "deadCodeResult", requestId, items });
					break;
				}

				case "getTestGaps": {
					const items = await this._bridge.testGaps(projectPath, requestId);
					this._postMessage({ type: "testGapsResult", requestId, items });
					break;
				}

				case "getImpact": {
					const data = await this._bridge.impact(
						message.name,
						projectPath,
						requestId,
					);
					this._postMessage({ type: "impactResult", requestId, data });
					break;
				}

				case "getStatus": {
					const status = await this._bridge.status(projectPath, requestId);
					this._postMessage({ type: "statusResult", requestId, status });
					break;
				}

				case "reindex": {
					await this._bridge.index(
						projectPath,
						(line) => {
							this._postMessage({ type: "reindexLine", requestId, line });
						},
						requestId,
					);
					this._postMessage({ type: "reindexComplete", requestId });
					break;
				}

				default: {
					// Unhandled message types are silently ignored for forward compatibility
					break;
				}
			}
		} catch (err) {
			const msg = err instanceof Error ? err.message : String(err);
			this._postMessage({ type: "error", requestId, message: msg });
		}
	}

	private _postMessage(message: HostToWebviewMessage): void {
		this._view?.webview.postMessage(message);
	}

	private async _openFile(
		filePath: string,
		line: number,
		endLine?: number,
	): Promise<void> {
		log(`openFile: ${filePath}:${line}${endLine ? `-${endLine}` : ""}`);
		try {
			const uri = vscode.Uri.file(filePath);
			const doc = await vscode.workspace.openTextDocument(uri);
			// Convert 1-based line numbers to 0-based VS Code positions
			const startPos = new vscode.Position(Math.max(0, line - 1), 0);
			const endPos =
				endLine && endLine > line
					? new vscode.Position(
							Math.min(endLine - 1, doc.lineCount - 1),
							doc.lineAt(Math.min(endLine - 1, doc.lineCount - 1)).text.length,
						)
					: startPos;
			await vscode.window.showTextDocument(doc, {
				selection: new vscode.Range(startPos, endPos),
			});
		} catch (err) {
			const msg = err instanceof Error ? err.message : String(err);
			void vscode.window.showErrorMessage(
				`mnemex: Cannot open file — ${msg}`,
			);
		}
	}

	private _getProjectPath(): string | undefined {
		const folders = vscode.workspace.workspaceFolders;
		if (!folders || folders.length === 0) {
			return undefined;
		}
		return folders[0].uri.fsPath

import * as vscode from "vscode";
import { SearchProvider } from "./SearchProvider.js";
import { CompanionPanelProvider } from "./CompanionPanelProvider.js";
import { findMnemex } from "./CliBridge.js";
import { log, getOutputChannel } from "./log.js";
import * as fs from "fs";

export function activate(context: vscode.ExtensionContext): void {
	const channel = getOutputChannel();
	context.subscriptions.push(channel);
	log("mnemex extension activating");

	// Auto-detect binary on activation and warn if not found
	const binaryPath = findMnemex();
	log(`Binary resolved: ${binaryPath}`);
	if (binaryPath === "mnemex" || !fs.existsSync(binaryPath)) {
		// Only warn if it's the bare name fallback (auto-detect found nothing)
		// We do a quick non-blocking check via which; if it fails, show a notification
		const cfg = vscode.workspace.getConfiguration("mnemex");
		const configured = cfg.get<string>("binaryPath", "");
		if (!configured || configured.trim() === "") {
			// Show notification with install instructions
			void vscode.window
				.showWarningMessage(
					"mnemex binary not found. Install with: npm install -g mnemex",
					"Open Settings",
				)
				.then((selection) => {
					if (selection === "Open Settings") {
						void vscode.commands.executeCommand(
							"workbench.action.openSettings",
							"mnemex.binaryPath",
						);
					}
				});
		}
	}

	log("Creating providers");
	const provider = new SearchProvider(context.extensionUri, context);
	const companion = new CompanionPanelProvider(context.extensionUri, context);

	context.subscriptions.push(
		vscode.window.registerWebviewViewProvider(SearchProvider.viewId, provider, {
			webviewOptions: { retainContextWhenHidden: true },
		}),
		vscode.commands.registerCommand("mnemex.reindex", () => {
			void provider.reindex();
		}),
		vscode.commands.registerCommand("mnemex.openSearch", () => {
			void vscode.commands.executeCommand("mnemexSearch.focus");
		}),
		vscode.commands.registerCommand("mnemex.openCompanion", () => {
			companion.open();
		}),
	);
}

export function deactivate(): void {}

import * as vscode from "vscode";
import * as fs from "fs";
import * as path from "path";

let _channel: vscode.OutputChannel | undefined;
let _logFile: string | undefined;

function getLogFile(): string {
	if (!_logFile) {
		const home = process.env["HOME"] ?? "/tmp";
		const dir = path.join(home, ".mnemex");
		try {
			fs.mkdirSync(dir, { recursive: true });
		} catch {}
		_logFile = path.join(dir, "vscode-extension.log");
		// Truncate on activation to avoid unbounded growth
		try {
			fs.writeFileSync(_logFile, "");
		} catch {}
	}
	return _logFile;
}

export function getOutputChannel(): vscode.OutputChannel {
	if (!_channel) {
		_channel = vscode.window.createOutputChannel("mnemex");
	}
	return _channel;
}

export function log(message: string): void {
	const ts = new Date().toISOString().slice(11, 23);
	const line = `[${ts}] ${message}\n`;
	getOutputChannel().appendLine(line.trimEnd());
	try {
		fs.appendFileSync(getLogFile(), line);
	} catch {}
}

