/**
 * Shared key=value parsing utilities used by all parsers.
 *
 * The mnemex --agent output has two line shapes:
 *   1. Simple:          key=value
 *   2. Multi-field:     prefix key1=value1 key2=value2 ...
 *
 * IMPORTANT: Values (especially file paths) may contain spaces.
 * We parse by locating key= boundaries using lookahead for " word=" patterns.
 */

/**
 * Parse a string of key=value pairs where values may contain spaces.
 *
 * Strategy: find all positions where "word=" appears (accounting for start-of-string
 * or a preceding space), then slice between consecutive key positions.
 *
 * Example: "file=/Users/John Doe/project/src/auth.ts line=42 score=0.9"
 * => { file: '/Users/John Doe/project/src/auth.ts', line: '42', score: '0.9' }
 */
export function parseKV(line: string): Record<string, string> {
	const result: Record<string, string> = {};

	// Find all positions where a key starts: beginning of string or after a space,
	// followed by word characters and '='
	const keyPattern = /(?:^|\s)(\w+)=/g;
	const matches: Array<{
		key: string;
		valueStart: number;
		boundaryPos: number;
	}> = [];

	let m: RegExpExecArray | null;
	while ((m = keyPattern.exec(line)) !== null) {
		const key = m[1];
		const valueStart = m.index + m[0].length;
		// boundaryPos is the position of the space before the key (or start of string)
		const boundaryPos = m.index;
		matches.push({ key, valueStart, boundaryPos });
	}

	for (let i = 0; i < matches.length; i++) {
		const { key, valueStart } = matches[i];
		// Value extends to the space before the next key, or end of string
		const valueEnd =
			i + 1 < matches.length ? matches[i + 1].boundaryPos : line.length;
		result[key] = line.slice(valueStart, valueEnd).trimEnd();
	}

	return result;
}

/**
 * Parse a line that starts with a prefix word followed by key=value pairs.
 *
 * Example: "result file=src/auth.ts line=42 score=0.923 type=function name=validateToken"
 * => { prefix: 'result', kv: { file: 'src/auth.ts', line: '42', ... } }
 */
export function parsePrefix(line: string): {
	prefix: string;
	kv: Record<string, string>;
} {
	const firstSpace = line.indexOf(" ");
	if (firstSpace === -1) {
		return { prefix: line, kv: {} };
	}
	return {
		prefix: line.slice(0, firstSpace),
		kv: parseKV(line.slice(firstSpace + 1)),
	};
}

import { parseKV } from "./kv.js";
import type { RepoMapEntry } from "../types/messages.js";

/**
 * Parse the output of `mnemex map --agent`.
 *
 * Format:
 *   file=<path>
 *   symbol name=<string> kind=<string> line=<n> rank=<f>
 *   symbol name=<string> kind=<string> line=<n> rank=<f>
 *   file=<path>
 *   ...
 */
export function parseMapOutput(raw: string): RepoMapEntry[] {
	const entries: RepoMapEntry[] = [];
	let current: RepoMapEntry | null = null;

	for (const line of raw.split("\n")) {
		const trimmed = line.trim();
		if (!trimmed) {
			continue;
		}

		if (trimmed.startsWith("file=")) {
			if (current) {
				entries.push(current);
			}
			current = {
				filePath: trimmed.slice("file=".length),
				symbols: [],
			};
		} else if (trimmed.startsWith("symbol ") && current) {
			const kv = parseKV(trimmed.slice("symbol ".length));
			current.symbols.push({
				name: kv["name"] ?? "",
				kind: kv["kind"] ?? "",
				line: parseInt(kv["line"] ?? "0", 10),
				rank: parseFloat(kv["rank"] ?? "0"),
			});
		}
	}

	if (current) {
		entries.push(current);
	}

	return entries;
}

import { parseKV } from "./kv.js";
import type { SearchResult } from "../types/messages.js";

/**
 * Parse the output of `mnemex search --agent`.
 *
 * Format:
 *   query=<string>
 *   result_count=<n>
 *   result file=<path> line=<n> score=<f> type=<chunkType> name=<string> [summary=<string>]
 *   ...
 */
export function parseSearchOutput(raw: string): SearchResult[] {
	const results: SearchResult[] = [];

	for (const line of raw.split("\n")) {
		if (!line.startsWith("result ")) {
			continue;
		}
		const kv = parseKV(line.slice("result ".length));
		results.push({
			file: kv["file"] ?? "",
			line: parseInt(kv["line"] ?? "0", 10),
			endLine: parseInt(kv["end_line"] ?? kv["line"] ?? "0", 10),
			score: parseFloat(kv["score"] ?? "0"),
			type: kv["type"] ?? "",
			name: kv["name"] ?? "",
			summary: kv["summary"],
		});
	}

	return results;
}

import type { IndexStatus } from "../types/messages.js";

/**
 * Parse the output of `mnemex status --agent`.
 *
 * Format:
 *   exists=<bool>
 *   [files=<n>]
 *   [chunks=<n>]
 *   [languages=<csv>]
 *   [model=<string>]
 *   [last_updated=<iso>]
 *
 * NOTE: model=none is emitted when no embedding model is configured.
 * This must be mapped to undefined, not propagated as the string "none".
 */
export function parseStatusOutput(raw: string): IndexStatus {
	const status: IndexStatus = { exists: false };

	for (const line of raw.split("\n")) {
		const trimmed = line.trim();
		if (!trimmed || !trimmed.includes("=")) {
			continue;
		}

		const eqIdx = trimmed.indexOf("=");
		const key = trimmed.slice(0, eqIdx);
		const value = trimmed.slice(eqIdx + 1);

		switch (key) {
			case "exists":
				status.exists = value === "true";
				break;
			case "files":
				status.files = parseInt(value, 10);
				break;
			case "chunks":
				status.chunks = parseInt(value, 10);
				break;
			case "languages":
				status.languages = value ? value.split(",").map((l) => l.trim()) : [];
				break;
			case "model":
				// model=none means no embedding model configured
				status.model = value === "none" ? undefined : value;
				break;
			case "last_updated":
				status.lastUpdated = value;
				break;
		}
	}

	return status;
}

