import { useState, useCallback, useRef } from "react";
import { getVsCodeApi } from "../vscode";
import type {
	HostToWebviewMessage,
	DeadCodeResult,
	TestGapResult,
	ImpactResult,
} from "../types/messages";

export type AnalysisTab = "dead-code" | "test-gaps" | "impact";

export interface AnalysisState {
	activeTab: AnalysisTab;
	impactQuery: string;
	loading: boolean;
	error: string | null;
	deadCodeItems: DeadCodeResult[] | null;
	testGapItems: TestGapResult[] | null;
	impactResult: ImpactResult | null;
}

export interface UseAnalysisReturn extends AnalysisState {
	setActiveTab: (tab: AnalysisTab) => void;
	setImpactQuery: (query: string) => void;
	runAnalysis: () => void;
	handleMessage: (message: HostToWebviewMessage) => void;
}

function makeRequestId(): string {
	return `analysis-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

export function useAnalysis(): UseAnalysisReturn {
	const [state, setState] = useState<AnalysisState>({
		activeTab: "dead-code",
		impactQuery: "",
		loading: false,
		error: null,
		deadCodeItems: null,
		testGapItems: null,
		impactResult: null,
	});

	const activeRequestId = useRef<string>("");

	const setActiveTab = useCallback((tab: AnalysisTab) => {
		setState((prev) => ({ ...prev, activeTab: tab, error: null }));
	}, []);

	const setImpactQuery = useCallback((query: string) => {
		setState((prev) => ({ ...prev, impactQuery: query }));
	}, []);

	const runAnalysis = useCallback(() => {
		setState((prev) => {
			const requestId = makeRequestId();
			activeRequestId.current = requestId;

			if (prev.activeTab === "dead-code") {
				getVsCodeApi().postMessage({ type: "getDeadCode", requestId });
				return { ...prev, loading: true, error: null, deadCodeItems: null };
			} else if (prev.activeTab === "test-gaps") {
				getVsCodeApi().postMessage({ type: "getTestGaps", requestId });
				return { ...prev, loading: true, error: null, testGapItems: null };
			} else if (prev.activeTab === "impact") {
				const name = prev.impactQuery.trim();
				if (!name) {
					return prev;
				}
				getVsCodeApi().postMessage({ type: "getImpact", name, requestId });
				return { ...prev, loading: true, error: null, impactResult: null };
			}
			return prev;
		});
	}, []);

	const handleMessage = useCallback((message: HostToWebviewMessage) => {
		const isActive = (id: string) => id === activeRequestId.current;

		if (message.type === "loading" && isActive(message.requestId)) {
			setState((prev) => ({ ...prev, loading: true }));
		} else if (message.type === "error" && isActive(message.requestId)) {
			setState((prev) => ({ ...prev, loading: false, error: message.message }));
		} else if (
			message.type === "deadCodeResult" &&
			isActive(message.requestId)
		) {
			setState((prev) => ({
				...prev,
				loading: false,
				error: null,
				deadCodeItems: message.items,
			}));
		} else if (
			message.type === "testGapsResult" &&
			isActive(message.requestId)
		) {
			setState((prev) => ({
				...prev,
				loading: false,
				error: null,
				testGapItems: message.items,
			}));
		} else if (message.type === "impactResult" && isActive(message.requestId)) {
			setState((prev) => ({
				...prev,
				loading: false,
				error: null,
				impactResult: message.data,
			}));
		}
	}, []);

	return { ...state, setActiveTab, setImpactQuery, runAnalysis, handleMessage };
}

import { useState, useCallback } from "react";
import type {
	HostToWebviewMessage,
	SymbolInfo,
	CallersResult,
	CalleesResult,
} from "../types/messages";

export interface CompanionState {
	symbolName: string | null;
	symbol: SymbolInfo | null;
	callers: CallersResult | null;
	callees: CalleesResult | null;
	summary: string | null;
	sourceCode: string | null;
	language: string | null;
	symbolCount: number;
	loading: boolean;
	empty: boolean;
	pinned: boolean;
}

export interface UseCompanionReturn extends CompanionState {
	handleMessage: (message: HostToWebviewMessage) => void;
	togglePin: () => void;
}

export function useCompanion(): UseCompanionReturn {
	const [state, setState] = useState<CompanionState>({
		symbolName: null,
		symbol: null,
		callers: null,
		callees: null,
		summary: null,
		sourceCode: null,
		language: null,
		symbolCount: 100,
		loading: false,
		empty: true,
		pinned: false,
	});

	const handleMessage = useCallback((message: HostToWebviewMessage) => {
		switch (message.type) {
			case "companionLoading":
				setState((prev) => ({
					...prev,
					loading: true,
					empty: false,
					symbolName: message.symbolName,
				}));
				break;

			case "companionUpdate":
				setState((prev) => ({
					...prev,
					loading: false,
					empty: false,
					symbolName: message.symbolName,
					symbol: message.symbol,
					callers: message.callers,
					callees: message.callees,
					summary: message.summary,
					sourceCode: message.sourceCode,
					language: message.language,
					symbolCount: message.symbolCount,
				}));
				break;

			case "companionEmpty":
				setState((prev) => ({
					...prev,
					loading: false,
					empty: true,
					symbolName: null,
					symbol: null,
					callers: null,
					callees: null,
					summary: null,
					sourceCode: null,
					language: null,
				}));
				break;

			default:
				break;
		}
	}, []);

	const togglePin = useCallback(() => {
		setState((prev) => ({ ...prev, pinned: !prev.pinned }));
	}, []);

	return { ...state, handleMessage, togglePin };
}

import { useState, useCallback, useRef, useEffect } from "react";
import { getVsCodeApi } from "../vscode";
import type { SearchResult, HostToWebviewMessage } from "../types/messages";

interface SearchState {
	query: string;
	results: SearchResult[];
	loading: boolean;
	error: string | null;
}

interface UseSearchReturn extends SearchState {
	setQuery: (query: string) => void;
	handleMessage: (message: HostToWebviewMessage) => void;
}

function makeRequestId(): string {
	return `search-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

/**
 * Search state hook with 300ms debounce.
 * Sends search messages to the host and handles searchResults/error responses.
 * Ignores responses with mismatched requestId to avoid stale results.
 */
export function useSearch(): UseSearchReturn {
	const [state, setState] = useState<SearchState>({
		query: "",
		results: [],
		loading: false,
		error: null,
	});

	const activeRequestId = useRef<string>("");
	const prevRequestId = useRef<string>("");
	const debounceTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

	const setQuery = useCallback((query: string) => {
		setState((prev) => ({ ...prev, query }));

		// Clear previous debounce
		if (debounceTimer.current !== null) {
			clearTimeout(debounceTimer.current);
		}

		const trimmed = query.trim();
		if (!trimmed) {
			setState((prev) => ({
				...prev,
				results: [],
				loading: false,
				error: null,
			}));
			return;
		}

		// Require at least 3 characters to avoid expensive short-query API calls
		if (trimmed.length < 3) {
			return;
		}

		debounceTimer.current = setTimeout(() => {
			const requestId = makeRequestId();
			prevRequestId.current = activeRequestId.current;
			activeRequestId.current = requestId;

			setState((prev) => ({ ...prev, loading: true, error: null }));

			// Cancel the previous request if any
			if (prevRequestId.current) {
				getVsCodeApi().postMessage({
					type: "cancel",
					requestId: prevRequestId.current,
				});
			}

			getVsCodeApi().postMessage({
				type: "search",
				query: query.trim(),
				requestId,
			});
		}, 600);
	}, []);

	// Cleanup debounce timer on unmount
	useEffect(() => {
		return () => {
			if (debounceTimer.current !== null) {
				clearTimeout(debounceTimer.current);
			}
		};
	}, []);

	const handleMessage = useCallback((message: HostToWebviewMessage) => {
		if (message.type === "searchResults") {
			if (message.requestId !== activeRequestId.current) {
				return; // Stale response — ignore
			}
			setState((prev) => ({
				...prev,
				results: message.results,
				loading: false,
				error: null,
			}));
		} else if (
			message.type === "loading" &&
			message.requestId === activeRequestId.current
		) {
			setState((prev) => ({ ...prev, loading: true }));
		} else if (
			message.type === "error" &&
			message.requestId === activeRequestId.current
		) {
			setState((prev) => ({
				...prev,
				loading: false,
				error: message.message,
			}));
		}
	}, []);

	return { ...state, setQuery, handleMessage };
}

import { useState, useCallback, useRef } from "react";
import { getVsCodeApi } from "../vscode";
import type {
	HostToWebviewMessage,
	SymbolInfo,
	CallersResult,
	CalleesResult,
	ContextResult,
} from "../types/messages";

export type SymbolCommand = "symbol" | "callers" | "callees" | "context";

export interface SymbolNavState {
	query: string;
	command: SymbolCommand;
	loading: boolean;
	error: string | null;
	symbolResult: SymbolInfo | null;
	callersResult: CallersResult | null;
	calleesResult: CalleesResult | null;
	contextResult: ContextResult | null;
}

export interface UseSymbolNavReturn extends SymbolNavState {
	setQuery: (query: string) => void;
	setCommand: (command: SymbolCommand) => void;
	submit: () => void;
	handleMessage: (message: HostToWebviewMessage) => void;
}

function makeRequestId(): string {
	return `symbol-${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

export function useSymbolNav(): UseSymbolNavReturn {
	const [state, setState] = useState<SymbolNavState>({
		query: "",
		command: "symbol",
		loading: false,
		error: null,
		symbolResult: null,
		callersResult: null,
		calleesResult: null,
		contextResult: null,
	});

	const activeRequestId = useRef<string>("");

	const setQuery = useCallback((query: string) => {
		setState((prev) => ({ ...prev, query }));
	}, []);

	const setCommand = useCallback((command: SymbolCommand) => {
		setState((prev) => ({
			...prev,
			command,
			symbolResult: null,
			callersResult: null,
			calleesResult: null,
			contextResult: null,
			error: null,
		}));
	}, []);

	const submit = useCallback(() => {
		setState((prev) => {
			if (!prev.query.trim()) {
				return prev;
			}

			const requestId = makeRequestId();
			activeRequestId.current = requestId;

			const name = prev.query.trim();
			const messageMap: Record<SymbolCommand, () => void> = {
				symbol: () =>
					getVsCodeApi().postMessage({ type: "getSymbol", name, requestId }),
				callers: () =>
					getVsCodeApi().postMessage({ type: "getCallers", name, requestId }),
				callees: () =>
					getVsCodeApi().postMessage({ type: "getCallees", name, requestId }),
				context: () =>
					getVsCodeApi().postMessage({ type: "getContext", name, requestId }),
			};
			messageMap[prev.command]();

			return {
				...prev,
				loading: true,
				error: null,
				symbolResult: null,
				callersResult: null,
				calleesResult: null,
				contextResult: null,
			};
		});
	}, []);

	const handleMessage = useCallback((message: HostToWebviewMessage) => {
		const isActive = (id: string) => id === activeRequestId.current;

		if (message.type === "loading" && isActive(message.requestId)) {
			setState((prev) => ({ ...prev, loading: true }));
		} else if (message.type === "error" && isActive(message.requestId)) {
			setState((prev) => ({ ...prev, loading: false, error: message.message }));
		} else if (message.type === "symbolResult" && isActive(message.requestId)) {
			setState((prev) => ({
				...prev,
				loading: false,
				error: null,
				symbolResult: message.symbol,
			}));
		} else if (
			message.type === "callersResult" &&
			isActive(message.requestId)
		) {
			setState((prev) => ({
				...prev,
				loading: false,
				error: null,
				callersResult: message.data,
			}));
		} else if (
			message.type === "calleesResult" &&
			isActive(message.requestId)
		) {
			setState((prev) => ({
				...prev,
				loading: false,
				error: null,
				calleesResult: message.data,
			}));
		} else if (
			message.type === "contextResult" &&
			isActive(message.requestId)
		) {
			setState((prev) => ({
				...prev,
				loading: false,
				error: null,
				contextResult: message.data,
			}));
		}
	}, []);

	return { ...state, setQuery, setCommand, submit, handleMessage };
}

import { useEffect } from "react";
import type { HostToWebviewMessage } from "../types/messages";

/**
 * Subscribe to messages from the VS Code extension host.
 * Calls handler with each typed message received.
 */
export function useVscodeMessages(
	handler: (message: HostToWebviewMessage) => void,
): void {
	useEffect(() => {
		const listener = (event: MessageEvent<HostToWebviewMessage>) => {
			handler(event.data);
		};

		window.addEventListener("message", listener);
		return () => {
			window.removeEventListener("message", listener);
		};
	}, [handler]);
}

